ClinicalChunks.register("data/orders-015.js",[{"id":"orders-d491a4c9c1b59bf4a021","key":"v1-c9ccc21dfe2a3058|orders-d491a4c9c1b59bf4a021","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肝硬化患者夜班处理要点","category":"夜班特殊人群","raw":{"name":"肝硬化患者夜班处理要点","category":"夜班特殊人群","summary":"肝硬化患者夜班处理需关注：门静脉高压并发症（食管胃底静脉破裂出血、腹水、肝性脑病、自发性腹膜炎）、肝功能储备差（用药需减量、避免肝毒性药物）、凝血功能障碍与低血糖风险，以及肝肾综合征与电解质紊乱（低钠、低钾）。","symptoms":["消化道出血：呕血、黑便（食管胃底静脉破裂，夜班常见危症）","肝性脑病：性格改变、嗜睡或烦躁、扑翼样震颤、定向力障碍、昏迷（夜间加重常见）","腹水与自发性腹膜炎：腹胀、腹围增大、腹痛、发热（SBP可无典型腹膜刺激征）","黄疸加深、皮肤瘙痒、尿色深；乏力、食欲减退、消瘦","低血糖（肝糖原储备不足，夜间与清晨易发）、电解质紊乱（低钠、低钾）"],"diagnosis":["血常规+凝血功能+肝功能+白蛋白+胆红素：肝储备（Child-Pugh/MELD评分）与出血风险评估","血氨+血气分析：肝性脑病评估（血氨与脑病程度不完全平行）","腹部超声（含腹水）+腹部CT：腹水量、肝形态、门静脉内径与血栓、有无肝癌","腹水检查（诊断性穿刺）：细胞数（中性粒细胞≥250/mm³诊断SBP）、蛋白、SAAG、培养","胃镜（出血者24小时内）：食管胃底静脉曲张程度与出血部位","电解质（钠、钾、镁）+肾功能+尿钠：低钠血症、肝肾综合征评估","血糖（夜间与清晨监测）：低血糖风险评估"],"infusion":["⚠️ 肝硬化患者用药需减量并避免肝毒性药物，输液需控制量与钠！","","方案1（食管胃底静脉破裂出血）：","  用法：生长抑素 250μg 静推后 3mg/12h 泵入 或 奥曲肽 0.1mg 静推后 25～50μg/h 泵入（3～5天）；艾司奥美拉唑 40mg 静推 q12h；头孢曲松 1～2g（NS 100ml 或 5%GS 100ml）静滴 qd（预防感染）；输血维持Hb 70～90g/L（避免过量输液升高门脉压）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","方案2（肝性脑病）：","  用法：乳果糖 30～45ml 口服/鼻饲（或 150ml 保留灌肠）q6～8h（调整至每日2～3次软便）；门冬氨酸鸟氨酸 10～20g + 5%葡萄糖 250ml 静滴 qd；支链氨基酸 250ml 静滴 qd；纠正电解质紊乱与碱中毒〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","","方案3（自发性腹膜炎，SBP）：","  用法：头孢曲松 2g 静滴 qd 或 头孢噻肟 2g 静滴 q8h（疗程5～7天）；白蛋白 1.5g/kg（第1天）+ 1g/kg（第3天）静滴（预防肝肾综合征）；避免使用肾毒性抗生素〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案4（腹水与低钠血症）：","  用法：限水（血钠<125mmol/L时限水800～1000ml/日）；白蛋白 10g 静滴（低蛋白）；呋塞米 20～40mg + 螺内酯 40～80mg（口服为主，按尿量电解质调整）；避免快速大量放腹水（每次<5L并补白蛋白）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","","📌 肝硬化患者输液避免大量生理盐水（加重腹水与水肿）；禁用NSAIDs、氨基糖苷类与镇静药（诱发肝性脑病）；低钠血症以限水为主（不盲目补钠）。"],"oral_medication":["⚠️ 肝硬化患者口服用药需注意肝代谢与不良反应：","药物1（降门脉压，预防再出血）：","用法：普萘洛尔 10mg bid 起（逐步调整至静息心率下降25%或55～60次/分）或 卡维地洛 6.25mg bid（禁用于心率<55次/分、低血压、哮喘）","药物2（利尿，腹水）：","用法：螺内酯 40～80mg qd + 呋塞米 20～40mg qd（按尿量、体重与电解质调整，避免过度利尿致肝性脑病与肾损）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","药物3（乳果糖，肝性脑病预防/治疗）：","用法：乳果糖 15～30ml bid～tid（调整至每日2～3次软便）；利福昔明 400mg q8h（预防复发）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4（营养与支持）：","用法：复合维生素B 2片 tid；维生素K1 10mg qd（凝血障碍）；锌剂（味觉与肝性脑病辅助）；支链氨基酸口服（营养不良者）","📌 禁用/慎用：NSAIDs（肾损与出血）、苯二氮卓类与阿片类（诱发肝性脑病）、对乙酰氨基酚（每日不超过2g）、中草药（肝毒性风险）。"],"treatment":["食管胃底静脉破裂出血：禁食、双通道补液、生长抑素/奥曲肽、抑酸、预防性抗生素、内镜下套扎/硬化（24小时内）、三腔二囊管压迫（内镜失败时）、TIPS（反复出血）","肝性脑病：去除诱因（感染、出血、便秘、电解质紊乱、镇静药）、乳果糖+门冬氨酸鸟氨酸、限制蛋白（短期，长期不主张过度限制）、支链氨基酸、纠正碱中毒与低钾","腹水管理：限钠（<2g/日）限水（低钠时）、利尿剂（螺内酯+呋塞米）、白蛋白（大量放腹水后每次10g/L）、顽固性腹水考虑TIPS或反复放腹水","自发性腹膜炎：诊断性穿刺（中性粒细胞≥250/mm³）+第三代头孢菌素（5～7天）+白蛋白（预防肝肾综合征），后续口服喹诺酮预防复发","肝肾综合征：停用肾毒性药物与利尿剂、白蛋白+特利加压素（或去甲肾上腺素）、必要时血液净化与肝移植评估","凝血与出血防治：维生素K1、新鲜冰冻血浆（活动性出血）、血小板（<20～30×10⁹/L伴出血），避免不必要的侵入操作","低血糖与营养：夜间加餐（睡前碳水化合物补充）、监测血糖、营养支持（热量25～35kcal/kg、蛋白1.2～1.5g/kg）","宣教：戒酒、避免肝毒性药物、规律随访、识别危险症状（呕血黑便、性格改变、腹胀加重）及时就诊"],"management":["意识与神经系统监测：每2～4小时评估意识、性格改变与扑翼样震颤（肝性脑病分级），异常立即报告","出血观察：观察呕血、黑便、生命体征与血红蛋白；保持静脉通路畅通，备血与急救药物","腹围与体重：每日测量腹围与体重，记录24小时出入量，观察利尿效果与水肿变化","电解质与血糖监测：每1～2天（或按病情）复查血钠、钾与血糖；夜间与清晨注意低血糖","用药核对与限制：核对肝功能剂量（Child-Pugh分级）、避免肝毒性与肾毒性药物、禁用镇静药","皮肤与口腔护理：黄疸瘙痒者温水擦洗、避免抓伤；口腔护理（氨味、牙龈出血）","饮食与宣教：限钠限水、少量多餐+夜间加餐、戒酒、遵医嘱用药、识别危险症状与随访安排"],"notes":["肝硬化患者夜班最常见的危症是食管胃底静脉破裂出血与肝性脑病，需立即处理","出血患者输血目标Hb 70～90g/L（避免过量输液升高门脉压加重出血）","肝性脑病需去除诱因（感染、出血、便秘、电解质紊乱、镇静药），乳果糖是基础治疗","自发性腹膜炎可无典型腹膜刺激征，腹水中性粒细胞≥250/mm³即可诊断（应常规诊断性穿刺）","肝硬化患者禁用NSAIDs、氨基糖苷类与镇静药；对乙酰氨基酚每日不超过2g；避免大量生理盐水输注"],"emergency":["大量呕血、黑便伴血压下降（食管胃底静脉破裂）→ 立即双通道抢救、生长抑素+抑酸+抗生素，急诊内镜止血","意识障碍伴扑翼样震颤（肝性脑病Ⅲ～Ⅳ级）→ 乳果糖+门冬氨酸鸟氨酸，去除诱因，防误吸与坠床","腹水迅速增多伴发热腹痛（自发性腹膜炎）→ 立即诊断性穿刺+经验性抗生素+白蛋白","少尿、无尿伴肌酐升高与低钠（肝肾综合征）→ 停用利尿剂与肾毒性药物、白蛋白+特利加压素，评估透析与肝移植","夜间突发意识模糊、出汗、心悸（低血糖）→ 立即测血糖并静脉推注50%葡萄糖"],"pinyin":"gyhhzybcl","icd10":"K74.6","physical_exam":["生命体征：血压（出血）、心率、体温（感染）、呼吸（肝肺综合征/腹水致呼吸困难）","意识与神经系统：意识状态、性格改变、定向力、扑翼样震颤（肝性脑病分级）、腱反射","皮肤黏膜：黄疸程度、蜘蛛痣、肝掌、瘀斑与出血点、注射部位渗血、男性乳房发育","腹部视诊：腹围（测量记录）、腹壁静脉曲张（'海蛇头'）、脐疝","腹部触诊：肝大小与质地（硬、结节）、脾大、液波震颤、压痛（腹膜炎）","腹部叩诊：移动性浊音（腹水）、肝浊音界缩小","营养与肌肉：消瘦、肌肉萎缩（肌少症）、下肢水肿、体重变化"],"lab_tests":["肝功能+白蛋白+胆红素+胆碱酯酶+凝血酶原时间：肝储备（Child-Pugh/MELD）与预后评估","血氨+血气分析：肝性脑病评估（血氨与脑病程度不完全平行，血气提示碱中毒）","血常规+血小板：脾功能亢进与出血评估（血小板<50×10⁹/L提示风险）","电解质（钠、钾、镁）+肾功能（肌酐、尿素氮）+尿钠：低钠血症、肝肾综合征评估","腹水检查（诊断性穿刺）：细胞数（中性粒细胞）、蛋白、SAAG、培养与细胞学","腹部超声+CT：腹水量、肝形态、门静脉内径与血栓、肝癌筛查（AFP+超声每3～6个月）","血糖（夜间与清晨）+心肌酶（胸痛者）：低血糖与心血管评估"],"nursing":["意识与肝性脑病观察：每2～4小时评估意识、性格改变与扑翼样震颤，异常立即报告；加床档防坠床","出血护理：观察呕血、黑便与生命体征，保持静脉通路，备三腔二囊管与急救药品，记录出血量","腹水与利尿护理：每日测腹围、体重与24小时出入量，限钠限水宣教，观察利尿效果与电解质","用药护理：核对肝功能剂量（Child-Pugh），避免肝毒性与肾毒性药物；乳果糖按排便次数调整剂量","饮食护理：限钠（<2g/日）、限水（低钠时）、少量多餐+夜间加餐（防低血糖）、蛋白适量（肝性脑病期遵医嘱）","皮肤与基础护理：黄疸瘙痒者温水清洁、剪短指甲；口腔护理（氨味与牙龈出血）；鼓励床上活动防血栓"],"diet":["限钠：每日钠盐<2g（腹水者），避免腌制品、加工食品与含钠调料","限水：血钠<125mmol/L时限制液体800～1000ml/日（含汤水与输液）","蛋白质：一般1.2～1.5g/kg/日（植物蛋白与乳制品优先）；肝性脑病发作期短期限制（不超过3～5天）并遵医嘱","夜间加餐：睡前加碳水化合物（面包、饼干）与适量蛋白，减少夜间分解代谢与低血糖","戒酒、避免生冷与粗糙坚硬食物（防静脉破裂出血）；少量多餐（每日4～6餐）、高维生素饮食"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1401},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0a2ab3038ebb7a28d0095ff796dec9a979310f4798aeeab9f85a9576b52fd7c2","pinyin":"ganyinghuahuanzheyebanchuliyaodian","initials":"gyhhzybclyd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","消化道出血：呕血、黑便（食管胃底静脉破裂，夜班常见危症）\\n肝性脑病：性格改变、嗜睡或烦躁、扑翼样震颤、定向力障碍、昏迷（夜间加重常见）\\n腹水与自发性腹膜炎：腹胀、腹围增大、腹痛、发热（SBP可无典型腹膜刺激征）\\n黄疸加深、皮肤瘙痒、尿色深；乏力、食欲减退、消瘦\\n低血糖（肝糖原储备不足，夜间与清晨易发）、电解质紊乱（低钠、低钾）",60],["摘要","肝硬化患者夜班处理需关注：门静脉高压并发症（食管胃底静脉破裂出血、腹水、肝性脑病、自发性腹膜炎）、肝功能储备差（用药需减量、避免肝毒性药物）、凝血功能障碍与低血糖风险，以及肝肾综合征与电解质紊乱（低钠、低钾）。",30],["疾病编码","K74.6",30],["原首字母","gyhhzybcl",60]]},{"id":"orders-f8f798571c6a73cfddc6","key":"v1-c9ccc21dfe2a3058|orders-f8f798571c6a73cfddc6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"降压药物微泵使用","category":"夜班静脉泵药","raw":{"name":"降压药物微泵使用","category":"夜班静脉泵药","summary":"高血压急症（血压>180/120mmHg伴靶器官损害）需静脉降压，常用微泵药物包括乌拉地尔、尼卡地平、拉贝洛尔与硝酸甘油/硝普钠。降压原则：个体化、平稳降压（首1小时降低不超过25%，2～6小时降至160/100mmHg左右），避免血压骤降致器官缺血。","symptoms":["高血压急症症状：剧烈头痛、视物模糊、恶心呕吐、胸痛、呼吸困难、意识改变、抽搐","靶器官损害表现：胸痛（主动脉夹层/心肌缺血）、呼吸困难（急性左心衰/肺水肿）、神经系统症状（脑卒中/高血压脑病）、少尿（肾损害）","降压过快致缺血：头晕、黑矇、胸闷、意识改变、肢体无力（脑/心/肾灌注不足）","药物不良反应：尼卡地平（头痛、面部潮红、心动过速）、乌拉地尔（头晕、体位性低血压）、硝普钠（氰化物蓄积）","监测要点：血压（每5～15分钟）、心率、尿量与神经系统症状"],"diagnosis":["血压监测：双上肢血压、有创动脉压（重症或需精确控制者）、每5～15分钟记录","靶器官评估：心电图+心肌酶（心肌缺血）、眼底检查（视网膜病变）、头颅CT/MRI（脑卒中/脑病）、肾功能+尿常规（肾损害）、胸部影像（肺水肿/主动脉夹层）","心率与心律：尼卡地平与硝普钠可致反射性心动过速（监测并必要时联用β受体阻滞剂）","病因与合并症：嗜铬细胞瘤（阵发性高血压+头痛心悸出汗）、肾动脉狭窄、子痫前期、停药综合征","药物剂量滴定：按血压反应每5～15分钟调整泵速（避免大幅度波动）","电解质+肾功能：长期泵入与利尿治疗监测","神经系统评估：意识、瞳孔、肢体肌力（脑灌注评估）"],"infusion":["⚠️ 降压泵入须监护下滴定，避免血压骤降！","方案1（乌拉地尔，多数高血压急症首选，尤合并脑卒中）：","用法：乌拉地尔 12.5～25mg 静推（缓慢）后 100～400μg/min 泵入（或 5～30ml/h，按50mg/50ml配置）；目标：首1小时MAP下降≤25%，随后逐步达标","方案2（尼卡地平，合并脑缺血/蛛网膜下腔出血）：","用法：尼卡地平 5mg/h 泵入起，每5～15分钟增加2.5mg/h，最大15mg/h；注意反射性心动过速","方案3（拉贝洛尔，合并主动脉夹层、子痫前期、冠心病）：","用法：拉贝洛尔 20～40mg 静推（每10分钟可重复，总量≤300mg）后 1～2mg/min 泵入；主动脉夹层需同时控制心率（<60次/分）","方案4（硝酸甘油/硝普钠，合并急性左心衰/肺水肿）：","用法：硝酸甘油 5～10μg/min 泵入起（每5分钟增5～10μg/min，最大200μg/min）；或 硝普钠 0.3μg/kg/min 起（避光，最大10μg/kg/min，监测氰化物中毒：代谢性酸中毒、意识改变）；两者均需监测血压与心率〔调 ★ 收缩压<90 或右室梗死禁用；★ 24h内用过PDE5抑制剂禁用〕","📌 降压速度：首1小时MAP下降不超过25%，2～6小时降至约160/100mmHg；主动脉夹层需更快控制（收缩压100～120mmHg+心率<60次/分）；避免舌下含服硝苯地平（血压骤降风险）。"],"oral_medication":["⚠️ 静脉降压稳定后逐步过渡到口服，避免血压波动：","药物1（过渡口服，按病因选择）：","用法：氨氯地平 5mg qd 或 硝苯地平控释片 30mg qd（起效平稳）；乌拉地尔缓释片 30mg bid（可与静脉衔接）〔调 肝功能不全减量；踝部水肿（剂量相关）〕","药物2（合并冠心病/心率快）：","用法：美托洛尔缓释片 23.75～47.5mg qd 或 比索洛尔 2.5～5mg qd（主动脉夹层必需）〔调 ★ 严重心动过缓/二度以上AVB禁用；哮喘慎用；★ 不可骤停〕","药物3（合并心衰/蛋白尿）：","用法：缬沙坦 80mg qd 或 培哚普利 4mg qd（ACEI/ARB）；注意与静脉降压药重叠后逐步停静脉〔调 ★ 妊娠禁用；双侧肾动脉狭窄禁用；★ 警惕高钾〕","药物4（对症与病因）：","用法：头痛（对乙酰氨基酚 0.5g）；嗜铬细胞瘤（酚苄明 10mg bid 起，α受体阻滞剂先于β受体阻滞剂）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 静脉-口服过渡期需重叠给药（一般4～6小时）并监测血压，避免突然停用静脉药物导致血压反跳。"],"treatment":["高血压急症处理：监护室（或监护条件下）静脉降压（拉贝洛尔 20～80mg 静推 q10min 或 0.5～2mg/min 泵入；乌拉地尔 12.5～25mg 静推 继以 5～40mg/h 泵入；尼卡地平 5mg/h 起始泵入），个体化设定目标血压（依靶器官损害与基础血压）","目标血压设定：无靶器官损害者的高血压亚急症可口服降压；急症首1小时MAP下降≤25%，2～6小时至160/100mmHg，24～48小时逐步达标","病因治疗：主动脉夹层（控制心率+血压，艾司洛尔 0.5mg/kg 静推 继以 50～200μg/kg/min 泵入，急诊手术评估）、急性左心衰（降压+利尿+扩血管）、脑卒中（溶栓/取栓评估，降压阈值不同）、子痫前期（硫酸镁+降压+终止妊娠评估）、嗜铬细胞瘤（α阻滞剂+手术）","监测与滴定：每5～15分钟测血压并调整泵速，记录剂量与反应；避免血压波动（骤降致脑/心/肾缺血）","并发症防治：降压过快致意识改变/肢体无力/胸痛（立即减慢或暂停并评估）、反射性心动过速（联用β阻滞剂）、硝普钠氰化物中毒（监测酸中毒与意识，必要时羟钴胺）","静脉-口服过渡：血压稳定后逐步加口服降压药并重叠4～6小时，缓慢撤除静脉泵","宣教与随访：高血压急症后需规范口服降压治疗与随访（依从性是预防复发的关键）、避免自行停药与滥用升压/降压药物"],"management":["血压监测：每5～15分钟测血压（重症用有创动脉压），记录泵速与血压反应，避免大幅度波动","泵入管理：专用静脉通路（避免与其他药物混用）、标识清晰、使用输液泵、定时更换药液（硝酸甘油/硝普钠需避光与现配现用）","神经系统观察：意识、瞳孔、肢体肌力与语言（降压过快致脑缺血/脑卒中加重），异常立即报告","心肺监测：心率与心律、呼吸、血氧、胸痛与呼吸困难（心肌缺血/肺水肿）","尿量与肾功能：记录每小时尿量（目标≥0.5ml/kg/h），监测肾功能与电解质","药物外渗与不良反应：观察穿刺部位（乌拉地尔/尼卡地平外渗可致组织损伤）、面部潮红、头痛、恶心","宣教：解释高血压急症与长期治疗的重要性、按时服药与随访、识别血压过低的症状（头晕、黑矇）"],"notes":["高血压急症降压须平稳（首1小时MAP下降≤25%），血压骤降可致脑、心、肾缺血（尤其老年与长期高血压者）","主动脉夹层需同时控制心率（<60次/分）与血压（收缩压100～120mmHg），β受体阻滞剂优先","硝普钠需避光、现配现用，长时间大剂量使用需警惕氰化物/硫氰酸盐中毒（代谢性酸中毒+意识改变）","避免舌下含服短效硝苯地平降压（血压骤降与心血管事件风险）","静脉降压药物与口服药物过渡需重叠4～6小时，避免突然停药致血压反跳"],"emergency":["血压骤降伴意识改变、肢体无力或胸痛（过度降压致器官缺血）→ 立即减慢/暂停降压泵，补液并评估","高血压伴急性主动脉夹层（撕裂样胸背痛）→ 立即控制心率与血压（β阻滞剂+血管扩张剂），急诊CT与手术评估","高血压伴急性左心衰/肺水肿（端坐呼吸、咳粉红色泡沫痰）→ 硝酸甘油/硝普钠泵入+利尿+吸氧，必要时无创通气","硝普钠使用中出现意识改变、代谢性酸中毒（氰化物中毒）→ 立即停药并予羟钴胺（或亚硝酸钠+硫代硫酸钠）","嗜铬细胞瘤危象（阵发性高血压+头痛心悸大汗）→ 酚妥拉明 5mg 静推后泵入，绝对禁用单纯β阻滞剂"],"pinyin":"jyjwywbsy","icd10":"I10","physical_exam":["生命体征：双上肢血压（对比）、心率与心律、呼吸、血氧、体温","神经系统：意识、瞳孔、肢体肌力与语言（靶器官损害与过度降压评估）","眼底：视网膜出血、渗出与视乳头水肿（高血压视网膜病变分级）","心肺：心界、心音、肺部湿啰音（肺水肿）、颈静脉充盈、胸痛体征","血管：双侧脉搏对比（主动脉夹层/大动脉炎）、血管杂音（肾动脉狭窄）","肾脏与容量：尿量、水肿、脱水征","皮肤与穿刺部位：泵入药物外渗（红肿、疼痛）、末梢循环"],"lab_tests":["心电图+心肌酶（肌钙蛋白）：心肌缺血与左室肥厚评估（所有高血压急症必查）","肾功能（肌酐、尿素氮）+尿常规+尿蛋白：肾损害与肾动脉狭窄评估","电解质（钾、钠）+血气分析：利尿与降压治疗监测","头颅CT/MRI（神经系统症状者）：脑卒中、脑出血与高血压脑病","胸部CT/心脏超声（疑主动脉夹层/心衰）：主动脉形态、心功能与肺水肿","血常规+乳酸：组织灌注与贫血评估","内分泌检查（疑继发性高血压）：血醛固酮/肾素、儿茶酚胺/甲氧基肾上腺素、皮质醇"],"nursing":["血压与泵速监测：每5～15分钟测血压并记录泵速，按医嘱滴定（不可自行调整），观察血压波动","泵入护理：专用通路、标识清晰、输液泵控制、定时更换药液（硝普钠/硝酸甘油避光现配），观察穿刺部位外渗","靶器官观察：意识、瞳孔、肢体肌力（脑）、胸痛与心律（心）、尿量（肾）、呼吸（肺）","体位与安全：卧床休息、必要时半卧位（肺水肿）、防跌倒（低血压致头晕）、床档保护","出入量与电解质：记录24小时出入量与每小时尿量，观察电解质紊乱（利尿剂）","宣教：解释高血压急症的治疗与长期服药重要性、识别低血压症状（头晕、黑矇）、避免自行停药与情绪激动"],"diet":["急性期：禁食或清淡流质（视病情），避免过饱","长期：严格限盐（每日<5g，高血压者<3g），避免腌制品与加工食品","低脂饮食、控制体重；增加蔬果与全谷物（DASH饮食原则）","限制酒精与咖啡因；戒烟","合并心衰/肾病者按医嘱限水限钾；合并糖尿病者控制碳水"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1402},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5c4d1272fab9587f5a1d8199cf0f1859809a32841a5a5afca3b36121e0cf36dc","pinyin":"jiangyayaowuweibengshiyong","initials":"jyywwbsy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","高血压急症症状：剧烈头痛、视物模糊、恶心呕吐、胸痛、呼吸困难、意识改变、抽搐\\n靶器官损害表现：胸痛（主动脉夹层/心肌缺血）、呼吸困难（急性左心衰/肺水肿）、神经系统症状（脑卒中/高血压脑病）、少尿（肾损害）\\n降压过快致缺血：头晕、黑矇、胸闷、意识改变、肢体无力（脑/心/肾灌注不足）\\n药物不良反应：尼卡地平（头痛、面部潮红、心动过速）、乌拉地尔（头晕、体位性低血压）、硝普钠（氰化物蓄积）\\n监测要点：血压（每5～15分钟）、心率、尿量与神经系统症状",60],["摘要","高血压急症（血压>180/120mmHg伴靶器官损害）需静脉降压，常用微泵药物包括乌拉地尔、尼卡地平、拉贝洛尔与硝酸甘油/硝普钠。降压原则：个体化、平稳降压（首1小时降低不超过25%，2～6小时降至160/100mmHg左右），避免血压骤降致器官缺血。",30],["疾病编码","I10",30],["原首字母","jyjwywbsy",60]]},{"id":"orders-28f52c48bcdf51b3c7b7","key":"v1-c9ccc21dfe2a3058|orders-28f52c48bcdf51b3c7b7","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"抑酸与生长抑素微泵使用","category":"夜班静脉泵药","raw":{"name":"抑酸与生长抑素微泵使用","category":"夜班静脉泵药","summary":"夜班常用抑酸与抑制消化液分泌的微泵药物：质子泵抑制剂（奥美拉唑/艾司奥美拉唑）用于上消化道出血与应激性溃疡预防；生长抑素/奥曲肽用于食管胃底静脉破裂出血、胰瘘、消化道瘘与急性胰腺炎。","symptoms":["适应证表现：呕血、黑便（消化道出血）、腹痛与腹胀（胰腺炎）、引流液量大（瘘）、反酸与胃灼热（溃疡）","抑酸不足表现：持续出血、胃液pH低（<6影响血凝块稳定）、反酸加重","生长抑素不良反应：血糖波动（抑制胰高血糖素与胰岛素）、恶心腹痛、注射部位反应、长期（>2周）胆结石风险","奥曲肽快速静推致心率与血压变化（应缓慢静推或持续泵入）","需警惕：出血未控制（血压下降、血红蛋白下降、呕血黑便持续）"],"diagnosis":["出血评估：呕血与黑便量、生命体征、血红蛋白动态、胃管引流性状","胃液pH监测（必要时）：维持pH>6（利于血凝块稳定）","血气分析与电解质：代谢性碱中毒（长期抑酸与胃肠减压）、低钾低镁","血糖监测（生长抑素/奥曲肽治疗期间，每4～6小时）","内镜检查（24小时内）：明确出血部位与内镜下止血","腹部CT+淀粉酶（胰腺炎/胰瘘）：评估病情与疗效","凝血功能+血小板：出血性疾病评估"],"infusion":["⚠️ 按适应证选择，泵入速度按医嘱，不可随意快推！","方案1（上消化道出血，大剂量PPI泵入）：","用法：艾司奥美拉唑 80mg 静推（负荷，20～30分钟）后 8mg/h 持续泵入 72小时（或 奥美拉唑 80mg 负荷后 8mg/h）；之后改为 40mg 静推 q12h〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","方案2（食管胃底静脉破裂出血，生长抑素）：","用法：生长抑素 250μg 静推（负荷）后 3mg/12h 持续泵入（或 250μg/h 泵入，疗程3～5天）；停药前需逐步减量（防再出血）〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","方案3（奥曲肽，替代生长抑素）：","用法：奥曲肽 0.1mg 静推（负荷）后 25～50μg/h 持续泵入（或 0.1mg 皮下注射 q8h）；疗程3～5天，逐步停药","方案4（急性胰腺炎/消化道瘘）：","用法：生长抑素 3mg/12h 泵入 或 奥曲肽 25～50μg/h（疗程1～2周）；艾司奥美拉唑 40mg 静推 q12h 辅助（减少胰液分泌刺激）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","📌 PPI负荷量后持续泵入是上消化道出血的标准方案；生长抑素/奥曲肽停药需逐步减量（突然停药可致反跳性出血）；奥曲肽快速静推可致心率变化（负荷量应缓慢）。"],"oral_medication":["⚠️ 出血期禁食，稳定后序贯口服：","药物1（抑酸序贯）：","用法：艾司奥美拉唑 20mg qd（晨起餐前）或 雷贝拉唑 10mg qd（疗程4～8周）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物2（胃黏膜保护与根除幽门螺杆菌）：","用法：铝碳酸镁 1.0g tid（餐后）；根除Hp：阿莫西林 1.0g bid + 克拉霉素 0.5g bid + PPI + 铋剂（14天）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物3（生长抑素口服替代，稳定后长期）：","用法：奥曲肽 0.1mg 皮下注射 q8h（过渡）；生长抑素类似物长效剂（如兰瑞肽，遵医嘱）〔调 糖尿病患者慎用（影响血糖）；需持续静脉泵入〕","药物4（降门脉压预防再出血）：","用法：普萘洛尔 10mg bid 起（调整至静息心率55～60次/分）或 卡维地洛 6.25mg bid","📌 上消化道出血停止后需根除幽门螺杆菌（溃疡者）并长期随访；肝硬化患者需长期降门脉压治疗。"],"treatment":["上消化道出血：大剂量PPI泵入（72小时）+内镜下止血（24小时内）+补液输血（Hb 70～90g/L），必要时介入栓塞或手术","食管胃底静脉破裂出血：生长抑素/奥曲肽+内镜套扎/硬化+预防性抗生素+必要时三腔二囊管/TIPS/手术","急性胰腺炎/胰瘘/消化道瘘：生长抑素或奥曲肽抑制消化液分泌+营养支持（肠外营养/远端肠内营养）+引流","应激性溃疡预防：高危患者（机械通气、凝血障碍、大手术、休克）使用PPI（静脉或口服）","药物疗程与停药：PPI疗程按病因（溃疡4～8周、出血后静脉72小时）；生长抑素/奥曲肽疗程3～5天（出血）或1～2周（瘘/胰腺炎），逐步减量","监测与调整：出血指标（呕血黑便、血红蛋白、生命体征）、血糖（生长抑素）、电解质与酸碱（长期抑酸）","并发症处理：再出血（内镜/介入/手术）、代谢性碱中毒与低钾（纠正）、血糖波动（调整降糖方案）","宣教：戒酒、避免NSAIDs与刺激食物、规律服药、识别再出血症状（黑便、头晕）及时就诊"],"management":["出血监测：记录呕血与黑便次数、量与颜色，监测生命体征与血红蛋白（每4～6小时），异常立即报告","泵入管理：标识清晰、输液泵控制速度、定时更换药液（生长抑素需现配，溶液24小时内使用）、避免与其他药物混用同一通路","胃管护理：保持通畅、记录引流液性状（血性、咖啡色）、冲洗按医嘱；口腔护理每日2～3次","血糖监测：生长抑素/奥曲肽治疗期间每4～6小时测血糖，异常报告并调整","电解质与酸碱：长期抑酸与胃肠减压患者监测血钾、镁与血气，纠正低钾与碱中毒","宣教：禁食期遵医嘱、恢复期从温凉流质开始、避免粗糙硬食与酒类、按时服药与随访内镜"],"notes":["上消化道出血的标准抑酸方案是PPI负荷量后 8mg/h 持续泵入72小时（维持胃内pH>6利于止血）","生长抑素/奥曲肽停药需逐步减量（突然停药可致反跳性出血）；奥曲肽负荷量需缓慢静推（防心率与血压变化）","生长抑素/奥曲肽可致血糖波动（抑制胰高血糖素与胰岛素），治疗期间需监测血糖","长期抑酸（尤其静脉大剂量）可致低镁血症与代谢性碱中毒，需监测电解质","肝硬化出血患者需预防性使用抗生素（降低感染与再出血风险）"],"emergency":["持续呕血、黑便伴血压下降（出血未控制）→ 加快抑酸泵入+急诊内镜止血，必要时三腔二囊管/介入/手术","生长抑素/奥曲肽泵入期间出现心悸、出汗、意识改变（低血糖）→ 立即测血糖并静推50%葡萄糖","抽搐、心律失常伴低镁低钾（长期抑酸致电解质紊乱）→ 补镁补钾并监测心电图","腹胀加剧伴停止排气排便（胰腺炎/瘘相关肠麻痹）→ 禁食减压+评估病情","内镜治疗后突发剧烈腹痛伴腹膜刺激征（穿孔）→ 急诊影像与外科评估"],"pinyin":"ysyszysswbsy","icd10":"K92.2","physical_exam":["生命体征：血压、心率、呼吸（出血与灌注评估）、体温","一般情况：面色苍白、皮肤湿冷、意识状态（出血量评估）","腹部：腹胀、压痛、肠鸣音、肝脾大小（肝硬化）、腹壁静脉曲张","胃管引流：性状（血性、咖啡色、清亮）、量与气味","皮肤黏膜：黄疸、蜘蛛痣、肝掌（肝硬化）、出血点与瘀斑","直肠指检：黑便或暗红色血便（出血评估）","血糖相关：出汗、手抖、意识改变（低血糖表现）"],"lab_tests":["血常规（动态每4～6小时）：血红蛋白与红细胞压积（出血量与疗效评估）","凝血功能+血小板+血型+交叉配血：出血性疾病与备血","肝功能+白蛋白+胆红素+血氨：肝硬化评估（食管静脉出血者）","电解质（钾、钠、镁、钙）+血气分析：长期抑酸与胃肠减压致低钾与碱中毒监测","血糖（每4～6小时，生长抑素/奥曲肽治疗期间）：血糖波动监测","淀粉酶+脂肪酶+腹部CT：胰腺炎与胰瘘评估","粪便隐血+胃液pH（必要时）：出血与抑酸效果评估"],"nursing":["出血观察与记录：记录呕血与黑便的量、颜色与次数，监测生命体征与血红蛋白，异常立即报告","泵入护理：输液泵控制速度、标识清晰、生长抑素现配现用（24小时内）、避免与其他药物同通路；观察穿刺部位","胃管与口腔护理：保持胃管通畅、记录引流液性状与量，口腔护理每日2～3次（防口腔感染与不适）","血糖监测：生长抑素/奥曲肽治疗期间每4～6小时测血糖，出现出汗、心悸、意识改变立即报告","电解质与酸碱监测：观察低钾（乏力、心律失常）与碱中毒表现，遵医嘱补钾补镁","宣教：出血期禁食、恢复期从温凉流质逐步过渡、避免粗糙硬食与酒类、按时服药、识别再出血症状（黑便、头晕）及时就诊"],"diet":["活动性出血期：严格禁食禁水（必要时胃肠减压）","出血停止24～48小时后：温凉流质（米汤、藕粉、温牛奶），少量多餐","恢复期：半流质→软食，避免粗糙、坚硬、带刺、过热与辛辣食物","溃疡患者：规律进食、少量多餐、避免浓茶咖啡与酒；根除幽门螺杆菌治疗期间按医嘱服药","肝硬化患者：限盐、适量蛋白（肝性脑病期遵医嘱）、忌粗糙硬食（防静脉破裂再出血）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1403},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"50a63aeebfc4218b6bb5359122151f377aa089e07a5232ee099f01dcf435593b","pinyin":"yisuanyushengzhangyisuweibengshiyong","initials":"ysyszyswbsy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","适应证表现：呕血、黑便（消化道出血）、腹痛与腹胀（胰腺炎）、引流液量大（瘘）、反酸与胃灼热（溃疡）\\n抑酸不足表现：持续出血、胃液pH低（<6影响血凝块稳定）、反酸加重\\n生长抑素不良反应：血糖波动（抑制胰高血糖素与胰岛素）、恶心腹痛、注射部位反应、长期（>2周）胆结石风险\\n奥曲肽快速静推致心率与血压变化（应缓慢静推或持续泵入）\\n需警惕：出血未控制（血压下降、血红蛋白下降、呕血黑便持续）",60],["摘要","夜班常用抑酸与抑制消化液分泌的微泵药物：质子泵抑制剂（奥美拉唑/艾司奥美拉唑）用于上消化道出血与应激性溃疡预防；生长抑素/奥曲肽用于食管胃底静脉破裂出血、胰瘘、消化道瘘与急性胰腺炎。",30],["疾病编码","K92.2",30],["原首字母","ysyszysswbsy",60]]},{"id":"orders-77f9ff26a771759448b0","key":"v1-c9ccc21dfe2a3058|orders-77f9ff26a771759448b0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"抗癫痫药物微泵使用","category":"夜班静脉泵药","raw":{"name":"抗癫痫药物微泵使用","category":"夜班静脉泵药","summary":"癫痫持续状态（SE）是神经科急症，需立即静脉负荷抗癫痫药物并维持泵入。常用：地西泮/咪达唑仑（一线止惊）、丙戊酸钠/左乙拉西坦（负荷与维持）、苯巴比妥（二线）。目标：5分钟内终止发作，同时寻找病因（脑卒中、颅内感染、代谢紊乱、停药、中毒）。","symptoms":["全身强直-阵挛发作持续>5分钟或反复发作而意识不恢复（惊厥性SE）","非惊厥性SE：意识模糊、行为异常、轻微抽动（需脑电图诊断）","发作后状态：意识模糊、嗜睡、头痛、肌痛（发作后）","并发症：缺氧、误吸、酸中毒、电解质紊乱、横纹肌溶解（CK升高）、心律失常、颅内压增高","病因线索：抗癫痫药停药/漏服、脑卒中、颅内感染、代谢紊乱（低钠、低钙、低血糖）、酒精戒断、中毒"],"diagnosis":["血糖（立即指尖血糖）：低血糖可致抽搐（立即纠正）","电解质（钠、钙、镁）+肾功能+肝功能+血气分析：代谢性病因与药物代谢评估","抗癫痫药物血药浓度：怀疑停药/中毒（丙戊酸、苯妥英、左乙拉西坦）","头颅CT/MRI（急诊）：脑出血、脑梗死、肿瘤、颅内感染","腰椎穿刺（疑颅内感染，注意颅压与影像排除禁忌）：脑脊液常规、生化、涂片与培养","脑电图（EEG）：非惊厥性SE诊断与疗效评估（必要时持续监测）","肌酸激酶（CK）+肌红蛋白+尿常规：横纹肌溶解与急性肾损伤评估"],"infusion":["⚠️ 抗癫痫药物静推速度必须严格按说明书（过快致呼吸抑制与低血压）！","","方案1（一线止惊，地西泮/咪达唑仑）：","  用法：地西泮 10mg 缓慢静推（速度≤2mg/min，必要时5～10分钟后重复，总量≤20～30mg）；或 咪达唑仑 5～10mg 肌注（无静脉通路）后 0.05～0.2mg/kg/h 泵入维持〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","","方案2（二线负荷，丙戊酸钠）：","  用法：丙戊酸钠 15～40mg/kg 静推 或（NS 100ml 或 5%GS 100ml）静滴（首剂15mg/kg，速度≤3mg/kg/min）后 1～2mg/kg/h 泵入维持（监测肝功能与血药浓度、血小板）〔调 ★ 肝功能不全禁用；★ 育龄女性慎用（致畸）〕","","方案3（二线负荷，左乙拉西坦）：","  用法：左乙拉西坦 60mg/kg（最大4500mg）（NS 100ml 或 5%GS 100ml）静滴（15分钟）后 500～1000mg 静滴 q12h（肾功能不全者减量）〔调 ★ 必须按 CrCl 减量；老年减量〕","","方案4（三线，苯巴比妥/丙泊酚，难治性SE需ICU）：","  用法：苯巴比妥 15～20mg/kg（NS 100ml 或 5%GS 100ml）静滴（速度≤50～100mg/min，监测呼吸与血压）；或 丙泊酚 1～2mg/kg 静推后 2～10mg/kg/h 泵入（需气管插管与机械通气，ICU）","","📌 地西泮静推须缓慢并监测呼吸（呼吸抑制风险）；难治性SE需气管插管+ICU+持续脑电监测；纠正低血糖、低钠、低钙等可逆病因。"],"oral_medication":["⚠️ 发作控制后尽早过渡到口服长期抗癫痫治疗：","药物1（口服长期用药，按发作类型选择）：","用法：左乙拉西坦 500mg bid（广谱，起效快）或 丙戊酸钠缓释片 500mg bid（全面性发作首选）；卡马西平 0.1g bid（局灶性发作，注意皮疹与血象）〔调 ★ 必须按 CrCl 减量；老年减量〕","药物2（病因治疗）：","用法：颅内感染者抗感染；脑卒中者按卒中二级预防；酒精戒断者补充B族维生素（硫胺素 100mg 肌注）；纠正电解质紊乱","药物3（预防并发症）：","用法：硫胺素 100mg 肌注 qd（酒精中毒/营养不良者，防Wernicke脑病）；维生素B1 10mg tid；乳果糖 15ml bid（便秘）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4（对症）：","用法：对乙酰氨基酚 0.5g 必要时（发作后肌痛与发热）；碳酸钙D3 600mg qd（长期抗癫痫药致骨密度下降）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 抗癫痫药不可骤停（可诱发SE）；需监测肝功能、血常规与血药浓度；育龄女性使用丙戊酸需评估致畸风险。"],"treatment":["立即止惊：地西泮 10mg 缓慢静推（一线，速度≤5mg/min，必要时10～15分钟重复）→ 二线负荷（丙戊酸钠 15～40mg/kg 静滴；左乙拉西坦 60mg/kg 静滴 单次）→ 三线（苯巴比妥 15～20mg/kg 静推/丙泊酚，ICU）","气道与呼吸管理：吸氧、头偏一侧防误吸、必要时气管插管（难治性SE或呼吸抑制）；监测血氧与二氧化碳","病因治疗：低血糖（50%葡萄糖 40～60ml 静推）、低钠低钙（纠正电解质）、颅内感染（抗感染）、脑卒中（溶栓/取栓评估）、药物停药（恢复用药）、中毒（解毒剂）","监护与监测：持续心电、血压、血氧监护；必要时持续脑电监测（难治性SE与非惊厥性SE）；监测CK与肾功能（横纹肌溶解）","难治性SE处理：气管插管+机械通气+丙泊酚 1～2mg/kg 静推 继以 2～10mg/kg/h 泵入/咪达唑仑 0.2mg/kg 静推 继以 0.05～2mg/kg/h 泵入（目标脑电爆发抑制），ICU监护，逐步减量（避免突然停药致复发）","并发症防治：误吸性肺炎（抗感染+气道管理）、横纹肌溶解（补液+碱化尿液）、颅内压增高（甘露醇 0.25～1g/kg 静滴）、深静脉血栓（预防）","口服过渡：发作控制24～48小时后逐步加用口服抗癫痫药并重叠静脉用药，缓慢撤除泵入药物","宣教：规律服药不可骤停、避免诱因（睡眠不足、饮酒、闪光刺激）、识别发作先兆与急救处理（保护气道与安全）、随访与血药浓度监测"],"management":["发作观察与记录：记录发作时间、形式、持续时间、意识与生命体征，发作时保护气道与安全（头偏一侧、移除硬物、防坠床与舌咬伤）","用药护理：地西泮严格缓慢静推（≤2mg/min）并监测呼吸；负荷量按体重计算并核对；泵入药物标识清晰、输液泵控制","气道与呼吸监测：吸氧、监测血氧与呼吸频率，观察呼吸抑制（地西泮/苯巴比妥/丙泊酚），床旁备气管插管与吸引装置","生命体征与意识：每15～30分钟（急性期）监测血压、心率、血氧与意识，直至稳定","病因相关监测：血糖（立即与定期）、电解质（钠、钙、镁）、肾功能与CK；观察感染征象与神经系统体征","安全护理：加床档、必要时约束（避免自伤）、避免强光与噪音刺激、保持病室安静；口腔与皮肤护理","宣教：规律服药、不可骤停、避免诱因、发作时家庭急救（保护头部与气道、记录时间、及时呼叫120）、定期复查血药浓度与肝肾功能"],"notes":["癫痫持续状态是急症：5分钟内未能终止发作即应积极用药，同时纠正低血糖与电解质等可逆病因","地西泮静推必须缓慢（≤2mg/min）并监测呼吸（呼吸抑制是最常见不良反应）","抗癫痫药不可骤停（漏服或突然停药是SE最常见诱因）；停药需缓慢减量（数周至数月）","难治性SE需气管插管+ICU+持续脑电监测（丙泊酚/咪达唑仑泵入），死亡率高","发作后需评估横纹肌溶解（CK升高）与误吸性肺炎，并寻找病因（脑卒中、颅内感染、代谢紊乱、中毒）"],"emergency":["发作持续>5分钟或反复发作意识不恢复（癫痫持续状态）→ 立即地西泮 10mg 缓慢静推+二线负荷药物，保护气道与吸氧","发作后呼吸抑制、血氧下降（药物致呼吸抑制）→ 立即吸氧、必要时气管插管与机械通气","抽搐伴低血糖（指尖血糖低）→ 立即静推50%葡萄糖 40～60ml","抽搐伴发热与颈抵抗（颅内感染）→ 抗感染+腰椎穿刺（评估颅压后）","丙泊酚/苯巴比妥泵入中出现低血压（>30%下降）→ 减慢泵速、补液、必要时升压药"],"pinyin":"kdxnywbsy","icd10":"G40.9","physical_exam":["生命体征：血压、心率、呼吸（药物致呼吸抑制）、血氧、体温（感染）","意识与神经系统：GCS、瞳孔、肢体抽动、病理反射、脑膜刺激征","发作形式：全身强直-阵挛、局灶性、非惊厥性（意识模糊+轻微抽动）","气道与口腔：舌咬伤、口腔分泌物、误吸风险、牙齿与口唇损伤","皮肤黏膜：外伤（跌倒）、发绀、皮疹（抗癫痫药过敏）","病因相关：神经系统定位体征（卒中）、感染灶（肺部、颅内）、酒精戒断体征（震颤、肝掌）","发作后状态：意识恢复时间、Todd麻痹（局灶性无力）、肌痛"],"lab_tests":["指尖血糖（立即）：低血糖是抽搐常见可逆病因，须立即检测与纠正","电解质（钠、钙、镁）+肾功能+肝功能+血气分析：代谢性病因与药物代谢评估","抗癫痫药物血药浓度（丙戊酸、苯妥英、左乙拉西坦）：停药、漏服或中毒评估","肌酸激酶（CK）+肌红蛋白+尿常规+肾功能：横纹肌溶解与急性肾损伤监测（每12～24小时）","头颅CT/MRI（急诊）：脑出血、梗死、肿瘤与颅内感染","腰椎穿刺（疑颅内感染，先评估颅压与CT）：脑脊液常规、生化、涂片与培养","脑电图（EEG，含持续监测）：非惊厥性SE诊断与疗效评估"],"nursing":["发作时护理：头偏一侧防误吸、移除周围硬物、加床档、勿强行按压肢体或塞入硬物、记录发作时间与表现","用药护理：地西泮严格缓慢静推（≤2mg/min）并监测呼吸与血压；负荷量按体重核对；泵入药物标识清晰、专人监护","气道与呼吸护理：吸氧、保持气道通畅、及时吸引分泌物；床旁备气管插管与简易呼吸器","生命体征监测：急性期每15～30分钟监测血压、心率、血氧与意识直至稳定","并发症护理：观察误吸（发热、肺部啰音）、横纹肌溶解（尿色深、少尿）、口腔与皮肤损伤；定时翻身防压疮","宣教与随访：规律服药不可骤停、避免诱因（睡眠不足、饮酒、闪光）、家庭急救要点、定期复查血药浓度与肝肾功能"],"diet":["急性期：禁食（防误吸），必要时鼻饲或静脉营养","恢复期：意识清醒、吞咽正常后从流质开始逐步过渡；少量多餐","酒精戒断相关抽搐：补充B族维生素（硫胺素）、高蛋白高维生素饮食、严格戒酒","长期抗癫痫治疗者：均衡饮食、补充钙与维生素D（防骨密度下降）、避免过量酒精（降低发作阈值与药物相互作用）","吞咽障碍者：鼻饲（床头抬高30～45°）防误吸，营养液温度与速度按规范"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1404},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6c1fca015019bae65086296beef317f02641e3668bc41b455ec5139b4eb1d355","pinyin":"kangdianxianyaowuweibengshiyong","initials":"kdxywwbsy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","全身强直-阵挛发作持续>5分钟或反复发作而意识不恢复（惊厥性SE）\\n非惊厥性SE：意识模糊、行为异常、轻微抽动（需脑电图诊断）\\n发作后状态：意识模糊、嗜睡、头痛、肌痛（发作后）\\n并发症：缺氧、误吸、酸中毒、电解质紊乱、横纹肌溶解（CK升高）、心律失常、颅内压增高\\n病因线索：抗癫痫药停药/漏服、脑卒中、颅内感染、代谢紊乱（低钠、低钙、低血糖）、酒精戒断、中毒",60],["摘要","癫痫持续状态（SE）是神经科急症，需立即静脉负荷抗癫痫药物并维持泵入。常用：地西泮/咪达唑仑（一线止惊）、丙戊酸钠/左乙拉西坦（负荷与维持）、苯巴比妥（二线）。目标：5分钟内终止发作，同时寻找病因（脑卒中、颅内感染、代谢紊乱、停药、中毒）。",30],["疾病编码","G40.9",30],["原首字母","kdxnywbsy",60]]},{"id":"orders-a1fafa552c28d64e1e56","key":"v1-c9ccc21dfe2a3058|orders-a1fafa552c28d64e1e56","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性结膜炎（红眼病）","category":"眼科","raw":{"name":"急性结膜炎（红眼病）","category":"眼科","summary":"急性结膜炎是结膜急性炎症，按病因分为细菌性（脓性分泌物、结膜充血）、病毒性（水样分泌物、耳前淋巴结肿大、传染性强）与过敏性（瘙痒、双侧、季节性）。多数预后良好，但需警惕角膜炎、虹膜炎与急性闭角型青光眼（红眼伴视力下降与剧痛为危险信号）。","symptoms":["眼红、异物感、烧灼感、流泪、分泌物增多","细菌性：脓性或黏液脓性分泌物，晨起眼睑粘连","病毒性：水样分泌物、耳前淋巴结肿大与压痛、传染性强（常双眼先后发病）","过敏性：剧烈瘙痒、双侧、结膜水肿（乳头增生）、伴鼻炎或哮喘","危险信号：视力下降、剧烈眼痛、畏光、角膜混浊、前房积脓（提示角膜炎/虹膜炎/青光眼，需急诊）"],"diagnosis":["视力检查（必查）：视力下降提示角膜或眼内病变（非单纯结膜炎）","裂隙灯检查：结膜充血类型（弥漫/睫状充血）、分泌物性状、角膜有无浸润或溃疡、前房与瞳孔","分泌物涂片与培养（脓性/重症/反复）：细菌性结膜炎病原学","角膜荧光素染色：排除角膜上皮缺损与溃疡（疑角膜炎时必查）","眼压测量：排除急性闭角型青光眼（眼痛+视力下降者必查）","耳前淋巴结检查：病毒性结膜炎常见肿大压痛","过敏原检测（必要时）：过敏性结膜炎"],"infusion":["⚠️ 结膜炎以局部用药为主，全身用药仅用于重症或特殊病原体！","","方案1（重症细菌性结膜炎/淋菌性，全身抗感染）：","  用法：头孢曲松 1g（NS 100ml 或 5%GS 100ml）静滴 qd（淋菌性结膜炎，疗程3～5天）或 阿奇霉素 0.5g 静滴 qd（沙眼衣原体）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案2（支持与对症）：","  用法：0.9%氯化钠 静滴（必要时补液）；对乙酰氨基酚 0.5g 静滴 必要时（疼痛）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","方案3（过敏性结膜炎重症，糖皮质激素）：","  用法：地塞米松 5mg 静推（严重过敏反应，短期）；0.9%氯化钠 静滴〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案4（合并全身感染）：","  用法：左氧氟沙星滴眼液 1滴 滴眼 每2小时1次（清醒时）；0.9%NS 冲洗结膜囊 每日3次；合并全身感染时头孢曲松 1g + 0.9%NS 100ml 静滴 每日1次；对乙酰氨基酚 0.5g 口服（发热时）","","📌 单纯结膜炎一般不需静脉用药；淋菌性结膜炎需全身抗生素（可致角膜穿孔）；新生儿结膜炎需按病原学治疗（淋菌/衣原体）。"],"oral_medication":["⚠️ 局部滴眼液为主，全身口服为辅：","药物1（细菌性，局部抗生素滴眼液）：","用法：左氧氟沙星滴眼液 1滴 q2h（首日）后 qid；或 妥布霉素滴眼液 qid；睡前用氧氟沙星眼膏〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（病毒性）：","用法：更昔洛韦滴眼液 qid（疱疹性）；病毒性结膜炎以对症为主（人工泪液 1滴 qid），不用抗生素","药物3（过敏性）：","用法：奥洛他定滴眼液 bid 或 依美斯汀滴眼液 qid；严重者 氟米龙滴眼液 qid（短期，监测眼压）；口服 氯雷他定 10mg qd / 西替利嗪 10mg qn〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物4（全身抗感染，重症）：","用法：阿莫西林克拉维酸 0.625g tid（3～5天）或 阿奇霉素 0.5g qd×3天（衣原体）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","📌 过敏性结膜炎避免长期使用糖皮质激素滴眼液（致青光眼与白内障）；病毒性结膜炎禁用糖皮质激素（可加重疱疹感染）。"],"treatment":["局部治疗：抗生素滴眼液（细菌性）、抗病毒滴眼液（疱疹性）、抗过敏滴眼液（过敏性）、人工泪液（对症）","眼部清洁：生理盐水冲洗结膜囊（清除分泌物）、冷敷（减轻充血与不适）","传染控制（病毒性/细菌性）：勤洗手、不共用毛巾与枕具、患者隔离（幼儿园/学校）、避免揉眼","禁忌与注意：急性期禁包扎患眼（分泌物积聚加重感染）、禁戴隐形眼镜、避免使用糖皮质激素（除非专科指导）","重症处理：淋菌性结膜炎需全身抗生素+频繁冲洗+密切观察角膜（可穿孔）；新生儿结膜炎按病原学治疗并排查母亲感染","并发症处理：角膜炎（抗感染+角膜保护）、虹膜炎（散瞳+激素）、眼压升高（降眼压）","随访：48～72小时复诊评估疗效，症状加重或视力下降立即就诊","宣教：正确滴眼药方法（洗手、下拉下睑、勿触及眼球、按压泪囊区）、足疗程用药、避免自行停药"],"management":["眼部护理：滴眼药前洗手、按医嘱频次用药、不同滴眼液间隔5～10分钟、眼膏睡前使用（视物模糊属正常）","分泌物护理：生理盐水棉签由内眦向外眦清洁，避免污染健眼；毛巾与脸盆专用并消毒","隔离与消毒：病毒性结膜炎传染性强（腺病毒），实施接触隔离、专用物品、医护人员手卫生","疼痛与不适护理：冷敷（每次10～15分钟）、避免强光刺激、减少用眼（休息与减少屏幕时间）","视力监测：每日评估视力与症状（视力下降、剧痛、畏光加重提示角膜炎/青光眼，立即报告）","宣教：不揉眼、不共用物品、按时滴药、足疗程、避免佩戴隐形眼镜与眼部化妆、家庭成员防护"],"notes":["红眼患者出现视力下降、剧烈眼痛或畏光提示非单纯结膜炎（角膜炎、虹膜炎或急性闭角型青光眼），需急诊眼科评估","病毒性结膜炎传染性强（腺病毒），需接触隔离与专用物品，避免交叉感染","急性期禁包扎患眼；过敏性结膜炎避免长期使用糖皮质激素滴眼液（青光眼与白内障风险）","淋菌性结膜炎可致角膜穿孔，需全身抗生素+频繁冲洗+密切观察","正确滴眼药方法（勿触及眼球、按压泪囊区）可减少污染与全身吸收"],"emergency":["剧烈眼痛、视力急剧下降伴头痛呕吐（急性闭角型青光眼）→ 立即测眼压并急诊降眼压","角膜混浊、溃疡或前房积脓（角膜炎/眼内炎）→ 急诊眼科评估与强化抗感染","淋菌性结膜炎伴角膜浸润（角膜穿孔风险）→ 立即全身抗生素+频繁冲洗+眼科急会诊","新生儿眼部分泌物增多（淋菌/衣原体结膜炎）→ 立即病原学检查与全身抗生素治疗","眼部外伤后眼红眼痛（异物/穿孔）→ 急诊眼科检查（禁自行冲洗与按压）"],"pinyin":"jxjmyhyb","icd10":"H10.9","physical_exam":["视力：裸眼与矫正视力（必查，视力下降提示角膜或眼内病变）","眼部外观：眼睑肿胀、结膜充血类型（弥漫性/睫状充血）、结膜下出血、分泌物性状","裂隙灯：角膜透明度与浸润、前房深度与积脓、瞳孔大小与对光反射、虹膜","耳前淋巴结：肿大与压痛（病毒性结膜炎）","眼压：指测或眼压计（眼痛与视力下降者必查）","角膜荧光素染色：角膜上皮缺损与溃疡","对侧眼与全身：双眼对比、有无鼻炎/哮喘/皮肤湿疹（过敏）、发热与上感症状（病毒）"],"lab_tests":["视力与裂隙灯检查（必查）：区分结膜炎与角膜炎/虹膜炎/青光眼","分泌物涂片+细菌培养及药敏：脓性分泌物、重症或治疗无效者","角膜荧光素染色：角膜上皮缺损与溃疡评估（疑角膜炎）","眼压测量：眼痛与视力下降者排除急性闭角型青光眼","病毒抗原/PCR（腺病毒、疱疹病毒）：流行性角结膜炎与疱疹性结膜炎诊断","过敏原检测（IgE、皮肤点刺）：反复过敏性结膜炎","新生儿结膜炎：结膜分泌物涂片与培养（淋菌、衣原体）+母亲生殖道感染筛查"],"nursing":["眼部用药护理：滴眼液按频次按时给予、不同药物间隔5～10分钟、眼膏睡前用；指导患者正确滴药（勿触及眼球、按压泪囊区）","分泌物清洁：生理盐水棉签由内眦向外眦清洁，物品专用，操作前后洗手","隔离与消毒：病毒性结膜炎实施接触隔离，患者毛巾、脸盆、枕具专用并消毒，医护手卫生","症状护理：冷敷减轻充血与不适（每次10～15分钟）、避免强光与长时间用眼、保证休息","病情观察：每日评估视力、眼痛、畏光与分泌物变化，视力下降或剧痛立即报告（角膜炎/青光眼预警）","宣教：不揉眼、不共用物品、按时足疗程用药、避免戴隐形眼镜与眼部化妆、家庭成员防护（勤洗手、分巾）"],"diet":["清淡易消化饮食，多饮水，多食新鲜蔬菜水果（维生素A、C促进眼部组织修复）","富含维生素A食物：胡萝卜、动物肝脏、蛋黄、深绿色蔬菜（维护角膜与结膜健康）","过敏性结膜炎：避免已知过敏食物（海鲜、坚果等）与刺激性食物","避免辛辣刺激、酒类与过量咖啡因（加重充血）","戒烟（烟雾刺激眼部）；保持大便通畅（避免用力致眼压升高）"],"topical_medication":["左氧氟沙星滴眼液 1滴 滴眼 qid；更昔洛韦滴眼液 1滴 滴眼 qid；盐酸奥洛他定滴眼液 1滴 滴眼 bid"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1405},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"12700942bc06d309bb352a6d942224b28329c6432237353019ae1ea67ee1fd1a","pinyin":"jixingjiemoyan（hongyanbing）","initials":"jxjmy（hyb）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","眼红、异物感、烧灼感、流泪、分泌物增多\\n细菌性：脓性或黏液脓性分泌物，晨起眼睑粘连\\n病毒性：水样分泌物、耳前淋巴结肿大与压痛、传染性强（常双眼先后发病）\\n过敏性：剧烈瘙痒、双侧、结膜水肿（乳头增生）、伴鼻炎或哮喘\\n危险信号：视力下降、剧烈眼痛、畏光、角膜混浊、前房积脓（提示角膜炎/虹膜炎/青光眼，需急诊）",60],["摘要","急性结膜炎是结膜急性炎症，按病因分为细菌性（脓性分泌物、结膜充血）、病毒性（水样分泌物、耳前淋巴结肿大、传染性强）与过敏性（瘙痒、双侧、季节性）。多数预后良好，但需警惕角膜炎、虹膜炎与急性闭角型青光眼（红眼伴视力下降与剧痛为危险信号）。",30],["疾病编码","H10.9",30],["原首字母","jxjmyhyb",60]]},{"id":"orders-48b7ed5df21cad56d58b","key":"v1-c9ccc21dfe2a3058|orders-48b7ed5df21cad56d58b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"急性闭角型青光眼发作","category":"眼科","raw":{"name":"急性闭角型青光眼发作","category":"眼科","summary":"急性闭角型青光眼发作是房角突然关闭致眼压急剧升高（常>40mmHg）的眼科急症，多见于中老年女性（远视眼、浅前房、晶状体增厚）。表现为剧烈眼痛伴头痛、恶心呕吐、视力骤降与虹视，需立即降眼压并尽快手术（周边虹膜切除/激光），延误可致永久失明。","symptoms":["突发剧烈眼痛（可放射至同侧头部）、头痛、恶心、呕吐（易误诊为偏头痛或急腹症）","视力急剧下降、虹视（看灯光有彩色光圈）、雾视","畏光、流泪、眼睑痉挛","眼压显著升高（常>40mmHg，指测眼硬如石）","诱因：暗环境、情绪激动、长时间阅读、散瞳药或抗胆碱药使用"],"diagnosis":["眼压测量（必查）：显著升高（常>40mmHg，可达60～80mmHg）","裂隙灯检查：角膜上皮水肿（雾状混浊）、前房极浅、瞳孔中度散大且固定、虹膜节段性萎缩","房角镜检查（角膜水肿消退后）：房角关闭（诊断关键）","视力与视野：视力骤降、视野缺损","对侧眼检查：浅前房、房角窄（预防性治疗依据）","眼底检查（眼压控制后）：视盘与视神经损害评估","鉴别诊断：急性虹膜睫状体炎（瞳孔缩小、眼压正常/低）、急性结膜炎（无眼压升高）"],"infusion":["⚠️ 眼科急症，降眼压需立即且多药联合，同时尽快手术！","方案1（快速降眼压，高渗脱水剂）：","用法：20%甘露醇 250ml 静滴（30分钟内快速滴完，监测尿量、肾功能与电解质）；或 甘油果糖 250ml 静滴（心肾功能不全者）〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","方案2（碳酸酐酶抑制剂，减少房水生成）：","用法：乙酰唑胺 500mg 静推（或口服 250mg q6h）；注意低钾、手足麻木与磺胺过敏","方案3（缩瞳与睫状肌麻痹剂，局部）：","用法：1%～2%毛果芸香碱滴眼液 1滴 q5min×3次后 q1h（开放房角，注意点药后按压泪囊区）；角膜水肿严重者先降眼压后使用","方案4（对症与止吐）：","用法：0.9%氯化钠 静滴；甲氧氯普胺 10mg 静推（呕吐）；镇痛（对乙酰氨基酚 0.5g 或 曲马多）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 降眼压后需尽快行激光周边虹膜切开（急性发作眼与对侧眼均需）或小梁切除手术；禁用散瞳药与抗胆碱药（阿托品、部分感冒药与解痉药）。"],"oral_medication":["⚠️ 急性期以静脉+局部用药为主，稳定后口服维持：","药物1（碳酸酐酶抑制剂）：","用法：乙酰唑胺片 250mg q6h（短期使用，监测血钾与肾功能；磺胺过敏者禁用）","药物2（局部降眼压滴眼液，急性期后）：","用法：噻吗洛尔滴眼液 bid（β受体阻滞剂，哮喘与心动过缓者禁用）；布林佐胺滴眼液 bid（碳酸酐酶抑制剂）；拉坦前列素滴眼液 qn（前列腺素类）","药物3（缩瞳）：","用法：毛果芸香碱滴眼液 qid（急性发作后维持，按医嘱）","药物4（对症）：","用法：对乙酰氨基酚 0.5g 必要时（疼痛）；乳果糖 15ml bid（乙酰唑胺致便秘不明显但可辅助）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 反复发作者需评估手术治疗；禁用散瞳药、抗胆碱药（阿托品、东莨菪碱、部分抗组胺药与抗抑郁药）。"],"treatment":["急性发作期紧急降眼压：高渗脱水剂（甘露醇 1～1.5g/kg 静滴 30分钟内）+碳酸酐酶抑制剂（乙酰唑胺 500mg 静推 后 250mg 口服 q6h）+局部缩瞳药（毛果芸香碱 2% 滴眼 q15min×2h）+β受体阻滞剂滴眼液（噻吗洛尔 0.5% 滴眼 bid），多药联合快速降眼压","激光治疗：周边虹膜切开术（LPI）——急性发作控制后尽快施行（发作眼与对侧眼均需），解除瞳孔阻滞","手术治疗：激光后房角仍关闭或眼压仍高者行小梁切除术（±抗代谢药）；白内障明显者可行白内障摘除+房角分离","对侧眼处理：浅前房、房角窄者行预防性激光周边虹膜切开（防发作）","降眼压监测：每30～60分钟测眼压直至下降，角膜水肿消退后行房角镜检查","并发症处理：视神经损害（长期降眼压与神经保护）、虹膜萎缩、白内障（后期手术）","宣教：避免诱因（暗环境、情绪激动、长时间低头）、禁用散瞳与抗胆碱药、规律随访（每3～6个月复查眼压与视野）","随访：术后1周、1个月、3个月复查（眼压、房角、视野与视盘）"],"management":["眼压监测：每30～60分钟测眼压直至明显下降，记录并报告医师；避免暗环境（可加重房角关闭）","用药护理：甘露醇快速静滴（30分钟内）并观察尿量与电解质；乙酰唑胺观察手足麻木与低钾；毛果芸香碱滴眼后按压泪囊区（减少全身吸收）","疼痛与呕吐护理：评估疼痛评分并镇痛；呕吐者补液与止吐，记录出入量","安全护理：视力骤降与头痛致跌倒风险（加床档、协助活动）、保持环境光线充足（避免暗室）","术前准备：禁食禁水、术前滴眼药、心理安慰与手术宣教（激光/小梁切除）","宣教：识别发作先兆（虹视、雾视、眼胀）立即就诊、避免诱因与禁用药物、按时复查、坚持用药（不可自行停用降眼压药）"],"notes":["急性闭角型青光眼发作是眼科急症：眼压急剧升高可在数小时内造成不可逆视神经损害，须立即降眼压","剧烈眼痛伴头痛、恶心呕吐易误诊为偏头痛、急性胃肠炎或急腹症——须常规测眼压","禁用散瞳药与抗胆碱药（阿托品、部分抗过敏药与解痉药）；避免暗环境与情绪激动（诱发因素）","急性发作控制后应尽快行激光周边虹膜切开（发作眼与对侧眼），否则易复发","乙酰唑胺可致低钾、手足麻木与肾结石（长期使用需监测）；磺胺过敏者禁用"],"emergency":["剧烈眼痛伴头痛呕吐与视力骤降、眼压>40mmHg（急性发作）→ 立即甘露醇+乙酰唑胺+缩瞳药降眼压，眼科急会诊","降眼压无效或眼压>60mmHg → 紧急前房穿刺或手术减压","对侧眼出现虹视、雾视与眼胀（先兆发作）→ 立即眼科评估并行激光治疗","用药后出现手足麻木、肌无力与心律失常（乙酰唑胺致低钾）→ 补钾并监测心电图"],"pinyin":"jxbjxqgyfz","icd10":"H40.2","physical_exam":["视力：裸眼视力（骤降）与光感","眼压：指测（硬如石）与眼压计测量（常>40mmHg）","裂隙灯：角膜上皮水肿、前房浅、瞳孔中度散大固定、虹膜节段萎缩","结膜：睫状充血或混合充血","房角镜（角膜水肿消退后）：房角关闭","对侧眼：前房深度与房角宽窄（浅前房与窄房角）","眼底（眼压控制后）：视盘杯盘比与视神经损害"],"lab_tests":["眼压测量（每30～60分钟）：疗效监测的核心指标","裂隙灯与房角镜检查：诊断与房角关闭评估（角膜水肿消退后）","视力与视野检查：功能损害（急性期后）","电解质（钾）+肾功能：甘露醇与乙酰唑胺治疗监测（每6～12小时）","血糖+尿常规：糖尿病与肾功能评估（高渗脱水剂与碳酸酐酶抑制剂使用前）","眼底与OCT（视神经纤维层）：视神经损害评估（急性期后）","超声生物显微镜（UBM，必要时）：房角与睫状体评估（角膜水肿无法行房角镜时）"],"nursing":["降眼压用药护理：甘露醇30分钟内快速静滴并记录尿量与电解质；乙酰唑胺观察手足麻木与低钾；缩瞳药滴眼后按压泪囊区","眼压与症状监测：每30～60分钟测眼压并记录，观察眼痛、头痛与呕吐变化，异常立即报告","环境与安全：保持病室光线充足（避免暗环境）、协助活动防跌倒（视力骤降）、加床档","疼痛护理：评估疼痛评分并遵医嘱镇痛，呕吐者补液与止吐","术前护理：禁食禁水、术前滴眼药、心理安慰（解释激光/手术必要性）","宣教：避免诱因（暗光、情绪激动、长时间低头）、禁用散瞳与抗胆碱药物、按时复查眼压与视野、坚持用药"],"diet":["急性期：清淡流质（避免呕吐加重）、适量饮水（避免短时间大量饮水致眼压升高，一次饮水<300ml）","避免咖啡因与大量液体快速摄入（可升高眼压）","高纤维饮食保持大便通畅（避免用力排便致眼压升高），必要时缓泻剂","长期：均衡饮食、控制血压与血糖；避免饮酒与辛辣刺激","合并糖尿病者控制血糖（糖尿病与青光眼相互影响）"],"topical_medication":["毛果芸香碱滴眼液 1滴 滴眼 qid；噻吗洛尔滴眼液 1滴 滴眼 bid；布林佐胺滴眼液 1滴 滴眼 bid"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1406},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8494f5971360e1826b605a707767eae3f73be7067eab806f124c7f5716146382","pinyin":"jixingbijiaoxingqingguangyanfazuo","initials":"jxbjxqgyfz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","突发剧烈眼痛（可放射至同侧头部）、头痛、恶心、呕吐（易误诊为偏头痛或急腹症）\\n视力急剧下降、虹视（看灯光有彩色光圈）、雾视\\n畏光、流泪、眼睑痉挛\\n眼压显著升高（常>40mmHg，指测眼硬如石）\\n诱因：暗环境、情绪激动、长时间阅读、散瞳药或抗胆碱药使用",60],["摘要","急性闭角型青光眼发作是房角突然关闭致眼压急剧升高（常>40mmHg）的眼科急症，多见于中老年女性（远视眼、浅前房、晶状体增厚）。表现为剧烈眼痛伴头痛、恶心呕吐、视力骤降与虹视，需立即降眼压并尽快手术（周边虹膜切除/激光），延误可致永久失明。",30],["疾病编码","H40.2",30],["原首字母","jxbjxqgyfz",60]]},{"id":"orders-5a28377d56a4119a94ee","key":"v1-c9ccc21dfe2a3058|orders-5a28377d56a4119a94ee","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"白内障（手术与围手术期）","category":"眼科","raw":{"name":"白内障（手术与围手术期）","category":"眼科","summary":"白内障是晶状体混浊致视力下降的最常见眼病，以年龄相关性最常见。表现为无痛性渐进性视力下降、眩光、单眼复视与屈光改变。手术（超声乳化+人工晶体植入）是唯一有效治疗；术后重点为感染预防（眼内炎）、眼压监测与视力康复。","symptoms":["无痛性渐进性视力下降（数月到数年），夜间与暗处更明显","眩光与畏光（尤其夜间遇车灯）、对比敏感度下降","单眼复视、视物变形、屈光度数变化（近视化）","晶状体核性混浊（棕黄色）、后囊下混浊（强光下视力更差）","晚期：仅存光感或手动视力（成熟期/过熟期）"],"diagnosis":["视力与屈光检查：裸眼与矫正视力、屈光度","裂隙灯检查：晶状体混浊部位与程度（核性/皮质性/后囊下）","散瞳后眼底检查（评估眼底病变）+眼压测量","眼部B超（晶状体混浊致眼底不可见时）：排除玻璃体与视网膜病变","角膜内皮计数+眼轴测量+角膜曲率（人工晶体度数计算，术前必查）","全身评估：血压、血糖（糖尿病患者控制后手术）、心肺功能、凝血功能","合并症评估：青光眼、黄斑病变、糖尿病视网膜病变（影响术后视力预后）"],"infusion":["⚠️ 白内障手术以局部麻醉为主，静脉用药仅用于特殊情况！","","方案1（术前预防性抗感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（术前0.5～1小时，单次）；青霉素过敏者 克林霉素 0.6g 或 万古霉素 1g〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（术后抗感染，复杂/高危病例）：","  用法：头孢呋辛 1.5g 静滴 q8h（24小时，按医嘱）；或 左氧氟沙星 0.5g 静滴 qd〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","","方案3（术前镇静与镇痛，按需）：","  用法：咪达唑仑 1～2mg 静推（焦虑者，需监护）；0.9%氯化钠 静滴维持静脉通路","","方案4（术后高眼压/疼痛）：","  用法：20%甘露醇 125ml 静滴（眼压增高者）；对乙酰氨基酚 0.5g 静滴 必要时（疼痛）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","📌 术前抗菌药物用于预防眼内炎（最严重并发症）；糖尿病患者围手术期需控制血糖（高血糖增加感染与出血风险）。"],"oral_medication":["⚠️ 以局部滴眼液为主，口服为辅：","药物1（术后抗感染滴眼）","用法：左氧氟沙星滴眼液 1滴 qid（1～2周）；或 妥布霉素滴眼液 qid〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（术后抗炎滴眼）","用法：氟米龙滴眼液 1滴 qid（逐渐减量至停用，监测眼压）；或 妥布霉素地塞米松滴眼液 qid（短期）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","药物3（散瞳/睫状肌麻痹，术后按需）：","用法：复方托吡卡胺滴眼液 1滴 qn（防虹膜粘连，遵医嘱）","药物4（口服，合并症）：","用法：对乙酰氨基酚 0.5g 必要时（疼痛）；糖尿病患者按原降糖方案（术前术后血糖管理）；乙酰唑胺 250mg q6h（眼压增高者，短期）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 术后滴眼药须严格按医嘱（不可自行停药），并注意滴药前洗手与瓶口勿接触眼部（防眼内炎）。"],"treatment":["手术治疗（唯一有效）：超声乳化白内障吸除+人工晶体（IOL）植入术（主流术式）；硬核或特殊情况可行囊外摘除","术前准备：完善眼部测量（眼轴、角膜曲率、IOL度数计算）、控制血压与血糖、停用抗凝药（按专科意见）、术前抗生素滴眼","术后管理：抗生素+激素滴眼液（逐渐减量）、眼压监测、避免揉眼与用力、戴眼罩保护","并发症处理：眼内炎（急诊玻璃体腔注药+玻璃体切除，最严重）、眼压升高（降眼压药）、后囊混浊（YAG激光后囊切开）、视网膜脱离（急诊手术）、角膜内皮失代偿（角膜移植）","术后视力康复：术后1天、1周、1个月复查；屈光结果评估与配镜；后发障行激光治疗","合并症处理：糖尿病视网膜病变（术前评估与治疗）、青光眼（联合手术或分期）、黄斑病变（术后视力受限原因）","宣教：术后避免剧烈运动、低头、用力排便与揉眼；按时滴药与复查；出现眼痛、视力下降、眼红加重立即就诊（眼内炎预警）","双侧手术：一般双眼分开手术（间隔数周），避免双眼同时感染风险"],"management":["术前护理：术前3天抗生素滴眼（按医嘱）、术前散瞳（按术式）、禁食禁水（按麻醉要求）、血糖与血压控制、心理安慰","术后护理：术眼戴眼罩（防碰撞与揉眼）、避免剧烈活动与低头、避免用力咳嗽与排便（防眼压升高与出血）","滴眼药护理：按时给予抗生素与激素滴眼液（间隔5分钟）、指导正确滴药方法、观察药物不良反应（激素致眼压升高）","眼压与症状观察：观察术眼疼痛、眼红、视力变化与恶心呕吐（眼压升高），异常立即报告","并发症预警：视力突然下降、剧烈眼痛、前房积脓、眼红加重（眼内炎，术后1周内高危）→ 立即急诊处理","宣教：按时复查（术后1天、1周、1个月）、继续滴药不可自行停、避免揉眼与外伤、避免污水入眼（1～2周）","长期随访：术后3个月验光配镜、后发障（术后数月至数年）出现视力下降需激光治疗"],"notes":["白内障是致盲首位原因，手术是唯一有效治疗（药物无法逆转晶状体混浊）","眼内炎是最严重并发症（发生率约0.05%～0.1%）：术后眼痛加重、视力下降、前房积脓须立即处理","糖尿病患者围手术期需控制血糖（高血糖增加感染、出血与黄斑水肿风险）","术前需停用抗凝/抗血小板药物（按专科与麻醉意见，权衡血栓风险）","术后激素滴眼液需按医嘱逐渐减量并监测眼压（长期使用可致激素性青光眼）"],"emergency":["术后剧烈眼痛、视力急剧下降、前房积脓（眼内炎）→ 立即玻璃体腔注药+急诊玻璃体切除，眼科急会诊","术后突发视野缺损或闪光感伴眼前黑影（视网膜脱离）→ 急诊眼底检查与手术","术后眼压显著升高伴眼痛呕吐（继发性青光眼）→ 立即降眼压处理","术眼受外伤后疼痛、视力下降与眼内结构异常（伤口裂开/晶体脱位）→ 急诊眼科处理","术后持续眼红眼痛伴角膜水肿（角膜内皮失代偿）→ 急诊评估与治疗"],"pinyin":"bnzssywssq","icd10":"H25.9","physical_exam":["视力：裸眼与矫正视力、光感与光定位（术前评估）","裂隙灯：晶状体混浊类型与程度（核性/皮质性/后囊下）、角膜透明度、前房深度","眼压：术前必查（合并青光眼评估）","散瞳眼底：黄斑、视盘与视网膜（术后视力预后评估）","眼部B超：晶状体混浊致眼底不可见时（排除视网膜脱离与玻璃体积血）","对侧眼：白内障程度与眼底（双侧评估）","全身：血压、血糖（糖尿病患者）、心肺与凝血功能（手术耐受性）"],"lab_tests":["视力+屈光+裂隙灯+眼压（必查）：诊断与术前评估","角膜内皮计数+眼轴长度+角膜曲率：人工晶体度数计算（术前必查）","眼部B超（必要时）：眼底不可见时的视网膜与玻璃体评估","血糖+糖化血红蛋白：糖尿病患者术前控糖（目标空腹<8mmol/L，餐后<10mmol/L）","凝血功能+血常规+心电图：术前常规评估（抗凝药使用者需专科评估）","血压监测：高血压患者术前控制（<140/90mmHg）","术后视力与眼压复查：术后1天、1周、1个月（评估手术效果与并发症）"],"nursing":["术前护理：按医嘱术前抗生素滴眼、散瞳、禁食禁水；控制血压与血糖；心理安慰（减轻对手术的恐惧）","术后体位与保护：术眼戴眼罩（防碰撞与揉眼）、避免剧烈活动与低头、睡觉时避免压术眼","滴眼药护理：按时给予抗生素与激素滴眼液、不同药物间隔5分钟、指导正确滴药（洗手、瓶口勿触眼、按压泪囊区）","症状观察：观察眼痛、眼红、视力与恶心呕吐（眼压升高），异常立即报告","眼内炎预警：术后1周内出现视力下降、眼痛加重或前房积脓立即报告医师（急症）","宣教：按时复查（1天/1周/1个月）、坚持滴药不可自行停、避免揉眼与污水入眼、避免用力与外伤、出现异常立即就诊"],"diet":["术前：清淡易消化饮食，按麻醉要求禁食禁水；糖尿病患者按糖尿病饮食控糖","术后：高蛋白、高维生素饮食促进愈合（鱼、瘦肉、蛋、蔬果）","多饮水、多食粗纤维食物，保持大便通畅（避免用力排便致眼压升高）","避免辛辣刺激、酒类与过量咖啡因；戒烟","控制血压与血糖（合并症管理影响手术安全与恢复）"],"topical_medication":["左氧氟沙星滴眼液 1滴 滴眼 qid；普拉洛芬滴眼液 1滴 滴眼 qid；玻璃酸钠滴眼液 1滴 滴眼 qid"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1407},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"53b2c01fb1e056daac7e418c1c425cf3ef6367b5eb7e973e09a585a67cca4f16","pinyin":"baineizhang（shoushuyuweishoushuqi）","initials":"bnz（ssywssq）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","无痛性渐进性视力下降（数月到数年），夜间与暗处更明显\\n眩光与畏光（尤其夜间遇车灯）、对比敏感度下降\\n单眼复视、视物变形、屈光度数变化（近视化）\\n晶状体核性混浊（棕黄色）、后囊下混浊（强光下视力更差）\\n晚期：仅存光感或手动视力（成熟期/过熟期）",60],["摘要","白内障是晶状体混浊致视力下降的最常见眼病，以年龄相关性最常见。表现为无痛性渐进性视力下降、眩光、单眼复视与屈光改变。手术（超声乳化+人工晶体植入）是唯一有效治疗；术后重点为感染预防（眼内炎）、眼压监测与视力康复。",30],["疾病编码","H25.9",30],["原首字母","bnzssywssq",60]]},{"id":"orders-fac068a1457fe7921f91","key":"v1-c9ccc21dfe2a3058|orders-fac068a1457fe7921f91","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"眼外伤（急诊处理）","category":"眼科","raw":{"name":"眼外伤（急诊处理）","category":"眼科","summary":"眼外伤包括机械性（角膜擦伤、眼球穿通伤、球内异物、钝挫伤）、化学性（酸碱烧伤）与热/辐射伤。化学伤需立即大量冲洗（现场急救最关键）；开放性眼外伤需保护眼球、禁冲洗与按压、禁自行取异物，尽快手术。眼外伤是单眼致盲的重要原因，及时正确处理决定预后。","symptoms":["眼痛、流泪、畏光、眼睑痉挛、视力下降","化学伤：眼部剧烈疼痛、眼睑与结膜充血水肿、角膜混浊（碱烧伤可进行性加重）","穿通伤：眼内容物脱出（虹膜、玻璃体）、前房变浅、瞳孔变形、低眼压，可见伤口","钝挫伤：眼睑淤血肿胀、结膜下出血、前房积血、瞳孔散大、晶状体脱位与视网膜震荡","球内异物：细小伤口伴视力下降、眼压异常（金属异物可致铁锈症）"],"diagnosis":["视力（必查，记录双眼）：评估损伤程度与预后","裂隙灯检查（勿压迫眼球）：角膜裂伤与异物、前房积血与深度、虹膜与晶状体情况","荧光素染色：角膜上皮缺损与裂伤","眼压测量（开放伤禁测或轻柔）：低眼压提示穿通伤，高眼压提示前房积血继发青光眼","眼眶与眼球CT（首选，含薄层）：球内异物（金属高密度）、眼眶骨折与球后血肿；MRI禁用于金属异物","眼部B超（闭合伤）：玻璃体积血与视网膜脱离；开放伤慎用","化学伤：结膜囊pH测定（试纸，正常7.0～7.4）与受伤时间、化学品种类","全身评估：是否合并颅脑与颌面部外伤（多发伤优先处理）"],"infusion":["⚠️ 化学伤立即冲洗是第一要务；全身用药用于抗感染与对症！","","方案1（抗感染，开放伤/球内异物/化学伤）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（或头孢曲松 2g 静滴 qd）；球内异物或污染重者 万古霉素 1g 静滴 q12h + 头孢他啶 2g 静滴 q8h（抗感染强化）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（化学伤，抗炎与胶原酶抑制）：","  用法：维生素C 2g（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（碱烧伤抗氧化）；四环素 0.5g 静滴 q12h（抑制胶原酶，碱烧伤）；必要时激素（地塞米松 10mg 静推，早期短期，须权衡感染风险）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（镇痛与支持）：","  用法：对乙酰氨基酚 0.5g 静滴 必要时；曲马多 100mg 静滴（剧痛）；0.9%氯化钠 静滴；破伤风抗毒素 1500IU 皮下注射（污染伤口）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","方案4（降眼压，前房积血/继发青光眼）：","  用法：20%甘露醇 125～250ml 静滴（眼压增高者）；乙酰唑胺 500mg 静推〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","📌 化学伤立即用大量生理盐水或清水冲洗（至少30分钟，翻转眼睑冲洗穹窿部）；开放伤禁冲洗、禁按压、禁自行取异物，用眼罩保护后急诊手术。"],"oral_medication":["⚠️ 局部用药为主，全身口服为辅：","药物1（抗生素滴眼液）：","用法：左氧氟沙星滴眼液 1滴 q1～2h（重症）后减量；氧氟沙星眼膏 睡前（保护创面）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（散瞳/睫状肌麻痹，防虹膜粘连）：","用法：复方托吡卡胺滴眼液 1～2滴 tid（前房积血与虹膜炎）；阿托品眼膏 qn（按医嘱）","药物3（抗炎滴眼，角膜上皮修复后）：","用法：氟米龙滴眼液 qid（短期，监测眼压）；人工泪液（qid 促进上皮修复）","药物4（口服）：","用法：对乙酰氨基酚 0.5g 必要时（镇痛）；氨甲环酸 0.5g tid（前房积血，遵医嘱）；碳酸钙D3（长期激素者）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 前房积血者禁阿司匹林与NSAIDs（加重出血）；角膜上皮缺损者禁忌激素滴眼（延缓愈合与感染风险）。"],"treatment":["化学伤：立即大量冲洗（生理盐水/清水至少30分钟，翻转眼睑冲洗穹窿）→ 评估pH并再次冲洗至中性 → 清除颗粒物 → 抗感染（左氧氟沙星滴眼液 q2h）+抗炎（泼尼松龙滴眼液 q1～2h）+维生素C（抗坏血酸 1～2g 口服 qd，碱烧伤）+胶原酶抑制剂（四环素 250mg 口服 qid）","开放伤（穿通伤/球内异物）：保护眼球（金属眼罩，禁冲洗、禁按压、禁自行取异物）→ 全身抗生素（头孢曲松 1g 静滴 q12h）+破伤风预防（破伤风抗毒素 1500IU 肌注/类毒素 0.5ml 肌注）→ 急诊手术修复（角膜/巩膜缝合、异物取出）","钝挫伤：前房积血（半卧位、双眼包扎制动、止血药如氨甲环酸 0.5g 静滴 q8h、监测眼压、必要时前房冲洗）；瞳孔散大与晶状体脱位（观察与手术）；视网膜震荡与脱离（眼底评估与手术）","角膜擦伤/异物：表面麻醉下取出异物（勿损伤角膜）、抗生素滴眼（左氧氟沙星滴眼液 qid）+眼膏（红霉素眼膏 涂眼 qn）、必要时眼罩（不包扎感染性）","眼压管理：前房积血或钝挫伤后眼压增高（甘露醇 1～1.5g/kg 静滴+乙酰唑胺 250mg 口服 q6h+β受体阻滞剂滴眼，如噻吗洛尔 0.5% 滴眼 bid），必要时手术","并发症处理：角膜瘢痕与角膜移植、外伤性白内障（手术）、视网膜脱离（急诊手术）、眼球萎缩、交感性眼炎（对侧眼炎症，需激素与免疫抑制）","随访：伤后1天、3天、1周、1个月复查（视力、眼压、眼底与前房），警惕迟发性并发症","宣教：眼部防护（工作与运动时戴护目镜）、化学伤现场急救（立即冲洗）、受伤后禁揉眼与自行处理"],"management":["化学伤急救：立即冲洗（首选生理盐水，无则清水），冲洗至少30分钟并翻转眼睑冲洗穹窿；记录化学品名称与接触时间，测结膜囊pH","开放伤护理：禁冲洗、禁按压、禁取出异物；用金属眼罩保护、禁食禁水（拟急诊手术）、快速建立静脉通路与备血","体位与制动：前房积血者半卧位（血液沉积于下方）、双眼包扎制动、避免用力与剧烈活动（防再出血）","疼痛与观察：评估疼痛评分并镇痛；观察视力、眼压、前房积血变化与眼内容物脱出情况","用药护理：抗生素与散瞳滴眼按时给予；破伤风抗毒素与抗生素全身用药观察过敏反应","术前准备与宣教：快速完成术前准备（禁食、备皮、术前用药），心理安慰与手术必要性解释","随访与宣教：按时复查（警惕交感性眼炎与迟发性视网膜脱离）、眼部防护（护目镜）、化学伤现场立即冲洗的重要性"],"notes":["化学性眼外伤的预后取决于现场冲洗是否及时（立即、大量、持续30分钟以上），冲洗比任何药物都重要","开放性眼外伤禁冲洗、禁按压、禁自行取异物，须用眼罩保护后急诊手术","球内异物禁用MRI检查（金属异物可致进一步损伤），首选CT","前房积血者禁用阿司匹林与NSAIDs、避免用力与剧烈活动（防再出血），并监测眼压","交感性眼炎是穿通伤后的严重并发症（对侧眼炎症，可致双眼失明），需长期随访与免疫抑制治疗"],"emergency":["化学伤（酸碱入眼）→ 立即大量冲洗30分钟以上，测pH，眼科急会诊","眼球穿通伤伴眼内容物脱出 → 金属眼罩保护、禁按压与冲洗、禁食禁水、全身抗生素、急诊手术","球内异物（CT证实）→ 急诊手术取出（金属异物尽快，防铁锈症）","前房积血伴眼压显著升高与剧痛（继发青光眼）→ 立即降眼压（甘露醇+乙酰唑胺），必要时前房冲洗","眼外伤后对侧眼出现眼红眼痛视力下降（交感性眼炎）→ 立即眼科急会诊并激素治疗","眼外伤伴颅脑或颌面部损伤 → 按多发伤原则优先处理危及生命的损伤"],"pinyin":"ywssjzcl","icd10":"S05.9","physical_exam":["视力：双眼裸眼视力（必查，记录并对比），光感与光定位","眼睑与眼眶：眼睑裂伤、淤血肿胀、眼眶畸形与压痛（骨折）、皮下气肿","眼球完整性与位置：眼球是否完整、有无眼内容物脱出、眼球运动受限（眶壁骨折/肌肉嵌顿）","结膜：结膜下出血、裂伤、异物、化学伤后缺血（苍白提示重度碱烧伤）","角膜：裂伤、异物、混浊与上皮缺损（荧光素染色）、角膜感觉","前房：深度（变浅提示穿通伤/晶状体脱位）、积血与积脓、虹膜与瞳孔（瞳孔变形提示虹膜嵌顿）","眼压：开放伤禁测或轻柔；低眼压提示穿通伤；高眼压提示前房积血继发青光眼","眼底（可能时）：玻璃体积血、视网膜脱离与震荡"],"lab_tests":["视力+裂隙灯+荧光素染色（必查）：损伤部位与程度评估","眼眶与眼球CT（薄层，首选）：球内异物、眼眶骨折与球后血肿（金属异物禁MRI）","眼压测量（闭合伤）：前房积血继发青光眼与穿通伤评估","眼部B超（闭合伤）：玻璃体积血与视网膜脱离（开放伤慎用）","结膜囊pH（化学伤）：冲洗前后测定（目标7.0～7.4）","血常规+凝血功能+感染筛查（拟手术）：术前准备；破伤风预防评估（污染伤口）","眼眶MRI（非金属异物、视神经损伤）：必要时"],"nursing":["化学伤急救护理：立即协助大量冲洗（生理盐水，翻转眼睑冲洗穹窿）至少30分钟，测pH并记录化学品名称与时间","开放伤护理：金属眼罩保护、禁冲洗与按压、禁食禁水、快速建立静脉通路与术前准备","体位与制动：前房积血者半卧位、双眼包扎制动、避免用力与活动（防再出血）","用药护理：按时给予抗生素与散瞳滴眼液；全身抗生素与破伤风抗毒素观察过敏反应","病情观察：视力、眼压、前房积血与眼内容物脱出情况，疼痛加剧或视力下降立即报告","宣教：眼部防护（工作与运动戴护目镜）、化学伤现场立即冲洗、受伤后禁揉眼与自行处理、按时复查（警惕交感性眼炎）"],"diet":["急诊期：禁食禁水（拟手术或需观察）","恢复期：高蛋白、高维生素饮食促进组织修复（鱼、瘦肉、蛋、蔬果，富含维生素A与C）","前房积血者：清淡饮食、多饮水、多纤维食物保持大便通畅（避免用力致再出血）","避免辛辣刺激、酒类与过量咖啡因；戒烟","长期使用激素者：低盐低糖饮食、补充钙与维生素D"],"topical_medication":["左氧氟沙星滴眼液 1滴 滴眼 qid；重组牛碱性成纤维细胞生长因子滴眼液 1滴 滴眼 qid；红霉素眼膏 涂眼 qn"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1408},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1de849cf405c45d7f2f8759ed332708aba88a2632aa32a169c3b80edfd1aecdb","pinyin":"yanwaishang（jizhenchuli）","initials":"yws（jzcl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","眼痛、流泪、畏光、眼睑痉挛、视力下降\\n化学伤：眼部剧烈疼痛、眼睑与结膜充血水肿、角膜混浊（碱烧伤可进行性加重）\\n穿通伤：眼内容物脱出（虹膜、玻璃体）、前房变浅、瞳孔变形、低眼压，可见伤口\\n钝挫伤：眼睑淤血肿胀、结膜下出血、前房积血、瞳孔散大、晶状体脱位与视网膜震荡\\n球内异物：细小伤口伴视力下降、眼压异常（金属异物可致铁锈症）",60],["摘要","眼外伤包括机械性（角膜擦伤、眼球穿通伤、球内异物、钝挫伤）、化学性（酸碱烧伤）与热/辐射伤。化学伤需立即大量冲洗（现场急救最关键）；开放性眼外伤需保护眼球、禁冲洗与按压、禁自行取异物，尽快手术。眼外伤是单眼致盲的重要原因，及时正确处理决定预后。",30],["疾病编码","S05.9",30],["原首字母","ywssjzcl",60]]},{"id":"orders-ad2a7a463e5b1da85aee","key":"v1-c9ccc21dfe2a3058|orders-ad2a7a463e5b1da85aee","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"牙外伤急诊处理","category":"口腔","raw":{"name":"牙外伤急诊处理","category":"口腔","summary":"牙外伤包括牙震荡、牙脱位（部分/完全脱位、嵌入）、牙折（冠折、根折、冠根折）与牙槽突骨折，多见于儿童与青少年（跌倒、运动、交通事故）。处理关键是及时（尤其完全脱位牙再植的黄金时间30分钟内）与正确保存离体牙（生理盐水、牛奶或口腔前庭）。","symptoms":["牙齿疼痛、松动、移位、伸长或嵌入（脱位）","牙齿缺损（冠折）、露髓（可见红点与剧痛）、牙冠变色（牙髓坏死）","牙龈与口腔黏膜撕裂出血、牙槽突骨折（多牙整体移动、咬合错乱）","完全脱位：牙齿脱落（需询问离体牙保存方式与时间）","合并伤：颌面部骨折、颅脑损伤、软组织裂伤（需优先评估）"],"diagnosis":["病史：受伤时间与方式、离体牙保存方式与时间（再植预后关键）","牙齿检查：松动度、移位、叩诊、牙髓活力测试（电活力/冷测）、露髓与颜色","牙龈与牙槽突：裂伤、出血、骨台阶感、多牙移动（牙槽突骨折）","X线（根尖片+全景片）：牙根折、牙槽突骨折、脱位与邻牙情况、恒牙胚（儿童）","CBCT（复杂病例）：根折位置、牙槽骨骨折细节与异物","全身评估：是否合并颌面部骨折、颅脑损伤（按ATLS原则优先处理）","儿童注意：区分乳牙与恒牙（乳牙损伤处理原则不同），评估恒牙胚受损风险"],"infusion":["⚠️ 牙外伤以局部处理为主，全身用药用于污染重/合并骨折/免疫低下者！","","方案1（抗感染，再植牙/开放性损伤/牙槽突骨折）：","  用法：阿莫西林 0.5g（NS 100ml 或 5%GS 100ml）静滴 q8h（或口服 0.5g tid，疗程5～7天）；青霉素过敏者 克林霉素 0.6g 静滴 q8h〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（破伤风预防，污染伤口）：","  用法：破伤风抗毒素 1500IU 皮下注射（皮试后）或 破伤风免疫球蛋白 250IU 肌注","","方案3（镇痛与支持）：","  用法：对乙酰氨基酚 0.5g 静滴 必要时（儿童按体重10～15mg/kg）；0.9%氯化钠 静滴〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","方案4（合并颌面部骨折/需手术）：","  用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h；地塞米松 10mg 静推（减轻水肿，短期）〔调 CrCl<30 减量；青霉素过敏禁用〕","","📌 完全脱位牙再植是关键：黄金时间30分钟内，离体牙只能握牙冠（勿触碰牙根）、用生理盐水/牛奶/唾液保存湿润；再植后抗生素+破伤风预防+牙髓治疗评估。"],"oral_medication":["⚠️ 局部处理+口服药物辅助：","药物1（抗感染）：","用法：阿莫西林 0.5g tid（疗程5～7天，儿童按体重25～45mg/kg/日分次）；青霉素过敏者 克林霉素 0.3g tid〔调 CrCl<30 减量；青霉素过敏禁用〕","药物2（镇痛）：","用法：对乙酰氨基酚 0.5g 必要时（儿童10～15mg/kg）；必要时布洛芬 0.3g bid（餐后）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物3（局部用药与护理）：","用法：0.2%氯己定含漱液 含漱 bid（儿童用棉签涂抹，避免吞咽）；康复新液 含漱促愈合","药物4（牙髓相关，按医嘱）：","用法：根管治疗期间必要时口服抗生素；牙髓坏死需行根管治疗（不做药物替代）","📌 牙外伤后需避免硬食与咬合刺激、保持口腔清洁、按时复查牙髓活力与X线（牙髓坏死与根吸收可延迟出现）。"],"treatment":["完全脱位牙：立即再植（黄金30分钟内）——握牙冠、生理盐水冲洗（勿刮牙根）、尽量复位并弹性固定2周；不能立即再植者保存于生理盐水/牛奶/唾液，尽快就诊；再植后按医嘱抗生素+破伤风预防+2周内根管治疗（成人恒牙）","部分脱位/移位：局麻下复位+弹性固定2～4周，监测牙髓活力（1、3、6、12个月）","嵌入性脱位：乳牙可观察自行萌出；恒牙（嵌入>7mm或牙根发育完成）需正畸牵引或手术复位","冠折（未露髓）：树脂修复+脱敏；露髓（<24小时、牙根未发育完成）行活髓切断/直接盖髓；露髓时间长或牙根发育完成者行根管治疗+桩核冠","根折：冠1/3（去除冠部+根管治疗后桩核修复）；中1/3（复位固定观察，必要时根管治疗）；根尖1/3（多为观察+固定）","牙槽突骨折：局麻下复位+牙弓夹板/正畸托槽固定4～6周，抗生素+破伤风预防，必要时手术","乳牙外伤：以保护恒牙胚为原则，避免不必要的手术与固定；乳牙完全脱位一般不再植","随访：伤后1、3、6、12个月复查（牙髓活力、X线与根吸收），青春期前儿童需长期随访"],"management":["急救与保存：完全脱位牙立即指导正确保存（勿触碰牙根、湿润保存），快速就诊（再植黄金时间30分钟）","疼痛与出血护理：评估疼痛并镇痛；牙龈与黏膜裂伤清创、压迫止血，必要时缝合","固定护理：固定期间避免咬硬物与剧烈运动、软食、保持口腔清洁（含漱液），按医嘱复查拆除固定","牙髓监测：按时评估牙髓活力（电活力/冷测）与牙齿颜色变化（变色提示牙髓坏死），异常报告并安排根管治疗","感染预防：抗感染与破伤风预防（污染伤口）；观察牙龈肿胀与溢脓（根尖感染）","儿童与家长宣教：乳牙与恒牙区分与随访重要性、运动时戴护齿、避免再次外伤、按时复查（牙髓坏死与根吸收可延迟数月至数年）","多学科协作：合并颌面部骨折或颅脑损伤时与口腔颌面外科、神经外科协作"],"notes":["完全脱位牙再植的黄金时间是30分钟内，离体牙只能握牙冠、勿触碰牙根，用生理盐水/牛奶/唾液湿润保存（不可干燥）","牙外伤后牙髓坏死与根吸收可延迟出现（数月至数年），必须长期随访（1、3、6、12个月）","乳牙外伤以保护恒牙胚为原则（避免不必要的手术与固定）；乳牙完全脱位一般不再植","牙外伤常提示运动防护不足（运动时佩戴护齿可显著降低发生率）","合并颌面部骨折或颅脑损伤时按多发伤原则优先处理危及生命的损伤"],"emergency":["完全脱位牙（30分钟内）→ 立即再植+弹性固定，抗感染与破伤风预防，2周内评估根管治疗","牙齿露髓伴剧痛 → 尽早（24小时内）行活髓切断/盖髓或根管治疗，镇痛处理","牙外伤伴颌面部骨折（咬合错乱、面部畸形）→ 口腔颌面外科急诊评估与手术","牙槽突骨折伴多牙移位 → 局麻下复位固定+抗生素，必要时手术","牙外伤伴颅脑损伤（意识改变、呕吐）→ 优先按颅脑损伤处理（头颅CT），口腔处理延后"],"pinyin":"ywssjzcl","icd10":"S03.2","physical_exam":["生命体征与意识：有无颅脑损伤（意识、瞳孔、呕吐）与颌面部多发伤","牙齿：松动度、移位、伸长、嵌入、缺牙（记录牙位与数目）、叩诊反应","牙髓活力：电活力测试与冷测（伤后即刻结果可能不准确，需复查）","牙冠：缺损范围、露髓（可见红点）、颜色（变色提示牙髓坏死）","牙龈与黏膜：裂伤、出血、撕裂范围与深度","牙槽突：骨台阶感、多牙整体移动（牙槽突骨折）、咬合错乱","颌面部：面部肿胀与畸形、张口受限、下颌运动异常（骨折评估）"],"lab_tests":["根尖片+口腔全景X线（必查）：根折、牙槽突骨折、脱位与恒牙胚评估","CBCT（复杂病例）：根折位置、牙槽骨骨折细节与异物定位","牙髓活力测试（电活力/冷测）：伤后即刻与随访（1、3、6、12个月）对比","血常规+凝血功能（拟手术/出血多者）：术前评估","破伤风预防评估（污染伤口）：破伤风抗毒素/免疫球蛋白接种","颌面部CT（疑骨折）：明确骨折部位与范围","头颅CT（合并颅脑损伤嫌疑）：优先评估颅内损伤"],"nursing":["急救与牙保存指导：指导患者/家长正确保存离体牙（握牙冠、湿润保存、尽快就诊），并记录受伤与保存时间","疼痛与出血护理：评估疼痛并镇痛；局部压迫止血、协助清创缝合、观察出血量","固定期护理：指导软食、避免咬硬物与剧烈运动、口腔清洁（含漱液）、按时复诊拆除固定","牙髓监测与随访提醒：按时复查牙髓活力与X线（1、3、6、12个月），变色或疼痛立即就诊","感染预防：遵医嘱抗生素与破伤风预防，观察牙龈肿胀、溢脓与发热","宣教：儿童与家长共同教育（运动戴护齿、避免再次外伤、牙外伤需长期随访）、口腔卫生维护"],"diet":["固定期：软食、温凉食物，避免过硬、过热与刺激性食物（减少牙齿受力与出血）","高蛋白、高维生素（维生素C）饮食促进牙龈与组织愈合","避免用患牙咀嚼；儿童避免吮指与咬硬物（玩具、笔）","保持口腔清洁：餐后漱口、含漱液使用（按医嘱）","避免含糖食物与饮料（防龋与感染）；戒烟酒（成人）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1409},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5c47cc55fc80afc4ca7a1100e970337b93fd8e3dec8f4ea1bdb91117e7bf5beb","pinyin":"yawaishangjizhenchuli","initials":"ywsjzcl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","牙齿疼痛、松动、移位、伸长或嵌入（脱位）\\n牙齿缺损（冠折）、露髓（可见红点与剧痛）、牙冠变色（牙髓坏死）\\n牙龈与口腔黏膜撕裂出血、牙槽突骨折（多牙整体移动、咬合错乱）\\n完全脱位：牙齿脱落（需询问离体牙保存方式与时间）\\n合并伤：颌面部骨折、颅脑损伤、软组织裂伤（需优先评估）",60],["摘要","牙外伤包括牙震荡、牙脱位（部分/完全脱位、嵌入）、牙折（冠折、根折、冠根折）与牙槽突骨折，多见于儿童与青少年（跌倒、运动、交通事故）。处理关键是及时（尤其完全脱位牙再植的黄金时间30分钟内）与正确保存离体牙（生理盐水、牛奶或口腔前庭）。",30],["疾病编码","S03.2",30],["原首字母","ywssjzcl",60]]},{"id":"orders-8d6ec63545fee6b4cb7e","key":"v1-c9ccc21dfe2a3058|orders-8d6ec63545fee6b4cb7e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"口腔白斑与癌前病变","category":"口腔","raw":{"name":"口腔白斑与癌前病变","category":"口腔","summary":"口腔白斑（OLK）是口腔黏膜上不能擦去的白色斑块，属癌前病变（恶变率约1%～5%）；其他癌前病变/状态包括口腔红斑（恶变率更高）、口腔扁平苔藓、口腔黏膜下纤维性变与红斑狼疮等。危险因素为吸烟、饮酒、嚼槟榔与人乳头瘤病毒（HPV）感染。处理重点为去除危险因素、活检明确诊断与密切随访。","symptoms":["口腔黏膜白色斑块（不能擦去）、边界清楚或弥漫","常无症状，部分有粗糙感、涩感或轻度疼痛（糜烂型）","红斑：鲜红色天鹅绒样斑块（恶变风险高，需警惕）","疣状/颗粒状白斑：表面不平、结节状（恶变风险较高）","合并口腔黏膜下纤维性变：张口受限、黏膜发白变硬（嚼槟榔者）"],"diagnosis":["口腔黏膜检查（含舌腹、口底、颊、软腭、牙龈）：记录部位、大小、形态（均质/非均质、疣状/颗粒状/糜烂）","醋酸染色/甲苯胺蓝染色（辅助）：指导活检部位","活检（确诊必需）：从最可疑（非均质、红斑、硬结、溃疡）部位取材，必要时多点活检","病理分级：上皮异常增生程度（轻/中/重度）——决定恶变风险与处理","HPV检测（必要时）：与口咽癌相关性评估","影像学（疑恶变）：颈部淋巴结超声/CT、MRI（评估浸润与转移）","危险因素评估：吸烟量、饮酒、嚼槟榔史、义齿修复不良与慢性刺激（残根、锐利牙尖）"],"infusion":["⚠️ 以去除危险因素与手术/随访为主，静脉用药仅用于合并感染或术后！","","方案1（合并感染/术后抗感染）：","  用法：阿莫西林 0.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（疗程3～5天）；或 头孢呋辛 1.5g 静滴 q8h〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（免疫调节，扁平苔藓/免疫相关病变）：","  用法：甲泼尼龙 40mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（重症糜烂型，短期）；羟氯喹 200mg（口服为主）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（维生素与营养支持）：","  用法：维生素A 与β-胡萝卜素（口服为主）；维生素B12 0.5mg 肌注 qd（营养缺乏者）；维生素C 2g（NS 100ml 或 5%GS 100ml）静滴 qd","","方案4（术后支持）：","  用法：0.9%氯化钠 静滴；镇痛（对乙酰氨基酚 0.5g 必要时）；必要时间断静脉营养（广泛切除者）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","📌 白斑治疗的核心是去除危险因素（戒烟、戒酒、戒槟榔）+ 活检 + 随访或手术切除，药物不能预防恶变。"],"oral_medication":["⚠️ 局部与口服用药为主：","药物1（局部）：","用法：维A酸乳膏/凝胶 局部涂抹 bid（非糜烂型，注意刺激反应）；0.2%氯己定含漱液 含漱 bid（继发感染）","药物2（口服，免疫相关病变/扁平苔藓）：","用法：羟氯喹 200mg bid（需眼科监测）；必要时小剂量激素（泼尼松 10～20mg qd，短期，遵医嘱）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物3（营养与辅助）：","用法：β-胡萝卜素 20mg tid；维生素B12 0.5mg qd；复合维生素B 2片 tid","药物4（对症）：","用法：对乙酰氨基酚 0.5g 必要时（疼痛）；康复新液 含漱（黏膜修复）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 维A酸局部使用可致黏膜刺激与脱屑（需小面积试用）；戒烟戒酒戒槟榔是阻止病变进展的最重要措施。"],"treatment":["去除危险因素（首要）：戒烟、戒酒、戒槟榔；去除慢性刺激因素（拔除残根、磨除锐利牙尖、修改不良义齿）","活检确诊与分级：所有可疑白斑均应活检（尤其非均质白斑、红斑、硬结或糜烂），明确有无上皮异常增生","手术切除：中重度异常增生、非均质白斑、疣状白斑及长期不愈者行手术切除（激光/冷冻/手术刀），切缘送检","定期随访：均质白斑无异常增生者每3～6个月复查（必要时再活检）；异常增生者缩短至1～3个月","恶变处理：确诊癌变者按口腔癌规范治疗（扩大切除+颈淋巴结清扫±放化疗），多学科协作","口腔扁平苔藓与黏膜下纤维性变：局部/全身免疫调节治疗、张口训练、密切随访","高危人群管理：长期吸烟饮酒者同时筛查肺部与消化道肿瘤（区域癌化风险）","宣教：自我检查方法（每月观察口腔黏膜）、发现白色斑块/溃疡>2周不愈立即就诊、坚持随访不可自行中断"],"management":["病变记录与随访：拍照记录病变部位与大小、绘制示意图、纤维测量（黏膜下纤维性变），每次随访对比","危险因素干预：提供戒烟（含转诊戒烟门诊）、戒酒与戒槟榔指导并记录，强调其对恶变风险的影响","随访依从性：建立随访档案并主动提醒（每3～6个月或更短），记录活检与病理结果","术后护理（切除者）：口腔清洁与含漱、软食、观察出血与感染、按时复查切缘","心理护理：癌前病变诊断易致焦虑，解释恶变风险较低但需随访，必要时心理支持","多学科协作：口腔科、口腔颌面外科、病理科与肿瘤科协作（可疑恶变者）","宣教与自我监测：教会自我检查（对镜观察舌腹、口底、颊部）、识别危险征象（变硬、溃疡不愈、出血、颈部肿块）立即就诊"],"notes":["口腔白斑是癌前病变（恶变率1%～5%），非均质白斑、红斑与疣状白斑恶变风险更高（红斑恶变率可达20%以上）","所有可疑病变均应活检（尤其非均质白斑、硬结、糜烂或>2周不愈的溃疡），诊断依靠病理","去除危险因素（戒烟、戒酒、戒槟榔）与去除慢性刺激是最重要的干预措施（药物不能预防恶变）","确诊癌变者需按口腔癌规范治疗（扩大切除+颈淋巴结清扫±放化疗），忌局部切除了事","口腔黏膜下纤维性变（嚼槟榔所致）恶变风险高，需长期随访与张口训练"],"emergency":["口腔溃疡/白斑>2周不愈伴硬结与出血（疑癌变）→ 尽快活检确诊","颈部出现无痛性肿块（淋巴结转移）→ 立即影像与活检评估","病变迅速增大、表面溃烂伴剧痛与吞咽困难 → 急诊评估（可能晚期癌变致气道/进食障碍）","术后大量出血或气道受压（广泛切除/复发肿瘤）→ 急诊处理并保护气道","合并严重感染（发热、面颈部肿胀）→ 抗感染+引流，必要时住院"],"pinyin":"kqbbdayqbb","icd10":"K13.2","physical_exam":["口腔黏膜（全面）：舌腹、口底、颊、软腭、牙龈与咽部，记录病变部位、大小、形态与质地（是否存在硬结）","病变特征：均质/非均质、白色/红色/混合、平坦/疣状/颗粒状、有无糜烂与溃疡","口腔黏膜下纤维性变：黏膜苍白变硬、张口受限（测量最大张口度）","牙齿与义齿：残根、锐利牙尖、不良修复体（慢性刺激）","颈部淋巴结：大小、质地、活动度（转移评估）","危险因素：吸烟与槟榔（牙渍、口腔异味）、饮酒","其他部位：鼻腔与咽部黏膜、皮肤（扁平苔藓的皮肤表现）"],"lab_tests":["口腔黏膜活检+病理（含异常增生分级）：确诊与恶变风险评估（必查）","醋酸/甲苯胺蓝染色（辅助）：指导活检部位选择","HPV检测（必要时）：与口咽癌相关性评估","颈部超声/增强CT/MRI（疑恶变）：浸润深度与淋巴结转移评估","血常规+肝肾功能+凝血功能：术前与治疗监测","营养相关（维生素B12、叶酸、铁）：营养缺乏相关口腔黏膜病变评估","胸部影像（长期吸烟者）：同时筛查肺部肿瘤"],"nursing":["病变记录与随访：拍照、绘图与测量病变，每次随访对比并记录变化","危险因素宣教：戒烟（必要时转诊戒烟门诊）、戒酒、戒槟榔的指导与随访；去除慢性刺激（建议口腔修复处理）","术后护理：口腔清洁（含漱液）、软食、观察出血与感染、按时复查切缘情况","心理护理：解释癌前病变的性质与随访必要性（恶变率较低但需监测），缓解焦虑","随访提醒：按医嘱每3～6个月（或更短）复查并主动联系患者，提高依从性","自我检查宣教：教会患者对镜自我检查（舌腹、口底、颊部）与识别危险征象（溃疡不愈、硬结、出血、颈部肿块）"],"diet":["高蛋白、高维生素（A、B族、C）饮食促进黏膜修复","避免辛辣、过烫、腌制、熏制与霉变食物（致癌风险）","严格戒烟、戒酒、戒槟榔（关键干预措施）","多食新鮮蔬果与全谷物（抗氧化营养素）；适量补充β-胡萝卜素","术后软食、温凉食物；张口受限者少量多餐、必要时营养补充剂"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1410},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"50e284b111cbb205f39927760c1a174e1cb7ce90cde43a69b8857cb61d02eb31","pinyin":"kouqiangbaibanyuaiqianbingbian","initials":"kqbbyaqbb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","口腔黏膜白色斑块（不能擦去）、边界清楚或弥漫\\n常无症状，部分有粗糙感、涩感或轻度疼痛（糜烂型）\\n红斑：鲜红色天鹅绒样斑块（恶变风险高，需警惕）\\n疣状/颗粒状白斑：表面不平、结节状（恶变风险较高）\\n合并口腔黏膜下纤维性变：张口受限、黏膜发白变硬（嚼槟榔者）",60],["摘要","口腔白斑（OLK）是口腔黏膜上不能擦去的白色斑块，属癌前病变（恶变率约1%～5%）；其他癌前病变/状态包括口腔红斑（恶变率更高）、口腔扁平苔藓、口腔黏膜下纤维性变与红斑狼疮等。危险因素为吸烟、饮酒、嚼槟榔与人乳头瘤病毒（HPV）感染。处理重点为去除危险因素、活检明确诊断与密切随访。",30],["疾病编码","K13.2",30],["原首字母","kqbbdayqbb",60]]},{"id":"orders-7ebeb4693552665e5617","key":"v1-c9ccc21dfe2a3058|orders-7ebeb4693552665e5617","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"糖皮质激素等效剂量与减量方案","category":"临床常用知识","raw":{"name":"糖皮质激素等效剂量与减量方案","category":"临床常用知识","summary":"糖皮质激素是临床常用药物，不同制剂抗炎强度与盐皮质激素作用不同，换算需按等效剂量进行；长期使用需缓慢减量（防肾上腺皮质功能不全与疾病反跳），并防治骨质疏松、高血糖、感染与消化道出血等不良反应。","symptoms":["长期使用的不良反应：向心性肥胖、满月脸、水牛背、皮肤紫纹、痤疮、多毛","代谢异常：高血糖、高血压、低钾、高脂血症","感染易感性增加（结核再激活、真菌、带状疱疹）","骨质疏松与骨折、股骨头坏死、肌病（近端肌无力）","减量过快/骤停：乏力、低血压、低血糖、关节痛、原发病反跳（肾上腺危象）"],"diagnosis":["等效剂量换算表（抗炎等效剂量）：氢化可的松 20mg = 泼尼松 5mg = 泼尼松龙 5mg = 甲泼尼龙 4mg = 曲安西龙 4mg = 地塞米松 0.75mg = 倍他米松 0.75mg","盐皮质激素作用：氢化可的松与可的松较强（水钠潴留明显）；甲泼尼龙与地塞米松几乎无盐皮质激素作用","用药史评估：剂量、疗程（>3周或剂量>泼尼松7.5mg/日者为长期使用）、给药方式（口服/静脉/局部）","肾上腺皮质功能评估（疑功能不全）：晨8时皮质醇、ACTH刺激试验","不良反应监测：血糖、血压、电解质、骨密度、眼压（青光眼）、眼底与感染筛查（结核、乙肝）","原发病活动度评估：决定减量速度（需结合原发病控制情况）","相互作用核查：与NSAIDs（消化道出血）、降糖药（血糖升高）、抗凝药、疫苗（活疫苗禁用）"],"infusion":["⚠️ 静脉激素用于急性重症，剂量按等效换算与病情选择！","","方案1（急性重症/冲击治疗）：","  用法：甲泼尼龙 500～1000mg + 0.9%氯化钠 250ml 静滴 qd×3天（冲击治疗，监测血糖、血压、心律与感染）后减量〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（常规静脉治疗）：","  用法：甲泼尼龙 40～80mg（NS 100ml 或 5%GS 100ml）静滴 q12h 或 qd；或 氢化可的松 100mg 静滴 q8h（替代治疗/肾上腺危象）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案3（肾上腺危象抢救）：","  用法：氢化可的松 100mg 静推后 100～200mg/24h 持续静滴；0.9%氯化钠 1000ml 快速补液；必要时去甲肾上腺素泵入〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案4（替代治疗，肾上腺皮质功能不全）：","  用法：氢化可的松 20mg 晨 + 10mg 下午（或泼尼松 5mg 晨 + 2.5mg 下午）；应激时（感染/手术）剂量加倍至3倍〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","📌 长期使用后不可骤停（需缓慢减量）；冲击治疗期间监测血糖、血压、电解质与感染征象；静脉激素需与口服重叠后过渡。"],"oral_medication":["⚠️ 口服给药是长期治疗主要方式，注意餐后服与减量方案：","药物1（常用口服制剂）：","用法：泼尼松 5～60mg qd（晨起顿服，模拟生理节律，减少副作用）；甲泼尼龙 4～48mg qd；地塞米松 0.75～9mg qd（长效，慎用于长期治疗）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","药物2（减量方案，长期使用后）：","用法：泼尼松 每日减量≤原剂量的10%～20%（如20mg→15mg→10mg，每1～2周减一次）；接近生理剂量（泼尼松5～7.5mg/日）时更慢（每月减1mg）；必要时改用隔日疗法〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物3（不良反应防治）：","用法：碳酸钙D3 600mg qd + 骨化三醇 0.25μg qd（骨质疏松预防）；艾司奥美拉唑 20mg qd（消化道保护，高危者）；氯化钾缓释片（低钾）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物4（伴用药物注意）：","用法：与NSAIDs同用增加消化道出血风险（避免或加PPI）；糖尿病患者需调整降糖方案；监测血压与血糖","📌 晨起顿服（模拟生理分泌高峰）可减少副作用；长期使用需监测骨密度、血糖、血压与眼压；不可骤停（防肾上腺危象）。"],"treatment":["用药原则：明确指征、最小有效剂量、短疗程、晨起顿服；吸入/外用/关节腔局部用药可减少全身副作用","等效剂量换算：氢化可的松20mg=泼尼松5mg=甲泼尼龙4mg=地塞米松0.75mg，据此进行制剂更换","减量方案：长期使用（>3周）者缓慢减量（每次≤10%～20%），接近生理剂量时更慢，避免骤停","肾上腺皮质功能不全的预防：长期使用后遇应激（感染、手术、创伤）需增加剂量2～3倍或静脉激素，必要时查皮质醇与ACTH刺激试验","不良反应防治：骨质疏松（钙+维生素D+双膦酸盐）、高血糖（监测与降糖）、消化道出血（PPI如奥美拉唑20mg qd）、感染（筛查结核与乙肝并预防）、眼科随访","相互作用管理：评估与NSAIDs、抗凝药、降糖药、抗癫痫药及利福平（降低激素疗效）的相互作用","停药后随访：停药后数月至1年内仍可能肾上腺皮质功能不全（应激时需补充激素），需告知患者与相关科室","宣教：不可自行停药或加量、携带激素治疗卡、避免接触传染病患者、接种灭活疫苗（活疫苗禁用）"],"management":["用药记录与核对：记录制剂、剂量、频次与疗程；核对等效剂量换算（更换制剂时）","减量计划制定：与医师共同制定书面减量计划（每周减量幅度、观察指标与复诊时间）","不良反应监测：血糖（每日或隔日）、血压（每日）、电解质（每1～2周）、骨密度（每年）、眼压（每6～12个月）","感染监测：体温、呼吸道症状、皮肤黏膜感染灶；长期使用者筛查结核（PPI与IGRA）与乙肝（HBV-DNA）","患者宣教：不可自行停药/减量（防肾上腺危象）、遵医嘱减量、应激时增加剂量、携带激素卡、避免活疫苗接种","消化道保护：高危者（既往溃疡、合用NSAIDs、老年）使用PPI并观察黑便与上腹不适","长期随访：原发病控制情况与激素不良反应同步评估，及时调整方案"],"notes":["等效剂量换算必须准确（尤其更换制剂时），如地塞米松 0.75mg 等效于泼尼松 5mg（长效且无盐皮质激素作用）","长期使用糖皮质激素不可骤停：突然停药可致肾上腺危象（乏力、低血压、低血糖、意识障碍）与原发病反跳","长期使用（>3周或泼尼松>7.5mg/日）者遇应激（感染、手术、创伤）需增加剂量（2～3倍）以防肾上腺危象","常见不良反应需主动防治：骨质疏松（钙+维生素D±双膦酸盐）、高血糖、消化道出血（PPI）、感染（结核/乙肝再激活）","晨起顿服与隔日疗法可减轻对下丘脑-垂体-肾上腺轴的抑制；局部用药可减少全身副作用"],"emergency":["长期使用激素后突发乏力、低血压、低血糖、意识障碍（肾上腺危象）→ 立即氢化可的松 100mg 静推+补液，转ICU","冲击治疗期间突发高热与感染征象（免疫抑制致重症感染）→ 立即抗感染并调整激素剂量","上腹剧痛伴黑便/呕血（激素相关消化道出血）→ 停用NSAIDs、PPI静脉泵入、内镜评估","严重高血糖伴酮症（激素性糖尿病急性并发症）→ 胰岛素治疗与补液，监测血糖与电解质","激素减量过程中原发病急剧加重（反跳）→ 恢复原剂量并重新评估减量方案"],"pinyin":"zjzsdjlyjlfa","icd10":"Z79.5","physical_exam":["生命体征：血压（激素致高血压或肾上腺危象致低血压）、心率、体温（感染）、体重（水钠潴留）","激素相关体征：满月脸、水牛背、向心性肥胖、皮肤紫纹、痤疮、多毛、皮肤变薄","眼部：白内障（后囊下）、青光眼（眼压升高）、视乳头（必要时）","骨骼与肌肉：脊柱后凸与骨压痛（骨质疏松/压缩性骨折）、近端肌无力（激素性肌病）、股骨头坏死（髋痛与活动受限）","皮肤与注射部位：感染灶、瘀斑、注射部位萎缩","原发病活动度：关节肿痛、皮疹与黏膜病变等（评估减量时机）","口腔：口腔念珠菌感染（鹅口疮，免疫抑制者）"],"lab_tests":["血糖+糖化血红蛋白（每1～4周）：激素性高血糖监测","电解质（钾、钠）+血压（每日）：低钾与水钠潴留监测","血常规+CRP+PCT（疑感染）：免疫抑制致感染风险增加（感染时白细胞可不升高）","骨密度（DEXA，每年）+血钙磷+25-羟维生素D：骨质疏松监测与治疗依据","晨8时皮质醇+ACTH刺激试验（疑肾上腺皮质功能不全）：长期使用后评估","结核筛查（PPI/IGRA）+乙肝标志物与HBV-DNA：治疗前与长期使用中（再激活风险）","眼压+眼底（每6～12个月）：青光眼与白内障监测"],"nursing":["用药护理：严格按医嘱剂量与时间给药（晨起顿服为佳）、核对等效剂量换算、观察疗效与不良反应","减量执行：按书面减量计划执行，观察减量过程中原发病反跳与肾上腺功能不全表现（乏力、低血压、低血糖）","不良反应监测与护理：血糖与血压监测、观察黑便与上腹不适（消化道出血）、皮肤感染灶与口腔念珠菌","感染防护：避免接触传染源、保持口腔与皮肤清洁、监测体温（感染时可不发热）、遵医嘱筛查与预防（结核/乙肝）","宣教：不可自行停药或减量（防肾上腺危象）、携带激素卡、应激时（发热/手术）需增加剂量并就医、避免活疫苗接种","长期随访提醒：骨密度、血糖、血压、眼压与电解质按时复查"],"diet":["低盐饮食（每日钠盐<5g，水钠潴留与高血压者<3g）","低糖饮食、控制碳水总量（防激素性高血糖）；糖尿病患者按糖尿病饮食","高钙与维生素D食物（牛奶、豆制品、小鱼虾、深绿色蔬菜）预防骨质疏松","高钾食物（在肾功能允许下）如橙子、香蕉、土豆（防低钾）","适量优质蛋白、控制总热量与体重；避免饮酒与辛辣刺激（消化道保护）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1411},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c3d14c418b2dc6c186c2d5c3225e7e07bb8328d213ef90b3235486fea3efbf16","pinyin":"tangpizhijisudengxiaojiliangyujianliangfangan","initials":"tpzjsdxjlyjlfa","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","长期使用的不良反应：向心性肥胖、满月脸、水牛背、皮肤紫纹、痤疮、多毛\\n代谢异常：高血糖、高血压、低钾、高脂血症\\n感染易感性增加（结核再激活、真菌、带状疱疹）\\n骨质疏松与骨折、股骨头坏死、肌病（近端肌无力）\\n减量过快/骤停：乏力、低血压、低血糖、关节痛、原发病反跳（肾上腺危象）",60],["摘要","糖皮质激素是临床常用药物，不同制剂抗炎强度与盐皮质激素作用不同，换算需按等效剂量进行；长期使用需缓慢减量（防肾上腺皮质功能不全与疾病反跳），并防治骨质疏松、高血糖、感染与消化道出血等不良反应。",30],["疾病编码","Z79.5",30],["原首字母","zjzsdjlyjlfa",60]]},{"id":"orders-f5e2c2abd66d767e9f7e","key":"v1-c9ccc21dfe2a3058|orders-f5e2c2abd66d767e9f7e","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肝肾功能不全用药剂量调整原则","category":"临床常用知识","raw":{"name":"肝肾功能不全用药剂量调整原则","category":"临床常用知识","summary":"肝肾功能不全是药物代谢与排泄受损的常见状态，用药需按功能损害程度调整剂量与给药间隔，并避免使用肝毒性/肾毒性药物。肝功能不全按Child-Pugh分级，肾功能不全按肌酐清除率（Cockcroft-Gault公式）调整。","symptoms":["肾功能不全表现：少尿/多尿、水肿、乏力、恶心呕吐、电解质紊乱、意识改变（尿毒症）","肝功能不全表现：黄疸、腹水、凝血障碍（出血倾向）、乏力、意识改变（肝性脑病）","药物蓄积中毒表现：耳鸣与听力下降（氨基糖苷类）、皮疹与肝损害（抗结核药）、意识改变（镇静药）、出血（抗凝药）","药效下降（前体药物需肝肾活化）：如可待因、氯吡格雷在肝功能不全时疗效降低","需警惕：药物相互作用与蛋白结合率下降致游离药物浓度升高（肝病/低白蛋白）"],"diagnosis":["肾功能评估：血肌酐+尿素氮+肌酐清除率（Cockcroft-Gault公式：CrCl=[(140－年龄)×体重(kg)×0.85(女性)]/[72×Scr(mg/dl)]）+尿量","肝功能评估：ALT、AST、胆红素、白蛋白、凝血酶原时间、胆碱酯酶（Child-Pugh分级：A/B/C）","药物代谢途径核查：经肝代谢（CYP450）或经肾排泄（原型排出比例）","蛋白结合率与分布容积：低白蛋白血症致游离药物升高（如苯妥英、华法林）","治疗药物浓度监测（TDM）：万古霉素、氨基糖苷类、苯妥英、地高辛、丙戊酸钠等","相互作用评估：CYP450抑制剂/诱导剂（如红霉素、利福平、酮康唑）","肝肾联合损害评估：肝肾综合征、多器官功能障碍（ICU患者）"],"infusion":["⚠️ 肝肾功能不全时静脉用药需按清除率调整剂量或间隔！","方案1（肾功能不全剂量调整原则）：","用法：按肌酐清除率分档：CrCl 50～80ml/min 用常规剂量的100%；10～50ml/min 用50%～75%；<10ml/min 用25%～50%或延长给药间隔1.5～2倍；血液透析者按透析清除补充剂量（透析后给药）","方案2（肾功能不全相对安全的静脉抗生素）：","用法：头孢曲松 1～2g 静滴 qd（肝肾双途径，一般不需调整）；莫西沙星 0.4g 静滴 qd（主要经肝代谢）；阿奇霉素 0.5g 静滴 qd（不需调整）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","方案3（肝功能不全剂量调整原则）：","用法：Child-Pugh A：用常规剂量；B：减量25%～50%；C：减量50%以上或避免使用经肝代谢药物；避免肝毒性药物（对乙酰氨基酚每日≤2g、抗结核药需监测肝功能）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","方案4（避免/慎用的药物）：","用法：肾功能不全避免——NSAIDs、氨基糖苷类、万古霉素（需调整与监测）、造影剂（充分水化）、二甲双胍（eGFR<30禁用）；肝功能不全避免——对乙酰氨基酚过量、利福平+异烟肼（需监测）、镇静催眠药（诱发肝性脑病）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 调整原则：肾功能不全优先延长给药间隔并监测血药浓度；肝功能不全优先选择经肾排泄药物；两害并存时选肝肾双途径药物（如头孢曲松）并监测。"],"oral_medication":["⚠️ 口服用药同样需按肝肾功能调整（常见药物示例）：","药物1（肾功能不全需调整）：","用法：二甲双胍（eGFR 30～45减量并慎用，<30禁用）；阿莫西林（CrCl<30 q12h）；左氧氟沙星（CrCl<50 减量）；别嘌醇（按CrCl减量，防过敏与毒性）；恩格列净（eGFR<20不用）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","药物2（肝功能不全需调整，主要经肝代谢）：","用法：辛伐他汀/阿托伐他汀（肝功能异常慎用/减量）；对乙酰氨基酚（肝病者每日≤2g）；苯二氮卓类（肝病者慎用，诱发肝性脑病）；丙戊酸钠（肝毒性，监测肝功能）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物3（肝肾双途径，相对安全）：","用法：头孢曲松、莫西沙星、阿奇霉素、奥美拉唑（一般不需调整）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","药物4（需监测血药浓度）：","用法：地高辛、苯妥英钠、丙戊酸钠、万古霉素（静脉）、他克莫司——按TDM调整剂量〔调 ★★ 按 CrCl 调量并监测谷浓度10-20mg/L；耳肾毒性〕","📌 用药前核对说明书肾功能剂量调整项；避免自行加量或合用肾毒性/肝毒性药物（包括中草药：马兜铃酸、雷公藤等）。"],"treatment":["评估肝肾功能：计算肌酐清除率与Child-Pugh分级作为剂量调整依据（入院与病情变化时评估）","剂量调整：按清除率与肝功能分级减少剂量或延长给药间隔，首次剂量通常不减，维持量调整","药物选择优化：优先选择经肝肾双途径排泄或对肝肾功能影响小的药物，避免肾毒性与肝毒性药物","治疗药物浓度监测（TDM）：万古霉素、氨基糖苷类、地高辛、苯妥英、丙戊酸、他克莫司等按浓度调整剂量","透析患者用药：注意药物是否经透析清除（必要时透析后补充剂量），避免透析可清除药物在透析前给药","药物相互作用管理：核查CYP450抑制剂/诱导剂、蛋白结合竞争（华法林+NSAIDs）","不良反应监测：肾功能（肌酐、尿量）、肝功能（ALT、胆红素）、血常规、听力（氨基糖苷类）与神经系统","宣教：避免自行服用来路不明中草药与保健品、慎用NSAIDs、遵医嘱复查肝肾功能与血药浓度"],"management":["用药前核对：核对说明书肾功能/肝功能剂量调整项，记录肌酐清除率与Child-Pugh分级于用药记录","剂量执行与记录：标注调整后的剂量与给药间隔（避免按常规剂量给药），交班时明确提示","TDM执行：按时采血（谷浓度/峰浓度）并追踪结果，按结果调整剂量","监测肝肾功能：用药期间监测肌酐、尿素氮、尿量、ALT、胆红素与凝血功能（每1～3天或按病情）","不良反应观察：听力与耳鸣（氨基糖苷类）、皮疹与肝损害（抗结核药）、出血倾向（抗凝药与肝病）、意识改变（镇静药与肝性脑病）","宣教：避免自行加量、避免合用肾毒性药物（NSAIDs、造影剂）与肝毒性中草药、按时复查肝肾功能","多学科协作：临床药师参与剂量调整（尤其重症与多种药物联用者）"],"notes":["肾功能不全剂量调整依据肌酐清除率（Cockcroft-Gault公式），并按药物经肾排泄比例决定减量幅度","肝功能不全按Child-Pugh分级减量，避免肝毒性药物；低白蛋白血症时游离药物浓度升高需警惕毒性","血液透析患者注意药物是否被透析清除（必要时透析后补充剂量）；避免透析前给予透析可清除的药物","肝肾功能不全时优先选择肝肾双途径排泄药物（如头孢曲松、莫西沙星）","中草药与保健品是肝肾功能损害的常见隐匿原因（马兜铃酸致肾衰、部分中药致肝损），须详细询问用药史"],"emergency":["用药后突发少尿、无尿伴肌酐快速上升（急性肾损伤）→ 立即停药、评估肾前/肾性原因、必要时血液净化","用药后出现黄疸、凝血障碍与意识改变（急性肝衰竭）→ 立即停药、保肝治疗、评估肝移植","万古霉素/氨基糖苷类用药后出现耳鸣与听力下降 → 立即停药并查听力（不可逆耳毒性风险）","地高辛中毒（恶心、黄视、心律失常）→ 停药、纠正电解质、必要时地高辛抗体","肝肾功能不全患者使用镇静药后出现意识障碍（肝性脑病/药物蓄积）→ 停药、降血氨、纠正诱因"],"pinyin":"gsgnbqyyjlbdz","icd10":"Z51.8","physical_exam":["生命体征：血压、心率、呼吸、体温、体重与尿量（肾功能与容量状态）","容量与水肿：下肢与骶部水肿、腹水、颈静脉充盈、肺部湿啰音（水钠潴留）","肝功能相关体征：黄疸、蜘蛛痣、肝掌、腹壁静脉曲张、肝脾大小（肝硬化）","神经系统：意识状态（肝性脑病/尿毒症脑病）、扑翼样震颤、定向力、腱反射","皮肤与黏膜：皮疹（药物过敏）、出血点与瘀斑（凝血障碍）、皮肤瘙痒（尿毒症/胆汁淤积）","听力与前庭（用氨基糖苷类者）：耳鸣、听力下降、眩晕","用药部位：静脉炎、外渗、注射部位反应（多种药物输注者）"],"lab_tests":["肾功能（肌酐、尿素氮、肌酐清除率）+尿量：剂量调整核心依据（每1～3天或按病情）","肝功能（ALT、AST、胆红素、白蛋白）+凝血酶原时间+胆碱酯酶：Child-Pugh分级与肝损害监测","电解质（钾、钠、钙、磷）+血气分析：肝肾功能不全常见电解质与酸碱紊乱","治疗药物浓度监测（TDM）：万古霉素、氨基糖苷类、地高辛、苯妥英、丙戊酸等","血常规+血小板：药物致骨髓抑制与感染评估（肝病者三系可减少）","尿常规+尿蛋白定量：肾损害评估（药物性肾损伤）","听力检查（氨基糖苷类使用者）：耳毒性监测（必要时）"],"nursing":["用药核对：核对肾功能/肝功能剂量调整（标注调整后剂量与间隔），交班明确提示，避免按常规剂量给药","监测执行：按时留取血标本（肝肾功能、TDM），追踪结果并报告异常","尿量与出入量：准确记录24小时出入量与每小时尿量（肾功能不全者目标≥0.5ml/kg/h）","不良反应观察：耳鸣与听力下降、皮疹、黄疸、出血倾向、意识改变与尿量减少，异常立即报告","宣教：避免自行加量或合用肾毒性药物（NSAIDs、造影剂）、避免不明中草药与保健品、按时复查肝肾功能与血药浓度","安全护理：肝性脑病/尿毒症脑病者加床档防坠床、意识评估每班记录，配合多学科治疗"],"diet":["肾功能不全：优质低蛋白饮食（按分期，0.6～0.8g/kg/日）、限钠、限钾、限磷；足够热量","肝功能不全：适量优质蛋白（肝性脑病期短期限制）、限钠（腹水）、低脂、高维生素","肝肾综合征/严重肝病：严格限钠限水、按医嘱补充白蛋白与支链氨基酸","避免加重肝肾负担：禁酒、避免腌制与加工食品、避免高钾高磷食物（肾衰）","糖尿病与高血压者按相应饮食控制（基础病管理影响脏器功能）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1412},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8e378678447f1522a6081a3ddc14908172110cbe66c5ac9ad442dcd5fe18c309","pinyin":"ganshengongnengbuquanyongyaojiliangtiaozhengyuanze","initials":"gsgnbqyyjltzyz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肾功能不全表现：少尿/多尿、水肿、乏力、恶心呕吐、电解质紊乱、意识改变（尿毒症）\\n肝功能不全表现：黄疸、腹水、凝血障碍（出血倾向）、乏力、意识改变（肝性脑病）\\n药物蓄积中毒表现：耳鸣与听力下降（氨基糖苷类）、皮疹与肝损害（抗结核药）、意识改变（镇静药）、出血（抗凝药）\\n药效下降（前体药物需肝肾活化）：如可待因、氯吡格雷在肝功能不全时疗效降低\\n需警惕：药物相互作用与蛋白结合率下降致游离药物浓度升高（肝病/低白蛋白）",60],["摘要","肝肾功能不全是药物代谢与排泄受损的常见状态，用药需按功能损害程度调整剂量与给药间隔，并避免使用肝毒性/肾毒性药物。肝功能不全按Child-Pugh分级，肾功能不全按肌酐清除率（Cockcroft-Gault公式）调整。",30],["疾病编码","Z51.8",30],["原首字母","gsgnbqyyjlbdz",60]]},{"id":"orders-a6a7f4ffd1a4b70f18b0","key":"v1-c9ccc21dfe2a3058|orders-a6a7f4ffd1a4b70f18b0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"围手术期抗凝与抗血小板药物管理","category":"临床常用知识","raw":{"name":"围手术期抗凝与抗血小板药物管理","category":"临床常用知识","summary":"围手术期抗凝与抗血小板药物管理需平衡出血与血栓风险：根据手术出血风险与血栓风险决定停药时间、是否需要桥接抗凝（低分子肝素），术后恢复用药时机。原则是多学科评估、个体化决策，高危血栓患者需桥接治疗。","symptoms":["抗凝/抗血小板治疗适应证：房颤（卒中预防）、机械瓣膜、静脉血栓栓塞症（VTE）、冠心病支架术后、脑血管病","出血风险表现：术中与术后渗血、血肿、消化道出血、颅内出血（抗凝相关最危险）","血栓风险表现：脑卒中（房颤停抗凝）、支架内血栓（停抗血小板）、VTE复发（深静脉血栓/肺栓塞）","桥接抗凝相关：注射部位血肿、肝素诱导血小板减少（HIT）","术后恢复用药过早：切口血肿、引流增多、二次手术止血"],"diagnosis":["手术出血风险评估：高出血风险（颅脑、脊柱、心脏、血管、大型腹部手术）；低出血风险（体表、内镜活检、拔牙、白内障）","血栓风险评估：CHA₂DS₂-VASc评分（房颤）、机械瓣膜类型与位置、VTE发生时间与复发风险、支架类型与植入时间（裸金属/药物洗脱）","凝血功能与血小板：术前基线PT/INR、APTT、血小板计数、肾功能（影响药物清除）","药物半衰期与停药时间：华法林停5天（INR<1.5可手术）、达比加群停1～2天（肾功能不全延长）、利伐沙班停1～2天、阿司匹林停5～7天、氯吡格雷停5天、替格瑞洛停3～5天","桥接抗凝方案：低分子肝素（依诺肝素 1mg/kg q12h 或 40mg q12h 高危/低危）术前24小时停用、术后24～48小时恢复","多学科评估：心内科/神经内科/血管外科与手术科室、麻醉科共同决策","术后恢复时机：低出血风险手术术后24小时恢复，高出血风险手术48～72小时（确认止血后）"],"infusion":["⚠️ 桥接抗凝与围手术期用药须多学科评估后执行！","","方案1（桥接抗凝，低分子肝素，术前3天开始）：","  用法：依诺肝素 1mg/kg 皮下注射 q12h（高危血栓）或 40mg q12h（中危）；末次剂量为术前24小时（治疗量）或术前12小时（预防量）","","方案2（术后恢复桥接）：","  用法：术后24～48小时（确认无出血）恢复 依诺肝素 40mg 皮下注射 qd 或治疗量；与口服抗凝药重叠至INR达标（华法林）或直接恢复口服抗凝（DOAC）〔调 ★ 需监测INR；★ 大量药物食物相互作用；妊娠禁用〕","","方案3（急诊手术逆转抗凝）：","  用法：华法林——维生素K1 5～10mg 静推 + 凝血酶原复合物（PCC）1000～2000IU；达比加群——依达赛珠单抗 5g（NS 100ml 或 5%GS 100ml）静滴；Xa抑制剂——Andexanet alfa（如可用）或PCC；肝素——鱼精蛋白 1mg/100U 静推〔调 ★ 需监测INR；★ 大量药物食物相互作用；妊娠禁用〕","","方案4（抗血小板药物相关出血）：","  用法：血小板输注（1～2个治疗量）；去氨加压素 0.3μg/kg（NS 100ml 或 5%GS 100ml）静滴（阿司匹林/氯吡格雷相关出血）；必要时氨甲环酸 1g 静滴〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","","📌 桥接抗凝用于高危血栓患者（机械瓣膜、近期VTE、CHA₂DS₂-VASc≥5）；低危患者可仅停药用（不桥接）；急诊手术用拮抗剂/凝血因子逆转。"],"oral_medication":["⚠️ 术前停药与术后恢复需严格按手术出血风险与药物特性：","药物1（华法林）：","用法：术前5天停用（监测INR至<1.5可手术）；术后（止血后12～24小时）恢复原剂量+桥接低分子肝素至INR 2～3","药物2（直接口服抗凝药DOAC）：","用法：利伐沙班/阿哌沙班 术前停48小时（肾功能不全/CrCl<50停72小时）；达比加群 术前停48～96小时（按CrCl）；术后24～48小时（止血确认）恢复〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","药物3（抗血小板药物）：","用法：阿司匹林 术前停5～7天（二级预防低危患者可不停）；氯吡格雷 术前停5天；替格瑞洛 术前停3～5天；支架术后患者须心内科会诊（不可擅自停用，支架内血栓风险）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","药物4（术后镇痛与出血预防）：","用法：对乙酰氨基酚 0.5g 必要时（避免NSAIDs增加出血）；艾司奥美拉唑 20mg qd（消化道保护，抗凝/抗血小板者）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 支架术后患者（尤其药物洗脱支架<6个月）停用抗血小板药需心内科会诊；NSAIDs与抗凝药合用增加出血风险（避免）。"],"treatment":["术前评估：评估手术出血风险与血栓风险（CHA₂DS₂-VASc、机械瓣膜、VTE病史、支架类型与时间），制定个体化方案","停药时间：按药物半衰期与肾功能确定（华法林5天、DOAC 48～96小时、氯吡格雷5天、替格瑞洛3～5天），复查凝血功能确认","桥接抗凝指征：高危血栓患者（机械二尖瓣、3个月内VTE、CHA₂DS₂-VASc≥5、既往卒中）用低分子肝素桥接（依诺肝素1mg/kg q12h或40mg qd）；低危不桥接","术后恢复用药：低出血风险手术术后24小时恢复；高出血风险手术48～72小时（确认止血后）；高血栓风险者优先恢复抗凝","急诊手术处理：按抗凝药类型使用拮抗剂（维生素K 5～10mg静推+PCC、依达赛珠单抗5g静推、鱼精蛋白）或输注凝血因子/血小板","多学科协作：心脏科/神经科（抗凝指征与停药风险）、血管外科（VTE）、麻醉科与手术科室共同决策","监测：术后监测出血（切口、引流、血红蛋白）、血栓征象（下肢肿胀、胸痛气促）与凝血功能","宣教：告知停药与恢复的具体时间、不可自行停药或加药、识别出血与血栓症状及时就诊、携带抗凝治疗卡"],"management":["术前记录与核对：记录抗凝/抗血小板药物名称、剂量、末次用药时间、适应证与血栓风险评分，交班明确提示","停药与桥接执行：按方案执行停药与桥接（记录末次低分子肝素时间与术前间隔），核对手术时间安排","术后观察出血：监测切口渗血、引流量、血红蛋白与生命体征；发现活动性出血立即报告并延缓恢复抗凝","术后观察血栓：下肢肿胀与疼痛、胸痛与气促（PE）、神经系统症状（卒中），异常立即报告","用药恢复执行：确认止血后按时恢复抗凝/抗血小板，与口服药重叠期间监测INR/APTT（华法林）","消化道保护：抗凝+抗血小板联合者加用PPI，观察黑便与上腹不适","宣教：抗凝治疗不可自行停药（除医嘱）、识别出血（牙龈、皮下瘀斑、黑便、血尿）与血栓症状、按时复查凝血功能"],"notes":["围手术期抗凝管理需平衡出血与血栓风险，多学科评估后个体化决策（不可一概停药或保留）","桥接抗凝适用于高危血栓患者（机械瓣膜、近期VTE、高CHA₂DS₂-VASc评分）；低危者可仅停药不桥接","支架术后患者（尤其药物洗脱支架植入<6个月）停用抗血小板药需心内科会诊（支架内血栓风险高）","NSAIDs与抗凝药/抗血小板药合用时消化道出血风险显著增加，应避免或加用PPI","急诊手术需按抗凝药类型使用拮抗剂（维生素K+PCC、依达赛珠单抗、鱼精蛋白）或输注血制品"],"emergency":["抗凝患者急诊手术需立即逆转（华法林：维生素K1+PCC；达比加群：依达赛珠单抗；Xa抑制剂：PCC/Andexanet）→ 同时评估血栓风险","术后突发出血（切口血肿、引流骤增、血压下降）→ 停抗凝/抗血小板、压迫止血、必要时拮抗与输血","停抗凝期间突发偏瘫、失语（脑卒中）→ 立即头颅CT并评估溶栓/取栓（房颤患者）","停抗血小板期间突发胸痛（支架内血栓/急性冠脉综合征）→ 立即心电图与心肌酶，急诊介入评估","抗凝后突发剧烈头痛与意识改变（颅内出血）→ 立即停药、头颅CT与神经外科急会诊"],"pinyin":"wssqqkykxbygl","icd10":"Z92.1","physical_exam":["生命体征：血压、心率、呼吸与意识（出血与血栓评估）","出血征象：切口渗血、皮下瘀斑与血肿、牙龈与鼻腔出血、注射部位血肿、黑便与血尿","血栓征象：下肢肿胀与压痛（DVT）、胸痛与呼吸急促（PE）、神经系统局灶体征（卒中）","心肺：心率与心律（房颤）、呼吸音（PE/肺水肿）、心音（瓣膜病）","机械瓣膜：金属瓣膜音（听诊）与瓣膜功能（杂音变化提示血栓）","支架相关：穿刺部位（桡动脉/股动脉）血肿与假性动脉瘤","末梢循环：足背动脉搏动、皮温与颜色（下肢缺血/血栓）"],"lab_tests":["凝血功能（PT/INR、APTT）+血小板：术前基线与术后监测（华法林需INR达标或<1.5再手术）","肾功能（肌酐、肌酐清除率）：DOAC停药时间与剂量调整依据","血常规+血红蛋白（动态）：出血监测（术后每4～6小时）","血型+交叉配血：高出血风险手术备血","抗Xa因子活性（必要时）：低分子肝素桥接监测（肾功能不全、肥胖者）","下肢静脉超声（疑DVT）与CTPA（疑PE）：血栓事件评估","血栓弹力图/TEG（必要时）：复杂病例的凝血功能全面评估"],"nursing":["术前核对与记录：抗凝/抗血小板药物名称、剂量、末次用药时间与桥接方案，交班明确提示手术时间","停药与桥接护理：按医嘱执行停药与低分子肝素桥接，皮下注射后不按摩、观察注射部位血肿","术后出血观察：每小时观察切口渗血、引流液性状与量、皮下瘀斑与生命体征，异常立即报告","术后血栓观察：下肢肿胀与疼痛（DVT）、胸痛气促（PE）、神经系统症状，异常立即报告","用药恢复护理：确认止血后按时恢复抗凝/抗血小板，与口服药重叠期间监测凝血功能","宣教：抗凝治疗不可自行停药、识别出血与血栓症状、按时复查凝血功能、携带抗凝治疗卡（急诊提示）"],"diet":["服用华法林者：保持维生素K摄入相对稳定（绿叶蔬菜量不宜骤增骤减），避免大量饮酒","术后：清淡易消化饮食，避免过硬与刺激性食物（消化道出血风险）","避免含酒精饮料（影响抗凝药代谢与出血风险）","高纤维饮食保持大便通畅（避免用力致切口出血与血栓）","多饮水（心肾功能允许下）预防血液浓缩与血栓形成"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1413},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"8ad3c724d2a81aa1cd9183170fa0168e7ade87049073ca862a99f5c1b51b0c20","pinyin":"weishoushuqikangningyukangxuexiaobanyaowuguanli","initials":"wssqknykxxbywgl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","抗凝/抗血小板治疗适应证：房颤（卒中预防）、机械瓣膜、静脉血栓栓塞症（VTE）、冠心病支架术后、脑血管病\\n出血风险表现：术中与术后渗血、血肿、消化道出血、颅内出血（抗凝相关最危险）\\n血栓风险表现：脑卒中（房颤停抗凝）、支架内血栓（停抗血小板）、VTE复发（深静脉血栓/肺栓塞）\\n桥接抗凝相关：注射部位血肿、肝素诱导血小板减少（HIT）\\n术后恢复用药过早：切口血肿、引流增多、二次手术止血",60],["摘要","围手术期抗凝与抗血小板药物管理需平衡出血与血栓风险：根据手术出血风险与血栓风险决定停药时间、是否需要桥接抗凝（低分子肝素），术后恢复用药时机。原则是多学科评估、个体化决策，高危血栓患者需桥接治疗。",30],["疾病编码","Z92.1",30],["原首字母","wssqqkykxbygl",60]]},{"id":"orders-df53327c63bb357d6ac2","key":"v1-c9ccc21dfe2a3058|orders-df53327c63bb357d6ac2","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"输血指征与成分输血选择","category":"临床常用知识","raw":{"name":"输血指征与成分输血选择","category":"临床常用知识","summary":"输血需严格掌握指征，遵循『能不输则不输、能少输则少输、缺什么补什么』原则。常用成分：红细胞悬液（贫血/失血）、血小板（血小板减少/功能障碍）、新鲜冰冻血浆（凝血因子缺乏）、冷沉淀（纤维蛋白原缺乏）。输血需知情同意、交叉配血并监测输血反应。","symptoms":["急性失血表现：面色苍白、心率增快、血压下降、尿量减少、意识改变（失血性休克）","慢性贫血表现：乏力、活动后心悸气短、头晕、皮肤黏膜苍白","血小板减少/功能障碍：皮肤瘀点瘀斑、牙龈与鼻腔出血、消化道出血、颅内出血（危急）","凝血因子缺乏：伤口渗血不止、血肿、穿刺点渗血（肝病/DIC/大量输血）","输血反应表现：发热寒战、皮疹瘙痒、腰背痛与酱油色尿（溶血）、呼吸困难（TRALI/TACO）"],"diagnosis":["血常规（血红蛋白、红细胞压积、血小板）：输血指征核心指标（动态监测）","凝血功能（PT/APTT/FIB）+血小板：血浆与冷沉淀指征评估","血型鉴定+交叉配血：输血前必做（ABO、RhD）","出血量与失血速度评估：生命体征、尿量、血红蛋白动态（急性失血早期Hb可正常）","容量状态评估：血压、心率、中心静脉压、尿量、肺部听诊（TACO风险评估）","输血反应相关检查：再次核对血型、直接抗人球蛋白试验（DAT）、血浆游离血红蛋白、尿血红蛋白（溶血评估）","特殊人群评估：冠心病（Hb阈值提高）、慢性肾病、老年患者（个体化阈值）"],"infusion":["⚠️ 输血须严格核对（患者身份、血型、交叉配血、有效期），并使用输血器与生理盐水冲管！","方案1（红细胞悬液，纠正贫血与携氧能力）：","用法：一般指征 Hb<70g/L；冠心病/脑血管病/老年患者 Hb<80～90g/L 或有症状（心悸气短、心绞痛、意识改变）时输注；一般1U可提升Hb约10g/L；急性大失血按失血量输注（目标Hb 70～90g/L，活动性出血未控制时避免过度升压）","方案2（血小板）：","用法：血小板<10×10⁹/L（预防性输注）或<20×10⁹/L伴发热/感染或<50×10⁹/L拟手术/有活动性出血时输注；1个治疗量可提升血小板约20～30×10⁹/L；输注后1小时复查血小板（评估有效性）","方案3（新鲜冰冻血浆，补充凝血因子）：","用法：PT/APTT>正常1.5倍伴活动性出血或急诊手术、大量输血（>1个血容量）、肝病凝血障碍时输注；10～15ml/kg（一般2～4U）；输注后复查凝血功能","方案4（冷沉淀，补充纤维蛋白原）：","用法：纤维蛋白原<1.5g/L（或<2.0g/L伴出血）时输注；1U可提升纤维蛋白原约0.1～0.15g/L；一般10U起（按体重与纤维蛋白原水平）","📌 输血前核对与知情同意；每袋血输注时间不超过4小时；输血中与输血后1小时密切观察；避免与药物同通路；大量输血注意枸橼酸中毒（补钙）、低体温与高钾血症。"],"oral_medication":["⚠️ 输血同时或之后的口服支持治疗：","药物1（补铁，慢性贫血）：","用法：琥珀酸亚铁 0.1g bid～tid（餐后服，与维生素C同服促吸收）；避免与钙剂、浓茶同服〔调 ★ 铁负荷过多禁用；★ 与四环素/喹诺酮/左甲状腺素间隔2小时〕","药物2（叶酸与维生素B12）：","用法：叶酸 5mg qd（巨幼细胞贫血）；维生素B12 500μg 肌注 每月1次（吸收障碍者）","药物3（促红素，慢性肾病/肿瘤贫血）：","用法：重组人促红素 10000IU 皮下注射 每周1～2次（目标Hb 100～120g/L，避免过高增加血栓风险）","药物4（预防输血相关不良反应）：","用法：对乙酰氨基酚 0.5g（发热性非溶血反应，输血前按医嘱）；苯海拉明 25mg（过敏反应史者，遵医嘱）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 输血不是治疗贫血的首选（缺铁性贫血应补铁）；输血后观察血红蛋白提升与症状改善，避免不必要的输血（感染与免疫风险）。"],"treatment":["严格掌握指征：红细胞（Hb<70g/L或缺血症状）、血小板（<10×10⁹/L或<50×10⁹/L拟手术/出血）、血浆（凝血因子缺乏伴出血）、冷沉淀（纤维蛋白原<1.5g/L）","输血前准备：知情同意、血型鉴定与交叉配血、核对患者身份（腕带+血型单）、选择合适血制品与输血器","输血过程管理：先慢后快（前15分钟≤2ml/min）、全程监测生命体征（前15分钟每5分钟）、单袋输注不超过4小时、不与其他药物同通路","输血反应处理：立即停止输血、保留静脉通路（生理盐水）、核对身份与血型、报告并留取标本（DAT、血浆游离血红蛋白、尿血红蛋白）、按反应类型处理","大量输血管理：按1:1:1（红细胞:血浆:血小板）输注、注意枸橼酸中毒（补钙10ml/4～6U血）、低体温（加温输血）、高钾血症与凝血障碍","特殊人群：冠心病患者Hb阈值提高（80～90g/L）、老年与慢性肾病患者个体化、 Jehovah见证者（拒绝输血，用替代方案如铁剂、促红素、术中血液回收）","输血后评估：复查血红蛋白/血小板与凝血功能、评估症状改善、记录输血反应与效果","宣教：解释输血必要性与风险、输血后观察症状（发热、皮疹、尿色变化）并及时报告、识别输血传播疾病风险"],"management":["身份核对：输血前双人核对患者姓名、住院号、床号、血型、血袋号、交叉配血结果与有效期（核对失误是溶血反应主因）","输血监测：前15分钟床旁守护（每5分钟测生命体征），之后每30分钟观察；记录输血开始与结束时间、血袋号与用量","输血反应观察与处理：发热寒战、皮疹瘙痒、腰背痛、酱油色尿、呼吸困难、低血压；出现任一项立即停止输血并报告","血制品管理：血制品取回后30分钟内输注（血小板需快速输注）、不得加温（除专用加温器）、不得加入任何药物","出入量与容量：监测尿量与心肺听诊（TACO：输血相关循环超负荷，尤其老年与心功能不全者）","记录与追溯：完整记录血制品编号、输注时间、反应与处理（便于追溯与报告）","宣教：告知输血风险与必要性、输血后症状观察与报告、后续贫血治疗（铁剂/促红素）与随访"],"notes":["输血指征以临床与检验综合判断：红细胞 Hb<70g/L（冠心病/老年<80～90g/L），血小板<10×10⁹/L（拟手术<50×10⁹/L），血浆用于凝血因子缺乏伴出血","输血前双人核对身份与血型是防止溶血反应的关键（核对失误是最常见原因）","输血反应处理第一步是立即停止输血并保持静脉通路（生理盐水），同时核对与报告","大量输血按1:1:1输注并监测枸橼酸中毒（补钙）、低体温与高钾血症；输血加温可防低体温","避免不必要输血（感染、免疫抑制、TRALI/TACO风险）；缺铁性贫血优先补铁，慢性贫血可用促红素"],"emergency":["急性溶血反应（腰背痛、寒战高热、酱油色尿、低血压）→ 立即停止输血、生理盐水维持通路、补液利尿保护肾功能、报告并留取标本","过敏性休克（呼吸困难、喉头水肿、血压下降）→ 立即停止输血、肾上腺素 0.3～0.5mg 肌注、激素与抗组胺药、吸氧","输血相关急性肺损伤（TRALI，输血后6小时内呼吸困难与双肺浸润）→ 立即停止输血、吸氧、必要时机械通气","输血相关循环超负荷（TACO，呼吸困难、颈静脉怒张、肺水肿）→ 停止输血、半卧位、吸氧、利尿","大量输血致枸橼酸中毒（口周麻木、手足搐搦、QT延长）→ 静脉补钙（10%葡萄糖酸钙10ml）并监测血钙与心电图","输血后发热伴寒战（发热性非溶血反应/细菌污染）→ 停止输血、留取血袋送培养、抗感染与对症处理"],"pinyin":"sxzzycfxsxz","icd10":"Z51.3","physical_exam":["生命体征：血压、心率、呼吸、体温、血氧（输血反应监测：前15分钟每5分钟）","一般情况：面色苍白、皮肤湿冷、意识状态（贫血/失血/反应）","皮肤黏膜：皮疹与荨麻疹（过敏反应）、瘀点瘀斑（血小板减少）、黄疸（溶血）","心肺：心率与心律、呼吸音与湿啰音（TACO/TACO/TRALI）、颈静脉充盈","尿量与尿色：记录每小时尿量与颜色（酱油色尿提示溶血，少尿提示肾损伤）","出血征象：伤口渗血、牙龈与鼻腔出血、消化道出血（凝血障碍）","输血部位：静脉通路通畅性、穿刺部位渗血与血肿"],"lab_tests":["血常规（血红蛋白、红细胞压积、血小板）：输血指征与效果评估（输血后1小时与24小时复查）","凝血功能（PT/APTT/FIB）+D-二聚体：血浆与冷沉淀指征及DIC评估","血型鉴定+交叉配血（含抗体筛查）：输血前必查","输血反应检查：再次血型核对、直接抗人球蛋白试验（DAT）、血浆游离血红蛋白、结合珠蛋白、尿血红蛋白（溶血评估）","血培养（疑细菌污染）：血袋残液与患者血培养","肾功能+电解质（钾、钙）+血气分析：大量输血或溶血后监测","血袋残液检查（必要时）：细菌涂片与培养"],"nursing":["身份与血型核对：双人核对患者姓名、住院号、床号、血型、血袋号、交叉配血与有效期（防溶血反应）","输血监测：前15分钟床旁守护并每5分钟测生命体征，之后每30分钟观察；记录开始/结束时间与血袋号","输血反应识别与处理：发热寒战、皮疹、腰背痛、酱油色尿、呼吸困难、低血压——出现任一项立即停止输血、生理盐水维持通路并报告","血制品管理：取回30分钟内输注、单独通路不与药物混合、血小板快速输注、必要时使用输血加温器（大量输血）","容量与尿量监测：记录出入量与每小时尿量，观察肺部啰音与颈静脉充盈（TACO，尤其老年与心衰患者）","宣教：解释输血必要性与风险、输血后观察症状（发热、皮疹、尿色）并及时报告、贫血后续治疗与随访"],"diet":["输血前后：清淡易消化饮食，避免过饱（减轻心脏负荷，防TACO）","贫血患者：高蛋白、高铁食物（瘦肉、动物肝脏、深绿色蔬菜）+ 维生素C促进铁吸收","避免浓茶、咖啡与钙剂与铁剂同服（影响铁吸收）","心功能不全/老年患者：限制液体与钠盐（防输血相关循环超负荷）","多饮水（心肾功能允许下）促进代谢产物排泄（溶血后保护肾功能）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1414},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1e1c9567df97c9fd15c7709751e7269e2d8cf81304692f839759c1ae545ca061","pinyin":"shuxuezhizhengyuchengfenshuxuexuanze","initials":"sxzzycfsxxz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性失血表现：面色苍白、心率增快、血压下降、尿量减少、意识改变（失血性休克）\\n慢性贫血表现：乏力、活动后心悸气短、头晕、皮肤黏膜苍白\\n血小板减少/功能障碍：皮肤瘀点瘀斑、牙龈与鼻腔出血、消化道出血、颅内出血（危急）\\n凝血因子缺乏：伤口渗血不止、血肿、穿刺点渗血（肝病/DIC/大量输血）\\n输血反应表现：发热寒战、皮疹瘙痒、腰背痛与酱油色尿（溶血）、呼吸困难（TRALI/TACO）",60],["摘要","输血需严格掌握指征，遵循『能不输则不输、能少输则少输、缺什么补什么』原则。常用成分：红细胞悬液（贫血/失血）、血小板（血小板减少/功能障碍）、新鲜冰冻血浆（凝血因子缺乏）、冷沉淀（纤维蛋白原缺乏）。输血需知情同意、交叉配血并监测输血反应。",30],["疾病编码","Z51.3",30],["原首字母","sxzzycfxsxz",60]]},{"id":"orders-d93499531a5d2bc8e93b","key":"v1-c9ccc21dfe2a3058|orders-d93499531a5d2bc8e93b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"晕厥（鉴别与处理）","category":"内科-循环","raw":{"name":"晕厥（鉴别与处理）","category":"内科-循环","summary":"晕厥是短暂全脑低灌注导致的短暂意识丧失（TLOC），特点为快速发生、持续时间短、自行完全恢复。常见类型：神经介导性（血管迷走性、情境性）、体位性低血压、心源性（心律失常、结构性心脏病）与脑血管性。心源性晕厥预后最差，需重点排查。","symptoms":["发作前先兆：头晕、恶心、出汗、视物模糊、耳鸣（血管迷走性晕厥常见）","意识丧失（数秒至数分钟）、面色苍白、肢体软瘫，可伴短暂抽搐（易误诊为癫痫）","恢复：快速完全恢复，可有乏力与恶心，无持续意识障碍（与癫痫鉴别）","心源性：无先兆、运动中或平卧时发作、伴心悸胸痛（危险信号）","体位性：站立后发作，伴血压明显下降（老年、糖尿病、服用降压药或利尿剂者）"],"diagnosis":["详细病史（最重要）：发作前情境（站立、情绪、咳嗽、排尿）、先兆、持续时间、恢复过程、既往心脏病史与用药","体位血压测量：卧立位血压（站立3分钟内收缩压下降≥20mmHg或舒张压≥10mmHg为体位性低血压）","心电图（必查）：心律失常、QT延长、Brugada波、预激、传导阻滞、心肌缺血（异常者高度提示心源性）","心脏超声：结构性心脏病（主动脉瓣狭窄、肥厚型心肌病、心脏肿瘤、肺动脉高压）","动态心电图/Holter或植入式心电记录仪：反复发作且疑心律失常者","颈动脉窦按摩与直立倾斜试验：疑神经介导性晕厥（专科进行）","实验室：血常规（贫血）、血糖（低血糖）、电解质、心肌酶（心肌缺血）、D-二聚体（肺栓塞）、妊娠试验（育龄女性）","神经系统评估（疑脑血管/癫痫）：头颅CT/MRI、脑电图（抽搐者）"],"infusion":["⚠️ 晕厥急性期以体位与病因处理为主，用药按病因选择！","方案1（急性发作时体位与补液）：","用法：立即平卧、抬高下肢（促进静脉回流）；0.9%氯化钠 500～1000ml 静滴（低血压/脱水者）","方案2（血管迷走性晕厥反复发作）：","用法：0.9%氯化钠 静滴（扩容）；必要时阿托品 0.5mg 静推（心动过缓者）；米多君 2.5mg tid（口服，遵医嘱）","方案3（心源性晕厥，心律失常）：","用法：缓慢型心律失常——阿托品 0.5mg 静推（必要时重复），准备临时起搏；快速型——按心律失常处理（腺苷/胺碘酮/电复律）〔调 ★ 甲功异常、QT延长者禁用；肝功能不全减量；需监测甲功/肺〕","方案4（体位性低血压）：","用法：0.9%氯化钠 1000ml 静滴（补液扩容）；停用/调整降压药与利尿剂（遵医嘱）；必要时米多君 2.5～5mg tid 或 氟氢可的松 0.1mg qd（口服）","📌 心源性晕厥需住院评估与治疗（猝死风险）；血管迷走性晕厥以教育、扩容与物理反压动作为主；体位性低血压需调整药物与病因治疗。"],"oral_medication":["⚠️ 按晕厥类型选择长期用药：","药物1（血管迷走性晕厥）：","用法：米多君 2.5mg tid（α1激动剂，升压）；或 氟氢可的松 0.1mg qd（扩容，监测血压与血钾）；β受体阻滞剂证据有限（遵医嘱）","药物2（体位性低血压）：","用法：米多君 2.5～5mg tid（避免睡前服用）；氟氢可的松 0.1mg qd；同时增加盐与水摄入","药物3（心源性，按病因）：","用法：心律失常（抗心律失常药或起搏器/ICD）；冠心病（抗血小板+他汀+β受体阻滞剂）；心衰（规范心衰治疗）","药物4（基础病调整）：","用法：停用或减量致晕厥药物（α受体阻滞剂、利尿剂、硝酸酯类、抗抑郁药，遵医嘱调整）；贫血者补铁","📌 药物调整须在医师指导下进行（不可自行停药）；米多君与氟氢可的松需监测卧位高血压与电解质。"],"treatment":["急性期处理：立即平卧抬高下肢、保持气道通畅、监测生命体征与血糖；恢复后评估病因","危险分层：高危（运动中发作、无先兆、伴心悸胸痛、心电图异常、结构性心脏病、老年、家族猝死史）→ 住院评估；低危（典型血管迷走性、有先兆、无心脏病）→ 门诊随访","病因治疗：心源性（起搏器/ICD、血运重建、瓣膜手术）、体位性低血压（调整药物、扩容、弹力袜）、神经介导性（教育+物理反压+扩容±药物）、脑血管性（抗血小板/抗凝、血管评估）","血管迷走性晕厥管理：避免诱因（久站、闷热、脱水）、识别先兆并立即平卧、增加盐与水摄入、物理反压动作（交叉腿、握拳）、必要时药物","体位性低血压管理：缓慢起身、睡眠抬高床头、弹力袜与腹带、增加盐与水、调整降压药与利尿剂","心电监测与起搏/除颤：反复心源性晕厥者植入式心电记录仪或ICD评估","宣教：避免驾驶与高危作业（反复发作未明确病因者）、家属学习急救（意识丧失时保护气道）、识别危险症状及时就诊","随访：按病因定期随访（心内科/神经内科），监测治疗效果与复发"],"management":["急性发作护理：立即平卧抬高下肢、松解衣领、保持气道通畅、测血压与血糖（低血糖者立即补糖）","生命体征与心律监测：持续心电监护（疑心源性者），记录晕厥发作时的心律变化（必要时长程监测）","安全护理：发作时防跌倒与外伤（加床档、地面防滑、呼叫器置于手边）、避免独处（高危患者）","病史与诱因记录：详细记录发作前情境、先兆、持续时间与恢复过程（诊断关键信息）","宣教：避免诱因（久站、闷热、脱水、突然起身）、识别先兆立即坐下或平卧、增加盐与水摄入、物理反压动作（交叉腿、握拳）","高危患者管理：限制驾驶与高危作业、家属学习急救方法、按时随访与用药（不可自行停药）"],"notes":["晕厥诊断的关键是详细病史（发作情境、先兆、持续时间与恢复过程），而非单纯依赖检查","心源性晕厥预后最差（猝死风险高）：运动中发作、无先兆、伴心悸胸痛、心电图异常或结构性心脏病者需住院评估","短暂抽搐可见于晕厥（脑缺血致肌阵挛），需与癫痫鉴别（晕厥恢复快、无发作后意识模糊与舌咬伤）","体位性低血压常见于老年、糖尿病与服用降压药/利尿剂者：需测量卧立位血压并调整用药","反复晕厥且病因不明者应限制驾驶与高危作业，并考虑植入式心电记录仪长期监测"],"emergency":["晕厥伴胸痛、心悸与心电图ST段改变（急性心肌梗死/心律失常）→ 立即心电监护与心内科急会诊","晕厥伴呼吸困难与低氧（肺栓塞）→ 立即评估并抗凝/溶栓治疗","晕厥后持续意识障碍或神经系统定位体征（脑卒中）→ 立即头颅CT与卒中中心评估","晕厥伴血压显著下降与休克表现（心脏压塞/大出血）→ 立即抢救与病因处理","缓慢型心律失常致反复晕厥（阿-斯综合征）→ 立即阿托品/临时起搏，评估永久起搏指征"],"pinyin":"yjbbycl","icd10":"R55","physical_exam":["生命体征：卧位与立位血压（间隔1～3分钟，必要时3、5分钟）、心率、呼吸、血氧、体温","意识与神经系统：意识状态、瞳孔、肢体肌力、病理反射、舌咬伤（癫痫鉴别）","心脏：心音、杂音（主动脉瓣狭窄、肥厚型心肌病）、心律不齐、颈静脉充盈","血管：双侧脉搏与血压差异（锁骨下动脉窃血、主动脉夹层）、颈动脉杂音","皮肤黏膜：面色苍白、发绀、出血点（贫血/出血）、脱水征","神经系统定位：偏瘫、失语、视野缺损（脑血管性晕厥）","诱因相关：颈动脉窦按摩反应（专科进行）、排尿/咳嗽/吞咽相关（情境性晕厥）"],"lab_tests":["心电图（必查）+动态心电图/Holter：心律失常、QT延长、Brugada波、传导阻滞与心肌缺血","卧立位血压测量：体位性低血压诊断（标准方法）","心脏超声：结构性心脏病（主动脉瓣狭窄、肥厚型心肌病、心脏肿瘤）","血常规（贫血）+血糖（低血糖）+电解质+肾功能：常见可逆病因筛查","心肌酶（肌钙蛋白）+BNP：心肌缺血与心衰评估","D-二聚体+血气分析（疑肺栓塞）+胸部CTPA（必要时）","头颅CT/MRI+脑电图（疑脑血管/癫痫）：神经系统评估","妊娠试验（育龄女性）+直立倾斜试验（疑神经介导性，专科）"],"nursing":["发作时护理：立即平卧抬高下肢、松解衣领、保持气道通畅、测血压与指尖血糖，记录发作时间与表现","安全护理：加床档、地面防滑、呼叫器置于手边、高危患者避免独处与独自下床活动","监测护理：持续心电监护（疑心源性）、记录血压与心律变化，必要时配合长程心电监测","病史采集：详细记录发作前情境、先兆、持续时间与恢复过程（为医师诊断提供关键信息）","宣教：识别先兆并立即坐下/平卧、避免诱因（久站、闷热、脱水、突然起身）、增加盐与水摄入、物理反压动作（交叉腿、握拳、蹲下）","高危管理：限制驾驶与高危作业、家属学习急救（意识丧失时保护气道与呼叫120）、按时随访与用药"],"diet":["增加盐与水分摄入（血管迷走性与体位性低血压者，按医嘱每日饮水2～2.5L）","少量多餐（避免餐后低血压）；避免大量饮酒与过热环境","咖啡因可短期改善体位性低血压（按医嘱适量）","贫血者高蛋白、高铁饮食（瘦肉、动物肝脏、深绿色蔬菜）+ 维生素C","合并心衰与高血压者按相应饮食管理（限盐限水），避免自行大量饮水"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1415},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6ac3a946f7bee73fd54e089504558505daa8efdc102e592470f67449ce244747","pinyin":"yunjue（jianbieyuchuli）","initials":"yj（jbycl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发作前先兆：头晕、恶心、出汗、视物模糊、耳鸣（血管迷走性晕厥常见）\\n意识丧失（数秒至数分钟）、面色苍白、肢体软瘫，可伴短暂抽搐（易误诊为癫痫）\\n恢复：快速完全恢复，可有乏力与恶心，无持续意识障碍（与癫痫鉴别）\\n心源性：无先兆、运动中或平卧时发作、伴心悸胸痛（危险信号）\\n体位性：站立后发作，伴血压明显下降（老年、糖尿病、服用降压药或利尿剂者）",60],["摘要","晕厥是短暂全脑低灌注导致的短暂意识丧失（TLOC），特点为快速发生、持续时间短、自行完全恢复。常见类型：神经介导性（血管迷走性、情境性）、体位性低血压、心源性（心律失常、结构性心脏病）与脑血管性。心源性晕厥预后最差，需重点排查。",30],["疾病编码","R55",30],["原首字母","yjbbycl",60]]},{"id":"orders-3aa508f73619e6d894cb","key":"v1-c9ccc21dfe2a3058|orders-3aa508f73619e6d894cb","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"慢性咳嗽（病因与处理）","category":"内科-呼吸","raw":{"name":"慢性咳嗽（病因与处理）","category":"内科-呼吸","summary":"慢性咳嗽指咳嗽持续>8周且胸部影像无明显异常，常见三大病因：上气道咳嗽综合征（UACS，鼻后滴漏）、咳嗽变异性哮喘（CVA）、胃食管反流性咳嗽（GERC）；其他包括嗜酸粒细胞性支气管炎（EB）、变应性咳嗽（AC）、ACEI类药物性咳嗽与感染后咳嗽。治疗关键是病因诊断与针对性治疗。","symptoms":["咳嗽>8周（干咳或伴少量白痰）、夜间或晨起加重（CVA/鼻后滴漏）","上气道咳嗽综合征：鼻塞、流涕、咽部异物感、频繁清嗓、咽后壁滤泡增生","咳嗽变异性哮喘：刺激性干咳、夜间/凌晨加重、遇冷空气或运动后加重、无喘息","胃食管反流性咳嗽：餐后或平卧时加重、伴反酸烧心、咳嗽为唯一表现（部分患者无反流症状）","警示症状（需排除严重疾病）：咯血、消瘦、发热、呼吸困难、吸烟史>20包年（肺癌风险）"],"diagnosis":["胸部X线/CT（必查）：排除肺部疾病（肿瘤、结核、间质性肺病、支气管扩张）","肺功能+支气管激发试验：咳嗽变异性哮喘（激发试验阳性、支气管舒张试验可阳性）","诱导痰嗜酸粒细胞计数：嗜酸粒细胞性支气管炎（>3%）、CVA鉴别","食管pH监测/阻抗-pH监测：胃食管反流性咳嗽（金标准，必要时）","鼻窦CT/鼻内镜：上气道咳嗽综合征（鼻窦炎、过敏性鼻炎）","血常规+总IgE+变应原检测：过敏性疾病评估","用药史核查：ACEI类药物（诱发干咳，停药后1～4周缓解）","必要时支气管镜：气道异物、肿瘤与支气管内膜结核"],"infusion":["⚠️ 慢性咳嗽以口服治疗为主，静脉用药仅用于急性加重或合并感染！","","方案1（合并急性感染/支气管痉挛加重）：","  用法：0.9%氯化钠 静滴；多索茶碱 0.2g 静滴 qd（支气管痉挛）；氨溴索 30mg 静滴 bid（化痰）〔调 妊娠早期禁用；胃溃疡者慎用〕","","方案2（重症哮喘样发作）：","  用法：甲泼尼龙 40mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 q12h；雾化吸入（布地奈德+特布他林 q6h）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（合并细菌感染）：","  用法：头孢呋辛 1.5g 静滴 q8h 或 左氧氟沙星 0.5g 静滴 qd（按痰培养与病情调整）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","","方案4（支持治疗）：","  用法：0.9%氯化钠 静滴；必要时雾化吸入（生理盐水+祛痰药）","","📌 慢性咳嗽的治疗核心是病因诊断与针对性治疗（不要盲目长期使用抗生素与镇咳药）；ACEI相关咳嗽应停药观察。"],"oral_medication":["⚠️ 按病因选择药物（咳嗽变异性哮喘与EB对激素反应好）：","方案1（咳嗽变异性哮喘/嗜酸粒细胞性支气管炎）：","用法：吸入性糖皮质激素（布地奈德/氟替卡松）1～2吸 bid（疗程≥8周）；必要时联合 LABAs 或 白三烯受体拮抗剂（孟鲁司特 10mg qn）","方案2（上气道咳嗽综合征）：","用法：鼻用糖皮质激素（糠酸莫米松鼻喷剂 每侧2喷 qd）+ 抗组胺药（氯雷他定 10mg qd 或 西替利嗪 10mg qn）；鼻窦炎者必要时抗生素（阿莫西林克拉维酸 0.625g tid×10～14天）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","方案3（胃食管反流性咳嗽）：","用法：质子泵抑制剂（艾司奥美拉唑 20～40mg bid，餐前30分钟，疗程≥8周）+ 促动力药（莫沙必利 5mg tid）；睡前3小时不进食〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","方案4（对症与诱因）：","用法：复方甲氧那明 2粒 tid（短期缓解症状）；停用ACEI类药物（改用ARB）；戒烟","📌 慢性咳嗽避免长期使用中枢性镇咳药（可待因）掩盖病情；PPI与吸入激素需足疗程（8周以上）后评估疗效。"],"treatment":["病因导向治疗：CVA/EB（吸入激素±LABA，疗程8周以上）、UACS（鼻用激素+抗组胺药±抗生素）、GERC（PPI+促动力药≥8周）","药物性咳嗽处理：停用ACEI类药物（改用ARB），停药后1～4周咳嗽缓解可确诊","感染后咳嗽：多为自限性（3～8周），必要时短期使用抗组胺药与镇咳药，不用抗生素","难治性咳嗽处理：评估依从性与诊断正确性（多病因共存常见），多病因联合治疗，必要时专科（呼吸科/耳鼻喉/消化）会诊","警示症状处理：咯血、消瘦、吸烟史长者需支气管镜与CT排除肿瘤与结核","非药物措施：戒烟、避免冷空气与刺激物、鼻盐水冲洗、抬高床头（GERD）、治疗过敏性鼻炎","疗效评估：治疗2～4周复诊评估，8周无效者重新评估诊断（多病因或误诊）","宣教：解释慢性咳嗽多为病因明确可治、坚持足疗程用药、避免自行使用抗生素与镇咳药"],"management":["病史采集（关键）：咳嗽持续时间、性质、诱因（冷空气、运动、餐后、体位）、伴随症状（鼻塞、反酸、喘息）与用药史（ACEI）","治疗依从性管理：强调足疗程用药（吸入激素与PPI需8周以上）、教会吸入装置正确使用方法","症状与疗效记录：咳嗽日记（频次、夜间影响、诱因）、复诊时评估变化","诱因控制：戒烟、避免过敏原与刺激气体、鼻部护理（盐水冲洗）、睡前3小时禁食（GERD）","口腔与吸入护理：吸入激素后漱口（防口腔念珠菌）、鼻喷剂正确使用方法指导","宣教：慢性咳嗽病因明确、治疗需时间（通常2～8周见效）、出现咯血与消瘦立即就诊、避免滥用抗生素与镇咳药"],"notes":["慢性咳嗽三大常见病因：上气道咳嗽综合征、咳嗽变异性哮喘、胃食管反流性咳嗽（占70%以上）","咳嗽变异性哮喘以咳嗽为唯一表现（无喘息），支气管激发试验阳性可确诊，对吸入激素反应好","胃食管反流性咳嗽可无反酸烧心症状（'沉默性反流'），需PPI足疗程（8周）治疗","ACEI类药物相关咳嗽发生率约10%～20%（停药后1～4周缓解），是常被忽略的可逆病因","慢性咳嗽患者不应长期使用抗生素与中枢镇咳药（掩盖病情、延误诊断）"],"emergency":["咳嗽伴咯血、消瘦、声音嘶哑（疑肺癌/结核）→ 尽快胸部CT与支气管镜检查","咳嗽伴呼吸困难与喘鸣加重（哮喘急性发作）→ 吸入β2激动剂+激素，必要时静脉激素与吸氧","咳嗽伴大量脓痰与发热（支气管扩张合并感染/肺脓肿）→ 抗感染+体位引流，必要时住院","咳嗽伴胸痛与气促（气胸/肺栓塞）→ 急诊影像与相应处理","突发剧烈咳嗽伴胸痛（肋骨骨折/气胸）→ 影像评估与镇痛"],"pinyin":"mxksbyycl","icd10":"R05","physical_exam":["生命体征：体温、呼吸频率、血氧（有无呼吸功能受损）","上气道：鼻腔黏膜与分泌物、鼻窦压痛、咽后壁滤泡（'鹅卵石样'）与分泌物（UACS）","肺部：呼吸音、哮鸣音（CVA/哮喘）、湿啰音（感染/支扩）、呼吸音减弱","心脏：心率、心音（心衰致咳嗽）","腹部：上腹压痛与反流征象（GERD）","其他：杵状指（支扩/肺癌）、颈部淋巴结（肿瘤）、吸烟体征（牙渍、口气）","用药史核对：ACEI类药物使用（药物性咳嗽）"],"lab_tests":["胸部X线/CT（必查）：排除肿瘤、结核、间质性肺病与支气管扩张","肺功能+支气管激发试验+舒张试验：咳嗽变异性哮喘诊断","诱导痰细胞学（嗜酸粒细胞计数）：EB与CVA鉴别（>3%提示嗜酸粒细胞性气道炎症）","血常规+总IgE+变应原检测：过敏性疾病评估","鼻窦CT/鼻内镜：上气道咳嗽综合征","食管pH-阻抗监测（必要时）：胃食管反流性咳嗽（金标准）","支气管镜（必要时）：气道异物、肿瘤、支气管内膜结核"],"nursing":["病史记录：详细记录咳嗽持续时间、性质、诱因与伴随症状（诊断关键）","用药指导：教会吸入装置（压力定量吸入器/干粉吸入器）正确使用方法，吸入激素后漱口；PPI餐前30分钟服用","症状日记指导：指导记录咳嗽频次、夜间影响与诱因，复诊时提供","诱因控制宣教：戒烟、避免过敏原与冷空气、鼻部盐水冲洗、睡前3小时禁食与抬高床头（GERD）","疗效随访：治疗2～4周提醒复诊评估，强调足疗程（吸入激素与PPI需8周以上）","宣教：避免滥用抗生素与中枢镇咳药、出现咯血/消瘦/呼吸困难立即就诊"],"diet":["胃食管反流性咳嗽：避免过饱与睡前进食（睡前3小时禁食）、减少高脂、巧克力、咖啡、浓茶与辛辣食物","少量多餐，餐后避免立即平卧（保持直立1～2小时）","过敏性咳嗽：避免已知过敏食物（海鲜、坚果等）","多饮水（稀释痰液），戒烟酒","肥胖者控制体重（减轻腹压与反流）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1416},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d59e7b0d791d0cbc87463404f7bba5b1c509b7635c1a29048bb0f05316a88401","pinyin":"manxingkesou（bingyinyuchuli）","initials":"mxks（byycl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","咳嗽>8周（干咳或伴少量白痰）、夜间或晨起加重（CVA/鼻后滴漏）\\n上气道咳嗽综合征：鼻塞、流涕、咽部异物感、频繁清嗓、咽后壁滤泡增生\\n咳嗽变异性哮喘：刺激性干咳、夜间/凌晨加重、遇冷空气或运动后加重、无喘息\\n胃食管反流性咳嗽：餐后或平卧时加重、伴反酸烧心、咳嗽为唯一表现（部分患者无反流症状）\\n警示症状（需排除严重疾病）：咯血、消瘦、发热、呼吸困难、吸烟史>20包年（肺癌风险）",60],["摘要","慢性咳嗽指咳嗽持续>8周且胸部影像无明显异常，常见三大病因：上气道咳嗽综合征（UACS，鼻后滴漏）、咳嗽变异性哮喘（CVA）、胃食管反流性咳嗽（GERC）；其他包括嗜酸粒细胞性支气管炎（EB）、变应性咳嗽（AC）、ACEI类药物性咳嗽与感染后咳嗽。治疗关键是病因诊断与针对性治疗。",30],["疾病编码","R05",30],["原首字母","mxksbyycl",60]]},{"id":"orders-c5f96b20a640f2912c15","key":"v1-c9ccc21dfe2a3058|orders-c5f96b20a640f2912c15","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"过敏性肺炎（外源性）","category":"内科-呼吸","raw":{"name":"过敏性肺炎（外源性）","category":"内科-呼吸","summary":"过敏性肺炎（外源性变应性肺泡炎，HP）是反复吸入有机粉尘抗原（发霉干草、鸟类蛋白、加湿器与空调污染、蘑菇与木材粉尘）引起的免疫介导性肺间质炎症。分为急性（接触后4～12小时发热、咳嗽、气促）、亚急性与慢性（进行性纤维化）。治疗核心是脱离抗原接触±糖皮质激素。","symptoms":["急性：接触抗原后4～12小时出现发热、寒战、干咳、胸闷与气促，脱离接触后数天缓解（反复发作）","亚急性：隐匿起病的咳嗽、气促、乏力、食欲减退与体重下降（数周至数月）","慢性：进行性呼吸困难、干咳、杵状指与呼吸衰竭（不可逆纤维化）","体征：双肺底爆裂音（velcro啰音）、紫绀、活动后气促加重","抗原接触史：鸟类（鸽、鹦鹉）饲养、发霉干草/谷物、加湿器与空调、蘑菇种植、木材加工"],"diagnosis":["胸部高分辨CT（HRCT）：急性为磨玻璃影与小结节影；慢性为纤维化、网格影与蜂窝（以上肺为主，与IPF不同）","肺功能：限制性通气障碍与弥散功能下降（DLCO降低）","支气管肺泡灌洗（BAL）：淋巴细胞增多（>40%～50%）伴CD4/CD8比值降低（诊断价值高）","血清特异性IgG抗体：针对鸟蛋白、嗜热放线菌等抗原（支持诊断，需结合临床）","抗原暴露史与激发试验（必要时）：详细询问职业与环境暴露（关键）","肺活检（必要时）：肉芽肿性炎症（诊断不明确或需与IPF鉴别）","血常规+CRP+血气分析：炎症与低氧血症评估；排除感染"],"infusion":["⚠️ 以脱离抗原与激素治疗为主，静脉用药用于重症！","","方案1（重症急性发作，糖皮质激素）：","  用法：甲泼尼龙 40～80mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（或 q12h，按病情），症状缓解后逐渐减量并过渡口服〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（低氧血症支持）：","  用法：0.9%氯化钠 静滴；鼻导管吸氧（维持SpO₂≥90%），必要时无创/有创机械通气","","方案3（合并感染/鉴别感染）：","  用法：头孢呋辛 1.5g 静滴 q8h 或 莫西沙星 0.4g 静滴 qd（在明确病原前短期经验性治疗）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案4（慢性纤维化支持）：","  用法：0.9%氯化钠 静滴；必要时抗纤维化治疗（吡非尼酮/尼达尼布，专科评估）；氧疗","","📌 治疗核心是彻底脱离抗原接触（脱离后常迅速缓解）；激素用于中重度或进展性病例，需逐渐减量（避免复发）。"],"oral_medication":["⚠️ 口服激素与对症为主：","药物1（糖皮质激素，中重度）：","用法：泼尼松 0.5～1mg/kg/日（晨起顿服，疗程4～8周后逐渐减量，总疗程3～6个月）；密切监测激素不良反应〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物2（抗纤维化，慢性进展型，专科评估）：","用法：吡非尼酮 200mg tid 起（逐渐加量）或 尼达尼布 150mg bid；监测肝功能与胃肠道反应","药物3（对症）：","用法：孟鲁司特 10mg qn（辅助）；氨溴索 30mg tid（化痰）；必要时支气管扩张剂（吸入）〔调 妊娠早期禁用；胃溃疡者慎用〕","药物4（氧疗与其他）：","用法：碳酸钙D3 600mg qd（长期激素者）；必要时疫苗（流感、肺炎球菌）","📌 避免再次接触抗原是关键（否则激素减量时易复发）；吸烟者戒烟（加重肺损伤）。"],"treatment":["脱离抗原暴露（最重要）：停止接触鸟类、发霉干草、污染加湿器与空调等；职业性者调离环境并改善通风与防护","糖皮质激素：中重度或进展性病例使用泼尼松 0.5～1mg/kg/日（口服）或甲泼尼龙静滴，逐渐减量（总疗程3～6个月）","氧疗与呼吸支持：低氧血症者吸氧，呼吸衰竭者无创/有创机械通气","抗纤维化治疗：慢性进展性纤维化者（吡非尼酮/尼达尼布）由呼吸专科评估","并发症处理：呼吸衰竭、肺心病、感染（激素治疗期间警惕）","鉴别诊断处理：与IPF、结节病、感染、嗜酸粒细胞性肺炎鉴别（BAL与活检）","随访与监测：肺功能与HRCT随访（每3～6个月），评估纤维化进展与治疗反应","宣教：避免抗原再暴露（家庭环境与职业防护）、识别急性发作症状（接触后发热气促）及时就诊、戒烟、接种疫苗"],"management":["暴露史采集（关键）：详细询问职业、居住环境、宠物（鸟类）、加湿器与空调使用史，记录抗原接触与症状时间关系","环境干预指导：清除霉变物质、更换/清洁加湿器与空调、避免饲养鸟类、改善通风、职业防护（口罩/呼吸器）","用药护理：激素按医嘱逐渐减量（不可骤停）、监测血糖、血压与感染征象；抗纤维化药监测肝功能与胃肠道反应","氧疗护理：按医嘱吸氧（维持SpO₂≥90%），观察氧疗效果与二氧化碳潴留（慢性者低流量吸氧）","肺功能与影像随访：按时复查肺功能、HRCT与血气，记录结果变化","宣教：抗原接触是病因（必须避免）、激素不可自行停药、出现发热与气促加重及时就诊、戒烟与疫苗接种"],"notes":["过敏性肺炎的诊断依赖抗原暴露史+BAL淋巴细胞增多+HRCT表现，脱离抗原是最好的'治疗'","急性发作多在抗原接触后4～12小时出现（发热、咳嗽、气促），脱离接触后迅速缓解——反复发作提示持续暴露","HRCT上肺为主的纤维化与蜂窝影有助于与特发性肺纤维化（IPF，下肺为主）鉴别","长期激素治疗需缓慢减量（突然停药易复发），并监测感染、血糖、血压与骨质疏松","预防胜于治疗：改善居住与工作环境、避免鸟类与霉变物质、加湿器与空调定期清洁是根本措施"],"emergency":["接触抗原后突发严重呼吸困难与低氧（急性重症发作）→ 立即吸氧+静脉激素，必要时机械通气","呼吸衰竭（SpO₂<90%、呼吸窘迫）→ 无创/有创机械通气支持并转ICU","激素治疗期间高热与肺部新发浸润（继发感染）→ 抗感染+病原学检查，必要时减停激素","慢性患者突发气胸（胸痛+呼吸困难）→ 急诊胸部影像与闭式引流","咯血伴呼吸困难加重 → 急诊评估（感染、气胸或疾病进展）"],"pinyin":"gmxgywysx","icd10":"J67.9","physical_exam":["生命体征：体温（急性发作可发热）、呼吸频率、血氧、心率","肺部：双肺底爆裂音（velcro啰音，特征性）、哮鸣音、呼吸音减弱","一般情况：气促程度（活动后加重）、紫绀、杵状指（慢性纤维化）","心脏：心率增快、肺动脉瓣区第二心音亢进（肺心病）","暴露相关：居住环境询问（霉变、鸟类、加湿器）、职业暴露（农业、蘑菇、木材加工）","体重与营养：消瘦（慢性病程）","其他：皮肤与关节（结缔组织病鉴别）、淋巴结（结节病鉴别）"],"lab_tests":["胸部高分辨CT（HRCT）：磨玻璃影、小结节影、马赛克灌注与纤维化（上肺为主）","肺功能+弥散功能：限制性通气障碍与DLCO下降（随访核心）","支气管肺泡灌洗（BAL）：淋巴细胞增多（>40%）伴CD4/CD8降低（诊断价值高）","血清特异性IgG抗体（鸟蛋白、嗜热放线菌等）：支持诊断","血气分析：低氧血症与肺泡-动脉氧分压差增大","血常规+CRP+PCT：炎症与感染鉴别","肺活检（必要时）：肉芽肿性炎与机化性肺炎（诊断不明确或需与IPF鉴别）"],"nursing":["暴露史与环境干预：详细采集暴露史，指导清除霉变物、清洁加湿器与空调、避免鸟类、改善通风与职业防护","氧疗护理：按医嘱吸氧并维持SpO₂≥90%，观察氧疗效果与呼吸状态变化","用药护理：激素按医嘱逐渐减量（不可骤停）、监测血糖、血压、体重与感染征象；抗纤维化药监测肝功能与胃肠道反应","呼吸功能观察：记录呼吸频率、血氧与活动耐量变化，异常立即报告","随访提醒：按时复查肺功能、HRCT与血气，记录并对比结果","宣教：避免抗原再暴露是关键、激素不可自行停药、出现发热与气促加重及时就诊、戒烟与疫苗接种"],"diet":["高蛋白、高热量饮食（慢性消耗与呼吸功增加）；少量多餐（避免饱胀影响呼吸）","长期激素治疗：低盐低糖饮食、补充钙与维生素D（防骨质疏松）","避免已知过敏食物；均衡蔬果摄入（抗氧化）","戒烟、避免饮酒；保持足够水分（稀释痰液，心功能允许下）","慢性低氧与呼吸衰竭者：营养支持（必要时肠内营养），避免过度碳水（减少二氧化碳产生）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1417},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"6ab1cb2a16affa45f45516f177d448ec8367c03ddcf2c234640a63c79823be99","pinyin":"guominxingfeiyan（waiyuanxing）","initials":"gmxfy（wyx）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性：接触抗原后4～12小时出现发热、寒战、干咳、胸闷与气促，脱离接触后数天缓解（反复发作）\\n亚急性：隐匿起病的咳嗽、气促、乏力、食欲减退与体重下降（数周至数月）\\n慢性：进行性呼吸困难、干咳、杵状指与呼吸衰竭（不可逆纤维化）\\n体征：双肺底爆裂音（velcro啰音）、紫绀、活动后气促加重\\n抗原接触史：鸟类（鸽、鹦鹉）饲养、发霉干草/谷物、加湿器与空调、蘑菇种植、木材加工",60],["摘要","过敏性肺炎（外源性变应性肺泡炎，HP）是反复吸入有机粉尘抗原（发霉干草、鸟类蛋白、加湿器与空调污染、蘑菇与木材粉尘）引起的免疫介导性肺间质炎症。分为急性（接触后4～12小时发热、咳嗽、气促）、亚急性与慢性（进行性纤维化）。治疗核心是脱离抗原接触±糖皮质激素。",30],["疾病编码","J67.9",30],["原首字母","gmxgywysx",60]]},{"id":"orders-0148bac3c5219f2bb769","key":"v1-c9ccc21dfe2a3058|orders-0148bac3c5219f2bb769","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"下消化道出血","category":"内科-消化","raw":{"name":"下消化道出血","category":"内科-消化","summary":"下消化道出血指屈氏韧带以下消化道（小肠、结肠、直肠与肛门）出血，表现为便血（鲜红色、暗红色或果酱样）、黑便（小肠出血）与贫血。常见病因：结肠息肉与肿瘤、结肠炎（缺血性、溃疡性、感染性）、血管畸形、痔与肛裂、小肠病变（血管畸形、肿瘤、克罗恩病）。","symptoms":["鲜血便（直肠与肛门病变）、暗红色血便（结肠病变）、果酱样便（肠套叠、阿米巴）","黑便（小肠出血、血液停留时间长）","腹痛（缺血性结肠炎、肠套叠、炎症性肠病）伴腹泻或便秘","头晕、心悸、乏力与晕厥（大量出血致失血性休克）","伴随症状：消瘦与排便习惯改变（肿瘤）、发热与里急后重（感染性结肠炎）"],"diagnosis":["生命体征与出血量评估：血压、心率、尿量与意识（大量出血需紧急处理）","血常规+血型+交叉配血+凝血功能：动态监测血红蛋白与备血","直肠指检与肛门镜：痔、肛裂与直肠病变（简单有效，勿遗漏）","结肠镜（首选，24小时内）：明确结肠病变并可行内镜下止血（活动性出血者肠道准备受限时可先行CT血管造影）","CT血管造影（CTA）：活动性出血（>0.5ml/min）定位（介入栓塞前评估）","小肠评估：胶囊内镜、小肠镜、CT/MR小肠成像（结肠镜阴性且出血持续）","核素扫描（99mTc标记红细胞）：间断出血定位（敏感性高、定位不精确）","血管造影（DSA）：活动性出血定位与栓塞治疗（介入）"],"infusion":["⚠️ 按出血量与病因选择，须先稳定生命体征！","","方案1（液体复苏与输血）：","  用法：平衡盐溶液/0.9%氯化钠 快速补液；红细胞悬液（目标Hb 70～90g/L，冠心病者80～100g/L）；必要时新鲜冰冻血浆（凝血障碍）","","方案2（止血药物）：","  用法：氨甲环酸 1g（NS 100ml 或 5%GS 100ml）静滴（8小时内，慎用于血栓风险者）；生长抑素 3mg/12h 泵入（小肠出血/血管畸形，遵医嘱）；维生素K1 10mg 静滴（凝血障碍）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案3（抑酸与肠道休息）：","  用法：艾司奥美拉唑 40mg 静推 q12h（合并上消化道出血或应激性溃疡）；0.9%氯化钠 静滴维持〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","方案4（病因治疗）：","  用法：感染性结肠炎——左氧氟沙星 0.5g 静滴 qd + 甲硝唑 0.5g 静滴 q8h；缺血性结肠炎——补液、禁食、抗感染、必要时手术；炎症性肠病——激素或生物制剂（专科）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","","📌 下消化道出血处理顺序：稳定生命体征→定位（结肠镜/CTA）→止血（内镜/介入/手术）；避免盲目使用止血药与抗生素。"],"oral_medication":["⚠️ 出血期禁食或流质，稳定后用药：","药物1（止血与黏膜保护）：","用法：凝血酶冻干粉 口服/灌肠（局部止血，遵医嘱）；蒙脱石散 3g tid（黏膜保护）〔调 ★ 与其他药间隔1-2小时；肠梗阻禁用〕","药物2（病因治疗）：","用法：溃疡性结肠炎——美沙拉嗪 1g qid（口服）+ 局部灌肠剂；感染——诺氟沙星 0.3g bid + 甲硝唑 0.4g tid（疗程3～5天）〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","药物3（补铁，慢性失血性贫血）：","用法：琥珀酸亚铁 0.1g bid～tid + 维生素C 0.2g tid〔调 ★ 铁负荷过多禁用；★ 与四环素/喹诺酮/左甲状腺素间隔2小时〕","药物4（对症）：","用法：对乙酰氨基酚 0.5g 必要时（避免NSAIDs）；益生菌（双歧杆菌 2粒 bid）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 避免NSAIDs与抗凝/抗血小板药物（加重出血）；痔出血者局部用药（复方角菜酸酯栓）与坐浴。"],"treatment":["生命体征稳定与复苏：建立静脉通路、补液输血、纠正凝血障碍（第一步）","定位诊断：结肠镜（首选，可同时内镜下止血：钛夹、电凝、1:10000肾上腺素局部注射）；活动性出血可行CT血管造影","介入治疗：DSA血管造影+栓塞（活动性出血不能内镜处理者）","手术治疗：内镜与介入失败、持续大量出血、肿瘤、缺血性肠坏死或穿孔者行手术切除","病因治疗：结肠息肉（内镜切除）、肿瘤（手术+肿瘤治疗）、缺血性结肠炎（支持治疗±手术）、炎症性肠病（专科用药如美沙拉秦）、感染性结肠炎（抗感染）","痔与肛裂出血：保守治疗（坐浴、通便、局部用药），必要时手术（痔切除、内痔套扎）","支持治疗：补铁（硫酸亚铁0.3g tid口服，慢性失血）、营养支持、必要时输注红细胞","随访：结肠镜复查（息肉与肿瘤术后）、贫血纠正评估、避免NSAIDs与抗凝药滥用"],"management":["出血监测：记录便血次数、量与颜色，监测生命体征与血红蛋白（每4～6小时），异常立即报告","肠道准备与检查配合：按医嘱完成肠道准备（活动性大出血者避免口服清肠液，配合CT血管造影）","禁食与饮食过渡：活动性出血期禁食、静脉补液；出血停止后从温凉流质逐步过渡","用药观察：止血药与抗感染治疗观察疗效与不良反应；避免NSAIDs与抗凝药物","贫血与营养管理：监测血红蛋白与铁代谢，遵医嘱补铁；必要时输血并观察输血反应","宣教与随访：按时复查结肠镜与血常规、避免剧烈活动与用力排便（防再出血）、痔疮患者生活方式调整（多纤维、多饮水、避免久坐）"],"notes":["下消化道出血的定位首选结肠镜（可同时止血）；活动性大出血时应先稳定生命体征，必要时行CT血管造影","直肠指检与肛门镜是简单有效的第一步检查（痔与肛裂常见且易被忽视）","结肠镜阴性且持续出血者需评估小肠（胶囊内镜、小肠镜或CT/MRI小肠成像）","缺血性结肠炎多见于老年与动脉硬化者，表现为腹痛+便血，多数可保守治疗（重症需手术）","避免在出血期盲目使用止血药与抗生素（应先明确病因）"],"emergency":["大量便血伴血压下降、心率增快（失血性休克）→ 立即双通道补液输血，稳定后急诊结肠镜/CTA","持续活动性出血不能内镜控制（>0.5ml/min）→ 急诊DSA栓塞或手术","腹痛剧烈伴腹膜刺激征与便血（肠坏死/穿孔）→ 急诊手术探查","便血伴高热与里急后重（暴发性结肠炎/中毒性巨结肠）→ 急诊评估与处理（禁泻药、抗感染、必要时手术）","儿童阵发性腹痛伴果酱样便与腹部包块（肠套叠）→ 急诊超声+空气灌肠复位"],"pinyin":"xxhdcx","icd10":"K92.2","physical_exam":["生命体征：血压、心率、呼吸、意识（休克评估）","一般情况：面色苍白、皮肤湿冷、脱水征、营养状态","腹部：腹胀、压痛部位、腹块（肿瘤/肠套叠）、肠鸣音（亢进或减弱）","直肠指检：痔、肛裂、直肠肿物、指套染血（暗红或鲜红）","皮肤黏膜：黄疸、出血点与瘀斑、贫血貌、蜘蛛痣（肝病）","肛门视诊：痔核、肛裂、瘘口（出血来源）","其他：淋巴结肿大（肿瘤转移）、下肢水肿（低蛋白）"],"lab_tests":["血常规+血型+交叉配血+凝血功能：动态监测血红蛋白（每4～6小时）与备血","粪便常规+隐血+培养+寄生虫检查：感染性与寄生虫病因","结肠镜+活检（首选）：定位与病因诊断，同时可行内镜下止血","CT血管造影/腹部增强CT：活动性出血定位与肿瘤评估","胶囊内镜/小肠镜（结肠镜阴性者）：小肠出血评估","核素扫描（99mTc红细胞，间断出血）：定位不精确但敏感","肝肾功能+电解质+白蛋白：病情与营养评估"],"nursing":["出血观察与记录：记录便血与黑便的次数、颜色与量，监测生命体征与血红蛋白并报告异常","补液输血护理：保持静脉通路畅通，按医嘱补液输血并观察输血反应","饮食与肠道准备护理：活动性出血禁食，之后温凉流质逐步过渡；按医嘱配合肠道准备或CTA检查","肠道休息与症状观察：观察腹痛、腹胀与肠鸣音（缺血性结肠炎/肠梗阻），异常立即报告","用药护理：止血药与抗感染按时给予；避免NSAIDs与抗凝药；观察药物不良反应","宣教：按时复查结肠镜、多纤维多饮水避免便秘、痔疮患者避免久坐与用力排便、出现便血及时就诊"],"diet":["活动性出血期：禁食禁水、静脉补液","出血停止后：温凉流质（米汤、藕粉）→ 少渣半流质 → 软食逐步过渡","恢复期：高蛋白、高维生素饮食促进恢复；避免粗糙、坚硬与刺激性食物","炎症性肠病与缺血性结肠炎：低渣、低脂饮食；感染性结肠炎避免乳制品与高纤维","痔与肛裂：多饮水（每日2000ml以上）、多纤维饮食（蔬菜水果粗粮）保持大便通畅，忌辛辣与酒类"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1418},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"33935a6c97911fb6cc4a4f9968044874c46ac60668a3d8803da98ba1c115953e","pinyin":"xiaxiaohuadaochuxie","initials":"xxhdcx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","鲜血便（直肠与肛门病变）、暗红色血便（结肠病变）、果酱样便（肠套叠、阿米巴）\\n黑便（小肠出血、血液停留时间长）\\n腹痛（缺血性结肠炎、肠套叠、炎症性肠病）伴腹泻或便秘\\n头晕、心悸、乏力与晕厥（大量出血致失血性休克）\\n伴随症状：消瘦与排便习惯改变（肿瘤）、发热与里急后重（感染性结肠炎）",60],["摘要","下消化道出血指屈氏韧带以下消化道（小肠、结肠、直肠与肛门）出血，表现为便血（鲜红色、暗红色或果酱样）、黑便（小肠出血）与贫血。常见病因：结肠息肉与肿瘤、结肠炎（缺血性、溃疡性、感染性）、血管畸形、痔与肛裂、小肠病变（血管畸形、肿瘤、克罗恩病）。",30],["疾病编码","K92.2",30],["原首字母","xxhdcx",60]]},{"id":"orders-9c24bcffec7cec81012b","key":"v1-c9ccc21dfe2a3058|orders-9c24bcffec7cec81012b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"腹水（鉴别与处理）","category":"内科-消化","raw":{"name":"腹水（鉴别与处理）","category":"内科-消化","summary":"腹水是腹腔内液体积聚，最常见于肝硬化门静脉高压（约75%），其他包括恶性肿瘤、心力衰竭、结核性腹膜炎、肾病综合征与胰源性腹水。诊断核心是腹腔穿刺（SAAG、细胞数、细胞学与培养），治疗包括限钠限水、利尿、放腹水与病因治疗。","symptoms":["腹胀、腹围增大、体重增加、食欲减退与早饱","呼吸困难（大量腹水致膈肌上抬）、端坐呼吸","下肢水肿、阴囊水肿（门静脉高压或低蛋白）","原发病表现：黄疸与蜘蛛痣（肝硬化）、消瘦与腹块（肿瘤）、发热与盗汗（结核）、颈静脉怒张（心衰）","并发症表现：发热与腹痛（自发性腹膜炎）、意识改变（肝性脑病）、少尿（肝肾综合征）"],"diagnosis":["腹腔穿刺（关键，所有新发腹水均应穿刺）：外观、细胞数（中性粒细胞≥250/mm³诊断SBP）、白蛋白、SAAG（血清腹水白蛋白梯度）、LDH、葡萄糖、细胞学与细菌培养","SAAG≥11g/L提示门静脉高压（肝硬化、心衰、Budd-Chiari）；<11g/L提示非门静脉高压（肿瘤、结核、胰源性、肾病）","腹部超声/CT：腹水量、肝脾形态、门静脉内径与血栓、腹块与淋巴结","肝功能+白蛋白+胆红素+凝血：肝储备与门静脉高压评估","肾功能+电解质+尿钠：肝肾综合征与低钠血症评估","肿瘤标志物+腹水细胞学：恶性腹水（卵巢癌、胃癌、肝癌）","腹水ADA+结核相关检查（T-SPOT、腹水培养）：结核性腹膜炎","心脏超声+BNP：心源性腹水（右心衰、缩窄性心包炎）"],"infusion":["⚠️ 按病因选择，肝硬化腹水以限钠+利尿为主，避免大量补液！","方案1（肝硬化腹水，白蛋白与利尿）：","用法：白蛋白 10～20g 静滴（低蛋白或大量放腹水后，每放1L腹水补6～8g白蛋白）；呋塞米 20～40mg 静推（与口服利尿剂配合，按医嘱）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","方案2（大量放腹水治疗，顽固性腹水）：","用法：一次性放腹水4～6L（每次<5L较安全）+ 白蛋白 40g 静滴（每升腹水6～8g）——术后腹围与体重下降、利尿剂继续使用","方案3（自发性腹膜炎，SBP）：","用法：头孢曲松 2g 静滴 qd 或 头孢噻肟 2g 静滴 q8h（疗程5～7天）；白蛋白 1.5g/kg（第1天）+ 1g/kg（第3天）静滴（预防肝肾综合征）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","方案4（恶性腹水与结核性腹膜炎）：","用法：恶性腹水——利尿+放腹水+腹腔化疗（顺铂/紫杉醇，按瘤种，肿瘤科指导）；结核性——异烟肼+利福平+吡嗪酰胺+乙胺丁醇（抗结核方案，结核科指导）+ 必要时激素〔调 ★ 肝功能不全慎用；★ 强CYP450诱导剂（大量相互作用）〕","📌 肝硬化腹水禁用大量生理盐水（加重腹水）；放腹水后必须补充白蛋白（防循环功能障碍）；SBP诊断后及早抗感染（不必等培养）。"],"oral_medication":["⚠️ 肝硬化腹水的口服治疗是基础（限钠+利尿）：","药物1（利尿剂，联合方案）：","用法：螺内酯 40～80mg qd + 呋塞米 20～40mg qd（起始比例100:40，按尿量与体重调整；每日体重下降不超过0.5kg（无水肿）～1kg（有下肢水肿））〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","药物2（低钠血症处理）：","用法：限水（血钠<125mmol/L时每日<1000ml）；避免快速纠正（防渗透性脱髓鞘）；必要时托伐普坦 15mg qd（遵医嘱）","药物3（预防SBP复发与肝性脑病）：","用法：诺氟沙星 0.4g qd 或 利福昔明 400mg q8h；乳果糖 15～30ml bid（软便为目标）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","药物4（营养与辅助）：","用法：复合维生素B 2片 tid；支链氨基酸口服（营养不良者）；锌剂（辅助）","📌 避免NSAIDs（肾损与出血）与氨基糖苷类；利尿剂过量致肝性脑病、肾损与电解质紊乱（需监测）。"],"treatment":["限钠限水：钠盐摄入<2g/日（严格限钠），血钠<125mmol/L时限水800～1000ml/日","利尿剂治疗：螺内酯（首选）+呋塞米联合，按尿量、体重与电解质调整；监测体重（每日0.5～1kg下降为宜）","放腹水治疗：大量放腹水（4～6L/次）+白蛋白补充（每升6～8g），用于利尿无效或张力性腹水","顽固性腹水：反复放腹水+白蛋白、TIPS（评估指征与禁忌）、肝移植评估","病因治疗：肝硬化（抗病毒、戒酒、护肝）、恶性肿瘤（化疗/靶向）、结核（抗结核）、心衰（强心利尿扩血管）、肾病综合征（激素与免疫抑制）","并发症防治：SBP（抗感染+白蛋白）、肝肾综合征（特利加压素+白蛋白）、肝性脑病（乳果糖）、低钠血症（限水±托伐普坦）","营养支持：热量25～35kcal/kg、蛋白1.2～1.5g/kg（不主张长期限制蛋白），夜间加餐","随访：监测体重、腹围、尿量、电解质与肾功能；定期超声与腹水检查（SBP筛查）"],"management":["体重与腹围监测：每日固定时间测体重与腹围，记录24小时出入量与尿量（评估利尿与放腹水效果）","限钠限水执行：饮食宣教（每日钠<2g）、记录液体入量（低钠者限水），观察口渴与脱水征","利尿剂观察：监测电解质（钾、钠、肌酐）每2～3天，观察过度利尿征象（乏力、意识改变、肌痉挛）","放腹水护理：术前排空膀胱、术中监测生命体征、术后腹带加压与记录引流量/放液量，观察穿刺点渗液与出血","并发症观察：发热与腹痛（SBP）、意识改变（肝性脑病）、少尿与肌酐升高（肝肾综合征）、呼吸困难（大量腹水）","皮肤与体位护理：半卧位（减轻呼吸困难）、皮肤保湿与减压（腹水致皮肤张力高易破损）、翻身防止压疮","宣教：严格限盐、遵医嘱服利尿剂与复查电解质、体重突增或发热腹痛及时就诊、戒酒与抗病毒治疗依从性"],"notes":["所有新发腹水均应行腹腔穿刺检查（SAAG、细胞数、细胞学与培养）——这是鉴别诊断的关键步骤","SAAG≥11g/L提示门静脉高压性腹水（肝硬化、心衰）；<11g/L提示肿瘤、结核、胰源性或肾病性","腹水中性粒细胞≥250/mm³即可诊断自发性腹膜炎（不必等培养），须立即抗感染","大量放腹水必须补充白蛋白（每升6～8g）以预防循环功能障碍（PPCD）","肝硬化腹水患者不主张长期严格限制蛋白（加重肌少症）；每日体重下降过快（>1kg）提示过度利尿"],"emergency":["腹水患者发热伴腹痛或意识改变（自发性腹膜炎）→ 立即诊断性穿刺+经验性抗生素+白蛋白","大量放腹水后出现低血压、心动过速与少尿（循环功能障碍）→ 立即补液与白蛋白输注","腹胀剧痛伴呼吸困难（张力性腹水/膈疝）→ 紧急放腹水减压并评估手术","少尿、无尿与肌酐升高（肝肾综合征）→ 停利尿剂与肾毒性药物，白蛋白+特利加压素，评估透析","意识改变伴扑翼样震颤（肝性脑病）→ 乳果糖+门冬氨酸鸟氨酸，去除诱因"],"pinyin":"fsjycl","icd10":"R18","physical_exam":["生命体征：血压、心率、呼吸（大量腹水致呼吸困难）、体温（感染）","腹部视诊：腹围（测量并记录）、腹壁静脉曲张、脐疝、皮肤张力与妊娠纹样改变","腹部触诊：液波震颤、肝脾大小与质地、腹块（肿瘤）、压痛（腹膜炎）","腹部叩诊：移动性浊音（腹水≥1000ml可检出）、肝浊音界","心肺：颈静脉充盈（心衰/缩窄性心包炎）、肺部呼吸音减弱（胸腔积液）、心音与杂音","下肢与阴囊：凹陷性水肿、阴囊水肿","肝病体征：黄疸、蜘蛛痣、肝掌、男性乳房发育（肝硬化）"],"lab_tests":["腹腔穿刺检查（必查）：外观、细胞数（中性粒细胞≥250/mm³提示SBP）、SAAG、白蛋白、LDH、葡萄糖、细胞学与培养","血清-腹水白蛋白梯度（SAAG）：门静脉高压性（≥11g/L）与非门静脉高压性（<11g/L）鉴别","肝功能+白蛋白+胆红素+凝血功能：肝储备与门静脉高压评估","肾功能+电解质（钠、钾）+尿钠：肝肾综合征、低钠血症与利尿治疗监测","腹水ADA+结核相关（T-SPOT、腹水培养）+腹水细胞学：结核性与恶性腹水鉴别","心脏超声+BNP：心源性腹水（右心衰、缩窄性心包炎）","腹部超声/CT+肿瘤标志物：肝脾形态、门静脉血栓、腹块与肿瘤评估"],"nursing":["体重腹围与出入量监测：每日固定条件测体重与腹围，记录24小时出入量与尿量，异常立即报告","利尿剂与电解质监测：按时给药并观察尿量变化，配合复查电解质（每2～3天），观察过度利尿征象","放腹水护理：术前排空膀胱与生命体征评估、术中监测、术后腹带加压、记录放液量与穿刺点情况","并发症观察：发热腹痛（SBP）、意识改变（肝性脑病）、少尿与肌酐升高（肝肾综合征）、呼吸困难加重","体位与皮肤护理：半卧位减轻呼吸困难、皮肤保湿与减压（腹水致腹壁张力高）、每2小时翻身防压疮","宣教：严格限盐（<2g/日）与限水（低钠者）、遵医嘱服药不可自行加量、按时复查、发热腹痛或意识改变立即就诊"],"diet":["严格限钠：每日钠盐<2g（避免腌制品、加工食品、含钠调料与饮料）","限水：血钠<125mmol/L时每日液体<800～1000ml（含汤水、水果与输液）","蛋白质：1.2～1.5g/kg/日（植物蛋白与乳制品优先），不主张长期严格限制","高热量、易消化、少量多餐（每日4～6餐）+夜间加餐；补充维生素与微量元素","绝对禁酒；避免粗糙坚硬食物（防静脉破裂出血）；低钠血症者避免大量饮水与低钠饮料"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1419},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"e6ef6fed5531c666e781347d3161ab1f2eb8bfb441ea99b1e6084d384be45877","pinyin":"fushui（jianbieyuchuli）","initials":"fs（jbycl）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹胀、腹围增大、体重增加、食欲减退与早饱\\n呼吸困难（大量腹水致膈肌上抬）、端坐呼吸\\n下肢水肿、阴囊水肿（门静脉高压或低蛋白）\\n原发病表现：黄疸与蜘蛛痣（肝硬化）、消瘦与腹块（肿瘤）、发热与盗汗（结核）、颈静脉怒张（心衰）\\n并发症表现：发热与腹痛（自发性腹膜炎）、意识改变（肝性脑病）、少尿（肝肾综合征）",60],["摘要","腹水是腹腔内液体积聚，最常见于肝硬化门静脉高压（约75%），其他包括恶性肿瘤、心力衰竭、结核性腹膜炎、肾病综合征与胰源性腹水。诊断核心是腹腔穿刺（SAAG、细胞数、细胞学与培养），治疗包括限钠限水、利尿、放腹水与病因治疗。",30],["疾病编码","R18",30],["原首字母","fsjycl",60]]},{"id":"orders-9d09b682292557cb6b15","key":"v1-c9ccc21dfe2a3058|orders-9d09b682292557cb6b15","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"代谢综合征","category":"内科-内分泌","raw":{"name":"代谢综合征","category":"内科-内分泌","summary":"代谢综合征是肥胖（尤其腹型肥胖）、高血压、高血糖、血脂异常（高甘油三酯、低高密度脂蛋白）等多种代谢危险因素聚集的临床综合征，显著增加心脑血管疾病与2型糖尿病风险。诊断采用CDS或IDF标准，治疗核心是生活方式干预（减重、运动、饮食）与各组分药物治疗。","symptoms":["腹型肥胖（腰围男性≥90cm、女性≥85cm；或BMI≥25kg/m²）","血压升高（≥130/85mmHg或已诊断高血压）","血糖升高（空腹≥6.1mmol/L或餐后2h≥7.8mmol/L或已诊断糖尿病）","血脂异常：甘油三酯≥1.7mmol/L、HDL-C<1.04mmol/L（男）或<1.3mmol/L（女）","常伴：脂肪肝、高尿酸血症、睡眠呼吸暂停、多囊卵巢综合征（女性）"],"diagnosis":["体格测量：腰围（站立位、肋弓下缘与髂嵴中点）、BMI、血压（多次测量）","血糖相关：空腹血糖+餐后2h血糖（OGTT）+糖化血红蛋白（HbA1c）","血脂全套：甘油三酯、总胆固醇、LDL-C、HDL-C","肝功能+腹部超声：非酒精性脂肪肝评估","血尿酸+肾功能：高尿酸血症与肾损害","尿微量白蛋白+肾功能：早期肾损害（糖尿病肾病/高血压肾损害）","心血管风险评估：颈动脉超声（斑块）、心电图、必要时心脏超声与踝肱指数","睡眠监测（疑OSA）：打鼾与白天嗜睡者"],"infusion":["⚠️ 代谢综合征以口服治疗为主，静脉用药用于急性并发症！","方案1（高血压急症/合并急性并发症）：","用法：乌拉地尔 12.5～25mg 静推后 100～400μg/min 泵入；或硝酸甘油 5～10μg/min 泵入（合并心衰/心绞痛）〔调 ★ 收缩压<90 或右室梗死禁用；★ 24h内用过PDE5抑制剂禁用〕","方案2（急性高血糖并发症，DKA/HHS）：","用法：胰岛素 0.1U/kg/h 泵入 + 0.9%氯化钠 补液（血糖降至13.9mmol/L后改用5%葡萄糖+胰岛素）；补钾（见尿补钾）","方案3（急性痛风发作）：","用法：地塞米松 5mg 静推（不能口服NSAIDs/秋水仙碱者）；或 甲泼尼龙 40mg 静滴 qd（短期）；0.9%氯化钠 静滴〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案4（急性胰腺炎/高脂血症危象）：","用法：0.9%氯化钠 静滴；必要时血浆置换/血液净化（甘油三酯>11.3mmol/L）","📌 代谢综合征本身不需静脉治疗，急性并发症（高血压危象、DKA、急性痛风、高脂性胰腺炎）按相应处理。"],"oral_medication":["⚠️ 按各组分选择药物（同类只选一种，注意联合用药风险）：","药物1（降压，高血压组分）：","用法：缬沙坦 80mg qd 或 培哚普利 4mg qd（ACEI/ARB 对代谢影响中性/有益，尤其合并糖尿病肾病）；必要时联合氨氯地平 5mg qd〔调 肝功能不全减量；踝部水肿（剂量相关）〕","药物2（降糖，糖尿病/糖尿病前期）：","用法：二甲双胍 0.5g bid（餐中/餐后，一线）；合并肥胖/心衰/CKD者考虑 SGLT2抑制剂（达格列净 10mg qd）或 GLP-1受体激动剂（司美格鲁肽 0.25mg 每周一次皮下）","药物3（调脂）：","用法：阿托伐他汀 20mg qn 或 瑞舒伐他汀 10mg qn（LDL-C 达标）；甘油三酯显著升高者加 非诺贝特 200mg qd（注意与他汀联用的肌病风险，建议分时服用）〔调 ★ 活动性肝病禁用；甲减/肌病史慎用；妊娠哺乳禁用〕","药物4（降尿酸与减重）：","用法：非布司他 40mg qd 或 别嘌醇 100mg qd 起（痛风者，按血尿酸调整）；奥利司他 120mg tid（餐时，减重辅助）","📌 二甲双胍禁用于 eGFR<30ml/min；他汀与贝特联用需监测肌酶与肝功能；减重5%～10%即可显著改善各组分。"],"treatment":["生活方式干预（基础）：减重（目标3～6个月减5%～10%）、限制热量（每日减少500～750kcal）、增加运动（每周≥150分钟中等强度有氧+抗阻训练）、戒烟限酒","饮食调整：控制总热量与精制碳水、增加膳食纤维与不饱和脂肪酸（地中海饮食/DASH饮食）、限制钠盐（<5g/日）","各组分药物治疗：高血压（ACEI/ARB优先）、糖尿病（二甲双胍±SGLT2i/GLP-1RA）、血脂异常（他汀±贝特）、高尿酸（降尿酸药）","综合风险管理：计算心血管风险（ASCVD），高危者强化降脂（LDL-C<1.8mmol/L或更低）与抗血小板治疗（评估出血风险）","并发症筛查：脂肪肝（肝功能+超声）、睡眠呼吸暂停（睡眠监测）、多囊卵巢（女性）、糖尿病视网膜病变与肾病（每年筛查）","多学科管理：内分泌科、心内科、营养科与运动康复协作，制定个体化方案","随访与监测：每3个月评估体重、腰围、血压、血糖、血脂与肝功能，调整方案","宣教：代谢综合征可逆（减重与生活方式改变效果显著）、坚持用药与随访、避免自行停药（尤其降压降糖药）"],"management":["体测与代谢指标记录：每次随访测量体重、腰围、BMI、血压，记录血糖、血脂与肝肾功能趋势","生活方式干预执行：与营养师协作制定饮食计划、制定运动处方（循序渐进）、记录运动与饮食日记","用药依从性：评估服药情况与不良反应（二甲双胍胃肠道反应、他汀肌痛、利尿剂电解质紊乱），及时调整","血糖与血压自我监测：指导家庭血压与血糖监测方法并记录，识别异常（低血糖、高血压）","并发症筛查提醒：按时安排眼底、尿微量白蛋白、颈动脉超声与肝脏超声检查","宣教：减重与运动是核心（效果优于单纯加药）、避免含糖饮料与高热量零食、戒烟限酒、定期复查","心理支持：长期管理易致倦怠，鼓励设定可行目标与家庭参与"],"notes":["代谢综合征的核心是腹型肥胖与胰岛素抵抗，减重5%～10%即可显著改善血压、血糖与血脂（生活方式干预优于单纯加药）","诊断需满足至少3项组分（腹型肥胖、高血压、高血糖、高甘油三酯、低HDL-C），按CDS/IDF标准判定","ACEI/ARB 对代谢无不良影响（优于β受体阻滞剂与噻嗪类利尿剂），糖尿病肾病者优先","他汀与非诺贝特联用增加肌病风险（需监测肌酶，建议分时服用并避免大剂量）","代谢综合征患者应常规筛查脂肪肝、睡眠呼吸暂停与糖尿病慢性并发症"],"emergency":["血压≥180/120mmHg伴靶器官损害（高血压急症）→ 静脉降压（乌拉地尔/硝酸甘油），监测靶器官功能","血糖显著升高伴意识障碍与脱水（DKA/HHS）→ 补液+胰岛素泵入+纠正电解质，转ICU","急性痛风发作伴剧痛与关节红肿 → 短期激素或秋水仙碱/NSAIDs（避免长期NSAIDs）","甘油三酯>11.3mmol/L伴剧烈腹痛（高脂性胰腺炎）→ 禁食、补液、降脂治疗，必要时血液净化","胸痛伴心电图改变（急性冠脉综合征）→ 立即抗血小板+他汀+急诊PCI评估"],"pinyin":"dxzhz","icd10":"E88.8","physical_exam":["体格测量：体重、BMI、腰围（男≥90cm、女≥85cm）、臀围与腰臀比","血压：多次测量（双上肢对比），必要时动态血压监测","皮肤：黑棘皮病（胰岛素抵抗征象）、皮肤紫纹（库欣）、黄色瘤（血脂异常）、痛风石","甲状腺与颈部：甲状腺大小（甲减致代谢异常）、颈部脂肪堆积与打鼾（OSA）","心肺：心界、心率、心音（高血压性心脏病）、肺部（OSA相关）","腹部：肝大与脂肪肝、腹型肥胖（内脏脂肪堆积）","四肢：下肢水肿（肾病/心衰）、足背动脉搏动（外周动脉疾病）、足部检查（糖尿病足筛查）"],"lab_tests":["空腹血糖+餐后2h血糖（OGTT）+糖化血红蛋白：糖尿病与糖尿病前期诊断（每3～6个月）","血脂全套（甘油三酯、总胆固醇、LDL-C、HDL-C）：每3～6个月复查","肝功能（ALT、AST、GGT）+腹部超声：非酒精性脂肪肝评估","血尿酸+肾功能（肌酐、eGFR）+尿微量白蛋白：高尿酸血症与早期肾损害","胰岛素+C肽（必要时）：胰岛素抵抗评估","颈动脉超声+心电图+踝肱指数：心血管风险与动脉粥样硬化评估","睡眠监测（多导睡眠图，疑OSA）：打鼾与白天嗜睡者"],"nursing":["体测与记录：每次随访测量体重、腰围、BMI与血压并记录趋势，评估减重效果","生活方式指导：协助制定饮食与运动计划、指导食物交换份与热量计算、鼓励记录饮食与运动日记","用药护理：按医嘱给药并观察不良反应（二甲双胍胃肠道反应、他汀肌痛、利尿剂电解质紊乱），异常报告","自我监测指导：教会家庭血压与血糖监测方法与记录，识别低血糖（出汗、心悸）与高血压症状","并发症筛查配合：按时安排眼底、尿微量白蛋白、颈动脉超声与肝脏超声检查","宣教与心理支持：强调减重与运动的核心作用、避免含糖饮料与高热量零食、戒烟限酒、长期随访与家庭参与"],"diet":["控制总热量：每日减少500～750kcal（目标减重0.5～1kg/周）","限制精制碳水（白米白面、含糖饮料、甜点），增加全谷物、豆类与蔬菜","增加膳食纤维（每日25～30g）与优质脂肪（深海鱼、橄榄油、坚果）","限制钠盐（每日<5g，高血压者<3g）；戒烟限酒","地中海饮食/DASH饮食模式；少量多餐、避免夜宵与暴饮暴食"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1420},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"93917ca47215c6876c6deea287a40e0e44b7f789bdcdb4f50034be1f8989b83c","pinyin":"daixiezonghezheng","initials":"dxzhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","腹型肥胖（腰围男性≥90cm、女性≥85cm；或BMI≥25kg/m²）\\n血压升高（≥130/85mmHg或已诊断高血压）\\n血糖升高（空腹≥6.1mmol/L或餐后2h≥7.8mmol/L或已诊断糖尿病）\\n血脂异常：甘油三酯≥1.7mmol/L、HDL-C<1.04mmol/L（男）或<1.3mmol/L（女）\\n常伴：脂肪肝、高尿酸血症、睡眠呼吸暂停、多囊卵巢综合征（女性）",60],["摘要","代谢综合征是肥胖（尤其腹型肥胖）、高血压、高血糖、血脂异常（高甘油三酯、低高密度脂蛋白）等多种代谢危险因素聚集的临床综合征，显著增加心脑血管疾病与2型糖尿病风险。诊断采用CDS或IDF标准，治疗核心是生活方式干预（减重、运动、饮食）与各组分药物治疗。",30],["疾病编码","E88.8",30],["原首字母","dxzhz",60]]},{"id":"orders-5598acb64e692e1d8298","key":"v1-c9ccc21dfe2a3058|orders-5598acb64e692e1d8298","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"糖尿病乳酸性酸中毒","category":"内科-内分泌","raw":{"name":"糖尿病乳酸性酸中毒","category":"内科-内分泌","summary":"糖尿病乳酸性酸中毒（DLA）是糖尿病患者因乳酸生成过多或清除减少致血乳酸>5mmol/L、pH<7.35的严重急性并发症，多见于服用二甲双胍（尤其肾功能不全、缺氧、造影剂使用时）、严重感染、休克、酗酒与心衰患者。表现为酸中毒、意识障碍与循环衰竭，病死率高。","symptoms":["乏力、食欲减退、恶心呕吐、腹痛（前驱症状）","呼吸深快（Kussmaul呼吸）、意识障碍（嗜睡至昏迷）","脱水、皮肤湿冷、血压下降（休克）","原有糖尿病症状加重（多饮多尿）但不伴明显酮症（与DKA鉴别）","诱因相关表现：感染发热、心衰气促、服用二甲双胍或造影剂史"],"diagnosis":["动脉血气分析：pH<7.35、HCO₃⁻降低、乳酸>5mmol/L（诊断核心）、阴离子间隙增大","血糖+血酮+尿酮：血糖可轻中度升高、血酮阴性或弱阳性（与DKA鉴别：DKA酮体显著升高）","肾功能（肌酐、eGFR）+电解质（钾、钠、氯）：二甲双胍蓄积与电解质紊乱评估","二甲双胍血药浓度（必要时）：明确药物相关（多数医院不能测，依用药史与肾功能判断）","血培养+CRP+PCT+乳酸（动态）：感染与组织灌注评估（乳酸清除率是复苏指标）","肝功能+心肌酶+心电图：肝肾功能与心肌缺血评估","腹部超声/CT（疑腹部病变）：腹痛病因鉴别"],"infusion":["⚠️ 抢救用药，须ICU监护并停用二甲双胍！","方案1（补液复苏与纠正循环，首要）：","用法：0.9%氯化钠 1000ml 快速静滴（首1小时，按心功能与血压调整）；必要时继续补液维持尿量≥0.5ml/kg/h；纠正休克用去甲肾上腺素 0.05～0.5μg/kg/min 泵入","方案2（胰岛素与葡萄糖）：","用法：胰岛素 0.1U/kg/h 泵入（血糖>13.9mmol/L时）；血糖降至13.9mmol/L后改用5%葡萄糖+胰岛素（维持血糖8～11mmol/L）；注意监测血糖与血钾","方案3（纠正酸中毒，谨慎补碱）：","用法：仅pH<7.1时考虑：5%碳酸氢钠 100～250ml 静滴（缓慢，监测血气与血钾）；避免过量补碱（加重细胞内酸中毒与乳酸生成）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","方案4（血液净化，重症）：","用法：血液透析/CRRT（清除乳酸与二甲双胍、纠正酸中毒与容量负荷）——指征：pH<7.1、乳酸>15mmol/L、肾功能衰竭、血流动力学不稳定","📌 立即停用二甲双胍；禁用双胍类与造影剂（急性期）；补碱须谨慎（pH<7.1）；重症应尽早血液净化（可同时清除二甲双胍）。"],"oral_medication":["⚠️ 急性期不宜口服用药；恢复期与预防：","药物1（降糖方案调整，恢复期）：","用法：停用二甲双胍（肾功能不全者永久停用或严格评估）；改用胰岛素或其他降糖药（如 DPP-4抑制剂 西格列汀 100mg qd，按肾功能调整）","药物2（肾功能保护）：","用法：碳酸氢钠片 1g tid（慢性轻度酸中毒，按血气调整）；避免肾毒性药物〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","药物3（营养支持）：","用法：复合维生素B 2片 tid（含硫胺素预防乳酸酸中毒）；叶酸 5mg qd","药物4（病因与相关疾病治疗）：","用法：抗感染（按感染灶）、心衰规范治疗、戒酒（酒精性乳酸酸中毒）","📌 恢复期应重新评估降糖方案（二甲双胍仅在肾功能正常且无缺氧风险时可谨慎恢复，需专科评估）；避免酗酒与过度运动。"],"treatment":["停用致病药物（二甲双胍、含乳酸输液等）并去除诱因（感染、休克、缺氧、心衰、酗酒）","积极补液与循环支持：恢复组织灌注是清除乳酸的关键（乳酸清除依赖肝脏与肾脏灌注），生理盐水静滴","胰岛素治疗：小剂量胰岛素静滴（0.1U/kg/h起）纠正高血糖并抑制脂肪分解与乳酸生成","纠正酸中毒：慎用碳酸氢钠（仅pH<7.1或有严重高钾/血流动力学不稳定时用5%碳酸氢钠100～250ml静滴），避免过度补碱","血液净化：CRRT/血液透析清除乳酸与二甲双胍（伴肾功能衰竭或重症者首选）","电解质与器官支持：纠正高钾（葡萄糖酸钙/胰岛素+葡萄糖）、低钾与低磷，必要时机械通气","病因治疗：抗感染（去除感染灶）、心衰治疗、戒酒、纠正缺氧（吸氧/机械通气）","随访与预防：重新评估肾功能的降糖方案（避免二甲双胍在 eGFR<45 时使用）、造影前后停用二甲双胍（48小时）"],"management":["严密监测：生命体征（每15～30分钟）、意识、每小时尿量、乳酸与血气（每1～2小时）","补液与尿量管理：快速建立两条静脉通路、记录24小时出入量、目标尿量≥0.5ml/kg/h","血糖与电解质监测：每1～2小时测血糖、每2～4小时测血钾与电解质（胰岛素与补碱可致低钾）","用药护理：胰岛素泵入按医嘱调整；碳酸氢钠缓慢静滴并监测血气（避免过量）","血液净化护理：CRRT/透析时监测血压、凝血与电解质，观察管路与穿刺部位","病因观察：感染灶（体温、肺部与泌尿系）、心衰（气促与水肿）与缺氧（血氧）","宣教：二甲双胍的使用禁忌（肾功能、缺氧、造影剂、酗酒）、识别前驱症状（乏力、恶心、呼吸深快）及时就诊、糖尿病规范管理"],"notes":["DLA的诊断依据血乳酸>5mmol/L+pH<7.35，血糖可仅轻中度升高、酮体阴性（与DKA鉴别）","二甲双胍相关DLA多发生于肾功能不全、缺氧、心衰、酗酒或造影剂使用后（eGFR<45应慎用，<30禁用）","补液恢复组织灌注与清除乳酸是治疗核心（乳酸清除依赖肝肾功能灌注）","补碱须谨慎（仅pH<7.1），过度补碱加重细胞内酸中毒与乳酸生成","重症应尽早血液净化（尤其伴肾功能衰竭者，可同时清除二甲双胍）"],"emergency":["呼吸深快伴意识障碍与乳酸>5mmol/L（乳酸性酸中毒）→ 立即补液+胰岛素+停二甲双胍，ICU监护","pH<7.1或乳酸>15mmol/L（重症）→ 谨慎补碱+血液净化（CRRT/血液透析）","休克（血压下降、乳酸持续升高）→ 液体复苏+升压药，评估感染灶与心功能","严重高钾血症伴心电图改变 → 补钙+胰岛素葡萄糖+利尿/透析","意识障碍加重伴呼吸抑制 → 保护气道、必要时机械通气，寻找诱因（感染/缺氧/药物）"],"pinyin":"tnbrsxzd","icd10":"E87.2","physical_exam":["生命体征：呼吸频率与深度（Kussmaul呼吸）、血压（低血压/休克）、心率、体温（感染）、血氧","意识与神经系统：意识状态（嗜睡至昏迷）、肌张力、瞳孔","脱水征：皮肤弹性、黏膜干燥、眼窝凹陷、体重变化","心肺：心律与心音、肺部湿啰音（心衰/感染）","腹部：腹痛与压痛（需排除急腹症）、肠鸣音","用药相关：二甲双胍用药史与剂量、近期造影剂使用、酗酒史","末梢循环：皮温、毛细血管充盈时间、尿量（组织灌注评估）"],"lab_tests":["动脉血气分析+乳酸（每1～2小时）：pH<7.35、乳酸>5mmol/L（诊断与疗效核心）","血糖+血酮（β-羟丁酸）+尿酮：与DKA鉴别（DLA酮体阴性/弱阳性）","肾功能（肌酐、eGFR）+电解质（钾、钠、氯、磷）：二甲双胍蓄积与电解质紊乱","血常规+CRP+PCT+血培养：感染与脓毒症评估","肝功能+心肌酶+心电图：肝肾功能与心肌缺血评估","阴离子间隙+血浆渗透压：酸中毒类型与脱水程度评估","二甲双胍血药浓度（如可测）+毒物筛查：病因确认"],"nursing":["急救护理：快速建立两条静脉通路、遵医嘱快速补液、记录每小时尿量与生命体征（每15～30分钟）","血糖与电解质监测：按时测血糖与血钾并报告异常（胰岛素与补碱可致低钾）","意识与气道护理：评估意识状态、必要时保护气道（侧卧/吸氧），防误吸与坠床","用药护理：胰岛素泵入按医嘱调整；碳酸氢钠缓慢静滴并观察血气变化；停用二甲双胍并记录","血液净化护理：CRRT/透析时监测血压、凝血与电解质，观察管路通畅与穿刺部位","宣教：二甲双胍禁忌（肾功能不全、缺氧、造影剂、酗酒）、前驱症状识别（乏力、恶心、呼吸深快）及时就诊、糖尿病规范治疗与随访"],"diet":["急性期：禁食或少量流质（视病情），静脉补液与营养支持","恢复期：糖尿病饮食（控制总热量与碳水），少量多餐、定时定量","补充B族维生素（硫胺素）与叶酸；避免酗酒（酒精性乳酸酸中毒）","避免高乳酸食物与含乳酸输液（如乳酸钠林格液，遵医嘱）","限制精制糖与含糖饮料；多饮水（心肾功能允许下）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1421},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"af52251a37d9e95ad739a521014812c8a01e17212cd48e26bd1e196c77abd3a3","pinyin":"tangniaobingrusuanxingsuanzhongdu","initials":"tnbrsxszd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、食欲减退、恶心呕吐、腹痛（前驱症状）\\n呼吸深快（Kussmaul呼吸）、意识障碍（嗜睡至昏迷）\\n脱水、皮肤湿冷、血压下降（休克）\\n原有糖尿病症状加重（多饮多尿）但不伴明显酮症（与DKA鉴别）\\n诱因相关表现：感染发热、心衰气促、服用二甲双胍或造影剂史",60],["摘要","糖尿病乳酸性酸中毒（DLA）是糖尿病患者因乳酸生成过多或清除减少致血乳酸>5mmol/L、pH<7.35的严重急性并发症，多见于服用二甲双胍（尤其肾功能不全、缺氧、造影剂使用时）、严重感染、休克、酗酒与心衰患者。表现为酸中毒、意识障碍与循环衰竭，病死率高。",30],["疾病编码","E87.2",30],["原首字母","tnbrsxzd",60]]},{"id":"orders-1263b045e4799b995871","key":"v1-c9ccc21dfe2a3058|orders-1263b045e4799b995871","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"糖尿病自主神经病变","category":"内科-内分泌","raw":{"name":"糖尿病自主神经病变","category":"内科-内分泌","summary":"糖尿病自主神经病变是糖尿病常见慢性并发症，累及心血管、胃肠道、泌尿生殖与汗腺系统，表现为静息性心动过速、体位性低血压、胃轻瘫、腹泻与便秘交替、排尿障碍与无汗。可致无痛性心肌梗死与猝死，需早期识别与综合管理。","symptoms":["心血管：静息性心动过速（>100次/分）、体位性低血压（站立后头晕黑矇）、运动耐量下降、无痛性心肌梗死","胃肠道：胃轻瘫（早饱、恶心、呕吐、餐后腹胀）、腹泻与便秘交替（夜间腹泻常见）、吞咽困难","泌尿生殖：排尿困难与尿潴留、尿失禁、膀胱排空不全（易泌尿系感染）、男性勃起功能障碍、女性性欲减退","汗腺：无汗或少汗（下肢无汗、上半身代偿性多汗）、皮肤干燥","其他：瞳孔对光反射迟钝、低血糖感知障碍（无警觉症状）"],"diagnosis":["心血管自主神经功能试验：心率变异性（深呼吸、Valsalva动作、体位变化）、卧立位血压（体位性低血压）","胃排空检查：胃排空闪烁扫描（金标准）、13C呼气试验、上消化道钡餐（胃轻瘫）","胃肠动力：胃电图、消化道测压（必要时）","泌尿系统：残余尿测定（超声）、尿流率、尿动力学检查（排尿障碍）","血糖与糖化血红蛋白：血糖控制水平（自主神经病变与血糖控制相关）","排除其他原因：甲状腺功能、维生素B12、肾功能、药物影响（降压药致体位性低血压）","心脏评估：心电图、动态心电图、心脏超声（无痛性心肌梗死与猝死风险）"],"infusion":["⚠️ 以口服对症治疗为主，静脉用药用于严重并发症！","方案1（严重体位性低血压/脱水）：","用法：0.9%氯化钠 500～1000ml 静滴（扩容）；必要时米多君 2.5mg 静推/口服（α1激动剂）","方案2（胃轻瘫致严重呕吐与脱水）：","用法：0.9%氯化钠 1000ml + 10%氯化钾 10～20ml 静滴（纠正脱水与低钾）；甲氧氯普胺 10mg 静推 q8h（促动力）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","方案3（神经病变营养治疗）：","用法：硫辛酸 0.6g + 0.9%氯化钠 250ml 静滴 qd（避光，疗程2～4周）；甲钴胺 0.5mg 静推 qd；前列地尔 10μg 静推 qd（改善微循环）","方案4（合并感染）：","用法：尿路感染——左氧氟沙星 0.5g 静滴 qd（按药敏）；0.9%氯化钠 静滴维持〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","📌 糖尿病自主神经病变的病因治疗是长期平稳控糖；体位性低血压者慎用降压药与利尿剂；胃轻瘫者需营养支持与促动力药。"],"oral_medication":["⚠️ 按受累系统选择药物（同类只选一种）：","药物1（神经病变基础治疗）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid；α-硫辛酸 0.6g qd（口服，餐前30分钟）","药物2（体位性低血压）：","用法：米多君 2.5～5mg tid（避免睡前服，防卧位高血压）；氟氢可的松 0.1mg qd（监测血压与血钾）","药物3（胃轻瘫）：","用法：甲氧氯普胺 10mg tid（餐前30分钟，短期）或 莫沙必利 5mg tid（餐前）；红霉素 250mg tid（短期促动力，遵医嘱）〔调 ★ 帕金森病禁用；消化道梗阻禁用；肾功能不全减量〕","药物4（腹泻/便秘与泌尿症状）：","用法：洛哌丁胺 2mg tid（腹泻）；乳果糖 15ml bid（便秘）；坦索罗辛 0.2mg qn（排尿困难，男性）；必要时间断导尿〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 甲氧氯普胺长期使用可致锥体外系反应（限短期）；米多君与氟氢可的松需监测卧位血压（防高血压与心衰）。"],"treatment":["基础治疗：长期平稳控制血糖（HbA1c 7%左右，避免血糖波动与低血糖）、控制血压与血脂、戒烟","体位性低血压管理：缓慢起身、睡眠抬高床头、弹力袜与腹带、增加盐与水摄入、减少/调整降压药与利尿剂、必要时米多君/氟氢可的松","胃轻瘫管理：少量多餐（低脂低纤维）、促动力药（甲氧氯普胺/莫沙必利/红霉素短期）、血糖控制、必要时幽门内镜治疗或胃电刺激","腹泻与便秘管理：腹泻（洛哌丁胺、益生菌、必要时抗生素如小肠细菌过度生长）、便秘（纤维+乳果糖+促动力药）","泌尿系统管理：排尿训练、定时排尿、必要时间歇导尿（残余尿>150ml）、治疗泌尿系感染（避免留置尿管）","心血管自主神经病变：无痛性心肌梗死风险教育（识别气促、乏力等非典型症状）、定期心脏评估（心电图/心脏超声）","汗腺与皮肤护理：皮肤保湿（无汗致干燥皲裂）、避免高温环境（无汗致体温调节障碍）、足部护理","多学科管理：内分泌科、消化科、泌尿科、心内科与神经科协作；糖尿病教育与足部护理"],"management":["血糖与代谢监测：监测空腹与餐后血糖、HbA1c（每3个月），避免低血糖（自主神经病变者低血糖感知障碍）","体位性低血压护理：测量卧立位血压、指导缓慢起身与物理反压动作、观察头晕与跌倒风险（加床档、防跌倒）","胃肠道护理：小量多餐、记录进食量与症状（早饱、呕吐、腹泻）、遵医嘱促动力药与止泻/通便药","泌尿护理：记录排尿情况与残余尿量、指导定时排尿与清洁间歇导尿、监测尿路感染征象（尿频、尿急、发热）","皮肤与足部护理：每日检查足部（感觉减退易受伤）、皮肤保湿、避免烫伤（无汗与感觉减退）、穿合适鞋袜","宣教：无痛性心肌梗死风险（出现气促、乏力、恶心立即就诊）、低血糖感知障碍（加强血糖监测）、长期控糖的重要性","心理支持：勃起功能障碍与排尿障碍影响生活质量，提供咨询与治疗选择"],"notes":["糖尿病自主神经病变可致无痛性心肌梗死与猝死，患者及家属需知晓非典型症状（气促、乏力、恶心）","体位性低血压常被降压药与利尿剂加重（需调整方案），处理首选非药物措施（缓慢起身、弹力袜、增加盐与水）","胃轻瘫治疗以少量多餐+促动力药为主，甲氧氯普胺不宜长期使用（锥体外系反应）","排尿障碍者应监测残余尿（>150ml需间歇导尿），避免长期留置尿管（感染风险）","硫辛酸与甲钴胺可用于神经病变治疗（疗效有限，控糖是根本）"],"emergency":["体位性低血压致晕厥或跌倒 → 立即平卧抬高下肢、补液，调整降压药与利尿剂","无痛性心肌梗死（气促、乏力、恶心、心电图改变）→ 立即心电图+心肌酶，按急性冠脉综合征处理","胃轻瘫致严重呕吐与脱水、电解质紊乱 → 静脉补液+止吐+促动力药","尿潴留（排尿困难、膀胱充盈）→ 导尿引流并评估残余尿与泌尿系感染","严重低血糖（自主神经病变者无警觉症状）→ 立即静推50%葡萄糖并加强血糖监测"],"pinyin":"tnbzszb","icd10":"G99.0","physical_exam":["生命体征：卧位与立位血压（体位性低血压）、心率（静息性心动过速）、呼吸","心血管：心率与心律、心音、颈静脉充盈（心衰）","腹部：腹胀、胃振水音（胃轻瘫）、肠鸣音（腹泻/便秘）","泌尿：膀胱充盈（叩诊浊音）、残余尿测定","皮肤与汗腺：皮肤干燥与皲裂、下肢无汗、足部皮肤完整性（溃疡与胼胝）","神经系：震动觉、针刺觉、踝反射（周围神经病变并存）、瞳孔对光反射","足部：足背动脉搏动、趾甲与皮肤、有无畸形（Charcot足）"],"lab_tests":["卧立位血压+心率变异性试验：心血管自主神经功能评估","糖化血红蛋白+空腹与餐后血糖（含动态血糖监测）：血糖控制水平","胃排空闪烁扫描或13C呼气试验：胃轻瘫诊断","残余尿超声+尿流率+尿动力学（必要时）：排尿功能障碍评估","尿常规+尿培养：泌尿系感染筛查","甲状腺功能+维生素B12+肾功能+电解质：排除其他神经病变病因","心电图+心脏超声+动态心电图：心脏自主神经病变与心血管风险评估"],"nursing":["体位性低血压护理：测量卧立位血压、指导缓慢起身与物理反压动作、观察头晕与跌倒风险，防跌倒措施（加床档、呼叫器）","胃肠道护理：少量多餐、记录进食量与呕吐腹泻情况、促动力药餐前30分钟给药、必要时补液","泌尿护理：记录排尿与残余尿量、指导定时排尿与清洁间歇导尿、监测尿路感染征象","皮肤与足部护理：每日检查足部与皮肤（感觉减退易受伤）、保湿、避免烫伤（无汗与感觉减退者禁热水袋）、穿合适鞋袜","用药护理：按医嘱给药并观察不良反应（甲氧氯普胺锥体外系反应、米多君卧位高血压）","宣教：无痛性心肌梗死与低血糖感知障碍风险、长期控糖与随访、生活方式（缓慢起身、少量多餐、足部护理）"],"diet":["胃轻瘫：少量多餐（每日6餐）、低脂低纤维、细软易消化；避免高脂与高纤维（延缓胃排空）","腹泻与便秘交替：避免产气食物与乳制品（腹泻期）、增加水分与可溶性纤维（便秘期）","糖尿病饮食：控制总热量与碳水、定时定量、低升糖指数食物","充足水分摄入（心肾功能允许下，体位性低血压者适当增加盐与水）","戒酒、限咖啡因；补充B族维生素（硫胺素、B12）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1422},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"4af831a9bc511e4049882d44c9b61de55233e42305ca31654226e56258fe4152","pinyin":"tangniaobingzizhushenjingbingbian","initials":"tnbzzsjbb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","心血管：静息性心动过速（>100次/分）、体位性低血压（站立后头晕黑矇）、运动耐量下降、无痛性心肌梗死\\n胃肠道：胃轻瘫（早饱、恶心、呕吐、餐后腹胀）、腹泻与便秘交替（夜间腹泻常见）、吞咽困难\\n泌尿生殖：排尿困难与尿潴留、尿失禁、膀胱排空不全（易泌尿系感染）、男性勃起功能障碍、女性性欲减退\\n汗腺：无汗或少汗（下肢无汗、上半身代偿性多汗）、皮肤干燥\\n其他：瞳孔对光反射迟钝、低血糖感知障碍（无警觉症状）",60],["摘要","糖尿病自主神经病变是糖尿病常见慢性并发症，累及心血管、胃肠道、泌尿生殖与汗腺系统，表现为静息性心动过速、体位性低血压、胃轻瘫、腹泻与便秘交替、排尿障碍与无汗。可致无痛性心肌梗死与猝死，需早期识别与综合管理。",30],["疾病编码","G99.0",30],["原首字母","tnbzszb",60]]},{"id":"orders-b1567abd7d57f3894e71","key":"v1-c9ccc21dfe2a3058|orders-b1567abd7d57f3894e71","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"肾性贫血","category":"内科-泌尿","raw":{"name":"肾性贫血","category":"内科-泌尿","summary":"肾性贫血是慢性肾脏病（CKD）常见并发症，主要由促红细胞生成素（EPO）相对缺乏所致，并伴铁缺乏、炎症、尿毒症毒素与营养不良等因素。表现为正细胞正色素性贫血，与CKD进展平行（eGFR<60ml/min开始出现）。治疗包括铁剂、促红素与低氧诱导因子脯氨酰羟化酶抑制剂（HIF-PHI）。","symptoms":["乏力、活动后心悸气短、头晕、注意力不集中","面色与结膜苍白、指甲苍白、心率增快（贫血代偿）","原有心衰或冠心病症状加重（贫血增加心脏负荷）","食欲减退、营养不良（与尿毒症症状重叠）","认知功能下降、睡眠障碍与生活质量下降"],"diagnosis":["血常规（血红蛋白、红细胞指数）：正细胞正色素性贫血（Hb<130g/L男、<120g/L女）","肾功能（肌酐、eGFR）+CKD分期：贫血与肾功能损害程度相关","铁代谢：血清铁蛋白（<100ng/ml提示绝对铁缺乏，100～300ng/ml伴转铁蛋白饱和度<20%提示功能性铁缺乏）、转铁蛋白饱和度（TSAT<20%）","网织红细胞计数+EPO水平：评估骨髓反应与EPO缺乏","维生素B12+叶酸：排除营养性巨幼细胞贫血","粪便隐血+消化内镜（必要时）：排除消化道失血（透析患者常见）","炎症指标（CRP、PCT）+甲状旁腺激素（PTH）：炎症与继发性甲旁亢影响（影响EPO反应）","骨髓穿刺（必要时）：排除其他血液病"],"infusion":["⚠️ 肾性贫血以铁剂与促红素治疗为主，静脉用药需监测血压与铁代谢！","方案1（静脉铁剂，透析或口服不耐受者）：","用法：蔗糖铁 100mg + 0.9%氯化钠 100ml 静滴（透析中缓慢输注，>30分钟；每周1～3次，累计剂量按铁缺乏程度计算：常用总剂量 1000mg）；或 右旋糖酐铁","方案2（促红素，纠正贫血）：","用法：重组人促红素 10000IU 皮下注射 每周1次（或 3000～5000IU 每周2～3次）；目标Hb 100～120g/L（避免>130g/L增加血栓风险）；透析患者可静脉给药（透析后）","方案3（输血，重度贫血或急性失血）：","用法：红细胞悬液输注（Hb<60g/L或<70g/L伴症状）；注意输血相关免疫致敏（影响肾移植）与容量负荷","方案4（营养与辅助支持）：","用法：0.9%氯化钠 静滴（稀释铁剂或药物）；左卡尼汀 1g 静推（透析患者，改善贫血与心功能）；维生素C 0.2g 静滴（促进铁利用，遵医嘱）","📌 促红素使用前必须纠正铁缺乏（铁缺乏是EPO抵抗最常见原因）；监测血压（EPO可致高血压）与血栓风险；目标Hb 100～120g/L。"],"oral_medication":["⚠️ 口服铁剂与HIF-PHI是常用方案：","药物1（口服铁剂）：","用法：琥珀酸亚铁 0.1g bid（餐间服，与维生素C 0.2g 同服促进吸收）；或多糖铁复合物 150mg qd（胃肠刺激小）；避免与钙剂、磷结合剂、浓茶同服（间隔2小时）〔调 ★ 铁负荷过多禁用；★ 与四环素/喹诺酮/左甲状腺素间隔2小时〕","药物2（HIF-PHI，口服纠正贫血）：","用法：罗沙司他 100mg tiw（按体重：40～60kg 100mg、>60kg 120mg，每周3次）；监测Hb（目标100～120g/L）与肝功能","药物3（叶酸与维生素B12）：","用法：叶酸 5mg qd；维生素B12 500μg 肌注 每月1次（吸收障碍或透析患者）","药物4（辅助治疗）：","用法：左卡尼汀 1g 口服 tid（透析患者，改善贫血与肌痉挛）；复合维生素B 2片 tid","📌 口服铁剂吸收受尿毒症与磷结合剂影响（透析患者静脉铁剂更有效）；HIF-PHI需监测Hb与肝功能（避免Hb过度升高）。"],"treatment":["评估与目标设定：明确贫血程度与铁状态（铁蛋白、TSAT），目标Hb 100～120g/L（不超过130g/L）","铁剂补充：优先静脉铁剂（透析患者或口服无效者），先纠正绝对与功能性铁缺乏（EPO治疗前必须）","促红素治疗：重组人促红素皮下或静脉给药，按Hb反应调整剂量（4～6周评估）；注意EPO抵抗原因（铁缺乏、炎症、感染、继发性甲旁亢、铝中毒、营养不良）","HIF-PHI（罗沙司他）：口服，适用于非透析与透析患者，尤其炎症状态下EPO反应差者","其他病因处理：补充叶酸与维生素B12、控制继发性甲旁亢（磷结合剂与活性维生素D）、纠正炎症与感染、避免透析失血（减少抽血与管路残留血）","输血原则：尽量避免（免疫致敏与容量负荷），仅重度贫血或急性失血时使用","营养与透析充分性：保证蛋白与营养摄入、充分透析（Kt/V达标）","随访：每2～4周监测血红蛋白与铁代谢，调整剂量；评估心血管风险与生活质量改善"],"management":["贫血指标监测：每2～4周复查血红蛋白、红细胞指数；每1～3个月复查铁代谢（铁蛋白、TSAT）","促红素与铁剂给药护理：铁剂缓慢静滴（>30分钟）观察过敏反应（低血压、皮疹）；促红素观察血压变化（EPO致高血压）","血压监测：EPO治疗可致高血压与血栓，需每日监测血压并遵医嘱调整降压药与EPO剂量","饮食护理：补充含铁食物（瘦肉、动物肝脏、深绿色蔬菜）+维生素C；使用磷结合剂者铁剂与磷结合剂间隔2小时","透析相关护理：减少管路残留血与不必要抽血（减少失血）、评估透析充分性（Kt/V）","宣教：铁剂与促红素需按医嘱使用（不可自行停）、避免浓茶与钙剂同服铁剂、定期复查血常规与铁代谢、识别贫血加重症状（气促、心悸）","功能状态与生活质量评估：评估活动耐量与睡眠，记录改善情况"],"notes":["肾性贫血的治疗顺序是『先补铁、后促红素』——铁缺乏是EPO抵抗最常见原因","目标血红蛋白 100～120g/L（避免>130g/L：增加血栓、高血压与心血管事件风险）","透析患者口服铁剂吸收差，静脉铁剂为首选；血清铁蛋白<100ng/ml或TSAT<20%提示需补铁","EPO抵抗原因：铁缺乏、炎症与感染、继发性甲旁亢、铝中毒、营养不良与失血（需逐一排查）","避免不必要输血（免疫致敏影响肾移植、容量负荷与输血反应）"],"emergency":["重度贫血（Hb<60g/L）伴呼吸困难、心绞痛或意识改变 → 输注红细胞悬液并吸氧、监护","静脉铁剂输注中出现低血压、皮疹与呼吸困难（过敏反应）→ 立即停止输注、肾上腺素/激素/抗组胺药、补液","EPO治疗后血压急剧升高伴头痛与意识改变（高血压脑病）→ 立即降压并停用EPO、评估","贫血伴急性左心衰（端坐呼吸、肺水肿）→ 吸氧、利尿、必要时输血（缓慢少量）与透析超滤","铁剂外渗致局部疼痛与色素沉着 → 停止输注、局部处理并记录"],"pinyin":"sxxp","icd10":"D63.8","physical_exam":["生命体征：血压（EPO相关高血压）、心率（贫血代偿性增快）、呼吸","一般情况：面色与结膜苍白、乏力程度、活动耐量（NYHA/功能状态）","心脏：心界扩大、心率增快、心音（贫血性杂音）、有无心衰体征","肺部：呼吸音、湿啰音（容量负荷）","皮肤黏膜：苍白、干燥、瘙痒（尿毒症）、出血点（血小板功能异常）","下肢与容量：水肿程度、体重变化（透析间期体重增长）","肾脏相关：肾区叩击痛、有无腹块（多囊肾）、透析通路（内瘘震颤与杂音）"],"lab_tests":["血常规（血红蛋白、红细胞指数、网织红细胞）：每2～4周（治疗期）监测与疗效评估","铁代谢（血清铁、铁蛋白、总铁结合力、转铁蛋白饱和度）：每1～3个月（治疗期）","肾功能（肌酐、eGFR、尿素氮）+电解质：CKD分期与透析充分性","维生素B12+叶酸：营养性贫血排除","粪便隐血（+消化道内镜必要时）：排除消化道失血","CRP+PCT+甲状旁腺激素（PTH）+血铝：炎症、继发性甲旁亢与铝中毒（EPO抵抗原因）","肝功能+血糖：HIF-PHI与用药安全监测"],"nursing":["给药护理：铁剂缓慢静滴（>30分钟）并观察过敏反应（低血压、皮疹、胸闷）；促红素皮下注射后观察血压与局部反应","血压与血栓监测：EPO治疗期间每日测血压，观察头痛、胸痛与下肢肿胀（高血压与血栓风险）","饮食与用药指导：鼓励含铁饮食与维生素C；指导铁剂与磷结合剂、钙剂间隔2小时服用；避免浓茶与咖啡","透析护理：配合减少管路残留血与不必要抽血；评估透析充分性并记录","症状观察：乏力、气促、心悸与活动耐量变化，异常报告；识别贫血加重与心衰征象","宣教：铁剂与促红素按医嘱使用不可自行停、定期复查血常规与铁代谢、出现胸闷气促立即就诊、坚持透析与饮食管理"],"diet":["高蛋白、含铁丰富饮食（瘦肉、动物肝脏、深绿色蔬菜、豆类）+ 维生素C促进铁吸收","避免浓茶、咖啡与钙剂、磷结合剂与铁剂同服（间隔2小时）","CKD饮食要求：限制钠（<3～5g）、钾与磷（按化验调整）；优质蛋白（0.8～1.2g/kg/日，透析患者1.0～1.2g/kg）","充足热量（30～35kcal/kg/日）避免蛋白质被消耗","透析患者按透析饮食要求控制液体摄入（体重增长<干体重3%～5%）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1423},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"74f3de4199a8af70884fe8d89865876d70380d7f9b0d0570c48b225b839b7a11","pinyin":"shenxingpinxue","initials":"sxpx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、活动后心悸气短、头晕、注意力不集中\\n面色与结膜苍白、指甲苍白、心率增快（贫血代偿）\\n原有心衰或冠心病症状加重（贫血增加心脏负荷）\\n食欲减退、营养不良（与尿毒症症状重叠）\\n认知功能下降、睡眠障碍与生活质量下降",60],["摘要","肾性贫血是慢性肾脏病（CKD）常见并发症，主要由促红细胞生成素（EPO）相对缺乏所致，并伴铁缺乏、炎症、尿毒症毒素与营养不良等因素。表现为正细胞正色素性贫血，与CKD进展平行（eGFR<60ml/min开始出现）。治疗包括铁剂、促红素与低氧诱导因子脯氨酰羟化酶抑制剂（HIF-PHI）。",30],["疾病编码","D63.8",30],["原首字母","sxxp",60]]},{"id":"orders-0374441ab5d784541661","key":"v1-c9ccc21dfe2a3058|orders-0374441ab5d784541661","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"腹膜透析相关腹膜炎","category":"内科-泌尿","raw":{"name":"腹膜透析相关腹膜炎","category":"内科-泌尿","summary":"腹膜透析相关腹膜炎是腹膜透析（PD）最常见的严重并发症，多因操作污染（接触污染、导管出口感染）致细菌（革兰阳性球菌为主，金黄色葡萄球菌与凝固酶阴性葡萄球菌）进入腹腔，也可为革兰阴性菌与真菌。表现为透出液浑浊、腹痛与发热，需立即留取透出液培养并经验性腹腔内抗生素治疗。","symptoms":["透出液浑浊（最早且最可靠的表现）、絮状物或纤维蛋白凝块","腹痛（弥漫性，程度不等，可伴压痛与反跳痛）、腹胀","发热（可低热或高热）、寒战、恶心呕吐","导管出口或隧道感染征象：红肿、压痛、脓性分泌物","严重者出现脓毒症表现（低血压、意识改变）"],"diagnosis":["透出液检查（关键）：细胞计数（白细胞>100/μl，中性粒细胞>50%诊断腹膜炎）、革兰染色、细菌培养（留取在抗生素前）","透出液培养：需氧+厌氧+真菌培养（阳性率>80%）；同时做血培养（疑脓毒症）","透出液生化+革兰染色+细胞学：排除其他原因（嗜酸性粒细胞增多性腹膜炎、肿瘤、结核）","导管出口与隧道检查：分泌物培养与体检","血常规+CRP+PCT：炎症程度评估","腹部超声/CT：排除腹腔内脓肿、脏器病变与其他急腹症（疑继发性腹膜炎）","鉴别诊断：继发性腹膜炎（外科急腹症）、化学性腹膜炎（透析液刺激）、嗜酸粒细胞性腹膜炎、结核性腹膜炎"],"infusion":["⚠️ 腹腔内给药是首选途径，须立即留取培养后开始经验性治疗！","","方案1（经验性腹腔内抗生素，覆盖革兰阳性与阴性菌）：","  用法：头孢唑林 1g（或万古霉素 1g）加入透析液 2L 中腹腔内留腹 6小时（负荷剂量），之后维持剂量（头孢唑林 250mg/2L 每袋）——革兰阳性覆盖；联合 头孢他啶 1g（负荷，腹腔内）+ 维持 250mg/2L 或 庆大霉素 40mg（负荷）——革兰阴性覆盖〔调 ★★ 按 CrCl 调量并监测谷浓度10-20mg/L；耳肾毒性〕","","方案2（静脉给药，重症/脓毒症）：","  用法：万古霉素 1g（NS 100ml 或 5%GS 100ml）静滴 q12h（监测血药浓度）+ 头孢他啶 2g 静滴 q8h（或 哌拉西林他唑巴坦 4.5g q8h）；脓毒症休克者按脓毒症处理〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","方案3（真菌性腹膜炎）：","  用法：氟康唑 200mg 腹腔内/静滴 qd 或 卡泊芬净 50～70mg 静滴 qd——通常需拔除导管","","方案4（支持治疗）：","  用法：0.9%氯化钠 静滴（补液）；白蛋白 10g 静滴（低蛋白者）；必要时镇痛（对乙酰氨基酚）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","📌 治疗前必须留取透出液培养；革兰阳性菌用头孢唑林/万古霉素，革兰阴性菌用头孢他啶/氨基糖苷类；反复或难治性腹膜炎（抗生素5天无效）需拔除PD导管（改血液透析）。"],"oral_medication":["⚠️ 腹腔内用药为主，口服为辅：","药物1（口服抗生素，按药敏序贯）：","用法：头孢氨苄 0.5g qid 或 阿莫西林克拉维酸 0.625g tid（敏感菌，疗程14～21天）；利福平 0.45g qd（金黄色葡萄球菌辅助，遵医嘱）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（对症与支持）：","用法：对乙酰氨基酚 0.5g 必要时（腹痛）；乳果糖 15ml bid（便秘，防导管移位）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物3（预防与出口护理）：","用法：莫匹罗星软膏 导管出口处 每日1次（金黄色葡萄球菌预防，遵医嘱）；聚维酮碘或氯己定出口护理（按中心规范）","药物4（营养支持）：","用法：口服营养补充剂 1～2份/日；复合维生素B 2片 tid","📌 抗生素疗程14～21天（金黄色葡萄球菌与难治性者更长）；治疗期间每日评估透出液变清情况；出口感染需加强护理。"],"treatment":["立即留取透出液培养（细胞计数+革兰染色+需氧厌氧真菌培养），随后开始经验性腹腔内抗生素（覆盖革兰阳性与阴性菌）","腹腔内给药方案：负荷剂量留腹6小时，随后每袋透析液维持剂量（疗程14～21天）；培养结果出来按药敏调整（尽量窄谱）","严重感染或脓毒症：静脉抗生素+腹腔内给药，必要时转ICU","拔管指征：难治性腹膜炎（抗生素治疗5天透出液不转清）、真菌性腹膜炎、反复发作（同一菌株复发）、难治性导管出口/隧道感染、脓毒症——拔管后改血液透析（4～6周后可再置管）","导管相关处理：出口感染加强局部护理与抗生素；隧道感染常需拔管","透出液冲洗：部分中心采用快速冲洗（1～2次交换不含抗生素）减少炎症介质","支持治疗：补液、营养支持（蛋白丢失增加）、镇痛与电解质监测","随访与预防：评估疗效（透出液细胞计数与培养复查），培训患者操作规范（洗手、戴口罩、无菌操作），定期评估出口与隧道"],"management":["透出液观察：每次换液观察透出液是否浑浊（记录浑浊、絮状物与颜色），异常立即留取标本并报告","标本留取：按规范留取透出液（>50ml，注入血培养瓶提高阳性率）并在使用抗生素前完成","腹腔内给药护理：按医嘱将抗生素加入透析液、留腹时间准确（负荷6小时）、记录给药时间与剂量","症状与体征监测：腹痛、发热、寒战与腹部压痛，监测生命体征与透出液性状变化（每袋记录）","导管出口护理：每日观察出口与隧道（红肿、渗液、压痛）、按规范清洁消毒、避免牵拉与污染","营养与液体管理：高蛋白饮食（腹透丢失蛋白3～5g/日）、记录出入量与体重（干体重评估）","宣教：严格无菌操作（洗手、口罩、戴手套）、连接与断开规范、出现透出液浑浊立即联系医疗团队（不可等待）、按时随访"],"notes":["透出液浑浊是腹膜透析相关腹膜炎最早、最可靠的表现——出现浑浊应立即留取标本并开始治疗（不必等结果）","诊断标准：透出液白细胞>100/μl且中性粒细胞>50%（或涂片/培养阳性）+ 临床表现","经验性抗生素必须同时覆盖革兰阳性与阴性菌（头孢唑林/万古霉素+头孢他啶/庆大霉素）","抗生素治疗5天透出液不转清为难治性腹膜炎，需拔除PD导管（避免导致包裹性硬化性腹膜炎）","真菌性腹膜炎一经诊断应拔管并抗真菌治疗（预后差）"],"emergency":["透出液浑浊伴剧烈腹痛与高热（重症腹膜炎）→ 立即留取标本+腹腔内/静脉抗生素，评估脓毒症","腹膜炎伴血压下降与意识改变（脓毒症休克）→ 立即复苏+静脉广谱抗生素+ICU，评估拔管","腹痛伴腹膜刺激征与影像提示腹腔内脓肿（继发性腹膜炎）→ 外科急会诊与手术评估","抗生素治疗5天透出液不转清（难治性腹膜炎）→ 拔除PD导管并改血液透析","真菌性腹膜炎伴透出液絮状物与发热 → 立即拔管+抗真菌治疗"],"pinyin":"fmtxxfmy","icd10":"T85.7","physical_exam":["生命体征：体温、血压（脓毒症）、心率、呼吸","腹部：弥漫压痛与反跳痛、腹胀、肠鸣音（减弱）","透析导管：出口与隧道（红肿、渗液、压痛、脓性分泌物）、导管位置与固定","透出液：浑浊程度、颜色、絮状物与纤维蛋白凝块（每袋观察）","一般情况：脱水或水肿、营养状态、体重与干体重对比","皮肤与穿刺部位：出口周围皮肤情况、有无感染灶","其他：肺部（感染灶）、泌尿系（感染源）"],"lab_tests":["透出液细胞计数（白细胞>100/μl、中性粒细胞>50%）+革兰染色：诊断核心（治疗前留取）","透出液细菌培养（需氧+厌氧+真菌，注入血培养瓶提高阳性率）：病原学诊断与药敏","血常规+CRP+PCT+血培养（疑脓毒症）：全身感染评估","透出液生化+淀粉酶（必要时）：排除胰源性与其他原因","腹部超声/CT（疑继发性腹膜炎或脓肿）：排除外科急腹症与腹腔脓肿","白蛋白+前白蛋白+电解质：营养与电解质状态（腹膜炎丢失蛋白增加）","导管出口分泌物培养：出口/隧道感染病原学"],"nursing":["透出液观察与记录：每袋换液观察透出液性状（浑浊、絮状物）并记录，发现浑浊立即留取标本并报告","标本留取护理：按规范留取透出液（>50ml注入血培养瓶），确保在抗生素使用前完成","腹腔内给药护理：按医嘱将抗生素加入透析液、准确记录留腹时间（负荷6小时）与剂量，观察疗效（透出液变清）","出口与导管护理：每日观察出口与隧道、按规范清洁消毒、固定导管避免牵拉、观察有无渗液与红肿","症状与生命体征监测：腹痛、发热、寒战与腹部压痛，每4小时测体温，异常立即报告","宣教：无菌操作规范（洗手、戴口罩、戴手套、连接消毒）、发现透出液浑浊立即联系团队、营养与液体管理、按时随访"],"diet":["高蛋白饮食（1.2～1.5g/kg/日，腹透每日丢失蛋白3～5g）、高热量（30～35kcal/kg/日）","限制钠（<3～5g/日）与液体（按超滤量与尿量调整，体重增长<干体重3%～5%）","限制钾与磷（按化验调整，腹透患者高钾风险低于血透）","腹膜炎期间：易消化、少量多餐，必要时口服营养补充剂（感染消耗增加）","避免生冷与不洁食物（腹透患者腹膜炎风险与肠道细菌移位相关）；充足维生素补充"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1424},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"77fcfb3e4cae02a2692547b9e662b02bcc64f980e84c27c8275ffb8ac0abb800","pinyin":"fumotouxixiangguanfumoyan","initials":"fmtxxgfmy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","透出液浑浊（最早且最可靠的表现）、絮状物或纤维蛋白凝块\\n腹痛（弥漫性，程度不等，可伴压痛与反跳痛）、腹胀\\n发热（可低热或高热）、寒战、恶心呕吐\\n导管出口或隧道感染征象：红肿、压痛、脓性分泌物\\n严重者出现脓毒症表现（低血压、意识改变）",60],["摘要","腹膜透析相关腹膜炎是腹膜透析（PD）最常见的严重并发症，多因操作污染（接触污染、导管出口感染）致细菌（革兰阳性球菌为主，金黄色葡萄球菌与凝固酶阴性葡萄球菌）进入腹腔，也可为革兰阴性菌与真菌。表现为透出液浑浊、腹痛与发热，需立即留取透出液培养并经验性腹腔内抗生素治疗。",30],["疾病编码","T85.7",30],["原首字母","fmtxxfmy",60]]},{"id":"orders-58796aa10e7590db0718","key":"v1-c9ccc21dfe2a3058|orders-58796aa10e7590db0718","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"贫血的鉴别诊断与处理思路","category":"内科-血液","raw":{"name":"贫血的鉴别诊断与处理思路","category":"内科-血液","summary":"贫血是外周血血红蛋白低于正常下限（成年男性<120g/L、女性<110g/L、孕妇<100g/L）的临床综合征。鉴别诊断按红细胞形态（MCV）分为小细胞性（缺铁、地中海贫血、慢性病贫血）、正细胞性（急性失血、溶血、肾性贫血、骨髓病性）与大细胞性（巨幼细胞贫血、MDS、肝病、甲减），据病因治疗。","symptoms":["乏力、头晕、活动后心悸气短、注意力不集中与睡眠障碍","面色与结膜苍白、指甲苍白脆薄、口角炎与舌炎（缺铁、营养性）","溶血表现：黄疸、脾大、酱油色尿（血红蛋白尿）、胆石症","出血表现：皮肤瘀点瘀斑、牙龈与鼻腔出血、黑便（合并血小板或凝血异常）","原发病表现：消瘦（肿瘤）、发热（感染/血液病）、骨痛（骨髓瘤）、水肿（肾病）、神经症状（维生素B12缺乏）"],"diagnosis":["血常规+红细胞形态（MCV、MCH、MCHC）+网织红细胞计数：贫血分类与骨髓代偿能力评估（第一步）","MCV分类：小细胞（MCV<80fl）、正细胞（80～100fl）、大细胞（>100fl）","铁代谢（血清铁、铁蛋白、总铁结合力、转铁蛋白饱和度）：缺铁性贫血（铁蛋白<15ng/ml）与其他小细胞贫血鉴别","维生素B12+叶酸+同型半胱氨酸：巨幼细胞贫血","溶血相关：网织红细胞升高、间接胆红素升高、LDH升高、结合珠蛋白降低、Coombs试验、红细胞脆性试验、G6PD活性","骨髓穿刺+活检+铁染色：骨髓病性贫血、MDS、白血病与再生障碍性贫血（必要时）","器官功能与病因筛查：肾功能（肾性贫血）、肝功能、甲状腺功能、粪便隐血+消化道内镜（失血）、妇科检查（月经过多）","促红细胞生成素（EPO）水平：肾性贫血与再障鉴别（必要时）"],"infusion":["⚠️ 按病因治疗，输血指征需严格掌握！","","方案1（重度贫血输血，Hb<60g/L或有症状）：","  用法：红细胞悬液 1～2U 静滴（目标Hb 70～90g/L，冠心病者80～100g/L）；缓慢输注并监测生命体征（防容量负荷）","","方案2（缺铁性贫血，静脉铁剂，口服不耐受或吸收障碍者）：","  用法：蔗糖铁 100～200mg + 0.9%氯化钠 100ml 静滴（>30分钟，每周1～3次）；按铁缺乏量计算总剂量（常用1000mg）","","方案3（巨幼细胞贫血，重度或吸收障碍）：","  用法：维生素B12 1000μg 肌注 qd×1周 → 每周1次；叶酸 5mg 口服/（NS 100ml 或 5%GS 100ml）静滴（注意先补B12再补叶酸，避免加重神经症状）","","方案4（病因治疗与支持）：","  用法：0.9%氯化钠 静滴（维持通路与补液）；肾性贫血用促红素（见肾性贫血条目）；溶血性贫血用激素（甲泼尼龙 40～80mg 静滴，免疫性溶血）；慢性病贫血治疗原发病〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","📌 贫血治疗必须先明确病因（不可盲目补铁与输血）；输血目标是缓解症状而非纠正数值；免疫性溶血禁用输血（除危急情况）。"],"oral_medication":["⚠️ 按病因选择（同类只选一种）：","药物1（缺铁性贫血）：","用法：琥珀酸亚铁 0.1g bid～tid（餐间服）+ 维生素C 0.2g tid（促进吸收）；或多糖铁复合物 150mg qd〔调 ★ 铁负荷过多禁用；★ 与四环素/喹诺酮/左甲状腺素间隔2小时〕","药物2（巨幼细胞贫血）：","用法：维生素B12 500μg 肌注 每月1次（终身，吸收障碍者）；叶酸 5mg qd","药物3（肾性贫血/慢性病贫血）：","用法：罗沙司他 100mg tiw（按体重）；促红素（皮下注射）；铁剂按铁代谢补充","药物4（辅助与饮食）：","用法：复合维生素B 2片 tid；维生素C 0.2g tid；避免与钙剂、浓茶、抗酸剂同服（影响铁吸收）","📌 缺铁性贫血补铁需持续至铁蛋白恢复正常（一般血红蛋白正常后继续3～6个月以补足储存铁）；巨幼贫需先查B12缺乏原因（萎缩性胃炎、素食、回肠切除）。"],"treatment":["病因治疗（核心）：缺铁（补铁+寻找失血原因：消化道、月经过多）、巨幼（补B12/叶酸+病因）、溶血（激素/免疫抑制/停用致病药物）、肾性贫血（EPO/铁剂/HIF-PHI）、慢性病贫血（治疗原发病）、骨髓病性（治疗原发病）","输血治疗：严格指征（Hb<60g/L或心血管症状），目标Hb 70～90g/L，避免不必要输血","营养支持：高蛋白、富含铁/叶酸/B12饮食；纠正营养不良","并发症防治：贫血性心脏病（严重贫血致心衰）、感染（白细胞减少）、出血（血小板减少）","监测疗效：补铁后2～4周网织红细胞升高、4周血红蛋白上升约10g/L（反应不佳需重新评估诊断与依从性）","多学科协作：血液科、消化科（失血）、妇科（月经过多）、肾内科（肾性贫血）","随访：血红蛋白与铁代谢每1～3个月复查至正常，之后定期随访","宣教：遵医嘱服药（铁剂需长期）、避免浓茶与钙剂同服铁剂、识别贫血加重症状（气促、心悸）、按时复查"],"management":["贫血评估与分类：记录血红蛋白、MCV与网织红细胞，初步分类并安排针对性检查（勿盲目补铁）","症状与功能评估：评估乏力、气促、活动耐量与心率，记录并监测（贫血性心脏病风险）","输血护理：严格核对与监测（输血反应），控制输注速度（尤其老年与心功能不全者，防容量负荷）","用药护理：铁剂餐间服用并与维生素C同服、观察胃肠道反应与黑便（正常现象）；静脉铁剂观察过敏反应","饮食指导：富铁（瘦肉、动物肝脏、深绿蔬菜）、富叶酸与B12（绿叶蔬菜、蛋奶、动物内脏）饮食","病因随访提醒：消化道失血者安排内镜、月经过多者妇科评估、老年贫血者警惕肿瘤","宣教：铁剂需长期（血红蛋白正常后继续3～6个月）、避免浓茶咖啡与钙剂同服、出现黑便与气促及时就诊"],"notes":["贫血鉴别第一步是红细胞形态（MCV）与网织红细胞计数，其次按分类选择铁代谢、B12/叶酸、溶血与骨髓检查","缺铁性贫血必须寻找失血原因（成人尤其男性与绝经后女性需排查消化道肿瘤）","巨幼细胞贫血：维生素B12缺乏可致神经系统损害（亚急性联合变性），补叶酸前必须先补B12（否则加重神经症状）","慢性病贫血（炎症性贫血）表现为铁利用障碍（铁蛋白正常或升高、TSAT降低），以治疗原发病为主","输血指征严格掌握（Hb<60g/L或有症状），不必要输血增加感染与免疫风险"],"emergency":["重度贫血伴呼吸困难、胸痛或意识改变（Hb<60g/L）→ 立即输注红细胞并吸氧、监护","急性溶血危象（寒战高热、酱油色尿、腰背痛、血红蛋白快速下降）→ 立即停用可疑药物、补液碱化尿液、激素，必要时输血与血液净化","溶血危象伴少尿与急性肾损伤 → 补液、碱化尿液、必要时CRRT","贫血伴急性左心衰（端坐呼吸、肺水肿）→ 吸氧、利尿、缓慢少量输血（必要时透析超滤）","贫血伴出血不止（血小板减少/凝血障碍）→ 输注血小板/凝血因子并病因处理"],"pinyin":"pxdjbzdyclsl","icd10":"D64.9","physical_exam":["生命体征：心率（贫血代偿增快）、血压、呼吸（气促）、体温（感染/淋巴瘤）","一般情况：面色与结膜苍白程度、营养状态、消瘦（肿瘤）、发育（儿童）","皮肤黏膜：口角炎与舌炎（缺铁）、牛肉舌与舌面光滑（B12缺乏）、黄疸（溶血）、瘀点瘀斑（血小板减少）、反甲","心脏：心界扩大、心率增快、贫血性收缩期杂音、心衰体征","腹部：肝脾大小（溶血、MDS、淋巴瘤）、腹块（肿瘤）","神经系统：深感觉减退、Romberg征、振动觉与位置觉（B12缺乏致亚急性联合变性）、病理反射","淋巴结与骨：淋巴结肿大（淋巴瘤）、骨压痛（骨髓瘤/白血病）"],"lab_tests":["血常规+红细胞形态（MCV、MCH、MCHC）+网织红细胞：贫血分类第一步","铁代谢（血清铁、铁蛋白、总铁结合力、TSAT）：缺铁性贫血与慢性病贫血鉴别","维生素B12+叶酸+同型半胱氨酸+甲基丙二酸（必要时）：巨幼细胞贫血诊断","溶血全套：间接胆红素、LDH、结合珠蛋白、网织红细胞、Coombs试验、红细胞脆性试验、G6PD活性、血红蛋白电泳","粪便隐血+消化道内镜（必要时）+妇科检查：失血来源（消化道肿瘤、月经过多）","骨髓穿刺+活检+铁染色+细胞遗传学：骨髓病性贫血、MDS、白血病与再障","肾功能+促红素水平+甲状腺功能+肝功能：肾性贫血、内分泌疾病与肝病性贫血"],"nursing":["病情观察：评估乏力、气促、心悸与活动耐量，监测心率与血压（贫血性心脏病风险），异常立即报告","输血护理：严格核对与监测（输血反应）、控制输注速度（老年与心功能不全者缓慢，防容量负荷）","用药护理：铁剂餐间服用并与维生素C同服、观察胃肠道反应（黑便为正常现象）；静脉铁剂缓慢输注并观察过敏反应","饮食指导：鼓励富铁、叶酸与B12饮食；避免浓茶、咖啡、钙剂与铁剂同服（间隔2小时）","安全护理：重度贫血者卧床休息、防跌倒（头晕）、活动时协助、必要时吸氧","宣教：铁剂需长期服用（血红蛋白正常后继续3～6个月）、按时复查血常规与铁代谢、出现气促/黑便/乏力加重及时就诊"],"diet":["富铁食物：瘦肉、动物肝脏与血制品、深绿色蔬菜、豆类、黑木耳（植物铁吸收差，需配合维生素C）","富叶酸食物：绿叶蔬菜、动物肝脏、豆类、全谷物（避免过度烹调破坏叶酸）","富维生素B12食物：动物肝脏、鱼虾、蛋奶（素食者需补充剂）","促进铁吸收：餐后或餐间服铁剂并同服维生素C；避免浓茶、咖啡、钙剂与抗酸剂同服","高蛋白饮食纠正营养不良；避免长期素食（B12缺乏）与过度节食"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1425},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a8f37506536b1a647aadae29d5cc5f2032d2174ecaa107b9bbf4ba582009f86b","pinyin":"pinxuedejianbiezhenduanyuchulisilu","initials":"pxdjbzdyclsl","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、头晕、活动后心悸气短、注意力不集中与睡眠障碍\\n面色与结膜苍白、指甲苍白脆薄、口角炎与舌炎（缺铁、营养性）\\n溶血表现：黄疸、脾大、酱油色尿（血红蛋白尿）、胆石症\\n出血表现：皮肤瘀点瘀斑、牙龈与鼻腔出血、黑便（合并血小板或凝血异常）\\n原发病表现：消瘦（肿瘤）、发热（感染/血液病）、骨痛（骨髓瘤）、水肿（肾病）、神经症状（维生素B12缺乏）",60],["摘要","贫血是外周血血红蛋白低于正常下限（成年男性<120g/L、女性<110g/L、孕妇<100g/L）的临床综合征。鉴别诊断按红细胞形态（MCV）分为小细胞性（缺铁、地中海贫血、慢性病贫血）、正细胞性（急性失血、溶血、肾性贫血、骨髓病性）与大细胞性（巨幼细胞贫血、MDS、肝病、甲减），据病因治疗。",30],["疾病编码","D64.9",30],["原首字母","pxdjbzdyclsl",60]]},{"id":"orders-3d6fb8ba4a1a3a4a43c7","key":"v1-c9ccc21dfe2a3058|orders-3d6fb8ba4a1a3a4a43c7","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"发热待查（FUO）","category":"内科-感染","raw":{"name":"发热待查（FUO）","category":"内科-感染","summary":"发热待查（FUO）指发热≥3周、体温多次>38.3℃、经≥1周系统检查仍未明确病因者。病因主要分四类：感染（结核、脓肿、感染性心内膜炎、EBV/CMV）、风湿免疫病（SLE、成人Still病、血管炎、巨细胞动脉炎）、肿瘤（淋巴瘤、白血病、肾癌、肝癌）与其他（药物热、甲状腺功能亢进、中枢性发热）。诊断关键是详细的病史与体检+分层检查。","symptoms":["长期发热（热型：稽留热、弛张热、间歇热或不规则热），可伴畏寒寒战与盗汗","全身症状：乏力、消瘦、食欲减退、贫血（慢性病）","定位症状：咳嗽咳痰（肺部）、腹痛腹泻（腹腔）、腰痛尿频（泌尿）、关节痛皮疹（风湿）、淋巴结肿大（淋巴瘤/结核）","药物热：发热与用药时间相关，伴皮疹与嗜酸性粒细胞增多，停药后缓解","注意：老年患者与免疫抑制者可无典型症状（感染灶隐匿）"],"diagnosis":["详细病史（关键）：起病方式、热型、伴随症状、旅行史、动物接触史、职业暴露、用药史（含中草药与保健品）、既往病史与手术史","完整体格检查（重复进行）：皮肤黏膜、淋巴结、心肺、腹部（肝脾与腹块）、直肠指检、关节与神经系统；注意齿、鼻窦、肛周与置管部位","第一阶段（必查）：血常规+CRP+PCT+血沉、肝肾功能、电解质、尿常规+尿培养、血培养×3套（不同时间）、胸片/胸部CT、腹部超声","第二阶段（按线索）：结核相关（PPI/IGRA、痰与体液培养、必要时活检）、感染性心内膜炎（心脏超声）、风湿免疫（ANA、抗dsDNA、ANCA、RF、补体）、肿瘤标志物、PET-CT（诊断不明时价值高）","第三阶段（有创检查）：骨髓穿刺+培养、淋巴结或肝活检、腹腔镜探查（必要时）","PET-CT：不明原因发热的重要检查（定位隐匿感染、肿瘤与炎症）","基因与特殊病原：mNGS（二代测序，疑难感染）、布鲁菌、Q热、立克次体、寄生虫与真菌检查"],"infusion":["⚠️ 未明确病因前避免盲目使用抗生素与激素（可掩盖病情、延误诊断）！","","方案1（经验性抗感染，仅用于病情危重或高度怀疑感染）：","  用法：病情危重者可用 头孢曲松 2g 静滴 qd + 莫西沙星 0.4g 静滴 qd（覆盖常见细菌与非典型病原）——同时留取培养；明确后按药敏调整〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案2（疑结核，诊断性治疗）：","  用法：异烟肼 0.3g + 利福平 0.45g + 吡嗪酰胺 1.5g + 乙胺丁醇 0.75g（口服为主；重症可用静脉制剂）——诊断性治疗需评估2～4周疗效（需先留取标本）〔调 ★ 肝功能不全慎用；★ 强CYP450诱导剂（大量相互作用）〕","","方案3（风湿免疫病，如成人Still病/血管炎）：","  用法：甲泼尼龙 40～80mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（诊断明确后，症状严重者）；或 非甾体抗炎药（口服为主）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案4（支持治疗与对症）：","  用法：0.9%氯化钠/葡萄糖 静滴（补液）；对乙酰氨基酚 0.5g 静滴 必要时（高热不适）；白蛋白（消耗明显者）；营养支持〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","📌 FUO处理原则：先检查后治疗；避免滥用抗生素、激素与退热药（掩盖热型与症状，延误诊断）；病情危重者可经验性治疗同时积极查找病因。"],"oral_medication":["⚠️ 对症与病因治疗（避免滥用退热药与激素）：","药物1（退热，慎用）：","用法：对乙酰氨基酚 0.5g 必要时（体温>39℃或明显不适，避免长期规律使用掩盖热型）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物2（病因治疗，明确后）：","用法：感染——按病原用药（抗感染/抗结核/抗真菌）；风湿免疫——泼尼松 0.5～1mg/kg/日+免疫抑制剂；肿瘤——按瘤种化疗〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物3（支持治疗）：","用法：复合维生素B 2片 tid + 维生素C 0.2g tid；口服营养补充剂（消瘦者）；必要时中药辨证（须与主管医师沟通）","药物4（避免）：","用法：避免自行使用抗生素、激素与中草药（可掩盖病情）；药物热者停用可疑药物（记录停药时间与体温变化）","📌 退热药不可规律长期使用（掩盖热型与症状）；明确病因后针对性治疗是根本。"],"treatment":["系统侦查性检查（分阶段）：第一阶段基础检查→第二阶段针对性检查→第三阶段有创检查（骨髓/活检）与PET-CT","避免盲目治疗：未明确病因前不常规使用抗生素、激素与退热药（可掩盖病情）；仅病情危重者经验性治疗","病因治疗：感染（抗生素/抗结核/抗真菌/抗寄生虫）、风湿免疫（激素+免疫抑制剂/生物制剂）、肿瘤（化疗/放疗）、药物热（停药）、其他（甲亢治疗、中枢性发热处理）","多学科协作与反复评估：感染科、风湿免疫科、血液科、影像科与病理科共同讨论；重复病史采集与体检（新体征常提示诊断）","营养与支持：足够热量与蛋白，纠正贫血与低蛋白，必要时肠内/肠外营养","对症处理：高热不适予退热（慎用）、疼痛镇痛、补液与电解质平衡","随访与告知：向患者与家属解释FUO的诊断难度与过程（多数最终可明确，约10%～20%始终不明病因，多预后良好）","宣教：配合完成各项检查与随访、避免自行用药（尤其抗生素与激素）、记录每日体温与症状变化"],"management":["体温与热型记录：每日测体温4～6次并绘制体温曲线（热型对诊断有提示价值），记录伴随症状与用药","检查配合与标本留取：按时留取血培养（不同时间、不同部位，需氧+厌氧）、尿培养与其他体液培养；配合影像与活检","用药记录与观察：详细记录所有用药（含院外药物、中草药与保健品）与用药-发热时间关系（药物热筛查）","症状与体征观察：每日重复体检（皮肤、淋巴结、腹部、关节与神经系统），记录新出现的体征","营养与支持护理：鼓励高蛋白高热量饮食，记录体重与进食量；高热者补液与口腔护理","心理护理：长期发热且诊断不明易致焦虑与不信任，需耐心解释检查必要性、保持沟通与支持","宣教：不可自行使用退热药与抗生素（观察热型）、按时复查、出现新症状（皮疹、关节痛、淋巴结肿大）立即报告"],"notes":["FUO三大病因类别：感染（约30%～40%）、风湿免疫病（20%～30%）、肿瘤（10%～20%），约10%～20%最终仍不明原因","诊断关键是详细病史（旅行、动物接触、用药史）与反复完整体检（新体征常提示诊断方向）","未明确病因前避免盲目使用抗生素、激素与退热药——可掩盖病情并延误诊断","PET-CT在FUO诊断中价值较高（定位隐匿感染、肿瘤与炎症），适用于一线检查阴性者","血培养需在使用抗生素前不同时间、不同部位采血（双侧×2～3套），可显著提高阳性率"],"emergency":["高热伴血压下降、意识改变（脓毒症休克）→ 立即血培养+广谱抗生素+液体复苏，转ICU","发热伴中性粒细胞缺乏（FN，化疗后）→ 1小时内经验性抗生素","发热伴颈项强直与意识改变（颅内感染）→ 立即腰穿（评估颅压后）+经验性抗生素，必要时头颅CT","发热伴皮疹与多器官损害（DRESS/血管炎）→ 停用可疑药物+激素+器官支持","发热伴心衰或呼吸困难（感染性心内膜炎/心包炎）→ 心脏超声+血培养+抗感染治疗"],"pinyin":"frdcfuo","icd10":"R50.9","physical_exam":["生命体征：体温（热型与曲线）、心率与脉率（相对缓脉提示伤寒/布鲁菌）、呼吸、血压","皮肤黏膜：皮疹（风湿/感染/药物热）、瘀点瘀斑、皮肤结节、甲床与结膜（贫血/栓塞）","淋巴结：全身浅表淋巴结大小、质地、活动度与压痛（淋巴瘤/结核）","头颈部：口腔与牙齿（牙源性感染）、扁桃体、鼻窦压痛、甲状腺（甲亢）、巩膜（黄疸）","心肺：心脏杂音（心内膜炎）、呼吸音与啰音（肺部感染）","腹部：肝脾大小与压痛、腹块、腹膜刺激征、直肠指检（肛周脓肿/前列腺）","关节与神经系统：关节红肿热痛、肌力与脑膜刺激征","其他：置管部位（导管相关感染）、手术瘢痕与植入物（深部感染）"],"lab_tests":["血常规+CRP+PCT+血沉：炎症与感染程度（多次动态观察）","血培养×3套（不同时间与部位，需氧+厌氧）+尿培养+痰培养：病原学诊断（抗生素前留取）","肝肾功能+电解质+尿常规+粪隐血：基础评估与隐性失血","结核相关：PPI/T-SPOT.TB、痰与体液抗酸染色与培养、胸片/胸部CT（必要时活检）","风湿免疫：ANA、抗dsDNA、ANCA、RF、抗CCP、补体、免疫球蛋白、抗磷脂抗体","心脏超声（疑心内膜炎）+腹部超声+PET-CT（不明原因时）","骨髓穿刺+培养+活检：血液病与骨髓感染（第三阶段检查）"],"nursing":["体温监测与记录：每4小时测体温并绘制曲线，记录热型、伴随症状与用药（诊断关键信息）","标本留取护理：配合按时采集血培养（不同时间与部位）、尿培养与体液培养，确保在抗生素前完成","用药记录：详细记录院内外所有药物、中草药与保健品使用及其与发热的时间关系（药物热筛查）","症状与体征观察：每日注意新出现的皮疹、淋巴结肿大、关节痛与腹部体征，及时报告","高热护理：物理降温与退热药（慎用）、补充水分与电解质、口腔与皮肤护理、卧床休息","心理护理与宣教：解释FUO诊断过程与耐心配合的必要性、避免自行使用抗生素与激素、按时复查与随访"],"diet":["高热量、高蛋白、高维生素饮食（长期发热消耗增加），少量多餐","充足水分摄入（每日2000ml以上，发热与出汗多者增加），维持水电解质平衡","易消化、清淡饮食；避免辛辣刺激与酒类","感染性疾病患者注意饮食卫生（避免生冷与不洁食物，布鲁菌病避免未消毒乳制品）","必要时口服营养补充剂或肠内营养支持（消瘦与食欲差者）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1426},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3174d93d457afaba5fd8517b8e954d22d730c531568eeaae70df9514c8aa0a5b","pinyin":"faredaicha（FUO）","initials":"frdc（","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","长期发热（热型：稽留热、弛张热、间歇热或不规则热），可伴畏寒寒战与盗汗\\n全身症状：乏力、消瘦、食欲减退、贫血（慢性病）\\n定位症状：咳嗽咳痰（肺部）、腹痛腹泻（腹腔）、腰痛尿频（泌尿）、关节痛皮疹（风湿）、淋巴结肿大（淋巴瘤/结核）\\n药物热：发热与用药时间相关，伴皮疹与嗜酸性粒细胞增多，停药后缓解\\n注意：老年患者与免疫抑制者可无典型症状（感染灶隐匿）",60],["摘要","发热待查（FUO）指发热≥3周、体温多次>38.3℃、经≥1周系统检查仍未明确病因者。病因主要分四类：感染（结核、脓肿、感染性心内膜炎、EBV/CMV）、风湿免疫病（SLE、成人Still病、血管炎、巨细胞动脉炎）、肿瘤（淋巴瘤、白血病、肾癌、肝癌）与其他（药物热、甲状腺功能亢进、中枢性发热）。诊断关键是详细的病史与体检+分层检查。",30],["疾病编码","R50.9",30],["原首字母","frdcfuo",60]]},{"id":"orders-3a8b37457cbb22a6d6d8","key":"v1-c9ccc21dfe2a3058|orders-3a8b37457cbb22a6d6d8","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"流行性脑脊髓膜炎","category":"内科-感染","raw":{"name":"流行性脑脊髓膜炎","category":"内科-感染","summary":"流行性脑脊髓膜炎（流脑）是脑膜炎奈瑟菌经呼吸道传播引起的急性化脓性脑膜炎，冬春季高发，儿童与青少年多见。表现为高热、头痛、呕吐、皮肤黏膜瘀点瘀斑与脑膜刺激征，暴发型可致休克与DIC（病死率高）。需尽早隔离与抗生素治疗（青霉素G首选）。","symptoms":["高热（39～40℃）、伴畏寒寒战、全身酸痛","剧烈头痛、喷射性呕吐、颈项强直、Kernig征与Brudzinski征阳性","皮肤黏膜瘀点瘀斑（特征性，多见于躯干与下肢，可融合成片）","暴发型（休克型）：瘀斑迅速增多融合、血压下降、皮肤发花、DIC与多器官衰竭","暴发型（脑型）：意识障碍、抽搐、瞳孔不等大与呼吸节律改变（脑疝）","婴幼儿表现不典型：拒奶、尖叫、前囟隆起、抽搐"],"diagnosis":["腰椎穿刺（关键，需先评估颅压，脑疝征象者暂缓）：脑脊液压力升高、外观混浊或脓性、白细胞显著升高（中性粒细胞为主）、蛋白升高、葡萄糖与氯化物降低","脑脊液涂片（革兰染色）：可见革兰阴性双球菌（快速诊断，阳性率60%～80%）","脑脊液培养+血培养（抗生素前留取）：病原学确诊与药敏","血常规+CRP+PCT：白细胞与炎症指标显著升高","皮肤瘀点涂片（革兰染色）：快速病原学证据（阳性率高）","头颅CT（意识障碍或颅压增高者，腰穿前）：排除颅内占位与脑疝风险","凝血功能+D-二聚体+乳酸（暴发型）：DIC与休克评估","脑脊液抗原检测/ PCR：脑膜炎奈瑟菌（快速诊断，尤其抗生素已用者）"],"infusion":["⚠️ 抢救用药，首选青霉素G，须尽早足量静脉给药！","","方案1（抗感染，首选青霉素G）：","  用法：青霉素G 400万～600万U（NS 100ml 或 5%GS 100ml）静滴 q4～6h（成人，疗程7～10天）；或 头孢曲松 2g 静滴 q12h（或头孢噻肟 2g q6h）——青霉素过敏或重症首选头孢曲松〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案2（降颅压，脑水肿/颅压增高）：","  用法：20%甘露醇 125～250ml 静滴 q6～8h（快速静滴，监测尿量与电解质）；地塞米松 10mg 静推 q6h（短期，减轻脑水肿与炎症，儿童可减少听力损害）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（休克型，抗休克与抗DIC）：","  用法：0.9%氯化钠/平衡盐溶液 20ml/kg 快速补液（评估后重复）；去甲肾上腺素 0.05～0.5μg/kg/min 泵入（维持MAP≥65mmHg）；氢化可的松 100mg 静滴 q8h（难治性休克）；新鲜冰冻血浆/血小板（DIC出血）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案4（抽搐与对症）：","  用法：地西泮 10mg 缓慢静推（抽搐，监测呼吸）；0.9%氯化钠 静滴维持水电解质；必要时气管插管与机械通气〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","","📌 流脑为乙类传染病，须呼吸道隔离（至少至有效抗生素治疗24小时后）；暴发型病死率高，需ICU监护与多学科抢救；密切接触者需预防性用药（利福平/环丙沙星/头孢曲松）。"],"oral_medication":["⚠️ 急性期静脉治疗为主，恢复期与密切接触者用药：","药物1（恢复期序贯）：","用法：阿莫西林 0.5g tid 或 头孢克肟 0.1g bid（敏感菌，疗程按医嘱完成总疗程7～10天）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物2（密切接触者预防用药，重要）：","用法：利福平 600mg bid×2天（成人）；或 环丙沙星 500mg 单次；或 头孢曲松 250mg 肌注 单次——所有密切接触者应预防性用药〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","药物3（对症与支持）：","用法：对乙酰氨基酚 0.5g 必要时（退热）；复合维生素B 2片 tid；乳果糖 15ml bid（防便秘与颅压波动）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4（后遗症相关）：","用法：甲钴胺 0.5mg tid（神经损害）；抗癫痫药（有癫痫发作者，遵医嘱）","📌 密切接触者预防性用药是控制暴发流行的关键；患者需隔离至抗生素治疗24小时后，接触者医学观察7天。"],"treatment":["病原治疗（尽早）：青霉素G大剂量静脉给药（首选）或三代头孢菌素（头孢曲松/头孢噻肟）；疗程7～10天（暴发型更长）","糖皮质激素：地塞米松（0.15mg/kg q6h，2～4天）用于儿童与重症，减轻脑水肿与听力损害","降颅压治疗：甘露醇/高渗盐水，头高位，避免过度补液；脑疝者加强脱水与急诊评估","暴发型抢救：抗休克（液体复苏+血管活性药）、纠正DIC（血浆/血小板/肝素按指征）、器官功能支持（机械通气、CRRT）","隔离与报告：呼吸道隔离（至有效抗生素24小时后）、按乙类传染病报告、密切接触者预防性用药与医学观察","并发症处理：硬膜下积液/积脓（穿刺引流）、脑积水（分流）、癫痫（抗癫痫药）、听力损害（听力评估与康复）","支持治疗：补液与电解质平衡、营养支持、口腔与皮肤护理（瘀斑处防感染）","随访：出院后评估神经系统后遗症（听力、认知、癫痫）与康复治疗"],"management":["隔离与防护：呼吸道隔离（单间、戴口罩）、接触者与家属预防性用药宣教、医护手卫生与防护","意识与神经系统监测：每1～2小时评估意识、瞳孔、脑膜刺激征与抽搐，异常立即报告（脑疝预警）","生命体征与循环监测：血压、心率、呼吸与尿量（暴发型休克监测），每15～30分钟（休克期）","皮肤瘀斑护理：观察瘀斑范围与融合情况（DIC进展）、保持清洁、避免受压与外伤、防感染","降颅压护理：头高位15～30°、避免用力与躁动、遵医嘱脱水治疗、监测电解质与尿量","标本留取：抗生素前留取脑脊液与血培养（注意腰穿后平卧6小时，观察头痛与穿刺点）","宣教：密切接触者需预防性服药、观察7天（发热、头痛及时就诊）、患者出院后随访听力与神经系统"],"notes":["流脑是乙类传染病，须呼吸道隔离至有效抗生素治疗24小时后，并按规定报告疾控","皮肤瘀点瘀斑是流脑的重要体征（涂片革兰染色可见革兰阴性双球菌，快速诊断价值高）","暴发型流脑（休克型与脑型）病死率高，需ICU抢救（抗休克、抗DIC、降颅压与器官支持）","密切接触者必须预防性用药（利福平/环丙沙星/头孢曲松）并医学观察7天","腰穿在颅压明显增高或脑疝征象者应暂缓（先脱水与影像评估），避免诱发脑疝"],"emergency":["高热伴皮肤瘀斑迅速增多融合与血压下降（暴发型休克型）→ 立即抗休克+抗生素+抗DIC，转ICU","意识障碍、瞳孔不等大与呼吸节律改变（脑疝）→ 立即甘露醇脱水+气管插管准备，急会诊","抽搐持续（癫痫持续状态）→ 地西泮缓慢静推+抗癫痫药负荷，保护气道","DIC伴出血（穿刺点渗血、消化道出血）→ 补充凝血因子与血小板，评估肝素指征","脑膜炎患者腰穿后突发呼吸停止（脑疝）→ 立即脱水、气管插管与机械通气"],"pinyin":"lxnjssmy","icd10":"A39.0","physical_exam":["生命体征：体温（高热）、血压（休克）、心率、呼吸（节律改变提示颅压增高）","意识与瞳孔：意识状态、瞳孔大小与对光反射（脑疝筛查）","皮肤黏膜：瘀点瘀斑（分布、数目、有无融合）、皮肤发花与肢端温度（休克）","脑膜刺激征：颈项强直、Kernig征、Brudzinski征","神经系统：肌力、腱反射、病理反射、颅神经（听力与眼球运动）","婴幼儿：前囟隆起与张力、尖叫、拒奶（不典型表现）","其他：口唇疱疹（流脑常见）、关节肿痛（关节炎并发症）"],"lab_tests":["脑脊液检查（关键）：压力、外观、细胞数（中性粒细胞为主）、蛋白、葡萄糖、氯化物、涂片革兰染色与培养","血培养+皮肤瘀点涂片（革兰染色）：病原学诊断（抗生素前留取）","血常规+CRP+PCT：白细胞与炎症指标（显著升高）","凝血功能+D-二聚体+纤维蛋白原+血小板：DIC评估（暴发型）","电解质+肾功能+血气分析+乳酸：器官功能与灌注评估","头颅CT（意识障碍或颅压增高者）+听力检查（出院前）","脑脊液抗原检测/PCR+脑膜炎奈瑟菌培养：病原确认与血清群分型（疾控）"],"nursing":["隔离护理：呼吸道隔离（单间、戴口罩）、严格执行手卫生、密切接触者预防用药宣教","意识与瞳孔观察：每1～2小时评估意识、瞳孔与抽搐（脑疝预警），异常立即报告","生命体征监测：血压、心率、呼吸与尿量（休克期每15～30分钟），配合抗休克治疗","皮肤护理：观察瘀斑范围与融合情况、保持清洁干燥、避免受压与外伤（防感染与出血）","降颅压护理：头高位15～30°、避免躁动与用力（必要时镇静）、遵医嘱脱水并监测尿量与电解质","腰穿后护理：去枕平卧4～6小时、观察头痛与穿刺点渗液，记录脑脊液性状","宣教与随访：密切接触者预防性服药与观察7天、出院后随访听力与神经系统后遗症、按时复诊"],"diet":["急性期：流质或半流质（清淡易消化），意识障碍者鼻饲或静脉营养","高热量、高蛋白、高维生素饮食促进恢复；少量多餐","充足水分（心肾功能允许下），维持水电解质平衡（记录出入量）","昏迷或吞咽困难者：鼻饲（床头抬高30～45°防误吸），营养液温度与速度按规范","恢复期：均衡饮食、加强营养（感染消耗大）；避免辛辣与刺激性食物"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1427},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3cbf5bbafdfbb1202ad5cc9e5ed46012697ffccab25f555336f1bcc70428ab53","pinyin":"liuxingxingnaojisuimoyan","initials":"lxxnjsmy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","高热（39～40℃）、伴畏寒寒战、全身酸痛\\n剧烈头痛、喷射性呕吐、颈项强直、Kernig征与Brudzinski征阳性\\n皮肤黏膜瘀点瘀斑（特征性，多见于躯干与下肢，可融合成片）\\n暴发型（休克型）：瘀斑迅速增多融合、血压下降、皮肤发花、DIC与多器官衰竭\\n暴发型（脑型）：意识障碍、抽搐、瞳孔不等大与呼吸节律改变（脑疝）\\n婴幼儿表现不典型：拒奶、尖叫、前囟隆起、抽搐",60],["摘要","流行性脑脊髓膜炎（流脑）是脑膜炎奈瑟菌经呼吸道传播引起的急性化脓性脑膜炎，冬春季高发，儿童与青少年多见。表现为高热、头痛、呕吐、皮肤黏膜瘀点瘀斑与脑膜刺激征，暴发型可致休克与DIC（病死率高）。需尽早隔离与抗生素治疗（青霉素G首选）。",30],["疾病编码","A39.0",30],["原首字母","lxnjssmy",60]]},{"id":"orders-d657e60216c149b0ef92","key":"v1-c9ccc21dfe2a3058|orders-d657e60216c149b0ef92","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"纤维肌痛综合征","category":"内科-风湿","raw":{"name":"纤维肌痛综合征","category":"内科-风湿","summary":"纤维肌痛综合征是一种以全身广泛性慢性疼痛、疲劳、睡眠障碍与认知功能障碍为特征的慢性非炎症性风湿病，多见于中年女性。诊断依据2016年ACR标准（广泛疼痛指数WPI与症状严重度SSS），无特异性实验室与影像学异常（属排除性诊断）。治疗以患者教育、运动、认知行为治疗与药物（度洛西汀、普瑞巴林、阿米替林）综合管理。","symptoms":["广泛性疼痛（身体左右侧、腰上下部与中轴部位，持续>3个月）","疲劳与晨起僵硬（非炎症性，活动后部分缓解）","睡眠障碍（入睡困难、睡眠浅、醒后不解乏）","认知功能障碍（'纤维雾'：注意力与记忆力下降）","伴随症状：头痛、肠易激综合征、焦虑抑郁、感觉异常与怕冷","特点：疼痛与体征不符（无关节肿胀与畸形），情绪与压力可加重症状"],"diagnosis":["2016年ACR标准：广泛疼痛指数（WPI≥7且SSS≥5，或WPI 4～6且SSS≥9）且症状持续≥3个月、无其他可解释疾病","体检与实验室：无关节肿胀与肌力下降；血常规、血沉、CRP、肌酶、甲状腺功能、风湿免疫抗体多为正常（用于排除其他疾病）","鉴别诊断：类风湿关节炎（关节肿胀与抗体阳性）、甲状腺功能减退（TSH升高）、多发性肌炎（肌酶升高）、风湿性多肌痛（老年、ESR升高）、维生素D缺乏与药物性肌痛（他汀）","睡眠评估与心理评估：匹兹堡睡眠质量指数（PSQI）、PHQ-9与GAD-7（焦虑抑郁共病常见）","疼痛分布图与压痛点评估（旧标准18个压痛点≥11个，现为辅助）","排除其他慢性疼痛疾病：慢性疲劳综合征、脊柱关节病、小纤维神经病"],"infusion":["⚠️ 纤维肌痛一般不需静脉治疗，静脉用药用于共病或急性疼痛加重！","","方案1（急性疼痛加重，非阿片类镇痛）：","  用法：对乙酰氨基酚 0.5～1.0g（NS 100ml）静滴（必要时，每日≤3g）；氟比洛芬酯 50mg 静滴 q12h（短期）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","方案2（共病焦虑/抑郁加重）：","  用法：0.9%氯化钠 静滴；必要时小剂量抗焦虑药（口服为主）；心理科会诊","","方案3（营养与维生素补充，缺乏时）：","  用法：维生素D 200000IU 肌注（严重缺乏者，随后口服维持）；维生素B12 0.5mg 肌注 qd（缺乏者）","","方案4（睡眠障碍与疼痛综合管理）：","  用法：0.9%氯化钠 静滴（维持通路）；针灸、理疗与心理干预配合（非药物为主）","","📌 纤维肌痛禁用阿片类药物与糖皮质激素（无效且有害）；治疗核心是非药物措施（教育、运动、认知行为治疗）。"],"oral_medication":["⚠️ 药物为辅助手段，需与非药物措施联合：","药物1（抗抑郁药，一线）：","用法：度洛西汀 30mg qd 起（渐加至60mg qd）或 阿米替林 10～25mg qn（改善疼痛与睡眠）","药物2（抗惊厥药，一线）：","用法：普瑞巴林 75mg bid 起（渐加至150～225mg bid）或 加巴喷丁 0.3g tid（逐渐加量）","药物3（肌松与睡眠）：","用法：环苯扎林 5～10mg qn（短期，注意嗜睡）或 曲唑酮 25～50mg qn（改善睡眠）","药物4（辅助与共病）：","用法：维生素D 800～1000IU/日（缺乏者按医嘱）；镁剂（部分患者有效）；5-羟色胺与去甲肾上腺素再摄取抑制剂（SNRI）联合心理治疗","📌 避免阿片类药物（无效、致依赖与痛觉过敏）与长期NSAIDs（无效且不良反应）；药物需按疗效与不良反应缓慢滴定。"],"treatment":["患者教育（核心）：解释本病为中枢痛觉敏化而非炎症或损伤，不会致残致畸，减轻焦虑与疾病恐惧","运动治疗：个体化低强度有氧运动（散步、游泳、太极，每周3～5次，从5～10分钟开始渐增）与力量训练、拉伸；避免过度运动","认知行为治疗（CBT）：改变疼痛相关负面认知与行为，改善功能与情绪（疗效确切）","药物治疗：度洛西汀/普瑞巴林/阿米替林（一线，按症状选择与滴定），联合用药需评估相互作用","睡眠管理：睡眠卫生教育（规律作息、睡眠限制疗法、避免咖啡因与屏幕），必要时曲唑酮或低剂量阿米替林","共病处理：焦虑抑郁（心理治疗±药物）、肠易激综合征（饮食与药物）、头痛与慢性疲劳","多学科与综合干预：风湿科、疼痛科、心理科、康复科与物理治疗协作；针灸、推拿、水疗等辅助（部分有效）","随访与目标设定：以改善功能与生活质量为目标（而非完全无痛），定期评估WPI/SSS、睡眠与情绪"],"management":["症状与功能评估：记录疼痛部位与强度（NRS）、疲劳、睡眠与情绪（PHQ-9、GAD-7），每1～3个月评估","运动计划执行：协助制定渐进运动计划，记录运动量与耐受情况（避免过度运动致症状加重）","睡眠护理：指导睡眠卫生（固定作息、睡前放松、避免咖啡因与酒精），记录睡眠质量","用药管理与观察：按医嘱滴定药物，观察不良反应（度洛西汀恶心与血压、普瑞巴林嗜睡与水肿、阿米替林口干与便秘）","心理支持与教育：反复解释疾病性质（非炎症、非进行性），减少不必要检查与用药，鼓励参与认知行为治疗","宣教：规律运动、改善睡眠、压力管理、避免阿片类药物与不必要激素、按时复诊与随访","共病筛查与转诊：筛查焦虑抑郁与睡眠障碍，必要时转心理科/精神科"],"notes":["纤维肌痛是排除性诊断（2016年ACR标准），无特异性实验室异常——避免过度检查与误诊","发病机制为中枢痛觉敏化（非炎症），因此NSAIDs与激素无效，阿片类药物禁用（可致痛觉过敏与依赖）","治疗以非药物措施为核心（患者教育+运动+认知行为治疗），药物仅为辅助（度洛西汀/普瑞巴林/阿米替林）","共病（焦虑抑郁、肠易激综合征、睡眠障碍）非常常见，需同步筛查与处理","治疗目标为改善功能与生活质量而非完全无痛，需与患者建立合理预期"],"emergency":["严重抑郁伴自杀意念（共病抑郁）→ 立即心理科/精神科会诊、评估自杀风险与安全监护","疼痛急剧加重伴新发神经症状（感觉缺失、肌力下降）→ 重新评估（排除神经病变、脊髓病）","药物过量（阿米替林、普瑞巴林）→ 急诊洗胃/活性炭、心电监护（阿米替林致心律失常）","药物不良反应致严重不适（普瑞巴林致严重水肿/嗜睡、度洛西汀致血压升高）→ 调整药物并监测","睡眠障碍致严重失眠与功能损害 → 专科评估（睡眠医学/心理科）"],"pinyin":"xwjthzz","icd10":"M79.7","physical_exam":["生命体征：血压（药物影响）、心率、体温、体重","疼痛评估：广泛疼痛部位分布（WPI区域）、压痛点（辅助）、疼痛强度（NRS）","关节与肌肉：无关节肿胀与畸形、肌力正常（与肌炎鉴别）、肌压痛（非特异性）","神经系统：感觉与肌力正常、无病理反射（排除神经病变）","精神状态：情绪（焦虑抑郁）、认知功能（注意力与记忆）、睡眠状态","皮肤：无皮疹与硬化（排除系统性硬化与皮肌炎）","其他系统：肠易激综合征（腹部压痛与排便习惯）、甲状腺（甲减鉴别）、口腔与眼部（干燥综合征鉴别）"],"lab_tests":["血常规+血沉+CRP：多正常（炎症性疾病鉴别：ESR/CRP升高提示其他疾病）","甲状腺功能（TSH、FT4）：甲减可致肌痛与疲劳（常被误诊）","肌酶（CK、LDH）+肌电图（必要时）：多发性肌炎/肌病排除","风湿免疫抗体（RF、抗CCP、ANA、抗dsDNA）：类风湿关节炎与狼疮排除","维生素D+血钙+磷+镁：缺乏与骨软化症评估","睡眠评估（PSQI）+心理评估（PHQ-9、GAD-7）：共病筛查","药物史核查（他汀、贝特）：药物性肌痛排除"],"nursing":["症状与功能评估：记录疼痛部位与强度、疲劳、睡眠与情绪变化，每1～3个月评估（WPI/SSS）","运动指导：协助制定渐进运动计划并记录耐受情况，鼓励低强度有氧运动（散步、游泳、太极）","睡眠护理：指导睡眠卫生（固定作息、睡前放松、避免咖啡因与屏幕），记录睡眠质量与干预效果","用药护理：按医嘱滴定药物并观察不良反应（恶心、嗜睡、水肿、血压升高），异常报告","心理支持：反复解释疾病性质（非炎症、非进展性），减轻恐惧与焦虑，鼓励参与认知行为治疗","宣教：规律运动、改善睡眠与压力管理、避免阿片类药物与激素、按时复诊、共病（抑郁与肠易激）同步治疗"],"diet":["均衡饮食，高纤维（蔬菜、水果、全谷物）、适量优质蛋白；控制体重（肥胖加重症状）","避免过量咖啡因与酒精（影响睡眠与症状）","肠易激综合征共病者：低FODMAP饮食（在营养师指导下）、少量多餐","补充维生素D与镁（缺乏者按医嘱）；多饮水","避免刺激性食物与不规律饮食；保持规律进餐时间有助于症状管理"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1428},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"b081e44ee48cc7e5dd413abfe5c075bea9d7020bb3fb7380d9ac349db85e22b7","pinyin":"xianweijitongzonghezheng","initials":"xwjtzhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","广泛性疼痛（身体左右侧、腰上下部与中轴部位，持续>3个月）\\n疲劳与晨起僵硬（非炎症性，活动后部分缓解）\\n睡眠障碍（入睡困难、睡眠浅、醒后不解乏）\\n认知功能障碍（'纤维雾'：注意力与记忆力下降）\\n伴随症状：头痛、肠易激综合征、焦虑抑郁、感觉异常与怕冷\\n特点：疼痛与体征不符（无关节肿胀与畸形），情绪与压力可加重症状",60],["摘要","纤维肌痛综合征是一种以全身广泛性慢性疼痛、疲劳、睡眠障碍与认知功能障碍为特征的慢性非炎症性风湿病，多见于中年女性。诊断依据2016年ACR标准（广泛疼痛指数WPI与症状严重度SSS），无特异性实验室与影像学异常（属排除性诊断）。治疗以患者教育、运动、认知行为治疗与药物（度洛西汀、普瑞巴林、阿米替林）综合管理。",30],["疾病编码","M79.7",30],["原首字母","xwjthzz",60]]},{"id":"orders-9686bfc395125c3c7b8c","key":"v1-c9ccc21dfe2a3058|orders-9686bfc395125c3c7b8c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"心肺复苏后管理（PCAS）","category":"内科-急救","raw":{"name":"心肺复苏后管理（PCAS）","category":"内科-急救","summary":"心肺复苏后综合征（PCAS）是心脏骤停自主循环恢复（ROSC）后出现的脑损伤、心肌功能障碍、全身缺血/再灌注损伤与持续致病因素共同导致的病理状态。管理核心：目标温度管理（TTM）、血流动力学优化、氧与二氧化碳管理、癫痫控制、血糖管理与病因治疗（尤其急诊PCI）。","symptoms":["意识障碍（昏迷或植物状态，脑损伤程度决定预后）","血流动力学不稳定：低血压、心律失常、心输出量下降（心肌顿抑）","呼吸功能障碍：低氧血症、呼吸机依赖、ARDS（缺血再灌注肺损伤）","癫痫发作与肌阵挛（缺氧性脑损伤）","多器官功能障碍：急性肾损伤（少尿）、肝损伤、DIC、肠道缺血（应激性溃疡与肠屏障受损）"],"diagnosis":["神经功能评估：GCS评分、瞳孔对光反射、脑干反射（每1～4小时），必要时脑电图（癫痫与非惊厥性发作）","血流动力学监测：有创动脉压、中心静脉压、心脏超声（心肌功能）、乳酸与混合静脉血氧饱和度","血气分析（每1～4小时）：氧合（PaO₂）与二氧化碳（PaCO₂）目标管理（避免高氧与过度通气）","心电图+心肌酶+冠脉造影：明确心脏骤停病因（急性心肌梗死需急诊PCI）","体温监测：核心体温（食管/膀胱/血管内探头），目标温度管理依据","器官功能：肾功能（肌酐、尿量）、肝功能、凝血功能（DIC）、电解质与血糖","影像学：头颅CT（缺氧性脑损伤、脑水肿）、胸部X线/CT（肋骨骨折、误吸、肺水肿）","预后评估（≥72小时）：瞳孔与角膜反射消失、肌阵挛持续、脑电图爆发抑制或等电位、NSE升高、影像示广泛脑损伤"],"infusion":["⚠️ ICU综合管理，按目标导向治疗（TTM+血流动力学+氧与CO₂管理）！","方案1（血流动力学优化）：","用法：0.9%氯化钠/平衡盐溶液 按需补液（评估容量状态，避免过量）；去甲肾上腺素 0.05～1μg/kg/min 泵入（维持MAP≥65mmHg，目标65～75mmHg）；必要时加用多巴酚丁胺 2～20μg/kg/min（心肌功能障碍）","方案2（目标温度管理TTM，核心措施）：","用法：目标温度32～36℃维持至少24小时（用冰毯/血管内降温/冷盐水输注）；降温期监测核心体温、电解质与凝血；复温速度≤0.25～0.5℃/h；镇静与肌松配合（丙泊酚/咪达唑仑+芬太尼，必要时维库溴铵）","方案3（氧与二氧化碳管理）：","用法：吸氧维持SpO₂ 92%～98%、PaO₂ 60～100mmHg（避免高氧）；机械通气调整 PaCO₂ 35～45mmHg（避免过度通气致脑血管收缩）","方案4（癫痫与代谢管理）：","用法：癫痫——丙戊酸钠 15～40mg/kg 负荷后维持 或 左乙拉西坦 60mg/kg 负荷；血糖管理——10%葡萄糖+胰岛素维持血糖 7.8～10mmol/L（避免低血糖与高血糖）〔调 ★ 必须按 CrCl 减量；老年减量〕","📌 目标温度管理（TTM）+血流动力学优化+病因治疗（急诊PCI）是改善预后的关键；避免高氧与过度通气；72小时后行多模态神经预后评估（避免过早判断）。"],"oral_medication":["⚠️ PCAS急性期不宜口服给药；恢复期用药：","药物1（心脏病因二级预防）：","用法：阿司匹林 100mg qd + 替格瑞洛 90mg bid（PCI术后）；阿托伐他汀 40mg qn；美托洛尔缓释片（按心率与血压）〔调 ★ 活动性肝病禁用；甲减/肌病史慎用；妊娠哺乳禁用〕","药物2（心功能与血压）：","用法：沙库巴曲缬沙坦 50mg bid 或 依那普利（按血压与肾功能）；螺内酯 20mg qd〔调 ★ eGFR<30 禁用；高钾血症禁用〕","药物3（神经康复与抗癫痫）：","用法：左乙拉西坦 500mg bid（有癫痫发作者，疗程依病因）；甲钴胺 0.5mg tid + 维生素B1 10mg tid〔调 ★ 必须按 CrCl 减量；老年减量〕","药物4（并发症防治）：","用法：艾司奥美拉唑 20mg qd（应激性溃疡预防）；乳果糖 15ml bid（便秘）；碳酸钙D3（长期卧床与激素者）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","📌 恢复期需评估心功能与神经功能，制定心脏康复与神经康复计划；抗癫痫药不可骤停；ICD评估（心脏骤停幸存者猝死二级预防）。"],"treatment":["目标温度管理（TTM）：昏迷患者ROSC后立即开始，目标32～36℃维持≥24小时，缓慢复温（≤0.5℃/h），密切监测电解质与凝血","血流动力学优化：目标MAP 65～75mmHg（有创监测），补液+血管活性药（去甲肾上腺素首选），心肌功能障碍者加正性肌力药","氧与通气管理：SpO₂ 92%～98%、PaCO₂ 35～45mmHg，避免高氧与过度通气；肺保护性通气（小潮气量）","病因治疗（关键）：急性心肌梗死急诊冠脉造影+PCI；心律失常（抗心律失常药/起搏/除颤）；肺栓塞溶栓；电解质紊乱纠正","癫痫控制：脑电图监测（非惊厥性发作常见），抗癫痫药治疗，避免使用影响预后判断的深镇静（除非TTM需要）","代谢与器官支持：血糖 7.8～10mmol/L、纠正电解质、CRRT（急性肾损伤）、输血（按指征）、应激性溃疡预防","预后评估与决策：ROSC后≥72小时行多模态评估（临床+脑电图+影像+生物标志物），避免过早（<72小时）判断预后","康复与随访：心脏康复（运动处方）、神经康复（认知与运动训练）、ICD评估与心理支持、家属沟通与随访"],"management":["监护与监测：ICU监护（心电、有创血压、血氧、体温、尿量），持续脑电监测（疑癫痫者）","目标温度管理护理：按医嘱降温与复温速度控制、监测核心体温（每1～2小时）、寒战控制（镇静肌松）、皮肤护理（防冻伤）","气道与呼吸护理：气管插管固定与口腔护理、吸痰与呼吸机参数监测、观察人机对抗与气压伤","血流动力学护理：血管活性药经中心静脉泵入并按时滴定、观察血压与尿量（每1～2小时）、防止外渗","神经系统观察：每1～4小时评估GCS、瞳孔与脑干反射并记录，观察抽搐与肌阵挛，异常立即报告","并发症预防：应激性溃疡（PPI）、深静脉血栓（抗凝+气压治疗）、压疮（每2小时翻身）、感染（呼吸机相关肺炎预防）","家属沟通与心理支持：解释病情与预后评估的时间要求（≥72小时），提供心理支持与后续康复信息"],"notes":["PCAS管理的四大支柱：目标温度管理、血流动力学优化、氧与二氧化碳目标管理、病因治疗（尤其急诊PCI）","避免高氧血症（PaO₂>300mmHg加重再灌注损伤）与过度通气（PaCO₂过低致脑血管收缩加重脑缺血）","神经预后评估应在ROSC后≥72小时进行（多模态：临床+脑电图+NSE+影像），避免过早判断导致不当撤治","心脏骤停幸存者应评估ICD指征（猝死二级预防）与可逆病因（急性心肌梗死、电解质紊乱、药物）","TTM期间注意电解质（低钾、低镁）、凝血功能与感染风险（低温抑制免疫）"],"emergency":["ROSC后再发心脏骤停/恶性心律失常 → 立即高质量CPR+除颤+抗心律失常药，评估急诊PCI","顽固性休克（MAP<65mmHg对升压药无反应）→ 增加升压药/正性肌力药，评估机械循环支持（ECMO/IABP）","严重低氧血症或呼吸衰竭 → 调整呼吸机参数（PEEP与FiO₂），必要时俯卧位通气","持续癫痫发作（非惊厥性发作也需处理）→ 抗癫痫药负荷量+持续脑电监测","严重高钾或电解质紊乱致心律失常 → 立即纠正电解质（补钙、胰岛素葡萄糖、透析）"],"pinyin":"xlfshglPCAS","icd10":"I46.9","physical_exam":["生命体征：核心体温（TTM期间）、有创血压、心率与心律、呼吸机参数与血氧","神经系统：GCS评分、瞳孔大小与对光反射、角膜反射、头眼反射、肌阵挛与抽搐","心脏：心律、心音、颈静脉充盈（心功能）","肺部：呼吸音、湿啰音（肺水肿/误吸）、呼吸机人机同步性","腹部：腹胀与肠鸣音（肠缺血与麻痹）、肝脾大小","皮肤与四肢：末梢循环与温度、水肿、压疮风险部位（骶尾、足跟）","置管与管路：气管插管、中心静脉置管、动脉置管与尿管的位置与固定、穿刺点情况"],"lab_tests":["血气分析（每1～4小时）：PaO₂ 60～100mmHg、PaCO₂ 35～45mmHg 目标管理","乳酸（每2～4小时）：组织灌注与乳酸清除率（复苏效果指标）","电解质（钾、镁、钙）+血糖（每2～6小时）：TTM期间电解质紊乱与血糖管理（目标7.8～10mmol/L）","心肌酶（肌钙蛋白）+BNP+心电图：心肌损伤与心功能评估","肾功能+尿量+肝功能+凝血功能+血小板：器官功能与DIC监测","脑电图（持续或间断）：癫痫（含非惊厥性）监测与预后评估","神经预后标志物（NSE）+头颅CT/MRI（≥72小时）：多模态预后评估"],"nursing":["ICU监护护理：持续心电、有创血压与血氧监测，记录每小时尿量，异常立即报告","目标温度管理护理：按医嘱控制降温与复温速度、监测核心体温、控制寒战（镇静肌松）、皮肤护理防冻伤","气道护理：气管插管固定与口腔护理（每日2～3次）、按需吸痰、呼吸机参数与报警处理、预防呼吸机相关肺炎（床头抬高30～45°）","血流动力学护理：血管活性药经中心静脉泵入并按时滴定、观察血压与灌注（尿量、乳酸），防外渗与药物中断","神经功能观察：每1～4小时评估GCS、瞳孔与脑干反射并记录，观察抽搐与肌阵挛，及时报告","并发症预防：应激性溃疡（PPI）、深静脉血栓（抗凝与气压治疗）、压疮（每2小时翻身）、感染与电解质紊乱监测","家属沟通与支持：解释病情与预后评估需≥72小时，提供心理支持与康复信息"],"diet":["急性期：禁食，肠外营养支持（血流动力学不稳定时）","稳定后（48～72小时）：尽早启动肠内营养（鼻胃管/鼻空肠管），从小剂量开始并监测耐受性（胃潴留、腹胀、腹泻）","热量目标25～30kcal/kg/日、蛋白1.2～2.0g/kg/日（重症患者需求增加）","血糖管理：肠内营养配合胰岛素，维持血糖7.8～10mmol/L","避免过量碳水（增加二氧化碳产生）；电解质与微量元素按化验补充"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1429},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a56dc9d5adb637cbb72ffa4954b24aa8d34d43aeb63f7c55f6e6f1dc4bab1dc3","pinyin":"xinfeifusuhouguanli（PCAS）","initials":"xffshgl（","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","意识障碍（昏迷或植物状态，脑损伤程度决定预后）\\n血流动力学不稳定：低血压、心律失常、心输出量下降（心肌顿抑）\\n呼吸功能障碍：低氧血症、呼吸机依赖、ARDS（缺血再灌注肺损伤）\\n癫痫发作与肌阵挛（缺氧性脑损伤）\\n多器官功能障碍：急性肾损伤（少尿）、肝损伤、DIC、肠道缺血（应激性溃疡与肠屏障受损）",60],["摘要","心肺复苏后综合征（PCAS）是心脏骤停自主循环恢复（ROSC）后出现的脑损伤、心肌功能障碍、全身缺血/再灌注损伤与持续致病因素共同导致的病理状态。管理核心：目标温度管理（TTM）、血流动力学优化、氧与二氧化碳管理、癫痫控制、血糖管理与病因治疗（尤其急诊PCI）。",30],["疾病编码","I46.9",30],["原首字母","xlfshglPCAS",60]]},{"id":"orders-ccb765bb9e45949e1d6d","key":"v1-c9ccc21dfe2a3058|orders-ccb765bb9e45949e1d6d","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"新生儿败血症","category":"儿科","raw":{"name":"新生儿败血症","category":"儿科","summary":"新生儿败血症是新生儿期细菌侵入血液循环并繁殖产生毒素引起的全身感染，可致脓毒症休克、脑膜炎与死亡。按发病时间分为早发型（<72小时，多经产道或宫内感染，以GBS、大肠埃希菌为主）与晚发型（>72小时，多经环境或院内感染，以金黄色葡萄球菌、凝固酶阴性葡萄球菌为主）。新生儿免疫低下，临床表现常不典型。","symptoms":["体温不稳定（发热或体温不升），反应差、嗜睡或烦躁不安","吸吮无力、拒奶、呕吐、腹胀（喂养困难与消化道症状）","黄疸加重或消退延迟、皮肤发花或硬肿","呼吸异常：呼吸急促、呻吟、呼吸暂停、发绀（易误诊为肺炎）","重者出现休克（血压下降、毛细血管充盈延长）、抽搐与昏迷（合并脑膜炎）"],"diagnosis":["血培养（确诊金标准，抗生素前采血，需氧+厌氧，双份）：阳性可确诊（需排除污染）","血常规+CRP+PCT：白细胞可升高或降低、血小板减少，CRP与PCT动态升高（每12～24小时复查）","脑脊液检查（所有疑败血症新生儿均建议腰穿）：排除脑膜炎（白细胞与蛋白升高、糖降低）","尿培养（晚发型）：泌尿道感染评估","感染灶寻找：脐部、皮肤、呼吸道、中耳与置管部位检查与培养","血气分析+血糖+电解质+乳酸：评估灌注、代谢紊乱与酸中毒","胸部X线（呼吸症状者）：肺炎评估；心脏超声（疑心内膜炎）"],"infusion":["⚠️ 抗生素须尽早静脉给药（怀疑即用，不等结果）！","","方案1（经验性抗感染，早发型/社区获得）：","  用法：氨苄西林 50mg/kg（NS 100ml 或 5%GS 100ml）静滴 q8～12h + 头孢噻肟 50mg/kg 静滴 q8～12h（覆盖GBS与大肠埃希菌）","","方案2（晚发型/院内感染，覆盖金黄色葡萄球菌与凝固酶阴性葡萄球菌）：","  用法：万古霉素 15mg/kg（NS 100ml 或 5%GS 100ml）静滴 q12h（监测血药浓度）+ 头孢噻肟 50mg/kg 静滴 q8h；或 美罗培南 20mg/kg 静滴 q8h（重症/耐药）〔调 ★★ 按 CrCl 调量并监测谷浓度10-20mg/L；耳肾毒性〕","","方案3（休克与支持）：","  用法：0.9%氯化钠 10～20ml/kg 缓慢静推（10～20分钟，评估后重复）；多巴胺 5～10μg/kg/min 泵入（升压）；10%葡萄糖 维持血糖>2.6mmol/L","","方案4（免疫支持）：","  用法：静脉丙种球蛋白 400mg/kg 静滴 qd（3～5天，重症或早产儿）；必要时输注新鲜冰冻血浆或血小板","","📌 新生儿用药按体重计算并注意剂量间隔；抗生素疗程一般10～14天（合并脑膜炎14～21天）；监测听力（GBS与脑膜炎）与神经发育。"],"oral_medication":["⚠️ 新生儿期以静脉用药为主，恢复期口服序贯：","药物1（口服抗生素序贯，血培养转阴与临床稳定后）：","用法：阿莫西林克拉维酸 25～45mg/kg/日 分2～3次（疗程按医嘱完成总疗程）；按药敏调整〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（益生菌，抗生素相关腹泻）：","用法：双歧杆菌 1粒 bid（温水或奶中服用，与抗生素间隔2小时）","药物3（维生素与支持）：","用法：维生素K1 1mg 肌注（出生时常规）；维生素D 400IU qd（按医嘱）","药物4（营养支持）：","用法：母乳喂养为主（母乳含免疫因子）；必要时母乳强化剂或早产儿配方奶","📌 抗生素疗程需足（不可因症状改善而过早停药）；母乳喂养有利于免疫恢复；随访听力与神经发育。"],"treatment":["尽早经验性抗生素治疗（怀疑即采血培养并立即给药），据药敏与临床调整（窄谱优先）","感染灶处理：脐部护理与消毒、皮肤感染灶换药、拔除感染的中心静脉置管、引流脓肿","循环支持：液体复苏（10～20ml/kg 生理盐水缓慢输注）+ 血管活性药（多巴胺/去甲肾上腺素）","呼吸支持：吸氧、无创/有创机械通气（呼吸衰竭），必要时肺表面活性物质（早产儿）","代谢与营养支持：维持血糖>2.6mmol/L、纠正酸中毒与电解质紊乱；肠内营养（母乳）或肠外营养","免疫支持：静脉丙种球蛋白、必要时血制品输注","并发症处理：脑膜炎（延长疗程与降颅压）、DIC（血浆与血小板）、休克（ICU监护）","随访：出院后评估听力、神经发育与生长发育（败血症与脑膜炎后遗症风险）"],"management":["体温与生命体征监测：每1～4小时测体温、心率、呼吸与血氧，注意体温不稳定与呼吸暂停","感染防护与隔离：严格执行手卫生、接触隔离（疑感染或确诊者）、暖箱与器械消毒","喂养与营养护理：评估吸吮力与喂养耐受性，必要时鼻饲或静脉营养，记录进食量与体重","标本采集：抗生素前按时采集血培养（双份）、脑脊液与尿培养，标本量达标（提高阳性率）","用药护理：按体重精确计算剂量与间隔、观察药物不良反应（万古霉素监测肾功能与血药浓度）","皮肤与脐部护理：保持脐部清洁干燥、观察红肿与渗液；皮肤护理防硬肿与感染","宣教：母乳喂养与手卫生的重要性、识别危险征象（反应差、拒奶、体温不升）立即就诊、按时随访听力与发育"],"notes":["新生儿败血症临床表现不典型（体温不稳定、反应差、拒奶），任何可疑均应采血培养并经验性用药","所有疑败血症新生儿均建议腰穿排除脑膜炎（影响疗程与预后）","GBS与大肠埃希菌是早发型主要病原，晚发型以金黄色葡萄球菌与凝固酶阴性葡萄球菌为主","新生儿用药按体重计算并延长给药间隔（肝肾功能未成熟）；万古霉素需监测血药浓度与肾功能","败血症与脑膜炎后需长期随访听力与神经发育"],"emergency":["新生儿体温不升或发热伴反应差、拒奶、皮肤发花（疑似败血症）→ 立即采血培养+静脉抗生素","呼吸暂停、发绀或呼吸窘迫 → 立即吸氧/复苏囊正压通气，必要时气管插管","休克（毛细血管充盈>3秒、低血压、少尿）→ 生理盐水 10～20ml/kg 缓慢复苏+血管活性药","抽搐或前囟隆起（脑膜炎/颅内压增高）→ 止惊（苯巴比妥 20mg/kg）+降颅压评估与腰穿","腹胀伴呕吐与血便（坏死性小肠结肠炎）→ 禁食、胃肠减压、腹部X线、抗感染，必要时手术"],"pinyin":"xsjbxz","icd10":"P36.9","physical_exam":["生命体征：体温（发热或体温不升）、心率（增快或减慢）、呼吸（急促、呻吟、呼吸暂停）、血氧、血压","一般反应：反应差、嗜睡、肌张力低下或增高、哭声弱","皮肤：黄疸程度、皮肤发花、硬肿、脓疱与脐部红肿渗液、出血点","前囟与颅缝：前囟隆起或张力增高（脑膜炎/颅压增高）、颅缝分离","呼吸系统：呼吸音、三凹征、呻吟、发绀","腹部：腹胀、肠鸣音、肝脾大小（肝脾大提示宫内感染）","置管部位：脐动静脉置管、中心静脉置管与静脉穿刺点（感染源）"],"lab_tests":["血培养（双份，需氧+厌氧，抗生素前）：确诊金标准","脑脊液检查（常规+生化+涂片+培养）：排除脑膜炎（所有疑似病例建议腰穿）","血常规+CRP+PCT（每12～24小时）：动态监测炎症指标（白细胞可升高或降低、血小板减少）","尿培养（晚发型）：泌尿道感染评估","血气分析+血糖+电解质+乳酸：代谢紊乱、低血糖与灌注不良评估","感染灶培养（脐部、皮肤、痰、置管尖端）：病原学定位","胸部X线+心脏超声（必要时）：肺炎与心内膜炎评估"],"nursing":["生命体征观察：每1～4小时测体温、心率、呼吸与血氧，观察反应、吸吮与哭声变化，异常立即报告","感染防护：严格手卫生、接触隔离措施、暖箱与器械消毒，防止交叉感染","喂养护理：评估喂养耐受性与吸吮力，记录进食量与呕吐；必要时鼻饲并观察腹胀","标本采集配合：抗生素使用前采集血培养、脑脊液与尿培养，规范留取与送检","用药护理：按体重精确计算并核对剂量、注意给药间隔与药物不良反应（监测万古霉素血药浓度与肾功能）","皮肤与脐部护理：保持清洁干燥、观察红肿渗液，及时换药与报告；注意保暖（防硬肿）","宣教：母乳喂养与手卫生、识别危险征象（拒奶、反应差、体温不升）立即就诊、按时随访听力与神经发育"],"diet":["首选母乳喂养（含免疫球蛋白与乳铁蛋白，增强免疫）","吸吮无力或病情重者：鼻饲母乳/配方奶或静脉营养（保证热量100～120kcal/kg/日）","监测血糖（新生儿易低血糖），必要时10%葡萄糖输注维持>2.6mmol/L","按体重与日龄计算奶量（逐步加量，观察耐受性：腹胀、呕吐、腹泻）","恢复期继续母乳喂养并监测体重增长（生长发育评估）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1430},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"31549f89b36663e2f50f3473a7bbfae10107e611c572b4fbe14ebcfb4a19812b","pinyin":"xinshengerbaixuezheng","initials":"xsebxz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","体温不稳定（发热或体温不升），反应差、嗜睡或烦躁不安\\n吸吮无力、拒奶、呕吐、腹胀（喂养困难与消化道症状）\\n黄疸加重或消退延迟、皮肤发花或硬肿\\n呼吸异常：呼吸急促、呻吟、呼吸暂停、发绀（易误诊为肺炎）\\n重者出现休克（血压下降、毛细血管充盈延长）、抽搐与昏迷（合并脑膜炎）",60],["摘要","新生儿败血症是新生儿期细菌侵入血液循环并繁殖产生毒素引起的全身感染，可致脓毒症休克、脑膜炎与死亡。按发病时间分为早发型（<72小时，多经产道或宫内感染，以GBS、大肠埃希菌为主）与晚发型（>72小时，多经环境或院内感染，以金黄色葡萄球菌、凝固酶阴性葡萄球菌为主）。新生儿免疫低下，临床表现常不典型。",30],["疾病编码","P36.9",30],["原首字母","xsjbxz",60]]},{"id":"orders-b67cc826c270956bf577","key":"v1-c9ccc21dfe2a3058|orders-b67cc826c270956bf577","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"新生儿缺氧缺血性脑病","category":"儿科","raw":{"name":"新生儿缺氧缺血性脑病","category":"儿科","summary":"新生儿缺氧缺血性脑病（HIE）是围产期窒息导致脑血流灌注不足与缺氧引起的脑损伤，是新生儿死亡与神经发育障碍（脑瘫、智力低下、癫痫）的重要原因。按临床表现分轻、中、重度。治疗核心是亚低温治疗（中重度，出生6小时内开始）、维持内环境稳定与器官功能支持。","symptoms":["轻度：兴奋、易激惹、拥抱反射活跃、肌张力正常或轻度增高（症状多在24～72小时消失）","中度：嗜睡、反应迟钝、肌张力低下、原始反射减弱、惊厥（多在生后12～24小时出现）","重度：昏迷、肌张力松软或去大脑强直、原始反射消失、频繁惊厥、呼吸节律不整（可致呼吸暂停）","出生时有窒息史：Apgar评分低、羊水胎粪污染、脐动脉血pH<7.0","合并多器官损害：少尿（急性肾损伤）、心肌损害（心率与血压异常）、消化道出血"],"diagnosis":["出生史与Apgar评分：围产期窒息证据（脐动脉血pH<7.0、BE<-12mmol/L、Apgar≤5分持续5分钟）","神经系统评估（每4～6小时）：意识状态、肌张力、原始反射、惊厥发作（临床分度依据）","头颅超声（床旁）：早期脑水肿与颅内出血筛查（可动态随访）","头颅MRI（生后3～7天为最佳）：评估脑损伤部位与程度（基底节、丘脑、白质损伤）与预后","振幅整合脑电图（aEEG）+常规脑电图：惊厥（含亚临床发作）监测与背景活动评估（预后判断）","血气分析+血糖+电解质+肝肾功能+心肌酶：多器官损害评估（每6～12小时）","脑脊液检查（疑颅内感染时）：排除化脓性脑膜炎"],"infusion":["⚠️ 亚低温治疗是中重度HIE的核心治疗，须在生后6小时内开始！","","方案1（亚低温治疗，中重度HIE）：","  用法：目标核心温度33.5～34.5℃维持72小时（全身降温或选择性头部降温），随后缓慢复温（0.5℃/h，总复温时间≥6小时）；期间监测体温、心率、血压、凝血与电解质，需NICU监护与镇静处理","","方案2（维持内环境稳定）：","  用法：10%葡萄糖 静滴维持血糖 4～6mmol/L；0.9%氯化钠 维持血压与灌注（低血压用多巴胺 5～10μg/kg/min 泵入）；纠正酸中毒与电解质紊乱（避免快速补碱与补钠）","","方案3（惊厥控制）：","  用法：苯巴比妥 20mg/kg 静推（负荷量，缓慢）→ 维持 3～5mg/kg/日；无效者加 咪达唑仑 0.1～0.2mg/kg/h 泵入 或 左乙拉西坦 20～40mg/kg（NS 100ml 或 5%GS 100ml）静滴（负荷）〔调 ★ 必须按 CrCl 减量；老年减量〕","","方案4（脑水肿与器官支持）：","  用法：限制液体（60～80ml/kg/日）；20%甘露醇 0.25～0.5g/kg 静推 q6～8h（颅压增高者，监测肾功能）；心肌损害者磷酸肌酸 0.5g 静滴 qd〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","📌 中重度HIE应在生后6小时内启动亚低温治疗（疗效明确）；避免过快纠正酸中毒与高渗液体；监测多器官功能与凝血功能。"],"oral_medication":["⚠️ 急性期以静脉治疗为主；恢复期用药：","药物1（抗癫痫维持，有惊厥者）：","用法：苯巴比妥 3～5mg/kg/日 口服（分1～2次，疗程依脑电图与临床，遵医嘱逐渐减停）；或 左乙拉西坦 10～20mg/kg bid〔调 ★ 必须按 CrCl 减量；老年减量〕","药物2（营养神经与康复辅助）：","用法：甲钴胺 0.25mg qd（口服/肌注）；神经节苷脂（遵医嘱）；维生素B1 5mg qd","药物3（营养与维生素）：","用法：维生素D 400IU qd；铁剂（按血红蛋白与铁代谢，4周后评估）；母乳强化剂（早产/生长迟缓者）","药物4（康复相关）：","用法：按康复计划进行运动与认知训练（非药物为主）；必要时抗痉挛药物（脑瘫者，康复科指导）","📌 恢复期需长期随访神经发育（运动、认知、听力与视力）并在6个月内开始早期干预/康复训练。"],"treatment":["亚低温治疗（核心）：中重度HIE在生后6小时内开始，目标33.5～34.5℃维持72小时，缓慢复温；需NICU与多学科团队","呼吸与循环支持：维持氧合（避免高氧与低氧）、必要时机械通气；维持血压与灌注（液体与血管活性药）","惊厥控制：苯巴比妥负荷与维持、咪达唑仑或左乙拉西坦；脑电图监测（含亚临床发作）","内环境稳定：血糖4～6mmol/L、电解质与酸碱平衡、限制液体（防脑水肿加重）","脑水肿与颅压管理：限液、甘露醇（必要时）、避免快速补液与高渗液","多器官损害处理：急性肾损伤（限制液体与肾毒性药物）、心肌损害（营养心肌）、消化道出血（禁食与抑酸）","营养支持：早期肠内营养（母乳）或肠外营养，保证热量与蛋白","随访与早期干预：出院后1、3、6、12个月评估神经发育（头颅MRI、脑电图、发育量表），早期康复干预"],"management":["NICU监护：持续心电、血压、血氧与体温监测（亚低温期间每1～2小时测核心体温）","神经系统观察：每4～6小时评估意识、肌张力、原始反射与惊厥，异常立即报告","亚低温护理：按医嘱控制降温与复温速度、监测寒战（必要时镇静）、皮肤护理（防硬肿与冻伤）、监测凝血与电解质","呼吸护理：保持气道通畅、按需吸痰、观察呼吸节律与暂停，必要时复苏囊或机械通气","喂养护理：评估喂养耐受性（HIE患儿常有胃肠功能不良），必要时推迟肠内喂养并用肠外营养","液体与电解质管理：严格记录出入量（限制液体），监测血糖（每4～6小时）与电解质","宣教与随访：解释病情与预后（依分度）、强调长期随访与早期康复的重要性、指导家长家庭康复训练"],"notes":["亚低温治疗是中重度HIE唯一有效的神经保护治疗，须在生后6小时内开始并持续72小时","HIE常合并多器官损害（肾、心、消化道、凝血），需全面评估与支持","避免高氧、过度通气与快速纠正酸中毒（可加重脑损伤）；限制液体以防脑水肿","惊厥可为亚临床型（仅脑电图异常），需脑电图监测（aEEG）指导治疗","预后与分度相关：轻度多无后遗症；中重度需长期随访与早期康复干预（6个月内开始）"],"emergency":["频繁惊厥或惊厥持续状态 → 苯巴比妥 20mg/kg 负荷静推，必要时咪达唑仑泵入，脑电监测","呼吸暂停或呼吸衰竭 → 立即复苏囊正压通气/气管插管机械通气","休克（低血压、少尿、毛细血管充盈延长）→ 生理盐水 10ml/kg 缓慢扩容+多巴胺泵入","少尿与肌酐升高（急性肾损伤）→ 限制液体、停用肾毒性药物、必要时腹膜透析","消化道出血（呕血、血便）→ 禁食、胃肠减压、抑酸与止血，监测血红蛋白"],"pinyin":"xsjyqsxnb","icd10":"P91.6","physical_exam":["生命体征：体温（亚低温目标33.5～34.5℃）、心率、呼吸（节律与暂停）、血压、血氧","意识状态：兴奋、嗜睡、昏迷（分度依据）","肌张力：正常、增高（上肢屈曲）、低下（松软）或去大脑强直","原始反射：吸吮、拥抱、握持与觅食反射（减弱或消失提示重度）","惊厥表现：面部或肢体抽动、眼球凝视与呼吸暂停（细微发作易漏诊）","前囟与颅缝：张力增高（脑水肿）、颅缝分离","多器官评估：尿量（少尿）、心脏（心率与心音）、腹部（腹胀与消化道出血）"],"lab_tests":["血气分析+乳酸（每6～12小时）：酸中毒与灌注评估（脐动脉血pH<7.0为窒息证据）","血糖（每4～6小时）：维持4～6mmol/L（低血糖加重脑损伤）","电解质（钠、钾、钙）+肾功能（肌酐、尿量）：抗利尿激素异常分泌与急性肾损伤评估","心肌酶（CK-MB、肌钙蛋白）+肝功能：多器官损害评估","凝血功能+血小板：凝血障碍与DIC评估（亚低温期间更需监测）","头颅超声（床旁，动态）+头颅MRI（生后3～7天）：脑损伤部位与程度及预后评估","振幅整合脑电图（aEEG）+常规脑电图：惊厥监测与背景活动（预后判断）"],"nursing":["亚低温护理：按医嘱控制降温与复温速度（0.5℃/h）、每1～2小时测核心体温、观察寒战与皮肤情况（防硬肿与冻伤）","神经系统观察：每4～6小时评估意识、肌张力与原始反射，观察惊厥表现（含细微发作）并立即报告","呼吸护理：保持气道通畅、观察呼吸节律与暂停、按需吸痰、必要时复苏囊辅助通气","血糖与液体管理：每4～6小时测血糖、严格记录出入量（限制液体60～80ml/kg/日）、监测电解质","喂养护理：评估喂养耐受性（腹胀、呕吐、胃潴留），必要时禁食与肠外营养，母乳喂养优先","皮肤与体位护理：每2小时翻身（防压疮与硬肿）、注意保暖与舒适、减少刺激（声光刺激可诱发惊厥）","宣教与随访：解释病情与预后、指导家长家庭康复（抚触、被动运动）、强调按时随访神经发育"],"diet":["病情稳定后尽早母乳喂养（少量多次，观察耐受性）；吸吮无力者鼻饲","热量需求100～120kcal/kg/日（脑损伤高代谢），必要时肠外营养支持","监测血糖并维持4～6mmol/L；低血糖者静脉输注10%葡萄糖","重度患儿常有胃肠功能不良：推迟肠内喂养、防误吸（鼻饲时床头抬高）","恢复期保证充足蛋白与能量促进脑发育；补充维生素D与铁剂（按医嘱）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1431},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"46ece3590f1a594e27e890b2080ea716d0f5e01e1890d6e9793bab9505214763","pinyin":"xinshengerqueyangquexuexingnaobing","initials":"xseqyqxxnb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","轻度：兴奋、易激惹、拥抱反射活跃、肌张力正常或轻度增高（症状多在24～72小时消失）\\n中度：嗜睡、反应迟钝、肌张力低下、原始反射减弱、惊厥（多在生后12～24小时出现）\\n重度：昏迷、肌张力松软或去大脑强直、原始反射消失、频繁惊厥、呼吸节律不整（可致呼吸暂停）\\n出生时有窒息史：Apgar评分低、羊水胎粪污染、脐动脉血pH<7.0\\n合并多器官损害：少尿（急性肾损伤）、心肌损害（心率与血压异常）、消化道出血",60],["摘要","新生儿缺氧缺血性脑病（HIE）是围产期窒息导致脑血流灌注不足与缺氧引起的脑损伤，是新生儿死亡与神经发育障碍（脑瘫、智力低下、癫痫）的重要原因。按临床表现分轻、中、重度。治疗核心是亚低温治疗（中重度，出生6小时内开始）、维持内环境稳定与器官功能支持。",30],["疾病编码","P91.6",30],["原首字母","xsjyqsxnb",60]]},{"id":"orders-4b991e978f0e39099d03","key":"v1-c9ccc21dfe2a3058|orders-4b991e978f0e39099d03","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"儿童支气管哮喘","category":"儿科","raw":{"name":"儿童支气管哮喘","category":"儿科","summary":"儿童支气管哮喘是以慢性气道炎症与气道高反应性为特征的常见儿童慢性呼吸道疾病，表现为反复发作性喘息、气促、胸闷与咳嗽（夜间与凌晨加重）。治疗核心是长期控制（吸入糖皮质激素为基础）与急性发作分级处理，并重视过敏原回避与家庭教育。","symptoms":["反复发作性喘息、气促、胸闷与咳嗽（夜间与清晨加重、运动后加重）","发作时呼气延长、双肺哮鸣音，重者端坐呼吸、三凹征与发绀","诱因：呼吸道感染、过敏原（尘螨、花粉、宠物）、冷空气、运动、烟雾与情绪激动","间歇期可无症状（咳嗽变异性哮喘仅表现为慢性咳嗽）","重度发作：说话断续、意识改变、呼吸音减弱（'寂静肺'，危急）"],"diagnosis":["病史与症状特征（反复发作、诱因、夜间加重、缓解药物有效）","肺功能+支气管舒张试验（≥6岁可配合）：FEV1改善≥12%支持诊断；支气管激发试验（必要时）","过敏原检测（皮肤点刺或血清特异性IgE）+总IgE：过敏体质评估","呼出气一氧化氮（FeNO）：气道嗜酸粒细胞炎症评估（指导治疗）","胸部X线：排除异物、肺炎与先天畸形（首次发作或治疗反应差）","血气分析（重度发作）：低氧血症与二氧化碳潴留（PaCO₂正常或升高提示呼吸衰竭）","鉴别诊断：毛细支气管炎、气道异物、先天性喉喘鸣、胃食管反流与抽动性咳嗽"],"infusion":["⚠️ 急性发作按严重度分级处理，重度需静脉激素与吸氧！","","方案1（中重度发作，全身糖皮质激素）：","  用法：甲泼尼龙 1～2mg/kg（NS 100ml 或 5%GS 100ml）静滴 q12h（最大40mg）或 氢化可的松 5～10mg/kg 静滴 q6h；症状缓解后改口服泼尼松 1～2mg/kg/日（3～5天）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案2（雾化吸入，首选给药途径）：","  用法：布地奈德 0.5～1mg + 特布他林 2.5～5mg（或沙丁胺醇 2.5mg）雾化吸入 q20min×3次（首小时），之后按病情q1～4h","","方案3（重度发作/持续状态）：","  用法：硫酸镁 25～40mg/kg（NS 100ml 或 5%GS 100ml；缓慢静滴）（20分钟，最大2g，监测血压与心率）；氨茶碱 4～6mg/kg 静滴（负荷，监测血药浓度与心律）；必要时无创/有创机械通气〔调 ★ 老年/心衰/肝功能不全减量；★ 治疗窗窄需监测血药浓度〕","","方案4（补液与支持）：","  用法：0.9%氯化钠 静滴（补液，注意避免过量致肺水肿）；吸氧维持SpO₂≥94%；必要时纠正酸中毒（慎用碳酸氢钠）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","","📌 首选吸入治疗（起效快、副作用小）；重度发作忌用镇静剂；PaCO₂升高提示呼吸衰竭需机械通气；避免使用抗生素（除非合并细菌感染）。"],"oral_medication":["⚠️ 长期控制用药是核心（吸入为主，按年龄选择装置）：","药物1（长期控制，吸入糖皮质激素）：","用法：布地奈德气雾剂/雾化 0.25～0.5mg bid（<6岁）或 氟替卡松吸入剂 100～250μg bid（≥6岁）；按控制水平降级或升级（阶梯治疗）","药物2（联合长效β2激动剂，中重度）：","用法：沙美特罗替卡松粉吸入剂 1吸 bid（≥4岁）；或 布地奈德福莫特罗 1吸 bid","药物3（缓解药，按需）：","用法：沙丁胺醇气雾剂 1～2吸 必要时（发作时）；或 特布他林雾化 2.5mg 必要时","药物4（白三烯受体拮抗剂，辅助）：","用法：孟鲁司特 4mg qn（1～5岁）、5mg qn（6～14岁）（尤其运动诱发与过敏性鼻炎共病）","📌 吸入装置使用技术决定疗效（需反复示教与检查）；长期控制药需每日使用（不可仅在发作时用）；定期评估控制水平并阶梯调整。"],"treatment":["急性发作分级处理：轻度（沙丁胺醇100～200μg吸入）、中度（雾化沙丁胺醇2.5～5mg+激素+吸氧）、重度（静脉激素+硫酸镁+机械通气评估）","长期控制（阶梯治疗）：1级（按需缓解药）→2级（低剂量ICS）→3级（低剂量ICS+LABA或LTRA）→4级（中高剂量ICS+LABA）→5级（加用生物制剂/口服激素）","过敏原回避与环境控制：尘螨防护（防螨床品、勤晒洗）、避免宠物与花粉、禁烟（家庭无烟环境）、除霉与通风","免疫治疗：尘螨过敏且药物控制不佳者可考虑特异性免疫治疗（皮下/舌下，专科进行）","合并症处理：过敏性鼻炎（鼻用激素如糠酸莫米松+抗组胺药如西替利嗪）、鼻窦炎、胃食管反流与肥胖","急性发作预防：识别诱因、随身携带缓解药、制定书面哮喘行动计划（含何时就医）","随访与监测：每1～3个月评估症状控制（ACT/C-ACT评分）、肺功能与FeNO，调整治疗","宣教：吸入装置使用技术、哮喘行动计划、识别重度发作征象、疫苗接种（流感疫苗）"],"management":["症状与控制评估：记录日间症状、夜间憋醒、缓解药使用频率与活动受限（C-ACT评分），评估控制水平","吸入装置指导：反复示教并检查（压力定量气雾剂需储雾罐、干粉吸入器需足够吸力），每次就诊复查技术","急性发作监测：呼吸频率、哮鸣音、三凹征、血氧与说话能力，重度征象（寂静肺、意识改变）立即报告","用药依从性管理：强调长期控制药每日使用（即使无症状）、检查剩余药量与吸入技术","环境与诱因管理：家庭无烟环境、防螨措施、避免过敏原与冷空气刺激、运动前预防用药（运动诱发者）","哮喘行动计划：提供书面计划（绿区/黄区/红区）指导家长识别恶化与用药调整、何时急诊","宣教与随访：疫苗接种（流感）、按时随访与肺功能复查、心理支持（哮喘儿童与家长焦虑常见）"],"notes":["儿童哮喘治疗核心是长期吸入糖皮质激素控制气道炎症（不是仅发作时用药）","吸入装置使用技术直接决定疗效（<6岁用雾化或储雾罐+气雾剂）","急性重度发作出现'寂静肺'（呼吸音减弱）、意识改变或PaCO₂升高提示呼吸衰竭，需机械通气","忌用镇静剂（抑制呼吸）；不常规使用抗生素（除非合并细菌感染）","环境控制（无烟、防螨、避免过敏原）与流感疫苗接种可显著减少发作"],"emergency":["重度发作（说话断续、三凹征、发绀、SpO₂<92%）→ 雾化β2激动剂+静脉激素+吸氧，必要时硫酸镁","呼吸音减弱伴意识改变（寂静肺/呼吸衰竭）→ 立即气管插管机械通气，转ICU","哮喘持续状态（>12小时不缓解）→ 静脉激素+硫酸镁+氨茶碱（监测），评估机械通气","发作伴发热与肺部啰音（合并肺炎）→ 抗感染+继续哮喘治疗","发作时突发一侧呼吸音消失伴胸痛（气胸）→ 急诊胸部影像与闭式引流"],"pinyin":"etzgqxc","icd10":"J45.9","physical_exam":["生命体征：呼吸频率与形态（三凹征、呼气延长）、心率、血氧、体温","一般情况：说话能力（成句/单词/不能说话）、意识状态、体位（端坐呼吸）","肺部：哮鸣音（双肺弥漫）、呼吸音减弱（重度/寂静肺）、湿啰音（合并感染）","皮肤与黏膜：发绀、皮疹与湿疹（过敏体质）、过敏性鼻炎体征（鼻黏膜苍白水肿）","胸廓：桶状胸（长期未控制）、肋间隙饱满","生长发育：身高体重（长期激素与疾病影响）","合并症：鼻窦压痛、咽后壁滤泡（过敏性鼻炎/鼻窦炎）、胃食管反流征象"],"lab_tests":["肺功能+支气管舒张试验（≥6岁）：FEV1改善≥12%支持诊断，随访评估控制水平","呼出气一氧化氮（FeNO）：气道炎症评估与治疗指导","过敏原检测（皮肤点刺/血清sIgE）+总IgE：过敏体质与诱因识别","血气分析（重度发作）：低氧血症与PaCO₂（升高提示呼吸衰竭）","胸部X线：首次发作、治疗反应差或疑并发症（气胸、肺炎）","血常规+CRP（疑感染）：细菌感染鉴别（嗜酸粒细胞升高提示过敏）","鼻窦影像/胃食管反流评估（必要时）：合并症筛查"],"nursing":["发作期护理：半卧位、吸氧（维持SpO₂≥94%）、按医嘱雾化给药并观察疗效（哮鸣音与呼吸改善）","病情观察：呼吸频率、三凹征、血氧、说话能力与意识，重度征象立即报告（寂静肺预警）","用药护理：雾化吸入正确操作与装置清洗、激素雾化后漱口（防口腔念珠菌）、观察药物不良反应（心悸、手抖）","吸入技术指导：反复示教并检查患儿与家长使用方法，强调长期控制药每日使用","环境与诱因护理：病室避免过敏原与烟雾、保持适宜温湿度、避免冷空气与剧烈活动刺激","宣教：哮喘行动计划（何时用药与就医）、识别重度发作征象、家庭无烟环境、流感疫苗接种、按时随访"],"diet":["均衡饮食，避免已知过敏食物（牛奶、鸡蛋、海鲜、坚果等，按个体过敏原检测）","避免含亚硫酸盐添加剂的食物（可能诱发发作）、冷饮与刺激性食物","肥胖患儿控制体重（肥胖加重哮喘）；保证充足维生素D与蔬果","发作期：清淡易消化饮食，少量多餐，避免过饱影响呼吸","保证充足水分（稀释痰液），避免碳酸饮料（腹胀影响呼吸）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1432},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1f575967f7276500cd4e24cbb1d750178e7b07a92fbc3c77487c425a825a964e","pinyin":"ertongzhiqiguanxiaochuan","initials":"etzqgxc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","反复发作性喘息、气促、胸闷与咳嗽（夜间与清晨加重、运动后加重）\\n发作时呼气延长、双肺哮鸣音，重者端坐呼吸、三凹征与发绀\\n诱因：呼吸道感染、过敏原（尘螨、花粉、宠物）、冷空气、运动、烟雾与情绪激动\\n间歇期可无症状（咳嗽变异性哮喘仅表现为慢性咳嗽）\\n重度发作：说话断续、意识改变、呼吸音减弱（'寂静肺'，危急）",60],["摘要","儿童支气管哮喘是以慢性气道炎症与气道高反应性为特征的常见儿童慢性呼吸道疾病，表现为反复发作性喘息、气促、胸闷与咳嗽（夜间与凌晨加重）。治疗核心是长期控制（吸入糖皮质激素为基础）与急性发作分级处理，并重视过敏原回避与家庭教育。",30],["疾病编码","J45.9",30],["原首字母","etzgqxc",60]]},{"id":"orders-9578511ec7d8d140ac53","key":"v1-c9ccc21dfe2a3058|orders-9578511ec7d8d140ac53","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿急性喉炎（喉梗阻）","category":"儿科","raw":{"name":"小儿急性喉炎（喉梗阻）","category":"儿科","summary":"小儿急性喉炎是喉部黏膜急性炎症（多由病毒引起，常见副流感病毒），因小儿喉腔狭小、黏膜下组织疏松，易发生喉梗阻致呼吸困难，多见于1～3岁幼儿，夜间加重。表现为犬吠样咳嗽、声音嘶哑、吸气性喉鸣与三凹征，重者可窒息，属儿科急症。","symptoms":["犬吠样咳嗽（特征性）、声音嘶哑、吸气性喉鸣（夜间加重）","吸气性呼吸困难：三凹征（胸骨上窝、锁骨上窝、肋间隙凹陷）、鼻翼扇动","发热（多低中度，病毒性）、流涕与咽痛（前驱上感症状）","烦躁不安、拒食、发绀（重度缺氧）","喉梗阻分度：Ⅰ度（活动后喉鸣）、Ⅱ度（安静时喉鸣与三凹征）、Ⅲ度（烦躁、发绀）、Ⅳ度（呼吸衰竭、昏迷）"],"diagnosis":["临床表现（犬吠样咳嗽+声嘶+吸气性喉鸣+三凹征）：典型者可临床诊断","喉梗阻分度评估（决定处理紧急程度）：呼吸频率、三凹征、发绀、意识与血氧","血氧饱和度+血气分析：低氧血症与二氧化碳潴留评估（重度）","血常规+CRP+PCT：感染类型评估（病毒性白细胞多正常或轻度升高）","病原学：呼吸道病毒抗原/PCR（副流感病毒、RSV、腺病毒）","颈部X线（必要时）：声门下狭窄（'尖塔征'）；排除异物与咽后脓肿（慎勿激惹患儿）","鉴别诊断：急性会厌炎（起病急、高热、吞咽困难、流涎、拒卧，需紧急处理）、气道异物、喉痉挛、先天性喉喘鸣与咽后脓肿"],"infusion":["⚠️ 喉梗阻是儿科急症，重度需立即处理并准备气道支持！","","方案1（糖皮质激素，关键治疗）：","  用法：地塞米松 0.15～0.6mg/kg 静推/肌注（最大10mg，单次，可重复）；或 甲泼尼龙 1～2mg/kg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 q6～12h；轻症可口服泼尼松 1mg/kg〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（雾化吸入）：","  用法：布地奈德 0.5～1mg 雾化吸入 q30min×2～3次（首小时）后 q4～6h；必要时联合肾上腺素雾化（见方案3）","","方案3（重度喉梗阻/Ⅲ度以上）：","  用法：肾上腺素 0.5ml/kg（1:1000，最大5ml）+ 生理盐水 3ml 雾化吸入（快速缓解水肿，可q20～30min重复，需监护心率）——注意疗效仅维持1～2小时，需同时用激素并观察反跳","","方案4（补液与支持）：","  用法：0.9%氯化钠/葡萄糖 静滴（补液，避免哭闹与挣扎）；吸氧（湿化）；必要时气管插管或气管切开（Ⅳ度或插管失败）","","📌 保持患儿安静（哭闹加重喉梗阻）；激素+雾化肾上腺素是主要治疗；Ⅲ度以上或进行性加重需准备气管插管（用小号导管）与气管切开；禁用镇静剂（可能掩盖缺氧）。"],"oral_medication":["⚠️ 轻症可口服，需密切观察病情变化：","药物1（糖皮质激素，轻症/恢复期）：","用法：泼尼松 1～2mg/kg/日（分次，疗程3～5天，逐渐减停）；或地塞米松 0.15～0.3mg/kg qd（口服）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","药物2（雾化吸入）：","用法：布地奈德 0.5mg 雾化 bid（家庭雾化需医嘱指导）","药物3（抗感染，仅合并细菌感染时）：","用法：阿莫西林克拉维酸 25～45mg/kg/日 分2次 或 头孢克肟 3～6mg/kg/日（疗程5～7天，按医嘱）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物4（对症与护理）：","用法：对乙酰氨基酚 10～15mg/kg 必要时（退热）；生理盐水雾化（湿化气道）；避免使用镇咳药与镇静剂〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 病毒性喉炎不需抗生素；激素疗程不宜过长但需足量早期使用；家长需学会观察呼吸与三凹征，病情加重立即就诊。"],"treatment":["保持安静与舒适体位：避免哭闹与挣扎（加重喉梗阻），怀抱或半卧位，避免颈部受压","糖皮质激素（核心）：地塞米松单次静推或肌注（0.15～0.6mg/kg），必要时每6～12小时重复；轻症口服泼尼松","雾化治疗：布地奈德雾化；重度加肾上腺素雾化（快速缓解水肿，需监护并警惕反跳）","氧疗：湿化吸氧，维持SpO₂≥92%；避免高浓度长时间吸氧（防二氧化碳潴留掩盖）","气道管理：Ⅲ度以上梗阻或进行性加重者准备气管插管（小号导管）或气管切开；插管前充分给氧与激素","病因与抗感染：病毒性以对症为主；疑细菌（会厌炎、细菌性气管炎）加用抗生素","补液与营养：静脉补液（不能进食者），避免脱水；恢复期流质饮食","随访与宣教：观察24～48小时（夜间加重），出院后继续口服激素；识别加重征象（安静时喉鸣、发绀）立即就诊"],"management":["呼吸与梗阻评估：每1～2小时（夜间更密切）评估呼吸频率、三凹征、喉鸣、发绀与意识，按分度变化调整治疗","保持安静护理：减少操作与刺激（避免哭闹加重梗阻）、家长陪伴安抚、集中护理操作","用药护理：激素按时给予并观察疗效；肾上腺素雾化后监护心率与血压（可致心动过速）、警惕疗效反跳（1～2小时后症状反弹）","氧疗护理：湿化吸氧、监测血氧、避免长时间高浓度吸氧（观察呼吸抑制与CO₂潴留）","气道准备：床旁备气管插管（小号）、喉镜、吸引器与氧气；Ⅲ度以上通知麻醉/耳鼻喉科待命","补液护理：静脉补液维持水电解质平衡；不能进食者记录出入量，观察脱水征","宣教：夜间病情易加重需留院观察、家长学会识别三凹征与喉鸣、避免哭闹与受凉、出现安静时喉鸣或发绀立即就诊"],"notes":["小儿急性喉炎的关键是识别喉梗阻程度（三凹征与安静时喉鸣提示Ⅱ度以上），夜间加重需住院观察","激素（地塞米松）是主要治疗，早期足量使用可显著缓解水肿；雾化肾上腺素用于重度（注意疗效反跳需监护）","禁用镇静剂（可掩盖缺氧）；避免不必要的刺激与哭闹（加重梗阻）","急性会厌炎（高热、流涎、吞咽困难、拒卧）更凶险，需立即气道准备与抗生素，避免强行检查咽喉","Ⅳ度梗阻或插管失败时行气管切开（备用方案）"],"emergency":["安静时喉鸣伴三凹征与发绀（Ⅲ度梗阻）→ 立即激素+肾上腺素雾化+吸氧，准备气管插管","意识改变、呼吸减弱或发绀加重（Ⅳ度梗阻/呼吸衰竭）→ 立即气管插管或气管切开，人工通气","高热、流涎、拒卧与吞咽困难（急性会厌炎）→ 立即激素+抗生素+气道准备，避免刺激咽喉","突发剧烈咳嗽伴一侧呼吸音减弱（气道异物）→ 立即海姆立克法/拍背压胸，必要时喉镜/支气管镜取出","呼吸困难伴颈部肿胀与发热（咽后脓肿）→ 急诊影像+抗生素+外科引流评估"],"pinyin":"etjxhyhgg","icd10":"J05.0","physical_exam":["生命体征：呼吸频率与形态（吸气性呼吸困难）、心率、血氧、体温","喉梗阻体征：喉鸣（吸气性）、三凹征（胸骨上窝、锁骨上窝、肋间隙）、鼻翼扇动、发绀","意识状态：安静、烦躁（Ⅲ度）、嗜睡（Ⅳ度）","声音与咳嗽：犬吠样咳嗽、声音嘶哑、哭声改变","咽部检查（轻柔）：咽部充血与扁桃体（避免激惹；疑会厌炎时禁强行检查）","颈部：颈部肿胀与压痛（咽后脓肿）、活动度","肺部：呼吸音（减弱提示梗阻加重）、有无啰音（合并下呼吸道感染）"],"lab_tests":["血氧饱和度+血气分析：低氧血症与二氧化碳潴留（重度梗阻）","血常规+CRP+PCT：病毒性与细菌性鉴别","呼吸道病原学（病毒抗原/PCR）：副流感病毒、RSV、腺病毒等","颈部X线（必要时）：声门下狭窄（'尖塔征'）与咽后脓肿（避免激惹患儿，需在气道可控条件下进行）","喉镜/支气管镜（必要时）：气道评估与异物取出","电解质+血糖：不能进食与脱水评估","胸部X线（疑下呼吸道感染/异物）：必要时"],"nursing":["保持安静与体位：减少操作与刺激、家长陪伴安抚、取半卧位或怀抱位，防止哭闹加重喉梗阻","呼吸观察：每1～2小时评估呼吸频率、三凹征、喉鸣与发绀并记录，夜间加密观察（病情易加重）","用药护理：激素按时给予并观察疗效；肾上腺素雾化后监测心率与血压，观察1～2小时后是否症状反跳","氧疗护理：湿化吸氧、监测血氧、观察呼吸抑制（避免高浓度长时间吸氧掩盖CO₂潴留）","急救准备：床旁备气管插管（小号）、喉镜、吸引器与复苏囊；Ⅲ度以上通知麻醉/耳鼻喉科待命","促进舒适与补液：保持病室适宜温湿度（湿化气道）、静脉补液、记录出入量","宣教：家长识别三凹征与安静时喉鸣、避免受凉与哭闹、按时用药与复诊、出现加重征象立即就诊"],"diet":["急性期：流质或半流质（温凉，避免刺激咽喉），少量多餐","保证水分摄入（稀释分泌物、湿润气道），避免冷饮与刺激性食物","喂养时避免呛咳与哭闹（呛咳加重梗阻）；不能进食者静脉补液","恢复期：清淡易消化、高蛋白高维生素饮食促进恢复","避免过敏与刺激性食物（如过敏体质者）；保持大便通畅"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1433},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"57db97c28190c5966eb0c44263ef7ec55e34b863386a7d1d375064ca6b8a6105","pinyin":"xiaoerjixinghouyan（hougengzu）","initials":"xejxhy（hgz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","犬吠样咳嗽（特征性）、声音嘶哑、吸气性喉鸣（夜间加重）\\n吸气性呼吸困难：三凹征（胸骨上窝、锁骨上窝、肋间隙凹陷）、鼻翼扇动\\n发热（多低中度，病毒性）、流涕与咽痛（前驱上感症状）\\n烦躁不安、拒食、发绀（重度缺氧）\\n喉梗阻分度：Ⅰ度（活动后喉鸣）、Ⅱ度（安静时喉鸣与三凹征）、Ⅲ度（烦躁、发绀）、Ⅳ度（呼吸衰竭、昏迷）",60],["摘要","小儿急性喉炎是喉部黏膜急性炎症（多由病毒引起，常见副流感病毒），因小儿喉腔狭小、黏膜下组织疏松，易发生喉梗阻致呼吸困难，多见于1～3岁幼儿，夜间加重。表现为犬吠样咳嗽、声音嘶哑、吸气性喉鸣与三凹征，重者可窒息，属儿科急症。",30],["疾病编码","J05.0",30],["原首字母","etjxhyhgg",60]]},{"id":"orders-8a3959b607a366135087","key":"v1-c9ccc21dfe2a3058|orders-8a3959b607a366135087","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿支原体肺炎","category":"儿科","raw":{"name":"小儿支原体肺炎","category":"儿科","summary":"小儿支原体肺炎由肺炎支原体引起，多见于学龄前与学龄期儿童，以发热、刺激性干咳（阵发性、夜间加重）、肺部体征轻而影像学改变明显为特点（'症状与体征分离'）。大环内酯类是首选抗生素（阿奇霉素），重症可合并胸腔积液、肺不张与肺外表现（皮疹、溶血、脑炎）。","symptoms":["发热（多为中高热，持续1～2周）、刺激性干咳（阵发性、夜间加重，可呈百日咳样）","咽痛、头痛、乏力、食欲减退；婴幼儿可喘息明显（与RSV感染相似）","肺部体征轻（早期可无啰音）而胸片改变明显（'症状与体征分离'）","肺外表现：皮疹、溶血性贫血、关节炎、中枢神经系统（脑炎）、消化系统（肝损、腹泻）与心血管表现","重症：持续高热、呼吸困难、胸腔积液与肺不张"],"diagnosis":["肺炎支原体抗体（IgM/IgG，恢复期滴度4倍升高有诊断价值；单次IgM阳性支持近期感染）","肺炎支原体核酸（咽拭子/痰PCR）：早期敏感（首选病原学）","胸部X线：间质浸润、斑片状影、肺门影增浓、胸腔积液与肺不张（影像重于体征）","胸部CT（重症/疑难）：磨玻璃影、支气管壁增厚与胸腔积液评估","血常规+CRP+PCT：白细胞多正常或轻度升高、CRP可升高（鉴别细菌感染）","冷凝集素试验（辅助）：滴度≥1:64 支持诊断","重症评估：血气分析、胸腔超声、肝肾功能与心肌酶（肺外损害）"],"infusion":["⚠️ 大环内酯类是首选抗生素，重症需静脉给药！","","方案1（抗感染，首选大环内酯类）：","  用法：阿奇霉素 10mg/kg（NS 250ml 或 5%GS 250ml）静滴 qd（首日10mg/kg，第2～5天 5mg/kg）或 红霉素 20～30mg/kg/日 分2～3次静滴（疗程7～14天）；重症可延长至2～3周","","方案2（糖皮质激素，重症/难治性）：","  用法：甲泼尼龙 1～2mg/kg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 q12h（或 qd），疗程3～5天后逐渐减量（用于持续高热、胸腔积液、肺不张与肺外表现明显者）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（胸腔积液/严重炎症）：","  用法：胸腔穿刺引流（中大量积液或脓胸）；必要时胸腔闭式引流；丙种球蛋白 400mg/kg（专用溶媒/NS（按说明书，先慢后快））静滴 qd×3～5天（重症）","","方案4（补液与支持）：","  用法：0.9%氯化钠/葡萄糖 静滴（补液与维持内环境）；氨溴索 15mg 静滴 bid或雾化化痰；必要时吸氧与退热〔调 妊娠早期禁用；胃溃疡者慎用〕","","📌 支原体无细胞壁，青霉素与头孢菌素无效（勿滥用）；阿奇霉素疗程依病情（轻症3天，重症可延长）；重症病例警惕混合感染与肺外并发症。"],"oral_medication":["⚠️ 恢复期口服序贯（大环内酯类）：","药物1（大环内酯类口服）：","用法：阿奇霉素 10mg/kg qd（口服，用3天停4天，疗程2～3个周期）或 克拉霉素 7.5mg/kg bid（疗程7～14天）；红霉素 30～50mg/kg/日 分次（胃肠反应较多）","药物2（对症止咳化痰）：","用法：氨溴索 15mg tid 或 乙酰半胱氨酸 0.1g tid（化痰）；孟鲁司特 4～5mg qn（咳嗽顽固者，遵医嘱）；避免使用强力镇咳药〔调 妊娠早期禁用；胃溃疡者慎用〕","药物3（退热与支持）：","用法：对乙酰氨基酚 10～15mg/kg q4～6h 或 布洛芬 5～10mg/kg q6～8h（≥6月龄）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4（营养与辅助）：","用法：维生素D 400～800IU qd；益生菌（抗生素相关腹泻）；必要时口服营养补充","📌 阿奇霉素口服生物利用度高（可序贯治疗）；咳嗽可持续数周（不必长期使用抗生素）；避免自行使用青霉素类与头孢菌素。"],"treatment":["抗感染治疗（大环内酯类为首选：阿奇霉素10mg/kg qd口服或静滴，疗程7～14天）","重症与难治性病例：甲泼尼龙1～2mg/kg/d静滴、丙种球蛋白1g/kg/d连用1～2天，必要时加用其他抗感染药物","胸腔积液处理：胸腔穿刺或闭式引流（中大量积液），积液培养与细胞学检查","对症治疗：退热（对乙酰氨基酚10～15mg/kg q4～6h或布洛芬5～10mg/kg q6～8h）、氨溴索化痰、支气管舒张剂（喘息者）、氧疗","肺外并发症处理：皮疹（抗组胺药如西替利嗪）、溶血性贫血（激素/输血）、脑炎（降颅压与激素）、心肌损害（营养心肌）","支持治疗：补液与营养、维持内环境稳定，必要时机械通气（呼吸衰竭）","治疗评估：用药48～72小时评估体温与症状，无效者考虑耐药、混合感染或其他诊断","随访：出院后1～2周复查胸片或超声（肺不张与积液吸收）、随访咳嗽与肺功能"],"management":["体温与症状监测：每4小时测体温，记录咳嗽性质与频次、呼吸困难与精神反应，异常立即报告","呼吸道护理：雾化吸入（稀释痰液）、拍背排痰（体位引流）、保持气道通畅、必要时吸氧","用药护理：阿奇霉素静滴速度不宜过快（>1小时，减少静脉刺激与胃肠反应）、观察药物不良反应","液体与营养：鼓励少量多次饮水与进食（稀释痰液）；不能进食者静脉补液，记录出入量","隔离与消毒：支原体经飞沫传播，住院患儿呼吸道隔离、病室通风、玩具与餐具消毒","重症监测：呼吸频率、血氧、胸腔积液征象（呼吸音减弱）与肺外表现（皮疹、尿色改变）","宣教：按疗程完成治疗（不可自行停药）、咳嗽可持续数周属正常、出现气促与精神差立即就诊、家庭通风与手卫生"],"notes":["支原体肺炎特点为'症状重、体征轻、影像重'（早期可无啰音但胸片明显）","肺炎支原体无细胞壁，青霉素与头孢菌素无效——首选大环内酯类（阿奇霉素）","阿奇霉素静滴时间应>1小时（减少静脉炎与胃肠反应）；口服生物利用度高，可序贯治疗","重症或难治性病例加用糖皮质激素（持续高热、胸腔积液、肺不张与肺外表现）","咳嗽可持续数周（气道高反应性），不需长期抗生素；治疗72小时无效需重新评估（耐药/混合感染/其他诊断）"],"emergency":["持续高热伴呼吸困难与血氧下降（重症肺炎）→ 吸氧、静脉激素+大环内酯类，评估机械通气","胸腔积液迅速增多伴呼吸受限（大量积液/脓胸）→ 急诊胸腔穿刺或闭式引流","意识改变与抽搐（支原体脑炎）→ 头颅影像+腰穿，降颅压与激素治疗","溶血性贫血（面色苍白、黄疸、血红蛋白快速下降）→ 激素±输血，监测血红蛋白与胆红素","暴发心肌炎（心率异常、心音低钝、血压下降）→ 心肌酶+心脏超声，营养心肌与循环支持"],"pinyin":"etztytfy","icd10":"J15.7","physical_exam":["生命体征：体温（中高热）、呼吸频率、心率、血氧","一般情况：精神状态、食欲与活动量（重症精神萎靡）","咽部与颈部：咽充血、扁桃体、颈部淋巴结肿大","肺部：早期呼吸音粗或无明显啰音、后期可闻及湿啰音或喘鸣音、呼吸音减弱（胸腔积液/肺不张）","心脏：心率、心音（心肌损害）","腹部：肝脾大小（肝损）、腹痛与压痛","皮肤：皮疹（支原体感染常见多形性皮疹）、结膜充血（黏膜炎表现）"],"lab_tests":["肺炎支原体核酸（咽拭子/痰PCR）：早期病原学诊断首选","肺炎支原体抗体（IgM/IgG，双份血清4倍升高）：诊断依据","胸部X线/CT：间质浸润、斑片影、肺门影增浓、胸腔积液与肺不张","血常规+CRP+PCT：白细胞多正常或轻度升高，CRP可升高（细菌感染鉴别）","冷凝集素试验（辅助）：滴度≥1:64 支持诊断","血气分析+胸腔超声（重症）：低氧血症与胸腔积液评估","肝肾功能+心肌酶+尿常规（肺外损害）：肝功能损害、心肌损害与溶血评估"],"nursing":["体温与病情观察：每4小时测体温，观察咳嗽、呼吸与精神状态，异常立即报告","呼吸道护理：雾化吸入后拍背排痰（由下向上、由外向内）、必要时体位引流与吸氧，保持气道通畅","用药护理：阿奇霉素静滴>1小时、观察胃肠反应与静脉炎；激素按医嘱减量（不可骤停）","液体与营养护理：鼓励少量多次饮水、清淡饮食；不能进食者静脉补液并记录出入量","隔离与消毒：呼吸道隔离、病室通风、餐具与玩具消毒、手卫生宣教","重症观察：呼吸频率与血氧、胸腔积液征象（一侧呼吸音减弱）、皮疹与尿色（肺外表现）","宣教：按疗程完成治疗、咳嗽可持续数周不必恐慌、出现气促/精神差/尿色加深立即就诊、家庭通风与手卫生"],"diet":["清淡易消化、高蛋白高维生素饮食（鱼、瘦肉、蛋、蔬果）促进恢复","少量多餐、多饮水（稀释痰液，每日适量），避免过饱影响呼吸","发热期：流质或半流质（米汤、面条、蒸蛋），避免油腻与辛辣刺激","咳嗽明显者：避免甜食与冷饮（刺激咳嗽）、避免易致敏食物（过敏体质者）","恢复期加强营养、补充维生素D与铁剂（按医嘱），保证充足睡眠"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1434},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a43440f71eac05f944a3564108c71647681222944626520e400439b0cf8dfd0f","pinyin":"xiaoerzhiyuantifeiyan","initials":"xezytfy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","发热（多为中高热，持续1～2周）、刺激性干咳（阵发性、夜间加重，可呈百日咳样）\\n咽痛、头痛、乏力、食欲减退；婴幼儿可喘息明显（与RSV感染相似）\\n肺部体征轻（早期可无啰音）而胸片改变明显（'症状与体征分离'）\\n肺外表现：皮疹、溶血性贫血、关节炎、中枢神经系统（脑炎）、消化系统（肝损、腹泻）与心血管表现\\n重症：持续高热、呼吸困难、胸腔积液与肺不张",60],["摘要","小儿支原体肺炎由肺炎支原体引起，多见于学龄前与学龄期儿童，以发热、刺激性干咳（阵发性、夜间加重）、肺部体征轻而影像学改变明显为特点（'症状与体征分离'）。大环内酯类是首选抗生素（阿奇霉素），重症可合并胸腔积液、肺不张与肺外表现（皮疹、溶血、脑炎）。",30],["疾病编码","J15.7",30],["原首字母","etztytfy",60]]},{"id":"orders-3c4995807e10908eba16","key":"v1-c9ccc21dfe2a3058|orders-3c4995807e10908eba16","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿泌尿道感染","category":"儿科","raw":{"name":"小儿泌尿道感染","category":"儿科","summary":"小儿泌尿道感染（UTI）是儿童常见细菌感染，婴幼儿常表现为不明原因发热而无泌尿系症状（易漏诊）；年长儿可有尿频、尿急、尿痛与腰痛。致病菌以大肠埃希菌为主。诊断依靠尿常规与尿培养，治疗需按年龄与病情选择抗生素，并评估有无泌尿系畸形（膀胱输尿管反流）。","symptoms":["婴幼儿：不明原因发热（可为唯一表现）、拒奶、呕吐、腹泻、生长发育迟缓、黄疸（新生儿）","年长儿：尿频、尿急、尿痛（膀胱刺激征）、下腹不适、遗尿复发","上尿路感染（肾盂肾炎）：高热寒战、腰痛（或肋脊角叩击痛）、呕吐","脓尿（尿液混浊）、血尿（镜下或肉眼）","反复感染：提示泌尿系畸形（膀胱输尿管反流、后尿道瓣膜）或膀胱功能障碍"],"diagnosis":["尿常规（白细胞、亚硝酸盐、白细胞酯酶）：筛查（离心尿白细胞>5/HPF提示感染）","尿培养+药敏（确诊金标准）：清洁中段尿（年长儿）或导尿/耻骨上穿刺（婴幼儿）；菌落计数≥10⁵CFU/ml（中段尿）有诊断意义","尿标本采集规范：避免污染（女童清洁外阴、男童清洗包皮；集尿袋标本阳性需导尿或穿刺复核）","血常规+CRP+PCT：感染程度与上/下尿路鉴别","肾功能+电解质：反复感染或肾损害评估","泌尿系超声（所有患儿建议）：评估肾大小、积水、结石、膀胱与输尿管异常","排尿性膀胱尿道造影（VCUG，指征：<2岁首次发热性UTI、反复感染、超声异常）：评估膀胱输尿管反流与后尿道瓣膜","DMSA肾扫描（必要时）：肾瘢痕评估"],"infusion":["⚠️ 婴幼儿与上尿路感染需静脉抗生素，按年龄与病情选择！","","方案1（经验性静脉抗感染，<3月龄或重症）：","  用法：氨苄西林 50mg/kg（NS 100ml 或 5%GS 100ml）静滴 q6～8h + 庆大霉素 5mg/kg 静滴 qd（或 头孢噻肟 50mg/kg 静滴 q8h）；<3月龄婴儿建议住院治疗","","方案2（>3月龄上尿路感染，经验性）：","  用法：头孢曲松 50～75mg/kg（NS 100ml 或 5%GS 100ml）静滴 qd（最大1～2g）或 头孢噻肟 50mg/kg 静滴 q8h；用药48～72小时评估疗效〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案3（药敏结果后调整，窄谱优先）：","  用法：头孢呋辛 30～50mg/kg（NS 100ml 或 5%GS 100ml）静滴 q8h；或 阿莫西林克拉维酸 30mg/kg 静滴 q8h（按药敏）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","","方案4（补液与支持）：","  用法：0.9%氯化钠/葡萄糖 静滴（补液，鼓励饮水）；对乙酰氨基酚 10～15mg/kg 静推（退热）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","","📌 尿培养应在抗生素使用前留取；婴幼儿UTI需评估泌尿系畸形（超声+必要时VCUG）；避免使用肾毒性药物（氨基糖苷类需监测肾功能与血药浓度）。"],"oral_medication":["⚠️ 恢复期口服序贯（疗程7～14天）：","药物1（口服抗生素，按药敏）：","用法：头孢克肟 3～6mg/kg/日 分2次 或 阿莫西林克拉维酸 25～45mg/kg/日 分2～3次；呋喃妥因 3mg/kg/日 分4次（仅下尿路感染，肾功能正常者）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（预防性用药，反复感染/膀胱输尿管反流）：","用法：复方磺胺甲噁唑（TMP 1～2mg/kg qn）或 呋喃妥因 1mg/kg qn（疗程按反流程度，遵医嘱）","药物3（对症与支持）：","用法：对乙酰氨基酚 10～15mg/kg 必要时（退热）；益生菌（抗生素相关腹泻，与抗生素间隔2小时）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物4（排尿与排便管理）：","用法：乳果糖 15ml bid（便秘可加重UTI）；保证充足饮水（每日排尿4～6次）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 疗程需足（下尿路感染7天、上尿路感染10～14天）；<3月龄婴儿与重症需住院静脉治疗；呋喃妥因与磺胺类在<2月龄婴儿禁用。"],"treatment":["抗感染治疗：按年龄与病情选择（婴幼儿与上尿路感染静脉给药，年长儿下尿路感染可口服），疗程7～14天","尿标本规范采集与培养（抗生素前），据药敏调整（窄谱优先）","泌尿系影像评估：所有患儿行泌尿系超声；<2岁发热性UTI或反复感染/超声异常者行VCUG（膀胱输尿管反流评估）","膀胱输尿管反流管理：预防性抗生素（按反流分级）、排尿训练与便秘管理，重度反流需手术（内镜下注射或输尿管再植）","膀胱与肠道功能管理：规律排尿（每2～3小时）、充分饮水、治疗便秘（便秘是复发重要因素）","复发与再感染防控：女童注意会阴清洁（由前向后擦拭）、包皮护理（男童）、避免长期憋尿","并发症处理：肾盂肾炎（延长疗程）、肾脓肿（引流）、败血症（ICU与广谱抗生素）","随访：反复感染者定期尿培养与超声随访、监测血压与肾功能（肾瘢痕风险）"],"management":["尿标本采集护理：严格清洁（女童由前向后清洁外阴、男童清洗包皮垢），中段尿或导尿/穿刺，标本及时送检（<1小时或冷藏）","体温与症状观察：婴幼儿每4小时测体温（不明原因发热需排查UTI），记录排尿情况与尿色，异常报告","用药护理：按体重计算剂量与间隔、观察药物不良反应（氨基糖苷类监测肾功能与听力），保证疗程完成","补液与排尿护理：鼓励多饮水（年长儿每日排尿4～6次）、不憋尿、规律排尿（每2～3小时一次）","会阴与皮肤护理：保持会阴清洁干燥、勤换尿布（婴幼儿）、女童擦拭方向正确、男童包皮护理","预防性用药管理（反流/复发者）：按医嘱按时给药、记录并随访（不可自行停药）","宣教：多饮水与规律排尿、会阴清洁方法、便秘防治、按时复查尿培养与超声、发热时告知既往UTI史"],"notes":["婴幼儿UTI常以不明原因发热为唯一表现（无泌尿系症状），<3月龄婴儿发热应常规查尿","尿培养是确诊金标准，标本采集规范至关重要（集尿袋标本阳性需导尿或耻骨上穿刺复核）","所有患儿应行泌尿系超声；<2岁发热性UTI或反复感染者行VCUG排除膀胱输尿管反流","便秘与憋尿是UTI复发的重要因素（需同步管理）","反复感染与膀胱输尿管反流可致肾瘢痕与高血压，需长期随访血压与肾功能"],"emergency":["高热寒战伴精神萎靡与循环不良（尿源性脓毒症）→ 立即血培养+尿培养+静脉广谱抗生素+液体复苏","少尿、无尿伴肌酐升高（急性肾损伤）→ 评估梗阻与血流灌注，必要时引流与肾替代","腰痛加剧伴高热与肾区叩击痛（肾脓肿/肾盂积脓）→ 急诊影像+引流+抗感染","排尿困难伴膀胱充盈（尿潴留/后尿道瓣膜）→ 导尿减压并评估（泌尿外科）","反复呕吐伴脱水与电解质紊乱 → 静脉补液纠正"],"pinyin":"etmndgr","icd10":"N39.0","physical_exam":["生命体征：体温（不明原因发热）、心率、呼吸、血压、体重（生长评估）","一般情况：精神状态、食欲、有无脱水（婴幼儿）","腹部：下腹压痛与膀胱充盈（尿潴留）、腹部包块（肾积水/膀胱扩张）","肾区：肋脊角叩击痛（上尿路感染）","外生殖器：会阴红肿与分泌物（女童外阴炎）、包皮过长与包茎（男童）、尿道口异常","脊柱与神经系统：腰骶部异常（脊柱裂/神经源性膀胱）、下肢肌力与反射","血压：反复感染或肾瘢痕者（肾性高血压）"],"lab_tests":["尿常规（白细胞、亚硝酸盐、白细胞酯酶、血尿）：筛查（尿培养前留取）","尿培养+药敏（诊断金标准）：抗生素前留取，规范采集（中段尿/导尿/耻骨上穿刺）","血常规+CRP+PCT：感染程度与上/下尿路感染鉴别","肾功能（肌酐、尿素氮）+电解质：肾损害与脱水评估","泌尿系超声（所有患儿）：肾大小、积水、结石、膀胱与输尿管异常","排尿性膀胱尿道造影（VCUG）：<2岁发热性UTI、反复感染或超声异常者（膀胱输尿管反流与后尿道瓣膜）","DMSA肾扫描（必要时）：肾瘢痕评估（反复感染或反流者）"],"nursing":["体温与排尿观察：婴幼儿每4小时测体温、记录尿量与尿色、排尿时哭闹（排尿疼痛），异常立即报告","标本采集护理：规范清洁会阴（女童前向后、男童洗包皮），中段尿/导尿留取并及时送检（<1小时）","用药护理：按体重计算剂量并核对间隔，观察药物不良反应（氨基糖苷类监测肾功能与听力），保证疗程完成","补液与排尿护理：鼓励多饮水、每2～3小时排尿一次、不憋尿、便秘者通便管理","会阴护理：保持清洁干燥、勤换尿布、女童擦拭方向正确（避免肠道菌污染尿道）","预防性用药随访（反流者）：按时给药并记录、提醒定期尿培养与超声复查","宣教：多饮水规律排尿、会阴清洁方法、便秘防治、出现发热时告知既往UTI史、按时随访与复查"],"diet":["多饮水（年长儿每日1000～1500ml，婴幼儿适量增加），稀释尿液并冲刷尿道","避免含咖啡因与刺激性饮料（刺激膀胱）；避免高盐与加工食品","均衡饮食、高维生素（蔬果）；酸奶与益生菌有助肠道与泌尿健康","便秘患儿：增加膳食纤维（蔬菜水果粗粮）与水分","反复感染者：避免长期使用抗生素残留的食品，注意饮食卫生"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1435},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"731b646ab08e1bd7310d9a9eb397f40380c581bcd138116bd57fd2f7b27fa212","pinyin":"xiaoerminiaodaoganran","initials":"xemndgr","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","婴幼儿：不明原因发热（可为唯一表现）、拒奶、呕吐、腹泻、生长发育迟缓、黄疸（新生儿）\\n年长儿：尿频、尿急、尿痛（膀胱刺激征）、下腹不适、遗尿复发\\n上尿路感染（肾盂肾炎）：高热寒战、腰痛（或肋脊角叩击痛）、呕吐\\n脓尿（尿液混浊）、血尿（镜下或肉眼）\\n反复感染：提示泌尿系畸形（膀胱输尿管反流、后尿道瓣膜）或膀胱功能障碍",60],["摘要","小儿泌尿道感染（UTI）是儿童常见细菌感染，婴幼儿常表现为不明原因发热而无泌尿系症状（易漏诊）；年长儿可有尿频、尿急、尿痛与腰痛。致病菌以大肠埃希菌为主。诊断依靠尿常规与尿培养，治疗需按年龄与病情选择抗生素，并评估有无泌尿系畸形（膀胱输尿管反流）。",30],["疾病编码","N39.0",30],["原首字母","etmndgr",60]]},{"id":"orders-0a3ce4f028a2920ac1a4","key":"v1-c9ccc21dfe2a3058|orders-0a3ce4f028a2920ac1a4","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"小儿肾病综合征","category":"儿科","raw":{"name":"小儿肾病综合征","category":"儿科","summary":"小儿肾病综合征（NS）是以大量蛋白尿（24小时尿蛋白>50mg/kg）、低白蛋白血症（<25g/L）、水肿与高脂血症为特征的临床综合征，儿童以微小病变型最常见（对激素敏感）。治疗核心是糖皮质激素（首选泼尼松），并防治感染、血栓与急性肾损伤等并发症。","symptoms":["水肿（首发症状，眼睑与颜面晨起明显、逐渐波及下肢与全身，可伴腹水与阴囊水肿）","尿量减少、尿中泡沫增多（大量蛋白尿）","食欲减退、腹胀、腹泻（肠道水肿）、乏力","感染易感（免疫功能低下与激素治疗）：呼吸道感染、腹膜炎（发热、腹痛）","并发症：低血容量（呕吐腹泻后）、血栓（肾静脉血栓：腰痛与血尿）、急性肾损伤与营养不良"],"diagnosis":["尿常规+24小时尿蛋白定量（>50mg/kg/日）：诊断核心（尿蛋白++++、尿蛋白/肌酐比升高）","血白蛋白（<25g/L）+总蛋白+血脂（胆固醇升高）：诊断与病情评估","肾功能（肌酐、尿素氮）+电解质：血容量与肾功能评估","补体C3+C4+抗核抗体（ANA）：排除继发性（狼疮性肾炎、乙肝相关）","乙肝、丙肝、梅毒与结核筛查：继发性病因与激素治疗前评估（结核）","泌尿系超声+肾静脉超声（疑血栓）：肾大小与肾静脉血栓评估","肾活检（指征：激素耐药/依赖、>10岁首发、血尿伴高血压、补体降低或疑继发性）：病理分型","感染评估（发热者）：血培养、腹水检查（原发性腹膜炎）"],"infusion":["⚠️ 激素是首选治疗，并发症处理按病情选择！","","方案1（糖皮质激素，诱导缓解）：","  用法：泼尼松 2mg/kg/日（最大60mg）分次口服（或晨起顿服）——通常口服；不能口服或重症可 甲泼尼龙 1～2mg/kg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 q12h（短期）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（水肿明显，白蛋白+利尿剂）：","  用法：20%人血白蛋白 0.5～1g/kg 静滴（快速输注后立即给利尿剂）；呋塞米 1～2mg/kg 静推（白蛋白输注后）；或 呋塞米+螺内酯口服（轻中度水肿）〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","","方案3（感染并发症，原发性腹膜炎）：","  用法：头孢曲松 50～75mg/kg 静滴 qd + 甲硝唑 7.5mg/kg 静滴 q8h（疗程10～14天）；血培养与腹水培养留取〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案4（激素耐药/频复发，免疫抑制剂）：","  用法：环磷酰胺 2～3mg/kg/日 口服（8～12周）或 环孢素 3～5mg/kg/日（监测血药浓度与肾功能）；或 他克莫司、利妥昔单抗（专科评估）","","📌 激素诱导缓解需足量足疗程（尿蛋白转阴后巩固并缓慢减量，总疗程9～12个月）；避免快速减量致复发；白蛋白+利尿剂仅用于严重水肿（需防低血容量）。"],"oral_medication":["⚠️ 激素口服是主要治疗（须遵医嘱规律减量）：","药物1（糖皮质激素，核心）：","用法：泼尼松 2mg/kg/日（最大60mg）分次/晨起顿服；尿蛋白转阴后改为 2mg/kg 隔日晨起顿服维持4周，之后逐渐减量（每2～4周减2.5～5mg至停用，总疗程9～12个月）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物2（利尿与消肿）：","用法：氢氯噻嗪 1～2mg/kg/日 + 螺内酯 1～2mg/kg/日（轻中度水肿）；必要时呋塞米 1～2mg/kg 口服〔调 ★ 肾功能不全常需加量；低钾/低血容量慎用〕","药物3（并发症预防）：","用法：碳酸钙D3 600mg qd + 维生素D 400～800IU/日（防骨质疏松）；氯化钾（利尿剂致低钾时）；抗凝（血栓高危者，遵医嘱）","药物4（免疫抑制剂，激素耐药/频复发）：","用法：环磷酰胺 2～3mg/kg/日、环孢素 3～5mg/kg/日 或 他克莫司 0.1mg/kg/日（监测血药浓度与肝肾功能）","📌 激素不可自行减量或停药（易复发且可能致肾上腺危机）；免疫抑制剂需监测血常规、肝肾功能与血药浓度。"],"treatment":["糖皮质激素（首选）：泼尼松诱导缓解（尿蛋白转阴后巩固+缓慢减量，总疗程9～12个月）；复发者重新诱导","水肿管理：限盐限水、利尿剂（轻中度）、严重水肿用白蛋白+呋塞米（避免过度利尿致低血容量与血栓）","感染防治：激素治疗前筛查结核与乙肝；发热者及时评估与抗感染（腹膜炎需早期诊断与治疗）；疫苗接种（灭活疫苗；活疫苗在激素治疗期避免）","血栓预防：重度水肿、低白蛋白（<20g/L）与长期激素者评估抗凝（低分子肝素或阿司匹林，遵医嘱）","急性肾损伤处理：纠正低血容量、停用肾毒性药物（NSAIDs、氨基糖苷类）、必要时透析","激素耐药/依赖：肾活检明确病理（FSGS等），加用免疫抑制剂（环磷酰胺/环孢素/他克莫司/利妥昔单抗）","营养与生长：保证蛋白与热量摄入（蛋白1.5～2g/kg/日）、补充钙与维生素D、监测生长发育与骨密度","随访：定期查尿蛋白（家庭尿试纸监测）、血白蛋白、肾功能与血压；复发早期识别与处理"],"management":["尿蛋白监测：指导家长家庭尿试纸监测（晨尿），记录结果与水肿变化（复发的早期指标）","水肿与体重监测：每日测体重与腹围、记录出入量与尿量，评估利尿效果与水肿消退","用药护理：激素按时给予并观察不良反应（高血压、高血糖、库欣貌、骨质疏松、感染）；利尿剂与白蛋白配合使用并监测电解质","感染防护：避免接触感染者、注意口腔与皮肤清洁、发热与腹痛立即评估（腹膜炎风险）","饮食与营养：限盐（<2g/日）、限水（水肿期）、适量优质蛋白、补充钙与维生素D，记录进食量与体重","活动与皮肤护理：水肿期卧床休息（可床上活动防血栓）、皮肤护理（水肿皮肤易破损与感染）、避免外伤","宣教：激素不可自行减停药、识别复发（尿蛋白转阳、水肿）、感染预防与疫苗接种注意、按时随访"],"notes":["小儿肾病综合征以微小病变型最常见，对激素敏感（80%～90%缓解），激素是首选治疗","激素总疗程9～12个月（诱导+巩固+缓慢减量），快速减量易复发；复发者重新诱导","严重水肿使用白蛋白+利尿剂时需警惕低血容量与血栓（利尿不宜过快）","激素治疗期间避免活疫苗接种（灭活疫苗可接种）；治疗前筛查结核与乙肝","血栓与感染是主要并发症（原发性腹膜炎需早期识别：发热+腹痛）"],"emergency":["发热伴腹痛与腹膜刺激征（原发性腹膜炎）→ 立即腹水检查+血培养+静脉抗生素","腰痛伴血尿与少尿（肾静脉血栓）→ 急诊超声/CT+抗凝治疗","少尿、无尿伴肌酐升高（急性肾损伤）→ 评估血容量、停用肾毒性药物，必要时透析","呕吐腹泻后低血容量休克（血压下降、心率增快）→ 立即补液（生理盐水20ml/kg）纠正","严重水肿伴呼吸困难（胸腔积液/腹水压迫）→ 白蛋白+利尿、吸氧，必要时穿刺引流","抽搐伴高血压（激素相关高血压脑病）→ 立即降压与止惊处理"],"pinyin":"etsbzhz","icd10":"N04.9","physical_exam":["生命体征：血压（激素相关高血压）、心率、呼吸、体温、体重（每日测量）","水肿评估：眼睑与颜面、下肢、阴囊与腹壁水肿（凹陷性）、腹水（移动性浊音）","腹部：腹围（测量）、腹胀与压痛（腹膜炎）、肝脾大小","皮肤：水肿皮肤张力与完整性、有无破损与感染、紫纹与库欣貌（激素）","心肺：心率、心音、呼吸音（胸腔积液）、有无心包积液","生长发育：身高、体重与生长曲线（长期激素影响）","眼部：白内障（长期激素）、眼压（必要时）"],"lab_tests":["尿常规+24小时尿蛋白定量：诊断与疗效监测（尿蛋白转阴为缓解指标）","血白蛋白+总蛋白+血脂（胆固醇）：诊断与病情评估（每1～2周复查）","肾功能（肌酐、尿素氮）+电解质（钾、钠、钙）：肾功能与电解质紊乱监测","补体C3/C4+ANA+乙肝/丙肝/结核筛查：继发性病因与激素治疗前评估","泌尿系超声+肾静脉超声（疑血栓）：肾大小与血栓评估","血常规+CRP+PCT（发热者）：感染并发症评估","肾活检（激素耐药/依赖、>10岁首发、血尿伴高血压、疑继发性）：病理分型"],"nursing":["尿蛋白与水肿监测：指导家庭晨尿试纸监测并记录；每日测体重、腹围与出入量，评估水肿消退","用药护理：激素按时给药并观察不良反应（高血压、高血糖、库欣貌、情绪改变）；白蛋白输注后立即给利尿剂并观察尿量","感染防护：实施保护性措施（避免接触感染者）、口腔与皮肤清洁、监测体温（发热立即报告，警惕腹膜炎）","皮肤与体位护理：水肿皮肤易破损（保持清洁干燥、剪短指甲、避免搔抓与受压）、卧床期间床上活动防血栓","饮食护理：限盐（<2g/日）、水肿期限水、适量优质蛋白（1.5～2g/kg/日）、补充钙与维生素D，记录进食量","心理与家庭支持：长期激素治疗与外观改变易致患儿与家长心理负担，提供心理支持与疾病教育","宣教：激素不可自行减停药、识别复发（尿蛋白转阳+水肿）、感染预防与疫苗接种注意、按时随访与家庭监测"],"diet":["限制钠盐（水肿期每日<2g），避免腌制品与加工食品","水肿明显时限水（按医嘱，一般前一日尿量+500ml）","适量优质蛋白（1.5～2g/kg/日，不宜过量以免加重肾负担），以蛋、奶、鱼、瘦肉为主","低脂饮食（高脂血症者），补充钙与维生素D（长期激素致骨质疏松）","水肿消退后逐步恢复正常饮食，保证热量与生长发育需求"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1436},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d5f1a91e1de9201a3f1817663bd40e71eedc25292b71023eeb8c47e4c3da3a23","pinyin":"xiaoershenbingzonghezheng","initials":"xesbzhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","水肿（首发症状，眼睑与颜面晨起明显、逐渐波及下肢与全身，可伴腹水与阴囊水肿）\\n尿量减少、尿中泡沫增多（大量蛋白尿）\\n食欲减退、腹胀、腹泻（肠道水肿）、乏力\\n感染易感（免疫功能低下与激素治疗）：呼吸道感染、腹膜炎（发热、腹痛）\\n并发症：低血容量（呕吐腹泻后）、血栓（肾静脉血栓：腰痛与血尿）、急性肾损伤与营养不良",60],["摘要","小儿肾病综合征（NS）是以大量蛋白尿（24小时尿蛋白>50mg/kg）、低白蛋白血症（<25g/L）、水肿与高脂血症为特征的临床综合征，儿童以微小病变型最常见（对激素敏感）。治疗核心是糖皮质激素（首选泼尼松），并防治感染、血栓与急性肾损伤等并发症。",30],["疾病编码","N04.9",30],["原首字母","etsbzhz",60]]},{"id":"orders-1647f7484f527f07f9be","key":"v1-c9ccc21dfe2a3058|orders-1647f7484f527f07f9be","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"儿童癫痫","category":"儿科","raw":{"name":"儿童癫痫","category":"儿科","summary":"儿童癫痫是由脑神经元异常同步放电引起的慢性反复发作性疾病，病因包括遗传、围产期损伤、颅内感染、脑发育异常与代谢性疾病。发作类型多样（局灶性、全面性、失神、肌阵挛等），诊断依靠病史（发作视频）、脑电图与影像学。治疗以抗癫痫药物单药起始、规律长期服用为原则。","symptoms":["全面强直-阵挛发作：意识丧失、四肢强直抽动、口吐白沫、尿失禁、发作后嗜睡","失神发作：短暂意识中断（数秒）、凝视、正在进行的活动停止（易被误认为走神）","局灶性发作：局部抽动或感觉异常、可伴意识障碍与自动症（咂嘴、摸索）","肌阵挛/失张力发作：突然点头、肢体抖动或跌倒","婴儿痉挛症：成串的点头、弯腰与四肢屈曲（婴儿期，需尽早治疗）"],"diagnosis":["详细发作史（关键）：发作前兆、发作表现（视频记录最有价值）、持续时间、发作后状态、频率与诱因","脑电图（EEG，含睡眠与长程监测）：发作间期痫样放电（必要时24小时视频脑电监测）","头颅MRI（首选）：脑结构异常（皮质发育不良、肿瘤、海马硬化、围产期损伤）","血生化+电解质+血糖+血氨+乳酸：代谢性病因与低血糖/电解质紊乱鉴别（尤其婴幼儿）","遗传学检查（必要时）：基因panel或全外显子测序（难治性癫痫与发育迟缓者）","腰椎穿刺（疑颅内感染或代谢病）：脑脊液检查","鉴别诊断：热性惊厥、晕厥、抽动障碍、睡眠障碍（夜惊）、低血糖、心源性晕厥与假性发作（心因性）"],"infusion":["⚠️ 癫痫持续状态需立即静脉止惊！","","方案1（惊厥持续状态，一线）：","  用法：地西泮 0.3～0.5mg/kg 缓慢静推（速度≤2mg/min，最大10mg，监测呼吸）；或 咪达唑仑 0.2mg/kg 肌注（无静脉通路）；必要时10分钟后重复一次〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","","方案2（二线负荷，一线无效时）：","  用法：苯巴比妥 15～20mg/kg（NS 100ml 或 5%GS 100ml）静滴（速度≤50mg/min，监测呼吸与血压）；或 丙戊酸钠 15～20mg/kg 静滴（速度≤3mg/kg/min，监测肝功能）；或 左乙拉西坦 40～60mg/kg 静滴（15～30分钟）〔调 ★ 必须按 CrCl 减量；老年减量〕","","方案3（难治性持续状态，ICU）：","  用法：咪达唑仑 0.1～0.2mg/kg/h 泵入（渐加量至发作控制，需机械通气准备）；或 丙泊酚 1～2mg/kg 静推后 2～10mg/kg/h 泵入（ICU与机械通气）","","方案4（病因治疗与支持）：","  用法：低血糖——10%葡萄糖 2ml/kg 静推；低钠/低钙——纠正电解质（3%氯化钠/葡萄糖酸钙）；颅内感染——抗感染；吸氧与保护气道","","📌 地西泮静推须缓慢并监测呼吸；惊厥持续状态需在5～10分钟内开始治疗；难治性者需ICU与机械通气支持；纠正低血糖与电解质等可逆病因。"],"oral_medication":["⚠️ 抗癫痫药单药起始、规律长期服用、缓慢调整：","药物1（局灶性发作首选）：","用法：奥卡西平 8～10mg/kg/日 分2次（渐加量）或 左乙拉西坦 20～40mg/kg/日 分2次；卡马西平（注意皮疹与血象）〔调 ★ 必须按 CrCl 减量；老年减量〕","药物2（全面性发作/多种类型）：","用法：丙戊酸钠 15～30mg/kg/日 分2次（注意肝功能与血小板，育龄女性慎用）；或 左乙拉西坦（广谱）〔调 ★ 必须按 CrCl 减量；老年减量〕","药物3（失神发作）：","用法：乙琥胺 20mg/kg/日 分2次 或 丙戊酸钠；注意丙戊酸与乙琥胺联用可能诱发失神持续状态〔调 ★ 肝功能不全禁用；★ 育龄女性慎用（致畸）〕","药物4（婴儿痉挛症）：","用法：促肾上腺皮质激素（ACTH）或 氨己烯酸 50～100mg/kg/日（结节性硬化首选）；或 托吡酯","📌 抗癫痫药需规律长期服用（不可漏服或骤停，可诱发持续状态）；单药起始、逐渐加量至有效或出现不良反应；定期监测血药浓度、肝功能与血常规。"],"treatment":["抗癫痫药物治疗：按发作类型选择单药（局灶性：奥卡西平/左乙拉西坦；全面性：丙戊酸/左乙拉西坦），逐渐加量至发作控制或出现不良反应；无效者换用或联合第二种药物","惊厥持续状态处理：一线地西泮/咪达唑仑→二线苯巴比妥/丙戊酸/左乙拉西坦→难治性用咪达唑仑或丙泊酚泵入（ICU）","病因治疗：颅内占位或皮质发育不良（手术评估）、感染（抗感染）、代谢性疾病（饮食与药物治疗）、遗传学诊断指导精准治疗","生酮饮食：药物难治性癫痫（尤其婴幼儿）可试用（营养师与专科指导）","手术治疗：药物难治性局灶性癫痫（明确致痫灶）可行手术（术前评估：视频脑电、MRI、PET与功能定位）","共病管理：认知与行为问题（注意力缺陷、学习困难）、情绪障碍与睡眠障碍需同步评估与干预","急性期安全与护理：发作时保护气道与安全（防外伤与误吸），避免诱因（睡眠不足、发热、闪光刺激、停药）","随访与减药：定期评估发作控制、药物不良反应与脑电图；无发作2～5年且脑电图正常者可考虑缓慢减药（专科评估，脑电图监测）"],"management":["发作观察与记录：详细记录发作时间、形式、持续时间与发作后状态（鼓励家长录像，对分型与用药极有价值）","急性发作护理：侧卧防误吸、移开危险物品、不强行按压肢体或塞入物品、记录时间，超过5分钟按持续状态处理","用药管理：按时按量给药（不可漏服）、观察药物不良反应（嗜睡、皮疹、肝功能异常、行为改变）、监测血药浓度","安全防护：避免游泳、登高与骑车等危险活动（未控制者）、洗澡用淋浴、避免独处，家庭与学校安全教育","诱因管理：保证充足睡眠、发热及时退热（发热可诱发发作）、避免闪光刺激（光敏性癫痫）与过度疲劳","心理与教育支持：减轻患儿与家长焦虑与病耻感、与学校沟通（发作处理与用药管理）、评估学习与行为问题","宣教：不可自行停药或减量（可诱发持续状态）、复发与不良反应及时就诊、按时随访与脑电图复查、疫苗接种（按医嘱，一般可接种）"],"notes":["儿童癫痫诊断的关键是详细发作史与视频记录（家长录像价值极高），脑电图与MRI为辅助","抗癫痫药单药起始、规律长期服用；不可自行停药或漏服（可诱发惊厥持续状态）","惊厥持续状态是急症：5分钟内未控制应积极用药，一线地西泮（缓慢静推监测呼吸）","药物难治性癫痫应尽早评估手术或生酮饮食（尤其婴幼儿与结构性病因）","热性惊厥与癫痫不同（多为自限性）；但复杂热性惊厥与癫痫家族史者需随访"],"emergency":["发作持续>5分钟或反复发作意识不恢复（惊厥持续状态）→ 立即地西泮 0.3～0.5mg/kg 缓慢静推（监测呼吸）→ 二线负荷药","发作后呼吸抑制或发绀 → 立即吸氧、清理气道，必要时复苏囊正压通气","发作伴发热与颈抵抗（颅内感染）→ 抗感染+评估腰穿（先评估颅压）","发作伴低血糖（指尖血糖低）→ 立即静推10%葡萄糖 2ml/kg","发作后一侧肢体无力持续（Todd麻痹）或意识不恢复 → 影像评估（排除卒中与占位）"],"pinyin":"etdx","icd10":"G40.9","physical_exam":["生命体征：体温（发热诱因）、心率、呼吸、血压、血氧","意识与神经系统：发作后意识状态、瞳孔、肢体肌力与反射、病理反射","头面部与皮肤：头围（婴幼儿）、面部血管瘤（Sturge-Weber）、皮肤色素斑（结节性硬化：叶状白斑、鲨鱼皮斑）","脊柱与四肢：脊柱畸形、肢体不对称（偏瘫）、运动发育（婴幼儿）","心肺：心律与心音（心源性晕厥鉴别）","生长发育：身高体重与发育里程碑（发育迟缓提示病因）","发作类型体征：发作后舌咬伤、尿失禁与外伤（支持癫痫发作）"],"lab_tests":["脑电图（含睡眠与长程视频脑电）：痫样放电与发作类型评估（必要时24小时监测）","头颅MRI（首选）：皮质发育不良、肿瘤、海马硬化与围产期损伤","血生化+血糖+电解质（钙、钠、镁）+血氨+乳酸：代谢性病因与可逆因素（尤其婴幼儿）","抗癫痫药物血药浓度：疗效不佳或疑中毒时（丙戊酸、卡马西平、苯巴比妥）","肝功能+血常规+凝血功能：抗癫痫药不良反应监测（丙戊酸致肝损与血小板减少）","遗传学检查（基因panel/全外显子测序）：难治性癫痫与发育迟缓者","腰椎穿刺（疑颅内感染/代谢病）：脑脊液检查"],"nursing":["发作护理：侧卧、移开危险物品、勿强行按压或塞入物品、记录发作时间与表现（必要时录像），>5分钟按持续状态处理","用药护理：按时按量给药（不可漏服）、观察不良反应（嗜睡、皮疹、行为改变、肝功能异常），监测血药浓度","安全防护：床档保护、避免独处与危险活动（游泳、登高）、洗澡用淋浴、佩戴医疗警示手环","诱因管理：保证充足睡眠、发热及时退热、避免闪光刺激与过度疲劳、发作日记记录诱因","心理与教育支持：减轻病耻感与焦虑、与学校沟通（发作处理与用药）、评估学习与行为问题","宣教：不可自行停药或减量（诱发持续状态）、发作处理（保护气道与安全）、按时随访与脑电图复查、疫苗接种按医嘱"],"diet":["均衡饮食，规律进餐（避免低血糖诱发发作）；保证充足水分","生酮饮食（药物难治性癫痫，尤其婴幼儿）：高脂、低碳水、适量蛋白（营养师与专科严格指导，需监测生长与血脂）","避免含酒精饮料与大量咖啡因（可能影响发作阈值与药物代谢）","抗癫痫药（丙戊酸）治疗者注意肝功能，避免高脂饮食加重肝负担；补充钙与维生素D","避免漏餐与暴饮暴食；发作控制不佳者避免独自进食（误吸风险）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1437},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"c91e4cb8ea2a12881f2a10503390c6224ede30d85837a945e076e3656d1dbcee","pinyin":"ertongdianxian","initials":"etdx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","全面强直-阵挛发作：意识丧失、四肢强直抽动、口吐白沫、尿失禁、发作后嗜睡\\n失神发作：短暂意识中断（数秒）、凝视、正在进行的活动停止（易被误认为走神）\\n局灶性发作：局部抽动或感觉异常、可伴意识障碍与自动症（咂嘴、摸索）\\n肌阵挛/失张力发作：突然点头、肢体抖动或跌倒\\n婴儿痉挛症：成串的点头、弯腰与四肢屈曲（婴儿期，需尽早治疗）",60],["摘要","儿童癫痫是由脑神经元异常同步放电引起的慢性反复发作性疾病，病因包括遗传、围产期损伤、颅内感染、脑发育异常与代谢性疾病。发作类型多样（局灶性、全面性、失神、肌阵挛等），诊断依靠病史（发作视频）、脑电图与影像学。治疗以抗癫痫药物单药起始、规律长期服用为原则。",30],["疾病编码","G40.9",30],["原首字母","etdx",60]]},{"id":"orders-a0acdccaca9b49fb26f6","key":"v1-c9ccc21dfe2a3058|orders-a0acdccaca9b49fb26f6","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"妊娠期肝内胆汁淤积症","category":"妇产科","raw":{"name":"妊娠期肝内胆汁淤积症","category":"妇产科","summary":"妊娠期肝内胆汁淤积症（ICP）是妊娠中晚期特有的肝脏疾病，以皮肤瘙痒与血清胆汁酸升高为特征（胆汁酸≥10μmol/L），可致胎儿窘迫、早产、羊水污染与死胎（胆汁酸≥40μmol/L风险显著增加）。治疗以熊去氧胆酸为主，重点在于胎儿监测与适时终止妊娠。","symptoms":["皮肤瘙痒（首发且主要症状，多始于手掌与足底，夜间加重，无皮疹）","黄疸（约10%～20%出现，多在瘙痒后1～4周）","尿色加深、大便颜色变浅（胆汁淤积）","抓痕与皮肤损伤（因瘙痒搔抓）","胎儿相关：胎动异常、胎心异常、羊水污染（胆汁酸高者风险增加）"],"diagnosis":["血清总胆汁酸（关键指标，≥10μmol/L为诊断标准；≥40μmol/L为重度）：空腹测定，每周复查","肝功能：ALT/AST轻中度升高、胆红素升高（黄疸者）、ALP升高（妊娠期本身升高需谨慎解读）","排除其他肝病：病毒性肝炎标志物、肝胆超声（排除胆结石与胆道梗阻）、自身免疫抗体（必要时）","凝血功能：重度ICP或拟手术者（维生素K吸收障碍）","胎儿监测：胎心监护（NST）、超声（胎儿生长、羊水量）、脐动脉血流（每周或按病情）","瘙痒程度评估（视觉模拟评分）：疗效评价参考","鉴别诊断：妊娠期急性脂肪肝、HELLP综合征、妊娠期肝损（病毒性肝炎、药物性）、妊娠瘙痒性荨麻疹性丘疹斑块（PUPPP）"],"infusion":["⚠️ 以口服熊去氧胆酸为主，静脉用药用于重症与手术前准备！","方案1（保肝退黄，重症或口服不耐受）：","用法：腺苷蛋氨酸 1g + 5%葡萄糖 250ml 静滴 qd（可改善瘙痒与生化指标）；还原型谷胱甘肽 1.2g 静滴 qd","方案2（维生素K补充，凝血功能异常或术前）：","用法：维生素K1 10mg 肌注 qd（连用3天，复查凝血功能）","方案3（促胎肺成熟，<37周需终止妊娠者）：","用法：地塞米松 6mg 肌注 q12h×4次（24～34周，48小时内）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案4（分娩期与支持）：","用法：0.9%氯化钠/葡萄糖 静滴（补液与维持内环境）；缩宫素按产科指征使用；产后出血预防（缩宫素与前列腺素类）","📌 熊去氧胆酸是一线治疗（口服为主）；重度ICP（胆汁酸≥40μmol/L）或≥36～37周应终止妊娠；产程中密切监测胎心（胎儿窘迫风险高）。"],"oral_medication":["⚠️ 熊去氧胆酸是ICP首选治疗（改善瘙痒与生化指标）：","药物1（熊去氧胆酸，一线）：","用法：熊去氧胆酸 15mg/kg/日 分2～3次口服（按胆汁酸与瘙痒调整，可加量至 20～25mg/kg/日）","药物2（止痒）：","用法：考来烯胺 4g tid（与其他药物间隔4小时）；或 西替利嗪 10mg qn（妊娠期相对安全）；润肤剂与炉甘石洗剂外用〔调 ★ 肾功能不全必须减量；老年减量〕","药物3（辅助保肝与维生素）：","用法：腺苷蛋氨酸肠溶片 500mg bid；维生素K1 10mg qd（口服，凝血异常或拟手术者）；复合维生素B 2片 tid","药物4（产后与随访）：","用法：产后继续熊去氧胆酸 1～2周（多数产后瘙痒与胆汁酸迅速缓解）；口服避孕药避免使用（可加重胆汁淤积）","📌 ICP产后多在数天内缓解（如持续需排查其他肝病）；再次妊娠复发率高达40%～70%（需早期监测胆汁酸）。"],"treatment":["药物治疗：熊去氧胆酸（一线，改善瘙痒与生化）± 腺苷蛋氨酸；止痒对症（考来烯胺、抗组胺药）","胎儿监测（关键）：每周胎心监护（NST）与超声（胎儿生长、羊水、脐血流）；重度ICP（胆汁酸≥40μmol/L）需更密切监测（每周2次或住院）","终止妊娠时机：轻度ICP可在37～38周终止；重度（胆汁酸≥40μmol/L）或≥36周建议终止；出现胎儿窘迫、胎心异常立即终止","分娩方式：以产科指征决定（ICP本身非剖宫产绝对指征，但重度或胎心异常者多需剖宫产）","产程管理：持续胎心监护、建立静脉通路、做好新生儿抢救准备（必要时儿科到场）","产后处理：产后继续熊去氧胆酸1～2周、监测肝功能与胆汁酸至正常；产后出血预防","并发症处理：早产（促胎肺成熟）、胎儿窘迫（立即终止妊娠）、产后出血（宫缩剂与止血措施）","随访与宣教：产后6周复查肝功能与胆汁酸；告知再次妊娠复发风险（早期监测）、避免口服避孕药与雌激素"],"management":["瘙痒与黄疸观察：评估瘙痒程度（夜间加重）与黄疸变化，记录抓痕与皮肤破损（防感染）","胎动与胎心监测：指导每日胎动计数（异常立即就诊）、按时胎心监护与超声检查","用药护理：熊去氧胆酸按时服用并观察疗效（瘙痒与胆汁酸改善）；维生素K与考来烯胺按医嘱（药物间隔）","皮肤护理：温水清洁、避免搔抓（剪短指甲）、润肤剂与炉甘石洗剂外用、穿宽松棉质衣物","饮食与营养：低脂饮食、少量多餐、补充脂溶性维生素；保证足够热量与蛋白","终止妊娠准备：按医嘱安排住院与分娩时机、术前准备（禁食、备血、促胎肺成熟）","宣教：ICP对胎儿风险（死胎与早产）需重视监测、产后随访、再次妊娠早期监测胆汁酸、避免雌激素类药物"],"notes":["ICP诊断标准为血清总胆汁酸≥10μmol/L伴皮肤瘙痒（无皮疹），产后迅速缓解可支持诊断","胆汁酸≥40μmol/L为重度，胎儿窘迫与死胎风险显著升高，需密切监测并适时终止妊娠","熊去氧胆酸是一线治疗（改善瘙痒与生化指标，但不能完全消除胎儿风险）","ICP是排他性诊断：需排除病毒性肝炎、妊娠期急性脂肪肝、HELLP综合征与胆道疾病","再次妊娠复发率高（40%～70%），应早期监测胆汁酸；避免口服避孕药与雌激素"],"emergency":["胎动明显减少或胎心监护异常（胎儿窘迫）→ 立即产科评估、左侧卧位吸氧，必要时紧急剖宫产","瘙痒剧烈伴黄疸迅速加深与凝血异常 → 评估重症ICP与肝功能，补充维生素K并准备终止妊娠","妊娠晚期出现上腹痛、恶心呕吐与黄疸（妊娠期急性脂肪肝/HELLP）→ 急诊肝功能、凝血与血小板，紧急终止妊娠","产后出血（宫缩乏力）→ 立即宫缩剂与止血措施、输血准备","早产临产（规律宫缩、宫口扩张）→ 促胎肺成熟+抑制宫缩（按孕周），产科处理"],"pinyin":"rsqgnszyjz","icd10":"O26.6","physical_exam":["生命体征：血压（子痫前期鉴别）、心率、体温、体重","皮肤：瘙痒抓痕（手掌与足底为主）、黄疸程度、皮疹（排除PUPPP）","腹部（产科）：宫高与腹围（胎儿生长）、胎心（多普勒，110～160次/分）、宫缩情况","肝区：肝区叩击痛与肝大小（排除其他肝病）","胎儿评估：胎动计数、胎心监护结果与超声（羊水量与脐血流）","其他：下肢水肿（胆汁淤积/子痫前期）、尿色（深黄）"],"lab_tests":["血清总胆汁酸（关键，每周复查）：≥10μmol/L诊断，≥40μmol/L为重度","肝功能（ALT、AST、胆红素、ALP、GGT）：ALT轻中度升高与胆红素升高（黄疸者）","凝血功能（PT/APTT）+血小板：重度ICP与拟手术者（维生素K缺乏风险）","病毒性肝炎标志物+肝胆超声：排除病毒性肝炎与胆道梗阻","胎儿监测：胎心监护（NST，每周或更频）、超声（胎儿生长、羊水与脐动脉血流）","总胆汁酸与肝功能产后复查（产后6周）：确认恢复（不恢复需排查其他肝病）","必要时自身免疫抗体（ANA、AMA）：排除自身免疫性肝病"],"nursing":["瘙痒护理：温水清洁、避免搔抓（剪短指甲、戴棉手套夜间）、润肤剂与炉甘石洗剂外用、保持皮肤完整防感染","胎动与胎心监测：指导每日固定时间数胎动（异常立即就诊）、按时配合胎心监护与超声检查","用药护理：熊去氧胆酸按时服用并记录疗效（瘙痒与胆汁酸变化）；考来烯胺与其他药物间隔4小时；维生素K按时给予","饮食护理：低脂、高蛋白、高维生素饮食，少量多餐；补充脂溶性维生素","分娩准备与产程护理：按医嘱入院待产、术前准备（禁食、备血）、产程中持续胎心监护与静脉通路、备好新生儿抢救","宣教：ICP对胎儿的风险与监测重要性、产后随访、再次妊娠早期监测、避免口服避孕药与雌激素类药物"],"diet":["低脂饮食（减少胆汁淤积负担），避免油炸、肥肉与浓汤","高蛋白、高维生素（新鲜蔬果），补充脂溶性维生素（A、D、E、K）","少量多餐（每日5～6餐），避免过饱与空腹时间过长","充足水分摄入；避免辛辣刺激与酒类","合并子痫前期者限盐；保证足够热量满足妊娠需求"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1438},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"d0ab66060a8ddd60c3dd3bc00414febb35775fe8b480a6f0db8382f89110cf98","pinyin":"renshenqiganneidanzhiyujizheng","initials":"rsqgndzyjz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤瘙痒（首发且主要症状，多始于手掌与足底，夜间加重，无皮疹）\\n黄疸（约10%～20%出现，多在瘙痒后1～4周）\\n尿色加深、大便颜色变浅（胆汁淤积）\\n抓痕与皮肤损伤（因瘙痒搔抓）\\n胎儿相关：胎动异常、胎心异常、羊水污染（胆汁酸高者风险增加）",60],["摘要","妊娠期肝内胆汁淤积症（ICP）是妊娠中晚期特有的肝脏疾病，以皮肤瘙痒与血清胆汁酸升高为特征（胆汁酸≥10μmol/L），可致胎儿窘迫、早产、羊水污染与死胎（胆汁酸≥40μmol/L风险显著增加）。治疗以熊去氧胆酸为主，重点在于胎儿监测与适时终止妊娠。",30],["疾病编码","O26.6",30],["原首字母","rsqgnszyjz",60]]},{"id":"orders-3fd7b736b960026f6483","key":"v1-c9ccc21dfe2a3058|orders-3fd7b736b960026f6483","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"妊娠合并甲状腺功能减退","category":"妇产科","raw":{"name":"妊娠合并甲状腺功能减退","category":"妇产科","summary":"妊娠合并甲状腺功能减退（甲减）包括临床甲减（TSH升高+FT4降低）与亚临床甲减（TSH升高+FT4正常），可致流产、早产、妊娠期高血压、胎盘早剥与胎儿神经智力发育损害。治疗以左甲状腺素替代为主，妊娠期需求增加（约增加20%～30%），需尽早治疗并密切监测TSH。","symptoms":["乏力、畏寒、嗜睡、反应迟钝、记忆力下降","体重增加异常（超过妊娠生理性增加）、便秘、皮肤干燥与脱发","水肿（黏液性水肿）、声音嘶哑、心率缓慢","亚临床甲减可无明显症状（依靠筛查发现）","胎儿影响：胎动减少、胎儿生长受限、早产与低出生体重"],"diagnosis":["甲状腺功能（TSH、FT4、FT3）+甲状腺自身抗体（TPOAb、TgAb）：妊娠期参考值按孕周（早孕期TSH上限2.5mIU/L，中晚期3.0mIU/L）","临床甲减：TSH升高+FT4降低；亚临床甲减：TSH升高+FT4正常；低甲状腺素血症：TSH正常+FT4降低","甲状腺超声：甲状腺形态、结节与自身免疫性甲状腺炎表现","血常规+血脂（胆固醇升高）+肌酶（肌酶升高）：甲减相关异常","产科评估：胎儿生长超声、胎心监护与胎动计数","鉴别诊断：妊娠期一过性甲减（hCG相关）、中枢性甲减（TSH正常或降低伴FT4降低）与碘缺乏","产后评估：产后6周复查甲状腺功能（产后甲状腺炎风险，尤其TPOAb阳性者）"],"infusion":["⚠️ 治疗以口服左甲状腺素为主，静脉用药用于并发症！","","方案1（左甲状腺素替代，核心治疗）：","  用法：左甲状腺素钠 起始 1.6μg/kg/日（或按病情25～50μg qd起），晨起空腹（早餐前30～60分钟）服用；妊娠期需求增加，每2～4周复查TSH调整剂量（目标TSH：早孕<2.5mIU/L、中晚孕<3.0mIU/L）","","方案2（重度甲减伴黏液性水肿或并发症）：","  用法：左甲状腺素钠 静推 或（NS 100ml 或 5%GS 100ml）静滴（按体重，仅重症不能口服者）；氢化可的松 100mg 静滴（合并肾上腺功能不全时，先补糖皮质激素）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","","方案3（妊娠期高血压/子痫前期并发症）：","  用法：拉贝洛尔 20～40mg 静推（降压）或 尼卡地平泵入；硫酸镁 4～5g（NS 100ml 或 5%GS 100ml）静滴后 1～2g/h 维持（防抽搐，监测腱反射与呼吸）","","方案4（贫血与营养支持）：","  用法：蔗糖铁 100mg 静滴（缺铁性贫血）；0.9%氯化钠 静滴（补液）；维生素D 与钙剂（按需）","","📌 左甲状腺素需空腹服用并与铁剂、钙剂间隔4小时；妊娠期剂量通常需增加20%～30%（确诊妊娠后立即复查并加量）；不可与抗甲状腺药同用（除非特殊病例）。"],"oral_medication":["⚠️ 左甲状腺素替代是核心，需按TSH动态调整：","药物1（左甲状腺素钠，一线）：","用法：左甲状腺素钠 50～100μg qd（按孕前剂量与TSH调整；妊娠后立即增加20%～30%——每周增加2次剂量法）；晨起空腹服，早餐前30～60分钟","药物2（补铁与钙，妊娠常规）：","用法：琥珀酸亚铁 0.1g bid（与左甲状腺素间隔4小时）；碳酸钙D3 600mg qd（间隔4小时）〔调 ★ 铁负荷过多禁用；★ 与四环素/喹诺酮/左甲状腺素间隔2小时〕","药物3（碘补充，碘缺乏地区）：","用法：含碘制剂（如碘化钾）按医嘱；避免过量碘（可致胎儿甲减）","药物4（产后与随访）：","用法：产后左甲状腺素剂量恢复至孕前水平（产后6周复查TSH调整）；甲状腺功能正常者产后仍需随访（产后甲状腺炎）","📌 左甲状腺素空腹服用（吸收受食物与铁钙影响）；妊娠期每2～4周复查TSH直至稳定（之后每4～6周）；不可自行停药。"],"treatment":["左甲状腺素替代治疗：确诊后立即开始（起始50～100μg qd口服），妊娠期需求增加20%～30%，按TSH个体化调整","监测计划：妊娠前半期每4周（或每2～4周）复查TSH，后半期每4～6周；产后6周复查","产科监测：胎儿生长超声（生长受限）、胎心监护、胎动计数；合并妊娠期高血压者加强监测","并发症处理：流产与早产（黄体支持如黄体酮、抑制宫缩）、妊娠期高血压（拉贝洛尔或硝苯地平降压+硫酸镁）、贫血（补铁）、胎盘早剥（急诊处理）","碘营养管理：适量碘摄入（避免缺碘与过量碘），碘缺乏地区补充含碘制剂（按医嘱）","分娩期管理：一般可阴道分娩；合并重度子痫前期或胎儿窘迫按产科指征剖宫产；产程中监测胎心","产后管理：产后甲状腺素剂量恢复孕前水平，产后6周复查甲状腺功能（产后甲状腺炎发生率约5%～10%）","宣教：妊娠期规律用药与复查、再次妊娠前优化TSH（目标<2.5mIU/L）、避免自行停药、新生儿甲状腺功能筛查"],"management":["用药依从性管理：强调左甲状腺素不可停药（胎儿神经发育依赖母体甲状腺激素）、空腹服用与间隔要求（铁剂/钙剂间隔4小时）","甲状腺功能监测：按医嘱每2～4周复查TSH并调整剂量，记录结果与剂量变化","产科监测：胎动计数指导、胎心监护与超声（胎儿生长与羊水）、妊娠期高血压筛查（血压与尿蛋白）","症状观察：乏力、畏寒、水肿、便秘与心率变化（甲减未控制），异常报告并复查甲状腺功能","饮食与营养：适量碘摄入（避免过量海带紫菜）、补铁与钙（与左甲状腺素间隔）、均衡营养控制体重","心理护理：甲减影响情绪与认知，妊娠期焦虑常见，提供心理支持与解释治疗安全性","宣教：按时服药与复查、产后6周复查、再次妊娠前就诊优化甲状腺功能、新生儿出生后甲状腺功能筛查"],"notes":["妊娠期甲减需尽早治疗（胎儿神经发育依赖母体甲状腺激素，尤其早孕期）","妊娠期左甲状腺素需求增加20%～30%（确诊妊娠后立即加量并复查TSH）","妊娠期TSH参考值按孕周制定（早孕<2.5mIU/L、中晚孕<3.0mIU/L），不可用非孕期标准判断","左甲状腺素空腹服用并与铁剂、钙剂间隔4小时（影响吸收）","产后甲状腺炎（多发生于产后6个月内）常见于TPOAb阳性者，需产后6周复查并随访"],"emergency":["重度甲减伴意识障碍、低体温与低血压（黏液性水肿昏迷）→ 立即左甲状腺素静脉给药+氢化可的松+保温与循环支持，转ICU","胎动消失或胎心异常（胎儿窘迫）→ 立即产科评估与处理（可能紧急终止妊娠）","妊娠期高血压伴头痛视力模糊与抽搐（子痫）→ 硫酸镁+降压+产科急会诊","早产临产（规律宫缩）→ 促胎肺成熟+抑制宫缩，产科处理","严重贫血伴心悸气促（血红蛋白显著降低）→ 补铁/输血并评估分娩时机"],"pinyin":"rsHbjzxgnjt","icd10":"O99.2","physical_exam":["生命体征：血压（妊娠期高血压）、心率（缓慢提示未控制）、体温（低体温）、体重","甲状腺：甲状腺大小、质地与结节（自身免疫性甲状腺炎可弥漫肿大）","一般情况：贫血貌、表情淡漠、反应迟钝、声音嘶哑","皮肤与毛发：皮肤干燥、脱发、非凹陷性水肿（黏液性水肿）","产科：宫高与腹围（胎儿生长）、胎心、宫缩与胎动","心脏：心率缓慢、心音低钝、心包积液（重度甲减）","神经系统：腱反射迟钝（甲减特征）、记忆力与情绪评估"],"lab_tests":["甲状腺功能（TSH、FT4、FT3）：妊娠期按孕周参考值判断（每2～4周复查直至稳定）","甲状腺自身抗体（TPOAb、TgAb）：自身免疫性甲状腺炎诊断与产后甲状腺炎风险","血常规（贫血）+铁代谢+血脂+肌酶：甲减相关异常评估","尿常规+尿蛋白+血压监测：妊娠期高血压筛查","胎儿超声（生长、羊水）+胎心监护：胎儿状况评估（生长受限风险）","碘营养评估（必要时尿碘）：碘缺乏或过量评估","产后6周甲状腺功能复查：产后甲状腺炎与剂量调整依据"],"nursing":["用药护理：指导左甲状腺素晨起空腹服用（早餐前30～60分钟）、与铁剂/钙剂间隔4小时；强调不可停药（胎儿发育依赖）","甲状腺功能监测配合：按时复查TSH并记录剂量调整，异常结果及时报告","产科监测：指导胎动计数、配合胎心监护与胎儿超声、监测血压与尿蛋白（妊娠期高血压筛查）","症状观察：乏力、畏寒、水肿、便秘、心率变化与情绪改变，异常报告","饮食护理：适量碘（避免海带紫菜过量）、补铁与钙（间隔用药）、均衡营养与体重管理","心理护理与宣教：解释甲减治疗对胎儿的重要性、缓解焦虑、产后6周复查与新生儿筛查、再次妊娠前就诊优化TSH"],"diet":["适量碘摄入：使用加碘盐，避免大量海带、紫菜与含碘保健品（过量碘可致胎儿甲减）","左甲状腺素空腹服用并与富铁（红肉、动物肝脏）、高钙（牛奶、钙片）食物/药物间隔4小时","均衡营养：高蛋白、高维生素、适量碳水；避免过度限制热量（影响胎儿生长）","便秘者增加膳食纤维与水分；贫血者增加含铁食物与维生素C","避免生食与未煮熟食物（妊娠期感染风险）；避免酒精与过量咖啡因"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1439},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"cc96504ae850ed17b324228ab93a352a1bbc623dd51bc45b0e752adceb8d1ed1","pinyin":"renshenhebingjiazhuangxiangongnengjiantui","initials":"rshbjzxgnjt","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、畏寒、嗜睡、反应迟钝、记忆力下降\\n体重增加异常（超过妊娠生理性增加）、便秘、皮肤干燥与脱发\\n水肿（黏液性水肿）、声音嘶哑、心率缓慢\\n亚临床甲减可无明显症状（依靠筛查发现）\\n胎儿影响：胎动减少、胎儿生长受限、早产与低出生体重",60],["摘要","妊娠合并甲状腺功能减退（甲减）包括临床甲减（TSH升高+FT4降低）与亚临床甲减（TSH升高+FT4正常），可致流产、早产、妊娠期高血压、胎盘早剥与胎儿神经智力发育损害。治疗以左甲状腺素替代为主，妊娠期需求增加（约增加20%～30%），需尽早治疗并密切监测TSH。",30],["疾病编码","O99.2",30],["原首字母","rsHbjzxgnjt",60]]},{"id":"orders-c8678dd4efaf3be1f296","key":"v1-c9ccc21dfe2a3058|orders-c8678dd4efaf3be1f296","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"产后抑郁症","category":"妇产科","raw":{"name":"产后抑郁症","category":"妇产科","summary":"产后抑郁症是分娩后出现的以持续情绪低落、兴趣减退、疲劳与焦虑为核心症状的精神障碍，多在产后4～6周内起病（可延至1年），发生率约10%～15%。与产后情绪低落（baby blues，产后3～5天短暂）不同，产后抑郁需≥2周的症状并影响功能，严重者可出现伤害婴儿或自杀意念（需紧急干预）。","symptoms":["持续情绪低落、易哭泣、兴趣与愉悦感丧失（≥2周）","疲劳与精力不足（超出产后生理性疲劳）、睡眠障碍（难以入睡或早醒，即使婴儿熟睡）","焦虑与过度担忧婴儿健康、易激惹、注意力不集中","自责与无用感、对婴儿缺乏情感连接或过度焦虑","严重者：伤害婴儿或自杀意念、幻觉与妄想（产后精神病，属急症）"],"diagnosis":["爱丁堡产后抑郁量表（EPDS≥10提示可能抑郁，≥13提示需专业评估；第10题阳性提示自伤风险需立即干预）","精神科评估（DSM-5标准）：症状持续≥2周、功能受损、排除物质与躯体疾病所致","甲状腺功能（TSH、FT4）+血常规+铁代谢：甲减与贫血可致类似症状（须排除）","筛查自伤与伤婴风险：直接询问自杀与伤害婴儿意念（必做，决定干预级别）","评估社会心理因素：婚姻关系、家庭支持、经济压力、婴儿健康问题与既往精神病史","鉴别诊断：产后情绪低落（短暂自限）、产后精神病（起病急、幻觉妄想，需精神科急诊）、焦虑障碍与双相障碍","必要时躯体评估：产后感染、贫血、甲状腺疾病与药物影响"],"infusion":["⚠️ 以心理治疗与口服抗抑郁药为主，静脉用药用于重症与并发症！","","方案1（重症伴拒食/脱水/严重失眠）：","  用法：0.9%氯化钠/葡萄糖 静滴（补液与营养支持）；必要时复合维生素与电解质补充","","方案2（产后精神病或严重自杀/伤婴风险）：","  用法：抗精神病药（奥氮平 5～10mg 肌注/口服 或 氟哌啶醇 5mg 肌注）+ 苯二氮卓类（劳拉西泮 1～2mg 静推，短期）——精神科急会诊，必要时住院（母婴同室或分离评估）","","方案3（甲状腺功能减退相关）：","  用法：左甲状腺素钠 按TSH调整（口服为主）；贫血者蔗糖铁 100mg（NS 100ml（静滴 ≥15 分钟；先做试验剂量））静滴（重度缺铁）","","方案4（营养支持）：","  用法：0.9%氯化钠 静滴；维生素B族与维生素D补充；必要时肠内营养（拒食者）","","📌 产后抑郁的治疗以心理治疗（认知行为治疗/人际心理治疗）与SSRI类抗抑郁药为主；哺乳期用药需权衡（舍曲林与帕罗西汀相对安全）；出现自杀或伤婴意念须立即精神科干预。"],"oral_medication":["⚠️ 哺乳期用药需权衡婴儿安全（优先舍曲林/帕罗西汀）：","药物1（抗抑郁药，SSRI一线）：","用法：舍曲林 50mg qd 起（哺乳期相对安全）或 帕罗西汀 20mg qd；效果不佳可加量或换用文拉法辛；起效需2～4周","药物2（焦虑与失眠短期）：","用法：劳拉西泮 0.5～1mg qn（短期，哺乳期慎用）；或 唑吡坦 5mg qn（短期，按医嘱）","药物3（重症/产后精神病，精神科指导）：","用法：奥氮平 5～10mg qn 或 喹硫平 25～50mg qn（监测嗜睡与代谢）；必要时联合抗抑郁药","药物4（营养与辅助）：","用法：复合维生素B 2片 tid；维生素D 800IU/日；铁剂（贫血者）；omega-3（辅助，证据有限）","📌 抗抑郁药起效需2～4周（需坚持服用），停药需逐渐减量；哺乳期用药应选安全性高的药物并观察婴儿反应（嗜睡、喂养差）。"],"treatment":["心理治疗（一线）：认知行为治疗（CBT）、人际心理治疗（IPT）与支持性心理治疗（轻中度首选）","抗抑郁药：中重度或心理治疗效果不佳者使用SSRI（舍曲林、帕罗西汀等），需2～4周起效并坚持6～12个月（防复发）","社会支持干预：家庭支持、母婴关系干预、育儿支持与同伴支持小组；减轻育儿压力与睡眠剥夺","睡眠干预：保障产妇睡眠（家属分担夜间照护）、睡眠卫生指导","重症与急症处理：产后精神病（抗精神病药+住院）、自杀或伤婴意念（立即精神科急诊与安全监护）","母婴安全评估：评估母婴互动与婴儿安全（必要时由家属临时照护）","内科因素纠正：甲状腺功能减退、贫血与营养不良的纠正","随访与复发预防：产后6周、3个月、6个月随访（EPDS复评）；既往有抑郁史者重点监测，再次妊娠需提前评估"],"management":["情绪与风险筛查：入院与产后访视使用EPDS筛查，直接询问自杀与伤害婴儿意念（每班/每次访视评估）","安全监护：有自伤或伤婴风险者安排家属24小时陪伴、移除危险物品、必要时精神科住院与母婴分离评估","心理护理：倾听与共情、不加评判、正常化其感受（产后情绪波动常见）、鼓励表达与求助","睡眠与休息支持：安排家属分担夜间照护、保障产妇连续睡眠时段（睡眠剥夺加重抑郁）","社会支持动员：评估家庭关系与经济压力、联系社区与心理支持资源、组织同伴支持","用药护理：哺乳期抗抑郁药需观察婴儿反应（嗜睡、喂养差、体重增长）、按时服药与随访调整","宣教：产后抑郁是疾病而非'矫情'、可治疗且预后良好、坚持治疗6～12个月（防复发）、出现自伤或伤婴意念立即求助"],"notes":["产后抑郁与'产后情绪低落'不同：后者产后3～5天出现、2周内自限；产后抑郁持续≥2周且影响功能","EPDS≥13或第10题（自伤意念）阳性需立即专业评估与干预","哺乳期抗抑郁药优先选择舍曲林与帕罗西汀（乳汁浓度低），并观察婴儿反应","产后精神病是精神科急症（起病急、幻觉妄想、伤婴风险高），需立即精神科干预与住院评估","既往抑郁史、孕期焦虑、缺乏家庭支持、婴儿健康问题与经济压力是高危因素（需重点筛查）"],"emergency":["出现自杀意念或计划（EPDS第10题阳性）→ 立即精神科会诊、24小时家属陪伴、移除危险物品、必要时住院","出现伤害婴儿的想法或行为 → 立即母婴分离（由家属/医护照护婴儿）并精神科急诊干预","产后精神病表现（幻觉、妄想、意识混乱、行为紊乱）→ 立即精神科急诊、抗精神病药与住院治疗","拒食拒饮伴脱水与电解质紊乱 → 静脉补液与营养支持，精神科评估","严重失眠伴兴奋躁动 → 短期苯二氮卓类/抗精神病药（精神科指导）并加强监护"],"pinyin":"chyyz","icd10":"F53.0","physical_exam":["生命体征：血压、心率、体温、体重（营养与甲减评估）","精神状态：情绪（低落/易激惹）、言语与思维、注意力、自知力","自杀与伤婴风险评估：意念、计划与准备行为（必查）","甲状腺与贫血体征：甲状腺肿大、皮肤干燥、结膜苍白、心率变化","产科评估：子宫复旧、恶露（产后感染）、会阴或腹部伤口愈合、乳房（哺乳情况）","睡眠与疲劳评估：入睡困难、早醒与睡眠时长","母婴互动评估：对婴儿的情感连接、照护能力与焦虑程度"],"lab_tests":["爱丁堡产后抑郁量表（EPDS）：筛查与随访复评（≥13需专业评估）","甲状腺功能（TSH、FT4）：甲减致抑郁样症状（产后甲状腺炎常见）","血常规+铁代谢：贫血与产后疲劳评估","电解质+白蛋白+血糖：拒食与营养不良评估","维生素D+维生素B12+叶酸：营养相关情绪影响评估","必要时性激素水平（雌激素）：产后激素波动评估（不作常规）","精神科量表（PHQ-9、GAD-7）与自杀风险评估工具：专业评估配套"],"nursing":["情绪与风险筛查：每次访视使用EPDS并直接询问自伤与伤婴意念，阳性者立即报告并加强监护","安全护理：有风险者安排家属24小时陪伴、移除危险物品、必要时母婴分离并由他人照护婴儿","心理护理：倾听共情、不加评判、正常化情绪体验、鼓励表达与求助、避免说教与否定感受","睡眠与休息支持：协调家属分担夜间照护，保障产妇连续睡眠（睡眠剥夺显著加重症状）","用药护理（哺乳期）：观察婴儿嗜睡与喂养情况、记录情绪与不良反应，按时随访调整","母婴互动支持：指导喂养与照护技巧、肯定母亲能力、必要时安排母婴关系干预","宣教：产后抑郁是疾病可治、坚持治疗6～12个月防复发、家庭支持的重要性、出现危险念头立即求助（提供心理热线与就诊途径）"],"diet":["均衡营养：高蛋白、高维生素与充足热量（哺乳期需求增加）","富含ω-3脂肪酸食物（深海鱼）与B族维生素（全谷物、绿叶蔬菜）有助情绪调节","补充铁剂与维生素D（贫血与缺乏者）；多饮水（哺乳期）","避免过量咖啡因（加重焦虑与失眠）与酒精（影响情绪与哺乳）","规律进餐、少量多餐，避免因情绪低落而漏餐或暴食"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1440},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5f0f65d7db0a0cc0ee8526dd774f546f468aacd34f12cf8cfae573080786be9f","pinyin":"chanhouyiyuzheng","initials":"chyyz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","持续情绪低落、易哭泣、兴趣与愉悦感丧失（≥2周）\\n疲劳与精力不足（超出产后生理性疲劳）、睡眠障碍（难以入睡或早醒，即使婴儿熟睡）\\n焦虑与过度担忧婴儿健康、易激惹、注意力不集中\\n自责与无用感、对婴儿缺乏情感连接或过度焦虑\\n严重者：伤害婴儿或自杀意念、幻觉与妄想（产后精神病，属急症）",60],["摘要","产后抑郁症是分娩后出现的以持续情绪低落、兴趣减退、疲劳与焦虑为核心症状的精神障碍，多在产后4～6周内起病（可延至1年），发生率约10%～15%。与产后情绪低落（baby blues，产后3～5天短暂）不同，产后抑郁需≥2周的症状并影响功能，严重者可出现伤害婴儿或自杀意念（需紧急干预）。",30],["疾病编码","F53.0",30],["原首字母","chyyz",60]]},{"id":"orders-3aace8d0e56d00ee290b","key":"v1-c9ccc21dfe2a3058|orders-3aace8d0e56d00ee290b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"妊娠期贫血","category":"妇产科","raw":{"name":"妊娠期贫血","category":"妇产科","summary":"妊娠期贫血指孕妇血红蛋白<110g/L（妊娠中晚期<105g/L），以缺铁性贫血最常见（占95%），其次为巨幼细胞贫血（叶酸/B12缺乏）与地中海贫血。贫血增加早产、低出生体重、胎儿生长受限与产后出血风险，需在妊娠期常规筛查并规范补铁治疗。","symptoms":["乏力、头晕、活动后心悸气短、注意力不集中","面色与结膜苍白、指甲苍白脆薄、口角炎与舌炎（缺铁）","重度贫血：心率增快、心界扩大（贫血性心脏病）、下肢水肿、呼吸困难","重度缺铁：异食癖（如嗜食泥土或冰）、吞咽困难（Plummer-Vinson综合征）","巨幼细胞贫血：舌面光滑（牛肉舌）、四肢麻木与感觉异常（B12缺乏）"],"diagnosis":["血常规（血红蛋白、MCV、MCH）：妊娠期贫血诊断（<110g/L，中晚期<105g/L）与形态分类","铁代谢（血清铁、铁蛋白、总铁结合力、转铁蛋白饱和度）：缺铁性贫血诊断（铁蛋白<20ng/ml提示缺铁；<30ng/ml提示铁储备不足）","维生素B12+叶酸+同型半胱氨酸：巨幼细胞贫血诊断","血红蛋白电泳+地中海贫血基因检测（MCV降低而铁代谢正常者）：地中海贫血筛查（南方地区高发）","粪便隐血+寄生虫检查（必要时）：失血与寄生虫（钩虫）病因","产科评估：胎儿生长超声、胎心监护与胎动计数（贫血影响胎儿）","产后评估：产后出血风险评估（贫血是危险因素）与产后复查"],"infusion":["⚠️ 中重度贫血或口服不耐受者需静脉铁剂，重度贫血需输血！","","方案1（静脉铁剂，中重度贫血或口服不耐受）：","  用法：蔗糖铁 100～200mg + 0.9%氯化钠 100ml 静滴（>30分钟，每周1～3次，累计总剂量按铁缺乏计算，常用1000mg）；或 右旋糖酐铁（按说明书）","","方案2（重度贫血输血，Hb<70g/L或有症状）：","  用法：红细胞悬液 1～2U 缓慢静滴（孕期输注需监测生命体征与胎儿，避免容量负荷）；目标Hb 80～100g/L","","方案3（巨幼细胞贫血，重度或吸收障碍）：","  用法：维生素B12 1000μg 肌注 qd×1周后改每周1次；叶酸 5mg 口服/（NS 100ml 或 5%GS 100ml）静滴（注意先补B12）","","方案4（分娩期与支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；分娩期备血（贫血者产后出血耐受差）；产后出血预防（缩宫素）","","📌 静脉铁剂需缓慢输注并观察过敏反应（低血压、皮疹、呼吸困难）；Hb<70g/L或有症状者输血；产后应继续补铁3～6个月以恢复储备。"],"oral_medication":["⚠️ 口服铁剂是妊娠期贫血的一线治疗：","药物1（口服铁剂）：","用法：琥珀酸亚铁 0.1g bid～tid（餐间服）或 多糖铁复合物 150mg qd；与维生素C 0.2g 同服促进吸收（避免与钙剂、浓茶、抗酸剂同服，间隔≥2小时）〔调 ★ 铁负荷过多禁用；★ 与四环素/喹诺酮/左甲状腺素间隔2小时〕","药物2（叶酸与B12）：","用法：叶酸 0.4～1mg qd（孕前3个月至孕早期，预防神经管缺陷）；B12缺乏者维生素B12 500μg 肌注 每月1次","药物3（钙与维生素D，妊娠常规）：","用法：碳酸钙D3 600mg qd（与铁剂间隔2小时以上）","药物4（辅助）：","用法：维生素C 0.2g tid（促进铁吸收）；复合维生素（含铁与叶酸，按需）","📌 口服铁剂治疗4周后血红蛋白应上升≥10g/L（否则需评估依从性、吸收障碍或诊断错误）；血红蛋白正常后继续服用3～6个月补足储备铁。"],"treatment":["病因治疗：缺铁（补铁+寻找失血原因）、巨幼（补B12/叶酸）、地中海贫血（遗传咨询，避免盲目补铁）、寄生虫（驱虫治疗）","补铁治疗：口服铁剂为首选，中重度或口服不耐受者静脉铁剂；治疗目标Hb≥110g/L并补足储备","营养与饮食指导：富铁饮食（红肉、动物肝脏、血制品）+维生素C促进吸收；避免浓茶与钙剂干扰","产科监测：胎儿生长超声、胎心监护与胎动计数；重度贫血者评估胎儿生长受限与窘迫风险","分娩期管理：贫血者需评估分娩方式与备血（产后出血耐受差）、产程中监测生命体征与胎儿","产后管理：继续补铁3～6个月、复查血常规；产后出血者积极纠正贫血","并发症处理：贫血性心脏病（心衰）、产后出血（宫缩剂与输血）、感染（贫血降低抵抗力）","宣教：妊娠期规律产检与血常规筛查、按时补铁与叶酸、地中海贫血高发地区孕前筛查（遗传咨询）"],"management":["血常规与铁代谢监测：妊娠期常规筛查（早中晚孕各1次），治疗期间每4周复查血红蛋白与铁代谢","用药护理：口服铁剂餐间服用并与维生素C同服、观察胃肠道反应与黑便（正常现象）；静脉铁剂缓慢输注并观察过敏反应","饮食护理：指导富铁饮食与促进吸收（维生素C）及干扰因素（浓茶、咖啡、钙剂间隔2小时）","产科监测：胎动计数指导、胎心监护与胎儿生长超声、血压与尿蛋白（子痫前期筛查）","症状观察：乏力、心悸、气促与水肿（贫血性心脏病），异常立即报告","分娩准备：贫血者备血与建立静脉通路、产程中监测、产后出血预防与观察","宣教：按时补铁与叶酸、坚持治疗（血红蛋白正常后仍需3～6个月）、地中海贫血筛查与遗传咨询、产后复查"],"notes":["妊娠期贫血以缺铁性最常见（约95%），诊断依据铁蛋白降低（<20ng/ml）","口服铁剂4周后血红蛋白应上升≥10g/L，反应不佳需评估依从性、吸收障碍或诊断（地中海贫血）","血红蛋白正常后仍需继续补铁3～6个月以补足储备铁（防复发）","MCV降低而铁代谢正常者需筛查地中海贫血（南方高发地区孕前筛查与遗传咨询）","贫血产妇产后出血耐受性差，分娩期需备血与积极预防产后出血"],"emergency":["重度贫血伴呼吸困难、心悸与意识改变（Hb<70g/L）→ 立即输注红细胞并吸氧、监护","分娩期大出血伴血压下降（产后出血）→ 立即宫缩剂+止血措施+输血，评估手术","贫血伴急性左心衰（端坐呼吸、肺水肿）→ 吸氧、利尿、缓慢少量输血","静脉铁剂输注中出现低血压、皮疹与呼吸困难（过敏反应）→ 立即停输、肾上腺素/激素/抗组胺药、补液","重度贫血伴胎心异常（胎儿窘迫）→ 产科评估与处理（可能紧急终止妊娠）"],"pinyin":"rsqpx","icd10":"O99.0","physical_exam":["生命体征：心率（代偿性增快）、血压、呼吸（气促）、体温、体重","一般情况：面色与结膜苍白程度、乏力与活动耐量、营养状态","皮肤黏膜：口角炎、舌炎、反甲、皮肤干燥（缺铁）","心脏：心界扩大、心率增快、贫血性收缩期杂音、有无心衰体征","产科：宫高与腹围（胎儿生长）、胎心（110～160次/分）、宫缩与胎动","神经系统：深感觉与振动觉（B12缺乏致亚急性联合变性）、腱反射","下肢：水肿（贫血/子痫前期）、静脉曲张"],"lab_tests":["血常规（血红蛋白、MCV、MCH）+网织红细胞：贫血诊断与形态分类（妊娠期常规筛查）","铁代谢（血清铁、铁蛋白、总铁结合力、TSAT）：缺铁性贫血诊断（铁蛋白<20ng/ml）","维生素B12+叶酸+同型半胱氨酸：巨幼细胞贫血评估","血红蛋白电泳+地中海贫血基因检测：MCV降低而铁正常者（南方高发地区）","粪便隐血+寄生虫（钩虫）检查：失血与寄生虫病因","胎儿超声（生长与羊水）+胎心监护：胎儿状况评估","产后血常规复查+铁代谢：治疗与恢复评估"],"nursing":["用药护理：口服铁剂餐间服用并与维生素C同服、观察胃肠道反应（黑便为正常）；静脉铁剂缓慢输注（>30分钟）并观察过敏反应","饮食指导：富铁食物（红肉、动物肝脏、血制品）搭配维生素C；避免浓茶、咖啡与钙剂同服（间隔2小时）","血常规与产科监测：按时复查血红蛋白与铁代谢；配合胎心监护与胎儿超声、指导胎动计数","症状观察：乏力、心悸、气促与水肿（贫血加重或心衰），异常立即报告","分娩期护理：建立静脉通路与备血、产程中监测生命体征与胎心、产后观察出血（贫血者耐受差）","宣教：按时补铁与叶酸、治疗需持续至产后（补足储备）、地中海贫血筛查与遗传咨询、产后复查血常规"],"diet":["富铁食物：红肉、动物肝脏与血制品、蛋黄、深绿色蔬菜、黑木耳、豆类","促进铁吸收：与维生素C（新鲜蔬果、橙汁）同食；蛋白质有助铁吸收","避免干扰：浓茶、咖啡、牛奶与钙剂应间隔2小时以上（影响铁吸收）","巨幼细胞贫血：富含叶酸（绿叶蔬菜、动物肝脏、豆类）与维生素B12（动物性食物）的饮食","均衡饮食与规律进餐；必要时口服营养补充剂，避免过度节食"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1441},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"033ba291c8c172775a00a69a52e1c320473a1a333861b6ac0bd4caf4a870babd","pinyin":"renshenqipinxue","initials":"rsqpx","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","乏力、头晕、活动后心悸气短、注意力不集中\\n面色与结膜苍白、指甲苍白脆薄、口角炎与舌炎（缺铁）\\n重度贫血：心率增快、心界扩大（贫血性心脏病）、下肢水肿、呼吸困难\\n重度缺铁：异食癖（如嗜食泥土或冰）、吞咽困难（Plummer-Vinson综合征）\\n巨幼细胞贫血：舌面光滑（牛肉舌）、四肢麻木与感觉异常（B12缺乏）",60],["摘要","妊娠期贫血指孕妇血红蛋白<110g/L（妊娠中晚期<105g/L），以缺铁性贫血最常见（占95%），其次为巨幼细胞贫血（叶酸/B12缺乏）与地中海贫血。贫血增加早产、低出生体重、胎儿生长受限与产后出血风险，需在妊娠期常规筛查并规范补铁治疗。",30],["疾病编码","O99.0",30],["原首字母","rsqpx",60]]},{"id":"orders-a7322c7f40154e334633","key":"v1-c9ccc21dfe2a3058|orders-a7322c7f40154e334633","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"早产","category":"妇产科","raw":{"name":"早产","category":"妇产科","summary":"早产指妊娠满28周至不足37周分娩（我国定义），是围产儿死亡与并发症（呼吸窘迫综合征、颅内出血、感染、坏死性小肠结肠炎）的主要原因。按发生原因分为自发性早产（早产临产与未足月胎膜早破）与治疗性早产（母胎指征）。处理核心是抑制宫缩、促胎肺成熟与防治感染。","symptoms":["规律宫缩（≥4次/20分钟或≥8次/60分钟）伴宫颈管缩短与宫口扩张","阴道少量流血（见红）、腰酸与下腹坠胀感","阴道流液（未足月胎膜早破，需与尿失禁鉴别）","胎动异常（胎儿窘迫或感染）","感染征象：发热、腹痛、阴道分泌物异味（绒毛膜羊膜炎）"],"diagnosis":["宫缩与宫颈评估：宫缩频率与强度、宫颈管长度（超声<25mm提示高风险）与宫口扩张（阴道检查慎用，胎膜早破时禁）","胎儿纤维连接蛋白（fFN）检测：阴道分泌物fFN阳性（<35周）提示早产风险高（阴性预测价值高）","胎膜早破诊断：阴道窥器见羊水自宫颈口流出、pH试纸（羊水呈碱性）、羊水结晶检查与超声羊水量减少","感染评估：血常规+CRP+PCT、阴道分泌物培养（GBS筛查）、羊水检查（疑绒毛膜羊膜炎可羊膜腔穿刺）","胎儿评估：胎心监护（NST）、超声（胎儿生长、羊水、胎位、脐血流）与生物物理评分","病因评估：宫颈机能不全（既往早产史、宫颈手术史）、子宫畸形、感染、多胎妊娠与胎盘异常","孕周确认：早期超声核对孕周（决定处理策略与预后判断）"],"infusion":["⚠️ 按孕周与病情选择抑制宫缩与促胎肺成熟！","","方案1（抑制宫缩，34周前）：","  用法：利托君 50～100μg/min 泵入（每10分钟增加50μg/min至有效，监测心率<140次/分）；或 阿托西班（按方案）；或 硝苯地平 10mg 口服（每20分钟×3次后改q6h，监测血压）","","方案2（促胎肺成熟，24～34周且7天内有早产风险）：","  用法：地塞米松 6mg 肌注 q12h×4次（48小时内完成）；或 倍他米松 12mg 肌注 q24h×2次〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（未足月胎膜早破/感染预防）：","  用法：青霉素G 500万U 静滴 q6h 或 氨苄西林 2g 静滴 q6h（GBS预防，疗程至分娩或48小时）；或 红霉素 250mg 静滴 q6h（青霉素过敏）；必要时加 甲硝唑 0.5g 静滴 q8h〔调 肝功能不全减量；妊娠早期禁用；用药期间及停药3日内禁酒〕","","方案4（硫酸镁；神经保护，<32周预期7天内分娩）：","  用法：硫酸镁 4～6g（NS 100ml 或 5%GS 100ml；缓慢静滴）（20～30分钟）后 1～2g/h 维持（神经保护减少脑瘫，监测腱反射、呼吸与尿量，疗程≤24小时）","","📌 抑制宫缩禁用于宫内感染、胎儿窘迫、重度子痫前期与胎盘早剥；促胎肺成熟是改善新生儿预后的关键措施；硫酸镁用于<32周的胎儿神经保护。"],"oral_medication":["⚠️ 早产治疗以静脉为主，稳定后口服维持：","药物1（抑制宫缩口服维持）：","用法：硝苯地平 10～20mg q6～8h（监测血压与心率）或 利托君片 10mg q4～6h（监测心率）；沙丁胺醇（副作用较多，少用）","药物2（抗生素口服序贯）：","用法：阿莫西林 0.5g tid（GBS预防，按医嘱）；或 阿奇霉素 0.5g qd×3天（衣原体/支原体）〔调 CrCl<30 减量；青霉素过敏禁用〕","药物3（营养与维生素）：","用法：叶酸 0.4～1mg qd；铁剂（按血常规）；碳酸钙D3 600mg qd；维生素D 400IU/日","药物4（产后与新生儿相关）：","用法：分娩后按产科常规用药；新生儿按早产儿管理（呼吸支持、喂养与感染防治）","📌 抑制宫缩药物有心血管与代谢副作用（心动过速、低血压、肺水肿、高血糖），需监测；感染是抑制宫缩的禁忌（需先抗感染）。"],"treatment":["抑制宫缩（34周前，无禁忌者）：利托君静滴50～100μg/min起（监测心率）或硝苯地平10～20mg口服q6～8h（监测血压）或阿托西班；疗程48小时","促胎肺成熟：24～34周有早产风险者给予地塞米松6mg肌注q12h×4次或倍他米松12mg肌注q24h×2次","胎儿神经保护：<32周预期7天内分娩者用硫酸镁4g静滴负荷后1～2g/h维持（降低脑瘫风险）","感染防治：未足月胎膜早破者预防性抗生素（青霉素或氨苄西林覆盖GBS）；疑绒毛膜羊膜炎者立即抗感染并考虑终止妊娠","分娩方式与时机：无禁忌者可期待治疗；宫内感染、胎儿窘迫、重度子痫前期或胎盘早剥需立即终止妊娠；臀位或胎儿窘迫多需剖宫产","产程与分娩管理：早产儿分娩时需儿科医师与新生儿复苏设备到场、避免产伤（慎用产钳与胎吸）、延迟断脐（30～60秒，条件允许）","新生儿管理：转入新生儿科（保暖、呼吸支持、喂养与感染防治）；早产儿随访（神经发育与视力听力）","宣教与随访：早产高危因素预防（宫颈机能不全者孕中期监测与宫颈环扎评估）、产后避孕指导与再次妊娠计划（间隔≥18个月）"],"management":["宫缩与胎心监测：记录宫缩频率与强度、胎心监护（每4～6小时或按病情）、胎动计数","抑制宫缩用药护理：利托君泵入监测心率与血压（心率>140次/分需减量）、观察肺水肿与高血糖；硝苯地平监测血压","促胎肺成熟执行：按医嘱按时肌注地塞米松（48小时内完成4次），记录注射时间","感染监测：每4小时测体温、观察阴道分泌物性状与异味、腹痛与子宫压痛（绒毛膜羊膜炎预警）","胎膜早破护理：卧床（抬高臀部）、避免不必要的阴道检查、会阴清洁与垫巾观察羊水量与性状、监测体温与感染指标","心理护理：早产焦虑与恐惧明显，解释治疗与预后、鼓励家属陪伴、必要时心理支持","宣教：识别早产征象（规律宫缩、阴道流液与见红）及时就诊、孕期保健与随访、早产儿喂养与随访计划"],"notes":["早产处理的核心是『抑制宫缩争取时间+促胎肺成熟+防治感染』，其中促胎肺成熟对新生儿预后最重要","抑制宫缩的禁忌：宫内感染、胎儿窘迫、重度子痫前期、胎盘早剥与胎儿畸形（需立即终止妊娠）","超声宫颈长度<25mm与fFN阳性提示早产高风险（尤其有早产史者）","未足月胎膜早破需预防性抗生素并密切监测感染（绒毛膜羊膜炎），一旦确诊应及时终止妊娠","<32周预期7天内分娩者使用硫酸镁进行胎儿神经保护（可降低脑瘫风险）","早产儿需延迟断脐（30～60秒）与新生儿科支持，出院后长期随访神经发育"],"emergency":["规律宫缩伴宫口扩张（早产临产）→ 立即抑制宫缩+促胎肺成熟+产科处理","阴道流液（未足月胎膜早破）→ 卧床、避免阴道检查、预防性抗生素、监测感染与胎心","发热腹痛伴子宫压痛与阴道异味（绒毛膜羊膜炎）→ 立即抗感染+终止妊娠（不可继续保胎）","胎心异常或胎动减少（胎儿窘迫）→ 左侧卧位吸氧、进一步评估，必要时紧急剖宫产","阴道大出血伴腹痛（胎盘早剥）→ 立即评估并紧急剖宫产"],"pinyin":"zc","icd10":"O60.0","physical_exam":["生命体征：体温（感染）、血压（子痫前期）、心率（抑制宫缩药物影响）、呼吸","产科：宫高与腹围、胎心（110～160次/分）、宫缩（频率与强度）、胎位","宫颈评估：宫口扩张与宫颈管消失（阴道检查慎用；胎膜早破时禁）","阴道与分泌物：流血（见红）、流液（胎膜早破）、分泌物性状与异味（感染）","腹部：腹痛与子宫压痛（绒毛膜羊膜炎/胎盘早剥）、宫缩间歇期子宫张力","胎动与胎心监护：胎动计数与NST结果","其他：下肢水肿与血压（子痫前期）、既往宫颈手术瘢痕"],"lab_tests":["胎儿纤维连接蛋白（fFN）+超声宫颈长度：早产风险预测（<35周）","胎膜早破检测：阴道液pH试纸、羊水结晶与超声羊水量","血常规+CRP+PCT：感染评估（绒毛膜羊膜炎）","阴道分泌物培养+GBS筛查：感染与GBS预防依据","胎心监护（NST）+超声（胎儿生长、羊水、脐血流与胎位）：胎儿状况评估","孕周核对（早期超声）：处理策略与预后判断基础","电解质+血糖（抑制宫缩药物监测）：利托君致高血糖与低钾"],"nursing":["宫缩与胎心监测：记录宫缩频率与强度、按时胎心监护与胎动计数，异常立即报告","抑制宫缩用药护理：按医嘱泵入并监测心率（<140次/分）与血压、观察心悸、胸痛与呼吸困难（肺水肿风险）","促胎肺成熟护理：按时肌注地塞米松并记录时间（48小时内完成4次），观察血糖变化","胎膜早破护理：卧床抬高臀部、会阴清洁、观察羊水量与颜色、避免阴道检查与盆浴、监测体温","感染观察：每4小时测体温、注意腹痛与子宫压痛、分泌物异味与胎心增快（绒毛膜羊膜炎预警）","心理护理：安抚焦虑与恐惧、解释治疗与新生儿预后、鼓励家属陪伴与支持","宣教：识别早产征象（规律宫缩、流液、见红）及时就诊、卧床休息与孕期保健、早产儿随访计划"],"diet":["高蛋白、高维生素、易消化饮食（妊娠晚期需求增加）；少量多餐","保证充足水分与膳食纤维（卧床期间防便秘，避免用力致宫缩）","抑制宫缩药物（利托君）治疗期间控制含糖食物（血糖升高风险）并监测血糖","贫血者补铁与维生素C；补充钙与维生素D（预防妊娠期并发症）","避免刺激性食物（辛辣、浓茶、咖啡）与饮酒；戒烟（吸烟是早产危险因素）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1442},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"3373ef9fec03e5139de8da6dedc51ecfb7bedda40a3f4330c704186388177dc4","pinyin":"zaochan","initials":"zc","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","规律宫缩（≥4次/20分钟或≥8次/60分钟）伴宫颈管缩短与宫口扩张\\n阴道少量流血（见红）、腰酸与下腹坠胀感\\n阴道流液（未足月胎膜早破，需与尿失禁鉴别）\\n胎动异常（胎儿窘迫或感染）\\n感染征象：发热、腹痛、阴道分泌物异味（绒毛膜羊膜炎）",60],["摘要","早产指妊娠满28周至不足37周分娩（我国定义），是围产儿死亡与并发症（呼吸窘迫综合征、颅内出血、感染、坏死性小肠结肠炎）的主要原因。按发生原因分为自发性早产（早产临产与未足月胎膜早破）与治疗性早产（母胎指征）。处理核心是抑制宫缩、促胎肺成熟与防治感染。",30],["疾病编码","O60.0",30],["原首字母","zc",60]]},{"id":"orders-17af946452e9eed67112","key":"v1-c9ccc21dfe2a3058|orders-17af946452e9eed67112","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"宫颈上皮内病变与HPV感染","category":"妇产科","raw":{"name":"宫颈上皮内病变与HPV感染","category":"妇产科","summary":"宫颈上皮内病变（CIN）是与高危型人乳头瘤病毒（HPV）持续感染相关的宫颈癌前病变，按程度分为CIN1（低级别）、CIN2与CIN3（高级别）。规范筛查（HPV检测+细胞学TCT）与阴道镜活检是诊断核心；CIN2/3需治疗（LEEP/冷刀锥切），CIN1多可随访观察。HPV疫苗可有效预防。","symptoms":["多数无症状（依靠筛查发现）","接触性出血（性交后或妇科检查后出血）","阴道分泌物增多（白带增多、可有异味）","CIN3/早期宫颈癌可有异常阴道流血（非经期或绝经后出血）","高危HPV感染通常无自觉症状（需检测发现）"],"diagnosis":["宫颈癌筛查（核心）：HPV检测（高危型）与液基细胞学（TCT）联合筛查（25～30岁起，每3～5年）","筛查异常分流：HPV16/18阳性直接转诊阴道镜；其他高危型阳性伴细胞学异常者转诊阴道镜","阴道镜检查+活检（金标准）：醋酸白试验与碘试验下定位活检（必要时宫颈管搔刮ECC）","病理分级：CIN1/CIN2/CIN3（或LSIL/HSIL），必要时免疫组化p16/Ki-67辅助","宫颈锥切（LEEP/冷刀）：CIN2/3的治疗与诊断（排除浸润癌），切缘状态影响随访策略","妊娠期筛查：妊娠期可行阴道镜检查（避免颈管搔刮与锥切），必要时推迟治疗至产后","鉴别诊断：宫颈炎、宫颈息肉、湿疣（低危HPV）、宫颈癌（浸润性）"],"infusion":["⚠️ CIN治疗以物理/手术为主，静脉用药用于手术与感染！","","方案1（锥切/LEEP术前预防性抗感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（术前0.5～1小时，单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（术后抗感染与止血）：","  用法：头孢呋辛 1.5g 静滴 q8h（24～48小时，按医嘱）；氨甲环酸 0.5g 静滴（出血时）；必要时缩宫素（出血多者）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案3（合并盆腔炎/宫颈炎感染）：","  用法：头孢曲松 1g 静滴 qd + 多西环素 0.1g bid 口服 + 甲硝唑 0.5g 静滴 q12h（覆盖淋菌、衣原体与厌氧菌，疗程14天）〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","方案4（支持与补液）：","  用法：0.9%氯化钠/葡萄糖 静滴；维生素C 2g 静滴 qd（创面愈合辅助）","","📌 宫颈病变治疗以LEEP/锥切/消融为主；术后需观察出血（多于术后7～14天脱痂期）与感染；妊娠期一般推迟治疗。"],"oral_medication":["⚠️ 术后与辅助用药（HPV无特效抗病毒药）：","药物1（术后抗感染序贯）：","用法：头孢呋辛酯 0.25g bid（3～5天，按医嘱）或 阿莫西林克拉维酸 0.625g tid〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（止血与创面愈合）：","用法：氨甲环酸片 0.5g tid（出血时，短期）；康复新液（局部或口服，促愈合）；维生素C 0.2g tid〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","药物3（免疫调节辅助，证据有限）：","用法：局部干扰素栓剂（如重组人干扰素α2b栓，qod，疗程1～3个月，遵医嘱）；保妇康栓（辅助）","药物4（合并感染）：","用法：阿奇霉素 0.5g qd×3天（衣原体）或多西环素 0.1g bid×7天；甲硝唑 0.4g tid×7天（细菌性阴道病）〔调 ★ 8岁以下及妊娠期禁用；食管刺激（需直立饮水送服）〕","📌 无特效抗HPV药物（干扰素等仅作辅助）；治疗核心是筛查-阴道镜-规范处理与随访；接种HPV疫苗可预防再感染。"],"treatment":["筛查与分流：HPV+TCT联合筛查，异常者阴道镜活检（病理分级决定处理）","CIN1（低级别）：多可自然消退，随访观察（每6～12个月复查HPV/TCT，必要时阴道镜）","CIN2：可行LEEP/消融治疗或随访观察（年轻女性与妊娠期可考虑随访）；CIN3：必须治疗（LEEP或冷刀锥切）","锥切与切缘管理：切缘阴性者随访（每6个月HPV检测）；切缘阳性（尤其内切缘）需再次评估与进一步处理","术后随访：术后6、12、24个月行HPV/TCT联合检测；持续异常者阴道镜评估（复发风险）","HPV疫苗接种：适龄女性接种（二价/四价/九价），已感染者接种仍可预防其他型别（推荐接种）","妊娠期管理：阴道镜评估（可推迟至产后6～8周复查），仅疑浸润癌时行锥切（避免影响妊娠）","宣教：定期筛查的重要性（按年龄与风险制定间隔）、安全性行为与避孕套使用（降低HPV传播）、戒烟（HPV持续感染危险因素）"],"management":["筛查随访管理：建立筛查档案，按年龄与风险制定筛查间隔（25～30岁起每3～5年联合筛查）并主动提醒","阴道镜与活检前准备：术前3天避免性生活与阴道用药、避开月经期、告知可能的出血与不适","术后护理（LEEP/锥切）：观察阴道出血（术后7～14天脱痂期出血常见）、禁性生活与盆浴1～2个月、避免剧烈运动与重体力劳动","感染预防：术后会阴清洁、按医嘱抗感染、观察分泌物异味与发热（感染征象）","心理护理：HPV阳性与CIN诊断易致焦虑与羞耻感，需解释HPV感染常见、多数可清除、规范随访可预防宫颈癌","宣教：HPV传播途径与预防（疫苗、避孕套、戒烟）、定期筛查、术后随访重要性、伴侣不需常规治疗但需注意防护"],"notes":["宫颈癌筛查是预防宫颈癌的关键：HPV+TCT联合筛查（25～30岁起每3～5年）可显著降低发病率","HPV感染常见且多为一过性（多数在1～2年内清除）；仅持续高危型感染与CIN2/3需积极处理","CIN2/3需治疗（LEEP/锥切）以排除浸润癌；CIN1多可随访观察（尤其年轻女性）","锥切后切缘阳性（尤其内切缘）需进一步评估（再次锥切或子宫切除，依年龄与生育需求决定）","HPV疫苗是有效的一级预防（适龄接种，最好在首次性行为前）；已感染者接种仍有获益"],"emergency":["锥切/LEEP术后大量阴道出血（>月经量）→ 立即妇科检查、压迫止血（纱条填塞）、必要时电凝或缝合，补液纠正贫血","术后发热伴腹痛与分泌物异味（盆腔感染）→ 抗感染+妇科评估，必要时住院","术后突发下腹剧痛伴腹腔内出血征象（子宫穿孔，罕见）→ 急诊评估与手术","绝经后阴道出血或接触性出血量大 → 急诊妇科检查与活检（排除宫颈癌）","妊娠期阴道出血伴宫颈病变 → 产科与妇科共同评估（避免盲目活检与手术）"],"pinyin":"gjspbnyHPVgr","icd10":"N87.9","physical_exam":["外阴与阴道：外观、分泌物性状与量、有无湿疣（低危HPV）","宫颈（窥器检查）：宫颈外观（糜烂样改变、息肉、接触性出血）、病变范围与醋酸白反应","双合诊/三合诊：子宫大小与活动度、附件区包块与压痛、宫骶韧带（宫颈癌浸润评估）","阴道镜所见：醋酸白上皮、点状血管与镶嵌（CIN表现）、病变范围与转化区类型","盆腔淋巴结（必要时）：腹股沟与锁骨上淋巴结（晚期转移）","其他：贫血貌（长期出血）、下腹压痛（合并盆腔炎）","妊娠期：宫高与胎心（合并妊娠者，避免颈管搔刮）"],"lab_tests":["高危型HPV检测+液基细胞学（TCT）：筛查与随访核心（每3～5年或按指南）","阴道镜+宫颈活检+病理分级（CIN1/2/3）：诊断金标准","免疫组化 p16/Ki-67（必要时）：辅助病理分级（尤其CIN2）","宫颈管搔刮（ECC，必要时）：评估颈管内病变（阴道镜不满意者）","宫颈分泌物培养+衣原体/淋菌检测：合并感染评估","血常规+凝血功能（拟手术者）：术前评估","妊娠试验（育龄女性）+妊娠期阴道镜：妊娠合并CIN的管理依据"],"nursing":["筛查随访管理：协助建立筛查档案与提醒、解释筛查意义与间隔、追踪异常结果（避免失访）","阴道镜/活检护理：术前准备宣教（避免性生活与阴道用药、避开月经期）、术后观察出血与不适","术后护理（LEEP/锥切）：观察阴道出血（脱痂期7～14天）、禁性生活与盆浴1～2个月、避免重体力劳动、会阴清洁","感染观察：体温、分泌物性状与异味、下腹疼痛，异常立即报告","心理护理：解释HPV感染常见与可清除、CIN可治愈，减轻焦虑与羞耻感，鼓励伴侣支持","宣教：HPV疫苗推荐（适龄接种）、安全性行为与避孕套使用、戒烟、定期筛查与术后随访重要性"],"diet":["高蛋白、高维生素饮食促进术后创面愈合（鱼、瘦肉、蛋、蔬果）","富含维生素A、C、E与叶酸的食物（抗氧化与免疫支持）","术后1～2个月避免辛辣刺激与酒类（减少创面充血与出血风险）","均衡饮食、控制体重；糖尿病患者控糖（影响愈合）","戒烟（吸烟是HPV持续感染与宫颈癌的独立危险因素）；限酒"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1443},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0e7b48129c918f6495968cfd875b58f1c4c8d7680fbe5e465b65c07072da838d","pinyin":"gongjingshangpineibingbianyuHPVganran","initials":"gjspnbbyHgr","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","多数无症状（依靠筛查发现）\\n接触性出血（性交后或妇科检查后出血）\\n阴道分泌物增多（白带增多、可有异味）\\nCIN3/早期宫颈癌可有异常阴道流血（非经期或绝经后出血）\\n高危HPV感染通常无自觉症状（需检测发现）",60],["摘要","宫颈上皮内病变（CIN）是与高危型人乳头瘤病毒（HPV）持续感染相关的宫颈癌前病变，按程度分为CIN1（低级别）、CIN2与CIN3（高级别）。规范筛查（HPV检测+细胞学TCT）与阴道镜活检是诊断核心；CIN2/3需治疗（LEEP/冷刀锥切），CIN1多可随访观察。HPV疫苗可有效预防。",30],["疾病编码","N87.9",30],["原首字母","gjspbnyHPVgr",60]]},{"id":"orders-a6af85cdac3de6063139","key":"v1-c9ccc21dfe2a3058|orders-a6af85cdac3de6063139","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"特应性皮炎","category":"皮肤科","raw":{"name":"特应性皮炎","category":"皮肤科","summary":"特应性皮炎（AD，异位性皮炎）是一种慢性复发性、瘙痒性、炎症性皮肤病，与遗传性皮肤屏障功能障碍（丝聚蛋白基因突变）和免疫异常相关，常伴过敏性鼻炎与哮喘（'特应性进程'）。儿童多见，表现为湿疹样皮损与剧烈瘙痒。治疗核心是基础保湿+外用抗炎（激素/钙调磷酸酶抑制剂），重症需系统治疗。","symptoms":["剧烈瘙痒（夜间加重，导致睡眠障碍与搔抓）","皮损分布随年龄变化：婴儿期（面颊、额部）、儿童期（肘窝、腘窝屈侧）、成人期（屈侧、颈部与手足）","急性期：红斑、丘疹、水疱与渗出；慢性期：皮肤增厚（苔藓样变）、干燥与抓痕","皮肤干燥（全身性，冬季加重）、毛周角化、掌纹增多（鱼鳞病样表现）","伴随过敏性疾病：过敏性鼻炎、哮喘、食物过敏（'特应性进程'）"],"diagnosis":["临床诊断（Hanifin-Rajka或中国标准）：瘙痒+典型皮损分布+慢性复发病程+个人或家族特应性疾病史","严重度评分：SCORAD或EASI评分（评估疗效与治疗升级依据）","过敏原检测（血清特异性IgE或皮肤点刺）：疑食物或环境过敏诱发者（不作常规）","血清总IgE+嗜酸性粒细胞计数：常升高（支持诊断，特异性低）","皮肤感染评估：细菌（金黄色葡萄球菌定植常见，脓疱与渗出）、病毒（疱疹性湿疹/Kaposi水痘样疹）与真菌","鉴别诊断：接触性皮炎、脂溢性皮炎、银屑病、疥疮、鱼鳞病与免疫缺陷病","必要检查：血常规、肝功能与肾功能（系统治疗前评估）；皮肤活检（疑难病例）"],"infusion":["⚠️ 以局部治疗与基础护理为主，静脉用药用于重症与感染！","","方案1（重症急性发作，系统糖皮质激素短期）：","  用法：甲泼尼龙 0.5～1mg/kg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（短期3～5天，症状控制后改口服并快速减停）；或 地塞米松 5～10mg 静推（重症，短期）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（继发感染，抗感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 阿莫西林克拉维酸 1.2g 静滴 q8h（金黄色葡萄球菌感染，疗程7～10天）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","","方案3（疱疹性湿疹/重症病毒感染）：","  用法：阿昔洛韦 5～10mg/kg（NS 100ml 或 5%GS 100ml）静滴 q8h（7～10天）；必要时丙种球蛋白 400mg/kg 静滴 qd（重症）","","方案4（补液与支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；维生素C 2g 静滴 qd；白蛋白（低蛋白或渗出严重者）","","📌 系统激素不宜长期使用（停药反跳）；重度难治性AD可考虑生物制剂（度普利尤单抗）或小分子药（JAK抑制剂），由皮肤科专科评估。"],"oral_medication":["⚠️ 基础保湿+外用抗炎是核心，口服为辅：","药物1（基础保湿，每日必用）：","用法：润肤剂（含神经酰胺或凡士林）每日2～3次或更多（洗澡后3分钟内涂抹，全身用量成人每周250g以上）","药物2（外用抗炎）：","用法：外用糖皮质激素（如糠酸莫米松乳膏 每日1次，按部位与严重度选择强度，面部与褶皱处用弱效）；钙调磷酸酶抑制剂（他克莫司软膏 0.03%～0.1% bid，面部与褶皱处首选，避免长期激素副作用）","药物3（口服抗组胺药，止痒）：","用法：西替利嗪 10mg qn 或 氯雷他定 10mg qd；夜间瘙痒重者可用 羟嗪 25mg qn 或 第一代抗组胺药（注意嗜睡）〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物4（系统治疗，重症）：","用法：环孢素 3～5mg/kg/日（短期，监测血压与肾功能）；度普利尤单抗 600mg 皮下注射（负荷，之后300mg q2w）；JAK抑制剂（巴瑞替尼等，按专科指导）","📌 避免长期大面积使用强效激素（皮肤萎缩、毛细血管扩张与全身吸收）；激素与钙调磷酸酶抑制剂可交替使用（主动治疗策略）。"],"treatment":["基础治疗（所有患者）：规律使用润肤剂（足量、每日多次）、温水短时沐浴（避免过热与过度清洁）、穿纯棉衣物、避免搔抓与刺激物","外用抗炎治疗：急性期外用糖皮质激素（按部位强度分级），面部与皱褶处首选钙调磷酸酶抑制剂；慢性期维持治疗（主动治疗：每周2次间歇外用）","系统治疗（中重度）：生物制剂（度普利尤单抗）、JAK抑制剂、环孢素（短期）；系统激素仅用于急性重症短期过渡","抗感染：金黄色葡萄球菌感染（脓疱、渗出）予外用莫匹罗星或口服/静脉抗生素；疱疹性湿疹用阿昔洛韦（急症）","瘙痒管理：抗组胺药、夜间镇静、避免搔抓（剪短指甲、戴手套睡眠）、冷敷与心理干预（瘙痒-搔抓循环）","诱因管理：避免过热出汗、羊毛与化纤衣物、刺激性洗剂、尘螨与宠物皮屑；疑食物过敏者（尤其婴幼儿）规范评估与回避（避免盲目忌口）","共病管理：过敏性鼻炎与哮喘同步治疗（鼻用激素与吸入治疗）；心理支持（睡眠障碍与焦虑抑郁常见）","随访与宣教：定期评估严重度评分（SCORAD/EASI）、指导用药与保湿、长期管理预期（慢性复发性疾病需长期治疗）"],"management":["皮肤评估与记录：记录皮损部位、范围、渗出与苔藓化程度，按SCORAD/EASI评分评估严重度与疗效","保湿护理指导：演示润肤剂用量与方法（洗澡后3分钟内、全身涂抹、每日≥2次），强调足量使用的重要性","外用药物护理：按部位与严重度选择强度、薄涂（指尖单位计量）、教家长正确使用（避免面部长期强效激素）","瘙痒与搔抓管理：剪短指甲、必要时夜间戴棉手套、冷敷、分散注意力、评估睡眠质量","感染观察：监测脓疱、渗出与发热（细菌感染）、簇集水疱（疱疹性湿疹，急症需立即处理）","诱因与生活指导：纯棉衣物、避免过热出汗、温和洗浴、环境除螨、必要时规范食物回避（避免盲目忌口）","宣教：AD为慢性病需长期基础治疗、激素外用安全性（避免恐惧激素导致治疗不足）、识别感染征象与及时就诊"],"notes":["特应性皮炎治疗的核心是『基础保湿+外用抗炎』，保湿剂用量常被严重低估（成人每周≥250g）","避免对激素外用的恐惧（'激素恐惧症'是治疗失败主因）；按部位选择强度并规范使用是安全的","面部与皱褶处首选钙调磷酸酶抑制剂（他克莫司/吡美莫司），减少激素副作用","疱疹性湿疹（Kaposi水痘样疹）是急症（簇集水疱+发热），需立即抗病毒治疗","儿童AD多随年龄改善（'特应性进程'），但需长期管理与共病（鼻炎/哮喘）同步治疗"],"emergency":["簇集水疱伴发热与全身不适（疱疹性湿疹）→ 立即阿昔洛韦静脉治疗，必要时住院","皮肤大面积渗出、红肿热痛伴发热（继发严重细菌感染/蜂窝织炎）→ 静脉抗生素并评估住院","严重过敏反应伴呼吸困难与血压下降（食物或药物过敏）→ 立即肾上腺素+激素+补液抢救","红皮病样改变（全身潮红脱屑伴体温异常）→ 住院评估与支持治疗","重症AD伴严重睡眠剥夺与情绪障碍 → 专科评估系统治疗与心理支持"],"pinyin":"tyxpy","icd10":"L20.9","physical_exam":["皮损分布与形态：婴儿（面颊额部）、儿童（肘窝腘窝）、成人（屈侧颈部手足）；红斑、丘疹、渗出、苔藓化","皮肤干燥度：全身干燥、鱼鳞病样改变、掌纹增多、毛周角化","瘙痒与搔抓痕迹：抓痕、血痂、色素沉着与苔藓样变","感染征象：脓疱、黄痂（细菌）、簇集水疱（疱疹）、白色斑块（念珠菌）","伴随过敏体征：鼻黏膜苍白水肿（过敏性鼻炎）、结膜充血（过敏性结膜炎）、喘息（哮喘）","生长发育（儿童）：身高体重与生长曲线（重症与长期激素影响）","心理与睡眠：情绪状态、睡眠质量与生活质量评估"],"lab_tests":["血清总IgE+特异性IgE（过敏原）：常升高，支持过敏体质（不作常规诊断依据）","血常规+嗜酸性粒细胞计数：常升高（病情活动相关）","皮肤细菌培养+药敏（感染时）：金黄色葡萄球菌感染诊断","病毒检测（PCR，疑疱疹性湿疹）：单纯疱疹病毒","严重度评分（SCORAD/EASI）：疗效评估（每次随访记录）","系统治疗前评估：血常规、肝肾功能、血压（环孢素、JAK抑制剂）、结核与乙肝筛查（生物制剂）","皮肤活检（疑难病例）：排除其他皮肤病"],"nursing":["保湿护理：指导并协助正确涂抹润肤剂（洗澡后3分钟内、足量、每日≥2次），记录皮肤干燥改善情况","外用药护理：按医嘱与部位用药、薄涂并示范正确方法，观察疗效与不良反应（皮肤萎缩、刺激）","瘙痒护理：剪短指甲、夜间戴棉手套、冷敷、分散注意力，评估睡眠与情绪","感染观察：监测脓疱、渗出、发热与簇集水疱（疱疹性湿疹急症），异常立即报告","生活指导：纯棉衣物、温和洗浴（温水短时）、避免过热出汗与刺激性洗剂、环境除螨","宣教：AD需长期管理、保湿与外用药不可间断、避免盲目忌口与激素恐惧、按时随访评估严重度"],"diet":["婴幼儿疑食物过敏（牛奶、鸡蛋、花生等）：规范评估（过敏原检测+食物激发试验）后针对性回避，避免盲目忌口（影响生长发育）","均衡营养，保证蛋白、维生素与必需脂肪酸摄入（皮肤屏障修复需要）","补充维生素D（部分研究显示与AD严重度相关）；多食富含ω-3脂肪酸食物","避免已明确的过敏食物与刺激性食物（辛辣、酒类）","多饮水、保持皮肤水分；必要时补充益生菌（证据有限，遵医嘱）"],"topical_medication":["糠酸莫米松乳膏 涂患处 qd；他克莫司软膏 涂患处 bid；尿素维E乳膏 涂患处 bid"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1444},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"a583351e677b4f567b19618aa1d2e132b1851f869e22ac02f5c2748614bf3618","pinyin":"teyingxingpiyan","initials":"tyxpy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","剧烈瘙痒（夜间加重，导致睡眠障碍与搔抓）\\n皮损分布随年龄变化：婴儿期（面颊、额部）、儿童期（肘窝、腘窝屈侧）、成人期（屈侧、颈部与手足）\\n急性期：红斑、丘疹、水疱与渗出；慢性期：皮肤增厚（苔藓样变）、干燥与抓痕\\n皮肤干燥（全身性，冬季加重）、毛周角化、掌纹增多（鱼鳞病样表现）\\n伴随过敏性疾病：过敏性鼻炎、哮喘、食物过敏（'特应性进程'）",60],["摘要","特应性皮炎（AD，异位性皮炎）是一种慢性复发性、瘙痒性、炎症性皮肤病，与遗传性皮肤屏障功能障碍（丝聚蛋白基因突变）和免疫异常相关，常伴过敏性鼻炎与哮喘（'特应性进程'）。儿童多见，表现为湿疹样皮损与剧烈瘙痒。治疗核心是基础保湿+外用抗炎（激素/钙调磷酸酶抑制剂），重症需系统治疗。",30],["疾病编码","L20.9",30],["原首字母","tyxpy",60]]},{"id":"orders-729aa0ad0688472536de","key":"v1-c9ccc21dfe2a3058|orders-729aa0ad0688472536de","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"鱼鳞病","category":"皮肤科","raw":{"name":"鱼鳞病","category":"皮肤科","summary":"鱼鳞病是一组以皮肤干燥、粗糙伴鱼鳞状鳞屑为特征的遗传性角化障碍性皮肤病，最常见为寻常型鱼鳞病（丝聚蛋白基因突变，与特应性皮炎相关），其他包括性连锁鱼鳞病、板层状鱼鳞病与先天性鱼鳞病样红皮病（重症）。治疗以保湿与角质剥脱为主，多数不能根治但可良好控制。","symptoms":["皮肤干燥粗糙，四肢伸侧（尤其小腿）多见菱形或多角形鳞屑（'鱼鳞状'）","冬季加重、夏季减轻（与湿度相关）；掌纹增多、毛周角化","轻度瘙痒、皮肤紧绷感；重者皮肤皲裂与疼痛","性连锁鱼鳞病：出生即有大片深褐色鳞屑，可伴角膜混浊（裂隙灯检查）","重症类型（板层状/红皮病型）：出生时'火棉胶样'包裹、眼睑外翻、皮肤裂隙与感染风险"],"diagnosis":["临床检查：皮损分布与鳞屑形态（寻常型：四肢伸侧菱形鳞屑；性连锁：颈部与躯干大片深褐色鳞屑）","家族史：遗传方式（寻常型为常染色体半显性，性连锁为X连锁隐性）","皮肤活检（必要时）：角化过度、颗粒层减少或缺失（寻常型）","基因检测（必要时）：丝聚蛋白（FLG）基因、类固醇硫酸酯酶（STS）基因等（遗传咨询）","眼科检查（性连锁型，成人）：角膜混浊（裂隙灯）","鉴别诊断：获得性鱼鳞病（甲减、肾病、淋巴瘤、HIV、药物）、特应性皮炎、银屑病与苔藓样皮肤病","合并症评估：特应性皮炎、过敏性鼻炎与哮喘（寻常型鱼鳞病常见共病）"],"infusion":["⚠️ 鱼鳞病一般不需静脉治疗，静脉用药用于重症红皮病型与感染！","","方案1（重症红皮病型/板层状鱼鳞病，支持治疗）：","  用法：0.9%氯化钠/葡萄糖 静滴（补液与电解质）；白蛋白 10g 静滴（低蛋白与渗出）；维生素C 2g 静滴 qd","","方案2（继发感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 阿莫西林克拉维酸 1.2g 静滴 q8h（皮肤感染/败血症，按药敏调整）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","","方案3（维A酸类重症治疗，专科）：","  用法：阿维A 0.5～1mg/kg/日 口服（板层状鱼鳞病与红皮病型，需监测肝功能、血脂与骨骼）；必要时静脉支持","","方案4（瘙痒与支持）：","  用法：0.9%氯化钠 静滴；抗组胺药（口服为主）；必要时镇痛（皲裂疼痛）","","📌 鱼鳞病治疗以局部保湿与角质剥脱为主；维A酸类用于重症（需长期监测）；新生儿火棉胶样婴儿需在NICU保温保湿与感染防治。"],"oral_medication":["⚠️ 以局部治疗为主，口服为辅：","药物1（局部保湿，核心）：","用法：含尿素（10%～20%）、乳酸（5%～12%）或神经酰胺的润肤剂 每日2～3次（洗澡后立即涂抹）；凡士林（重症者）","药物2（角质剥脱）：","用法：10%尿素霜 bid 或 水杨酸软膏 3%～6% bid（避免大面积使用，防吸收中毒，儿童慎用）；丙二醇溶液（40%～60%，封包使用，遵医嘱）","药物3（外用维A酸，辅助）：","用法：他扎罗汀乳膏 0.05% qn（小面积试用，注意刺激）；或 阿达帕林凝胶","药物4（口服维A酸类，重症）：","用法：阿维A 10～25mg qd（板层状/红皮病型，需监测肝功能、血脂与骨密度；育龄女性严格避孕）；或 异维A酸","📌 局部治疗需长期坚持（不可根治但可显著改善）；避免使用碱性强的肥皂与过热洗浴；口服维A酸类有致畸风险（育龄女性须严格避孕）。"],"treatment":["基础治疗：每日温和洗浴（温水、避免过度清洁）、立即涂抹润肤剂（含尿素/乳酸/神经酰胺）、湿化环境（加湿器）","角质剥脱与保湿：10%～20%尿素霜、乳酸软膏、水杨酸软膏（小面积、儿童慎用）、丙二醇封包（重症）","外用维A酸：他扎罗汀或阿达帕林（辅助，注意刺激）","系统维A酸类：阿维A或异维A酸（板层状鱼鳞病、红皮病型，需长期监测与避孕）","重症新生儿（火棉胶样婴儿）：NICU保温保湿、无菌操作防感染、必要时静脉补液与营养支持、监测电解质（经皮水分丢失增加）","合并症治疗：特应性皮炎（保湿+外用抗炎）、过敏性鼻炎与哮喘（相应治疗）","遗传咨询：性连锁型（X连锁隐性）与重症类型的家系筛查与产前诊断咨询","随访与宣教：长期局部治疗依从性、冬季加强保湿、避免搔抓与刺激性洗剂、识别感染征象"],"management":["皮肤评估与记录：记录鳞屑分布与程度、皲裂与感染征象，评估保湿治疗效果","保湿与用药护理：指导正确洗浴（温水、短时、温和清洁剂）与润肤剂使用（洗澡后立即、足量、每日多次）；角质剥脱剂按部位使用","瘙痒与皲裂护理：避免搔抓、剪短指甲、皲裂处保护与换药（防感染），必要时镇痛","感染观察：监测皮肤感染（脓疱、渗出、发热）与新生儿败血症风险（重症类型）","环境护理：保持病室湿度（加湿器）、避免干燥与过热环境","宣教：鱼鳞病为遗传性疾病需长期管理（可改善不可根治）、坚持保湿是核心、避免碱性肥皂与搔抓、口服维A酸类育龄女性须避孕、遗传咨询"],"notes":["鱼鳞病以寻常型最常见（与丝聚蛋白基因突变相关，常合并特应性皮炎、鼻炎与哮喘）","治疗核心是长期『保湿+角质剥脱』（不可根治但可良好控制）；冬季需加强","水杨酸大面积使用可经皮吸收致中毒（尤其儿童），应限局使用；尿素与乳酸制剂更安全","重症类型（板层状、红皮病型）需口服维A酸类（有致畸与骨骼影响，需长期监测）","获得性鱼鳞病（成人新发）需排查甲减、肾病、淋巴瘤、HIV与药物（维A酸、烟酸、西咪替丁）"],"emergency":["新生儿火棉胶样包裹伴呼吸困难与脱水（重症鱼鳞病）→ NICU保温保湿、静脉补液与感染防治","皮肤大面积裂隙伴渗出与发热（继发感染/败血症）→ 静脉抗生素+皮肤护理+支持治疗","红皮病样改变伴体温不稳与电解质紊乱 → 住院支持治疗（保温、补液与营养）","皮肤皲裂出血疼痛剧烈 → 局部护理与镇痛，评估感染","口服维A酸类后出现剧烈头痛与视乳头水肿（假性脑瘤）→ 停药并神经科评估"],"pinyin":"ylb","icd10":"Q80.9","physical_exam":["皮损分布与形态：四肢伸侧（小腿）菱形鳞屑（寻常型）、颈部与躯干大片深褐色鳞屑（性连锁型）、全身红皮病样（重症）","皮肤干燥度与皲裂：皮肤紧绷、皲裂（尤其手足与关节处）与疼痛程度","掌纹与毛周角化：掌纹增多、毛囊角化性丘疹（寻常型）","眼部（性连锁型）：角膜混浊（裂隙灯检查）","感染征象：脓疱、渗出、黄痂与发热","生长发育（儿童）：身高体重与生长曲线","合并症：特应性皮炎皮损、过敏性鼻炎与哮喘体征"],"lab_tests":["临床检查与家族史：多数可临床诊断（遗传方式与皮损特征）","皮肤活检（必要时）：角化过度、颗粒层减少或缺失","基因检测（必要时）：FLG、STS等基因（遗传咨询与产前诊断）","眼科裂隙灯检查（性连锁型）：角膜混浊","获得性鱼鳞病筛查（成人新发）：甲状腺功能、肾功能、血常规、HIV与肿瘤筛查（淋巴瘤）","口服维A酸类监测：肝功能、血脂、血常规与骨密度（长期使用）","电解质+白蛋白（重症/新生儿）：经皮水分丢失与营养评估"],"nursing":["保湿护理：指导正确洗浴与润肤剂足量使用（洗澡后立即、每日2～3次），记录皮肤改善情况","用药护理：角质剥脱剂（尿素/乳酸/水杨酸）按部位与年龄使用、观察刺激与吸收中毒（水杨酸）","皮损与感染观察：监测皲裂、渗出、脓疱与发热，异常立即报告","环境护理：保持病室湿度充足（加湿器）、避免干燥与过热（加重鳞屑）","新生儿护理（重症）：保温（暖箱）、无菌操作、皮肤保湿与保护、监测电解质与喂养","宣教：长期保湿与外用药的重要性、避免碱性肥皂与搔抓、冬季加强护理、遗传咨询与口服药避孕要求"],"diet":["均衡营养，富含维生素A（胡萝卜、动物肝脏）与必需脂肪酸（深海鱼、坚果）促进皮肤健康","充足水分摄入（皮肤水合状态）；避免过量饮酒与辛辣刺激食物","口服维A酸类者：低脂饮食（药物致血脂升高）、避免同时服用维生素A补充剂（中毒风险）","儿童保证充足热量与蛋白（重症类型经皮丢失增加、代谢需求高）","多食新鲜蔬果（抗氧化），避免已知过敏食物（合并特应性皮炎者）"],"topical_medication":["尿素软膏 涂患处 bid；维A酸乳膏 涂患处 qn"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1445},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"bc33cb48cc9afd5ac34cc6ffc3f0ab8cc18438e019b04bcdb12530c90eb5c79f","pinyin":"yulinbing","initials":"ylb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","皮肤干燥粗糙，四肢伸侧（尤其小腿）多见菱形或多角形鳞屑（'鱼鳞状'）\\n冬季加重、夏季减轻（与湿度相关）；掌纹增多、毛周角化\\n轻度瘙痒、皮肤紧绷感；重者皮肤皲裂与疼痛\\n性连锁鱼鳞病：出生即有大片深褐色鳞屑，可伴角膜混浊（裂隙灯检查）\\n重症类型（板层状/红皮病型）：出生时'火棉胶样'包裹、眼睑外翻、皮肤裂隙与感染风险",60],["摘要","鱼鳞病是一组以皮肤干燥、粗糙伴鱼鳞状鳞屑为特征的遗传性角化障碍性皮肤病，最常见为寻常型鱼鳞病（丝聚蛋白基因突变，与特应性皮炎相关），其他包括性连锁鱼鳞病、板层状鱼鳞病与先天性鱼鳞病样红皮病（重症）。治疗以保湿与角质剥脱为主，多数不能根治但可良好控制。",30],["疾病编码","Q80.9",30],["原首字母","ylb",60]]},{"id":"orders-66a084c6d50b7eee2854","key":"v1-c9ccc21dfe2a3058|orders-66a084c6d50b7eee2854","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"光化性角化病","category":"皮肤科","raw":{"name":"光化性角化病","category":"皮肤科","summary":"光化性角化病（AK）是长期紫外线暴露引起的癌前病变，多见于老年人曝光部位（面部、头皮、手背与前臂），表现为粗糙鳞屑性斑丘疹。可进展为鳞状细胞癌（年进展率约0.025%～16%），需积极治疗（冷冻、外用药物、光动力或手术切除）与防晒。","symptoms":["曝光部位（面部、头皮、耳、手背、前臂）出现粗糙、干燥的鳞屑性斑丘疹","皮损呈肤色、淡红或褐色，表面附着不易剥离的角质鳞屑","触诊粗糙（'砂纸样'），偶有瘙痒或触痛","部分皮损增厚呈皮角样（'皮角'，需警惕恶变）","可多发（'区域癌化'，周围皮肤有光损伤表现：皱纹、色素斑与毛细血管扩张）"],"diagnosis":["临床检查（皮肤镜）：典型AK表现为红色背景上的黄色鳞屑、'草莓样'毛囊开口与玫瑰花结征","皮肤活检（诊断金标准，尤其增厚、结节、出血或治疗抵抗者）：排除鳞状细胞癌","皮损数目与范围评估：记录部位与数量（多发者需区域治疗）","免疫抑制患者评估（器官移植者AK发生率与恶变风险显著升高）","鉴别诊断：鳞状细胞癌（浸润性，需活检）、基底细胞癌、脂溢性角化、盘状红斑狼疮、银屑病与疣","全身皮肤检查：其他光损伤与皮肤肿瘤筛查（同时存在其他皮肤癌风险）","光损伤与危险因素评估：职业与生活紫外线暴露史、肤色（Fitzpatrick分型）、免疫抑制治疗与既往皮肤癌史"],"infusion":["⚠️ AK以局部治疗为主，静脉用药仅用于手术与光动力治疗辅助！","","方案1（手术切除/活检，术前预防性抗感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴（术前0.5～1小时，单次）或 头孢唑林 1g 静滴〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案2（光动力治疗（PDT）辅助）：","  用法：5-氨基酮戊酸（ALA）外用封包3小时后红光照射（局部治疗，非静脉）；必要时静脉镇痛与抗焦虑（疼痛明显者）","","方案3（继发感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 阿莫西林克拉维酸 1.2g 静滴 q8h（皮损感染/溃疡，疗程5～7天）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","","方案4（免疫抑制患者，减少复发）：","  用法：口服阿维A 10～30mg qd（器官移植者化学预防，需监测肝功能与血脂）；必要时调整免疫抑制方案（与移植科协作）","","📌 AK治疗以冷冻、外用药物（5-FU、咪喹莫特）、光动力或手术为主；免疫抑制患者需长期随访与化学预防；防晒是预防与防复发的关键。"],"oral_medication":["⚠️ 局部治疗为主，口服用于多发与化学预防：","药物1（外用，局部治疗）：","用法：5-氟尿嘧啶乳膏 5% bid（疗程2～4周，出现明显炎症反应为有效表现）；或 咪喹莫特乳膏 5% 每周3次（疗程4～16周）；或 双氯芬酸凝胶 3% bid + 钙泊三醇（联合方案）","药物2（光动力治疗）：","用法：5-氨基酮戊酸（ALA）或甲基氨基酮戊酸（MAL）外用封包后红光照射（医院进行，可区域治疗）","药物3（口服维A酸，多发/免疫抑制化学预防）：","用法：阿维A 10～30mg qd（需监测肝功能、血脂与骨密度；育龄女性严格避孕）；或 异维A酸低剂量","药物4（局部破坏性治疗配合）：","用法：冷冻后局部抗菌软膏（莫匹罗星）预防感染；防晒霜（SPF≥50，每日使用）","📌 治疗需覆盖整个光损伤区域（'区域癌化'，局部治疗常复发）；口服维A酸类有致畸风险；防晒霜需每日使用（含物理遮蔽）。"],"treatment":["局部破坏性治疗（单发或少发）：液氮冷冻（最常用）、电干燥与刮除、激光（CO2或铒激光）","外用药物治疗（多发/区域治疗）：5-氟尿嘧啶（2～4周）、咪喹莫特（4～16周）、双氯芬酸+钙泊三醇（8～12周）","光动力治疗（PDT）：区域治疗（尤其面部多发），美容效果好但费用较高与疼痛明显","手术切除：增厚、结节、皮角样或疑恶变者（活检+完整切除，切缘评估）","化学预防（免疫抑制患者与多发者）：口服阿维A或维A酸类、口服烟酰胺（证据有限）、调整免疫抑制方案（移植科协作）","防晒（基础）：广谱防晒霜（SPF≥50、PA+++）每日使用、物理遮蔽（帽子、长袖）、避免正午紫外线","随访：治疗后3～6个月复诊评估复发；免疫抑制患者每3～6个月皮肤检查；全身皮肤检查筛查其他皮肤肿瘤","宣教：AK为癌前病变需积极治疗（不能仅观察）、长期防晒、自我检查（新发或变化皮损及时就诊）、避免使用日晒床"],"management":["皮损记录：绘制皮损分布图并拍照、记录数目与部位（多发者便于随访对比）","治疗护理：冷冻后观察水疱与结痂（勿撕脱）、外用药物（5-FU/咪喹莫特）指导正确使用并解释炎症反应属预期疗效、光动力治疗前后护理","疼痛与皮肤护理：治疗后皮损区保护（避免搔抓与日晒）、必要时镇痛与抗菌软膏预防感染","防晒宣教（核心）：SPF≥50广谱防晒霜每日使用（每2小时补涂）、物理遮蔽、避免正午户外与日晒床","免疫抑制患者管理：记录免疫抑制方案与移植史、加强随访频次、必要时化学预防（阿维A）与移植科协作","随访提醒：治疗后3～6个月复查、长期随访（复发与恶变风险）、全身皮肤检查","宣教：AK是癌前病变需治疗、长期防晒与自我检查、出现增厚/出血/不愈合皮损立即就诊"],"notes":["光化性角化病是鳞状细胞癌的癌前病变（需积极治疗而非单纯观察），增厚、结节、出血或治疗抵抗者应活检排除恶变","皮肤镜（黄色鳞屑、草莓样毛囊开口、玫瑰花结征）有助诊断但确诊依赖病理","治疗常需区域治疗（'区域癌化'，周围皮肤均有光损伤），局部治疗后复发常见","器官移植等免疫抑制患者AK发生率高、恶变风险显著增加，需密集随访与化学预防","防晒是预防与防复发的关键（SPF≥50每日使用+物理遮蔽+避免日晒床）"],"emergency":["皮损迅速增大、溃烂出血或出现硬结（疑恶变为鳞状细胞癌）→ 尽快活检与完整切除","皮损感染伴红肿热痛与脓性分泌物 → 抗感染治疗与局部护理","免疫抑制患者短期内出现大量新发皮损 → 皮肤科评估并调整免疫抑制方案（移植科协作）","光动力治疗后严重疼痛与水肿影响生活 → 镇痛、冷敷与短期激素外用","冷冻治疗后出现感染或延迟愈合 → 换药与抗感染，评估其他病因（糖尿病、循环障碍）"],"pinyin":"ghxjzb","icd10":"L57.0","physical_exam":["皮损部位与形态：曝光部位（面部、耳、头皮、手背、前臂）鳞屑性斑丘疹、皮角样增厚","触诊：粗糙（砂纸样）、硬结（提示浸润或恶变）","皮肤镜：黄色鳞屑、草莓样毛囊开口、玫瑰花结征、红色背景","周围光损伤皮肤：皱纹、色素斑（雀斑样）、毛细血管扩张、皮肤萎缩","全身皮肤检查：同时存在的皮肤肿瘤（基底细胞癌、鳞状细胞癌、黑色素瘤）与其他AK皮损","免疫抑制评估：移植史、免疫抑制药物使用与剂量","淋巴结（疑恶变）：引流区淋巴结肿大"],"lab_tests":["皮肤活检+病理（诊断与恶变排除金标准）：尤其增厚、结节、出血或治疗抵抗皮损","皮肤镜检查：无创诊断与随访对比","皮损分布图与影像记录：多发者随访对比","免疫抑制患者评估：免疫抑制药物方案、移植史与血药浓度","口服维A酸类监测：肝功能、血脂、血常规与骨密度","全身皮肤检查+必要时影像（疑转移）：淋巴结超声与其他皮肤肿瘤筛查","维生素D水平（防晒严格者）：必要时补充评估"],"nursing":["治疗护理：冷冻后观察水疱与结痂（勿撕脱以防感染）、外用药物指导（5-FU/咪喹莫特出现红斑脱屑属预期疗效）、光动力治疗前后护理","皮肤与疼痛护理：治疗后皮损区保护（避免搔抓与日晒）、必要时镇痛与抗菌软膏","防晒宣教（重点）：SPF≥50广谱防晒霜每日使用与补涂、物理遮蔽（帽子、长袖、墨镜）、避免正午户外与日晒床","随访管理：治疗后3～6个月复查提醒、免疫抑制患者加密随访、记录皮损变化与照片对比","自我检查宣教：教会患者观察皮损变化（增大、出血、不愈合）并及时就诊","心理支持：多发皮损与'癌前病变'诊断易致焦虑，解释预后良好但需坚持治疗与防晒"],"diet":["富含抗氧化物质的食物（新鲜蔬果、番茄红素、绿茶）有助减少光损伤","口服维A酸类者：低脂饮食（药物致血脂升高）、避免维生素A补充剂（中毒风险）","充足饮水，均衡营养；避免过量饮酒（与皮肤癌风险相关）","烟酰胺（维生素B3）口服（部分研究显示可降低AK与皮肤癌发生，遵医嘱）","避免吸烟（与皮肤癌及多种肿瘤风险相关）"],"topical_medication":["氟尿嘧啶乳膏 涂患处 bid；咪喹莫特乳膏 涂患处 每周3次"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1446},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"9b507be7799a7ba68fe3093b71af31e1f925d3dddc42367448d867482abec07f","pinyin":"guanghuaxingjiaohuabing","initials":"ghxjhb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","曝光部位（面部、头皮、耳、手背、前臂）出现粗糙、干燥的鳞屑性斑丘疹\\n皮损呈肤色、淡红或褐色，表面附着不易剥离的角质鳞屑\\n触诊粗糙（'砂纸样'），偶有瘙痒或触痛\\n部分皮损增厚呈皮角样（'皮角'，需警惕恶变）\\n可多发（'区域癌化'，周围皮肤有光损伤表现：皱纹、色素斑与毛细血管扩张）",60],["摘要","光化性角化病（AK）是长期紫外线暴露引起的癌前病变，多见于老年人曝光部位（面部、头皮、手背与前臂），表现为粗糙鳞屑性斑丘疹。可进展为鳞状细胞癌（年进展率约0.025%～16%），需积极治疗（冷冻、外用药物、光动力或手术切除）与防晒。",30],["疾病编码","L57.0",30],["原首字母","ghxjzb",60]]},{"id":"orders-52c6a68fb53e892cb1ef","key":"v1-c9ccc21dfe2a3058|orders-52c6a68fb53e892cb1ef","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"妊娠期皮肤病（PUPPP与妊娠瘙痒）","category":"皮肤科","raw":{"name":"妊娠期皮肤病（PUPPP与妊娠瘙痒）","category":"皮肤科","summary":"妊娠期特异性皮肤病包括妊娠瘙痒性荨麻疹性丘疹与斑块（PUPPP，最常见，初产妇妊娠晚期多发）、妊娠期肝内胆汁淤积症（ICP，见妇产科）、妊娠疱疹（疱疹样脓疱病，自身免疫性，需重视）、妊娠期多形性皮疹与妊娠期丘疹性皮炎。多对症治疗与产后自愈，但需与ICP及妊娠疱疹鉴别。","symptoms":["PUPPP：腹部妊娠纹处首发红色丘疹与荨麻疹样斑块，剧痒，逐渐扩展至大腿与四肢（面部与黏膜多不受累）","妊娠疱疹：躯干与四肢出现环形水疱与荨麻疹样斑块，剧痒，可于产后加重（自身免疫性）","妊娠期丘疹性皮炎：躯干与四肢散发红色丘疹（类似痒疹），剧痒","瘙痒（夜间加重）影响睡眠与情绪；抓痕与皮肤破损","ICP区别：无原发皮损的全身瘙痒（尤其手掌足底）+ 胆汁酸升高（无皮疹是关键鉴别点）"],"diagnosis":["皮损分布与形态评估：PUPPP（妊娠纹处首发）、妊娠疱疹（环形水疱）、丘疹性皮炎（散在丘疹）","血清总胆汁酸+肝功能：排除妊娠期肝内胆汁淤积症（ICP，无原发皮损的瘙痒必查）","皮肤direct免疫荧光（DIF）+血清BP180抗体（疑妊娠疱疹）：诊断依据","皮肤活检（必要时）：PUPPP（表皮海绵水肿与真皮淋巴细胞浸润）、妊娠疱疹（表皮下水疱与嗜酸粒细胞）","胎儿监测（妊娠疱疹）：胎儿生长超声与胎心监护（可致胎儿生长受限与早产）","鉴别诊断：妊娠期肝内胆汁淤积症、妊娠期湿疹、接触性皮炎、药疹、疥疮与妊娠期特异性皮疹","病史（既往妊娠史）：PUPPP多见于初产妇与多胎妊娠；妊娠疱疹多见于经产妇与既往妊娠史"],"infusion":["⚠️ 轻症局部治疗，重症需系统激素，静脉用药用于重症与并发症！","","方案1（重症PUPPP/妊娠期丘疹性皮炎，系统糖皮质激素）：","  用法：甲泼尼龙 0.5～1mg/kg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（短期3～5天，症状缓解后改口服泼尼松并逐渐减量）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案2（妊娠疱疹（疱疹样脓疱病），系统激素+支持）：","  用法：泼尼松 0.5～1mg/kg/日（口服为主，重症可静脉甲泼尼龙）；必要时静脉丙种球蛋白 400mg/kg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（3～5天，难治性）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（继发感染）：","  用法：头孢呋辛 1.5g（NS 100ml 或 5%GS 100ml）静滴 q8h 或 阿莫西林克拉维酸 1.2g 静滴 q8h（皮肤感染，孕期相对安全）；避免使用四环素类与喹诺酮类〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","","方案4（补液与支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；维生素C 2g 静滴 qd；白蛋白（重症/低蛋白者）","","📌 妊娠期用药需兼顾胎儿安全（泼尼松在孕期相对安全；避免四环素类、喹诺酮类与维A酸类）；PUPPP产后迅速自愈；妊娠疱疹需重视胎儿监测。"],"oral_medication":["⚠️ 局部治疗为主，系统用药需权衡胎儿安全：","药物1（局部抗炎，一线）：","用法：外用中弱效糖皮质激素（糠酸莫米松乳膏 qd 或 氢化可的松乳膏 bid，避免强效与大面积长期使用）；炉甘石洗剂 外用（止痒收敛）〔调 ★ 盐皮质激素作用强，高血压/心衰/低钾者慎用〕","药物2（止痒，口服）：","用法：西替利嗪 10mg qn 或 氯雷他定 10mg qd（孕期相对安全）；重度瘙痒可短期使用 泼尼松 20～40mg qd（PUPPP，逐渐减量）〔调 肝功能/肾功能不全减量；妊娠哺乳慎用〕","药物3（妊娠疱疹，系统治疗）：","用法：泼尼松 0.5～1mg/kg/日（逐渐减量至维持量，多数产后可停）；局部强效激素辅助；必要时氨苯砜 50～100mg qd（专科指导，孕期慎用）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物4（皮肤护理）：","用法：温和保湿剂（每日2～3次）；燕麦浴（止痒）；避免刺激性洗剂与搔抓","📌 妊娠期禁用四环素类、喹诺酮类、维A酸类与高剂量水杨酸；PUPPP产后数天至数周自愈；妊娠疱疹产后可加重并需长期随访（再次妊娠复发风险）。"],"treatment":["PUPPP治疗：局部中弱效激素+止痒（抗组胺药与炉甘石）、冷敷与温和保湿；重症短期口服/静脉激素；产后自愈（不需过早终止妊娠）","妊娠疱疹：系统激素（泼尼松 0.5～1mg/kg/日，逐渐减量）+ 局部强效激素；难治性用丙种球蛋白或氨苯砜；密切监测胎儿（生长受限与早产）","妊娠期丘疹性皮炎：局部激素+抗组胺药，必要时短期系统激素","ICP鉴别与处理：无原发皮损的瘙痒必须查总胆汁酸（ICP见妇产科条目，需胎儿监测与适时终止妊娠）","皮肤护理：温和清洁与保湿、燕麦浴、避免搔抓（剪短指甲、夜间戴棉手套）、穿宽松棉质衣物","胎儿监测（妊娠疱疹与其他重症）：胎儿生长超声、胎心监护与胎动计数","分娩与产后管理：PUPPP产后自愈、妊娠疱疹产后可能加重（继续激素并逐渐减量）、产后随访皮肤与新生儿（妊娠疱疹新生儿可有一过性皮疹）","宣教：多数妊娠期皮肤病产后自愈、瘙痒需先排除ICP（查胆汁酸）、用药需孕期安全、再次妊娠复发风险（妊娠疱疹）"],"management":["瘙痒与皮损评估：评估瘙痒程度（视觉模拟评分）、皮损分布与形态，记录变化","ICP排查执行：无原发皮损的瘙痒必须安排总胆汁酸与肝功能检查（不可仅按皮肤病处理）","用药护理：局部激素按部位与孕期安全使用（避免强效大面积长期）、口服药观察疗效与不良反应、静脉激素按医嘱减量","皮肤护理指导：温和清洁（温水短时）、保湿剂每日多次、燕麦浴止痒、避免搔抓与刺激性洗剂","胎儿监测配合：妊娠疱疹与重症者配合胎儿超声与胎心监护，指导胎动计数","心理护理：剧痒与睡眠障碍致焦虑明显，解释产后自愈与治疗安全性、提供心理支持","宣教：识别危险症状（无皮疹的瘙痒、黄疸）需查胆汁酸、按时用药与随访、产后皮疹可能加重（妊娠疱疹）需继续治疗"],"notes":["妊娠期无原发皮损的全身瘙痒（尤其手掌足底）必须查总胆汁酸排除ICP（可致胎儿死胎，需密切监测与适时终止妊娠）","PUPPP最常见（初产妇、妊娠晚期、妊娠纹处首发），产后自愈，治疗以局部激素与止痒为主","妊娠疱疹是自身免疫性大疱病（BP180抗体阳性），可致胎儿生长受限与早产，需系统激素与胎儿监测","妊娠期用药安全：泼尼松与多数抗组胺药相对安全；禁用四环素类、喹诺酮类与维A酸类","妊娠疱疹再次妊娠复发风险高，产后需皮肤科随访（可能产后加重）"],"emergency":["无皮疹的全身瘙痒伴黄疸（疑ICP）→ 立即查总胆汁酸与肝功能，产科评估胎儿监测与终止妊娠时机","妊娠疱疹大面积水疱伴发热与皮肤剥脱（继发感染/SJS样反应）→ 立即评估与抗感染、系统激素，必要时住院","瘙痒剧烈致严重失眠与情绪障碍 → 专科评估系统治疗与心理支持","胎动减少或胎心异常（妊娠疱疹/ICP相关胎儿风险）→ 立即产科评估与处理","皮肤感染扩散伴全身症状（蜂窝织炎/脓毒症）→ 静脉抗生素与住院治疗"],"pinyin":"rsqpfbbPUPPP","icd10":"O26.8","physical_exam":["皮损分布与形态：腹部妊娠纹处（PUPPP）、躯干四肢环形水疱（妊娠疱疹）、散在丘疹（丘疹性皮炎）","黏膜与面部：PUPPP与丘疹性皮炎多不累及面部与黏膜（妊娠疱疹亦少见）","皮肤抓痕与破损：瘙痒致抓痕、血痂与继发感染征象","黄疸与皮肤颜色：黄疸（ICP提示）、皮肤干燥","产科检查：宫高与腹围（胎儿生长）、胎心、宫缩与胎动","淋巴结：肿大（继发感染）","其他：下肢水肿（妊娠生理性或ICP）、血压（子痫前期鉴别）"],"lab_tests":["血清总胆汁酸+肝功能（必查无皮疹的瘙痒）：排除妊娠期肝内胆汁淤积症（ICP）","皮肤直接免疫荧光（DIF）+血清BP180抗体（疑妊娠疱疹）：诊断依据（盐裂皮肤DIF见IgG线状沉积）","皮肤活检（必要时）：PUPPP与妊娠疱疹病理鉴别","血常规+CRP（继发感染）：感染评估","胎儿超声（生长与羊水）+胎心监护：妊娠疱疹与重症者的胎儿监测","电解质+白蛋白（重症）：营养与渗出评估","产科常规检查：血压、尿蛋白（子痫前期）与血糖"],"nursing":["瘙痒护理：冷敷、燕麦浴、温和保湿剂、剪短指甲与夜间戴棉手套防搔抓，评估瘙痒与睡眠","用药护理：局部激素按部位与孕期安全性使用、口服抗组胺药与泼尼松按医嘱并观察疗效、静脉激素按医嘱减量","胎儿监测配合：妊娠疱疹与重症者配合胎心监护与超声检查，指导胎动计数（异常立即报告）","皮肤与感染观察：监测水疱、渗出、脓疱与发热，异常立即报告（妊娠疱疹感染风险）","心理护理：剧痒与睡眠障碍致焦虑，解释产后自愈与治疗安全性、提供情绪支持","宣教：无皮疹的瘙痒须查胆汁酸（ICP）、按时用药与随访、产后皮疹可能加重（妊娠疱疹）、再次妊娠复发风险"],"diet":["清淡易消化饮食，避免辛辣刺激、酒类与过量咖啡因（加重瘙痒）","均衡营养（高蛋白、高维生素），满足妊娠与皮肤修复需求","避免已知过敏食物（合并湿疹/过敏者）；必要时规范评估食物过敏","充足水分；多食富含维生素C与抗氧化物质食物","妊娠疱疹与重症者：保证热量与蛋白摄入（皮肤渗出损失增加）"],"topical_medication":["丁酸氢化可的松乳膏 涂患处 bid；炉甘石洗剂 涂患处 tid"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1447},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"2afe5ffb2d72a2bb172e82ae18bdb56dccdfebbdef446a27d75b7dca286ee105","pinyin":"renshenqipifubing（PUPPPyurenshensaoyang）","initials":"rsqpfb（yrssy）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","PUPPP：腹部妊娠纹处首发红色丘疹与荨麻疹样斑块，剧痒，逐渐扩展至大腿与四肢（面部与黏膜多不受累）\\n妊娠疱疹：躯干与四肢出现环形水疱与荨麻疹样斑块，剧痒，可于产后加重（自身免疫性）\\n妊娠期丘疹性皮炎：躯干与四肢散发红色丘疹（类似痒疹），剧痒\\n瘙痒（夜间加重）影响睡眠与情绪；抓痕与皮肤破损\\nICP区别：无原发皮损的全身瘙痒（尤其手掌足底）+ 胆汁酸升高（无皮疹是关键鉴别点）",60],["摘要","妊娠期特异性皮肤病包括妊娠瘙痒性荨麻疹性丘疹与斑块（PUPPP，最常见，初产妇妊娠晚期多发）、妊娠期肝内胆汁淤积症（ICP，见妇产科）、妊娠疱疹（疱疹样脓疱病，自身免疫性，需重视）、妊娠期多形性皮疹与妊娠期丘疹性皮炎。多对症治疗与产后自愈，但需与ICP及妊娠疱疹鉴别。",30],["疾病编码","O26.8",30],["原首字母","rsqpfbbPUPPP",60]]},{"id":"orders-2093385695571d69655a","key":"v1-c9ccc21dfe2a3058|orders-2093385695571d69655a","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"躯体形式障碍","category":"精神心理","raw":{"name":"躯体形式障碍","category":"精神心理","summary":"躯体形式障碍是一类以多种躯体症状为主诉、但检查无法完全用器质性疾病解释的精神障碍（包括躯体化障碍、未分化躯体形式障碍、疑病症、躯体形式的自主神经功能紊乱与持续性躯体形式疼痛障碍）。患者痛苦真实、反复就医，治疗以建立稳定医患关系、心理治疗（CBT）与谨慎用药为核心，避免过度检查与手术。","symptoms":["多种、反复、变化的躯体症状（疼痛、胃肠道不适、心悸、气促、头晕与假性神经系统症状）","症状持续≥2年（躯体化障碍）、反复就医与检查但无明确器质性发现","对健康的过度关注与焦虑（疑病症：担心患重病，反复检查与求医）","常伴焦虑、抑郁、失眠与功能障碍（工作与家庭）","医患关系紧张：对医师解释不信任、要求更多检查与治疗"],"diagnosis":["详细病史与全面体检：排除器质性疾病（不遗漏常见病，避免过度检查）","合理的基础检查：血常规、生化（肝肾功能、电解质、血糖、甲状腺功能）、心电图与必要的影像（按症状定位）","量表评估：躯体症状量表（PHQ-15/SSS-8）、焦虑抑郁量表（PHQ-9、GAD-7）与健康焦虑量表","排除物质与药物因素：酒精、镇静药与其他药物影响","精神科诊断标准（DSM-5）：躯体症状障碍（症状+对症状的过度关注与焦虑+病程≥6个月）","评估共病：抑郁障碍、焦虑障碍与人格特征","避免过度检查：反复无指征检查与手术可加重症状与医源性损害（需明确诊疗计划与边界）"],"infusion":["⚠️ 躯体形式障碍一般不需静脉治疗，静脉用药仅用于共病急性发作！","方案1（共病急性焦虑/惊恐发作）：","用法：0.9%氯化钠 静滴（建立静脉通路与安慰作用）；必要时地西泮 5～10mg 缓慢静推（慎用，短期）〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","方案2（严重失眠与兴奋）：","用法：0.9%氯化钠 静滴；必要时小剂量抗精神病药（奥氮平 2.5～5mg 口服/肌注）或苯二氮卓类（短期，避免依赖）","方案3（抑郁共病，需静脉治疗者）：","用法：0.9%氯化钠 静滴；抗抑郁药以口服为主（SSRI/SNRI），必要时静脉给药（如严重拒食水者支持治疗）","方案4（拒食与营养不良）：","用法：0.9%氯化钠/葡萄糖 静滴；维生素B族与电解质补充；必要时肠内营养","📌 静脉输液本身可能强化'疾病角色'（需谨慎使用并解释目的）；治疗核心是心理治疗与规律随访，避免过度检查与用药。"],"oral_medication":["⚠️ 药物为辅助（针对共病症状），避免多重用药与依赖：","药物1（抗抑郁药，一线，改善躯体症状与情绪）：","用法：舍曲林 50mg qd 或 帕罗西汀 20mg qd（SSRI）；或 度洛西汀 30～60mg qd、文拉法辛 75mg qd（SNRI，对躯体疼痛有效）；起效需2～4周","药物2（抗焦虑，短期）：","用法：劳拉西泮 0.5～1mg bid（短期，避免长期依赖）；丁螺环酮 5mg tid（非苯二氮卓类，无依赖）","药物3（睡眠与疼痛辅助）：","用法：曲唑酮 25～50mg qn（睡眠）；加巴喷丁 0.3g tid 或 普瑞巴林 75mg bid（疼痛症状，遵医嘱）","药物4（避免）：","用法：避免长期使用苯二氮卓类与阿片类药物（依赖与症状加重）；避免不必要的多种药物联合","📌 用药原则：单药、小剂量起始、以功能改善为目标（而非完全消除症状）；定期评估疗效与依赖风险。"],"treatment":["建立稳定、信任的医患关系（治疗核心）：定期规律随访（固定时间与频次）、认真倾听与共情、承认症状的真实性","单一医师负责制：避免多科重复检查与治疗冲突；制定明确的诊疗计划与检查边界（减少过度检查）","心理治疗：认知行为治疗（CBT，识别与改变症状相关认知与行为）、正念治疗与心理动力治疗","药物治疗（针对共病）：SSRI/SNRI 改善躯体症状与焦虑抑郁；短期抗焦虑药；避免长期苯二氮卓类与阿片类","功能康复：制定渐进活动计划（避免完全卧床与过度休息）、鼓励恢复正常工作与生活节奏","共病治疗：抑郁、焦虑与失眠同步治疗；酒精与药物依赖者转介戒断治疗","躯体疾病同步管理：确有器质性疾病时正常治疗（不因精神因素忽略躯体病）","随访与宣教：解释症状机制（'症状真实但检查未见异常，与情绪及神经系统敏感性相关'）、设定合理治疗目标（改善功能而非完全无症状）"],"management":["症状与功能评估：记录症状部位、频次与影响（PHQ-15、功能评估），避免仅凭主诉增加检查","沟通与共情护理：倾听与接纳症状真实体验、避免说'没什么病'或'心理作用'（易致对立）、解释检查结果与机制","诊疗计划执行：按约定的随访与检查计划执行、减少不必要的急诊就诊与检查（与患者共同制定'就医规则'）","用药管理与观察：按医嘱单药治疗、观察疗效与不良反应、评估依赖风险（苯二氮卓类）","活动与作息支持：协助制定渐进活动与作息计划、鼓励社交与工作回归","心理护理与转介：心理治疗配合、必要时转介心理科/精神科专科治疗","宣教：症状与情绪压力相关（非'装病'）、治疗需时间与耐心、规律随访比反复检查更有益、避免自行停药或滥用药物"],"notes":["躯体形式障碍患者痛苦真实，医患关系与合作是治疗基础；否认或轻描淡写症状会破坏治疗联盟","避免过度检查与手术（医源性损害、强化疾病角色）；应制定明确的诊疗计划与检查边界","单一医师负责制可减少多科重复检查与治疗冲突（是管理关键）","SSRI/SNRI 对躯体症状与共病焦虑抑郁有效（需2～4周起效，足疗程6～12个月）","避免长期苯二氮卓类与阿片类药物（依赖、耐受与症状加重）"],"emergency":["自杀意念或自伤行为 → 立即精神科评估、加强安全监护并移除危险物品","急性惊恐发作伴过度通气与手足搐搦 → 安抚、呼吸指导（缓慢腹式呼吸）、必要时短期苯二氮卓类","因躯体症状要求进行有创检查或手术（医源性风险）→ 多学科沟通、明确拒绝指征并做好解释与心理支持","拒食拒水伴脱水与电解质紊乱 → 静脉补液与营养支持+精神科评估","药物过量（自杀企图）→ 急诊洗胃/解毒与精神科会诊"],"pinyin":"xtxsza","icd10":"F45.9","physical_exam":["全面体检（不遗漏器质性疾病）：生命体征、心肺、腹部、神经系统与甲状腺","症状定位相关检查：按主诉部位重点检查（但避免过度）","精神状态：情绪（焦虑、抑郁）、思维内容（疑病观念）、对症状的关注度与解释方式","功能状态：日常活动、工作与社会功能（功能障碍程度）","皮肤与自伤痕迹：抓痕、注射痕迹（药物滥用）与自伤瘢痕","药物使用史：镇静药、镇痛药与中草药（依赖与相互作用）","社会心理因素：近期应激事件、家庭关系与经济压力"],"lab_tests":["血常规+生化（肝肾功能、电解质、血糖）+甲状腺功能：基础筛查（排除常见器质病）","心电图+必要影像（按症状定位）：合理检查，避免重复无指征检查","焦虑抑郁量表（PHQ-9、GAD-7）+躯体症状量表（PHQ-15）：评估共病与严重度","药物与酒精筛查（必要时）：物质相关因素","精神科量表评估（SSD/健康焦虑量表）：诊断与随访","按症状选择性检查（如胃肠道症状的内镜、心悸的动态心电图）：有指征时进行，避免撒网式检查"],"nursing":["沟通与共情：倾听并承认症状真实、避免否定性语言（'你没病'），建立信任关系（治疗基础）","随访与计划执行：按约定时间随访、配合单一医师负责制、减少不必要急诊与检查","用药护理：按医嘱单药治疗、观察疗效与不良反应、评估苯二氮卓类依赖风险","症状与功能记录：记录症状变化与日常活动量，鼓励渐进增加活动","心理护理：配合心理治疗、识别情绪与症状的关系、鼓励表达与压力管理技巧","宣教：解释症状机制与治疗目标（改善功能而非完全无症状）、规律随访的重要性、避免自行停药与滥用药物"],"diet":["规律进餐、均衡营养（避免因症状而过度限制饮食或盲目忌口）","避免过量咖啡因与酒精（加重心悸、焦虑与失眠）","胃肠症状明显者：少量多餐、避免刺激性食物（但避免过度限制导致营养不良）","充足饮水与膳食纤维（改善便秘等常见症状）","必要时营养评估与补充（体重下降或拒食者）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1448},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1953be4cb4d97ef07323fa11f145c9cd9bde95b2c24de028d59481929118fae6","pinyin":"qutixingshizhangai","initials":"qtxsza","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","多种、反复、变化的躯体症状（疼痛、胃肠道不适、心悸、气促、头晕与假性神经系统症状）\\n症状持续≥2年（躯体化障碍）、反复就医与检查但无明确器质性发现\\n对健康的过度关注与焦虑（疑病症：担心患重病，反复检查与求医）\\n常伴焦虑、抑郁、失眠与功能障碍（工作与家庭）\\n医患关系紧张：对医师解释不信任、要求更多检查与治疗",60],["摘要","躯体形式障碍是一类以多种躯体症状为主诉、但检查无法完全用器质性疾病解释的精神障碍（包括躯体化障碍、未分化躯体形式障碍、疑病症、躯体形式的自主神经功能紊乱与持续性躯体形式疼痛障碍）。患者痛苦真实、反复就医，治疗以建立稳定医患关系、心理治疗（CBT）与谨慎用药为核心，避免过度检查与手术。",30],["疾病编码","F45.9",30],["原首字母","xtxsza",60]]},{"id":"orders-59792ff6bcc4a946bf5b","key":"v1-c9ccc21dfe2a3058|orders-59792ff6bcc4a946bf5b","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"酒精戒断综合征","category":"精神心理","raw":{"name":"酒精戒断综合征","category":"精神心理","summary":"酒精戒断综合征是长期大量饮酒者突然减少或停止饮酒后出现的症状群，轻者震颤、出汗、焦虑与失眠，重者出现戒断性癫痫发作、酒精性幻觉与震颤谵妄（DT，病死率可达5%～15%）。处理核心是苯二氮卓类替代治疗、补充维生素B1（防Wernicke脑病）与电解质纠正。","symptoms":["戒断早期（6～12小时）：手抖、出汗、恶心呕吐、焦虑、失眠与心率增快","戒断性癫痫发作（12～48小时）：全身强直-阵挛发作（可反复）","酒精性幻觉（12～48小时）：幻视或幻听（意识多清醒）","震颤谵妄（48～96小时）：意识模糊、定向障碍、幻觉、剧烈震颤、发热、大汗与心动过速（危急）","自主神经兴奋：血压升高、心率增快（>100次/分）、瞳孔扩大与体温升高"],"diagnosis":["饮酒史与戒断时间：末次饮酒时间、每日饮酒量与年限（关键病史）","戒断评估量表（CIWA-Ar）：评估严重度（≥10分需药物治疗，≥20分为重度）","电解质（钾、镁、磷、钙）+血糖+肾功能+肝功能：低钾、低镁、低磷与低血糖常见（酒精性）","血气分析+血氨：酸碱失衡与肝性脑病鉴别","头颅CT（癫痫发作、意识障碍或外伤史）：排除颅内病变与出血","维生素B1水平与神经系统评估：Wernicke脑病（眼肌麻痹、共济失调、意识障碍三联征）","鉴别诊断：肝性脑病、低血糖、颅内感染、药物中毒、甲状腺功能亢进与精神疾病"],"infusion":["⚠️ 苯二氮卓类替代+补充维生素B1是核心，须监测呼吸！","方案1（苯二氮卓类替代，地西泮方案）：","用法：地西泮 10mg 静推（缓慢，>5分钟）q10～15min 直至症状控制（CIWA-Ar降至<10），随后 10mg 静推 q1～4h 或口服减量方案（按症状评分给药）；或 劳拉西泮 2～4mg 静推 q15min（肝功能不全者首选，代谢不受肝影响）〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","方案2（维生素B1与营养支持，必用）：","用法：维生素B1 100mg 静推/肌注 qd（或 100mg 静滴，连用3～5天，之后口服100mg qd）——必须在补充葡萄糖之前给予；复合维生素B 2ml 肌注 qd","方案3（电解质与补液）：","用法：0.9%氯化钠 1000ml + 10%氯化钾 10～20ml 静滴（补钾，监测血钾与尿量）；25%硫酸镁 10ml + 0.9%氯化钠 250ml 静滴（低镁）；10%葡萄糖 静滴（低血糖或营养不良者，须在B1之后）","方案4（震颤谵妄/重症）：","用法：地西泮 10mg 静推 q10～15min 至镇静（需监护呼吸与血氧）；或 咪达唑仑 0.05～0.2mg/kg/h 泵入（ICU）；氟哌啶醇 5mg 肌注（幻觉与激越，慎用）；必要时转ICU〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","📌 维生素B1必须在葡萄糖之前给予（防诱发Wernicke脑病）；地西泮静推须缓慢并监测呼吸；震颤谵妄病死率高需ICU监护。"],"oral_medication":["⚠️ 稳定期口服替代与长期维持：","药物1（苯二氮卓类口服减量方案）：","用法：地西泮 10mg tid 起（或按CIWA-Ar评分给药），每1～2天减量20%～25%，7～10天减停；肝功能不全者用 劳拉西泮 2mg tid（代谢不受肝影响）〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","药物2（维生素与营养）：","用法：维生素B1 100mg qd（口服，长期）；复合维生素B 2片 tid；叶酸 5mg qd；维生素C 0.2g tid","药物3（戒酒维持与防复发）：","用法：纳曲酮 50mg qd（阿片受体拮抗剂，减少渴求）；或 阿坎酸 666mg tid；双硫仑 250mg qd（需完全戒酒，遵医嘱）","药物4（共病与对症）：","用法：抗抑郁药（抑郁共病，SSRI）；戒酒硫样药物避免与含酒精制剂同用；睡眠障碍者短期曲唑酮 25～50mg qn","📌 戒酒治疗需综合干预（药物+心理+社会支持）；苯二氮卓类仅短期用于戒断（避免长期依赖）；纳曲酮需肝功能正常（监测肝酶）。"],"treatment":["苯二氮卓类替代治疗（核心）：按CIWA-Ar评分给药（症状触发方案），逐渐减量7～10天（地西泮或劳拉西泮；肝功能不全者选劳拉西泮）","维生素B1补充（必用）：100mg 静推/肌注（在葡萄糖之前），预防Wernicke脑病与Korsakoff综合征","电解质与营养纠正：补钾、补镁、补磷与补液；低血糖处理（葡萄糖）；营养支持（酒精性营养不良常见）","震颤谵妄处理：大剂量苯二氮卓类（地西泮静推或咪达唑仑泵入）+ICU监护+氟哌啶醇（幻觉激越）+环境安静与约束保护","癫痫发作处理：苯二氮卓类为主（避免长期抗癫痫药），持续发作者按癫痫持续状态处理","共病治疗：肝病、胰腺炎、周围神经病变与认知障碍评估；抑郁焦虑治疗（戒酒后评估）","戒酒康复：纳曲酮/阿坎酸/双硫仑（防复发）+心理治疗（CBT）+社会支持（戒酒互助组织）","宣教与随访：告知戒断风险（不可自行突然停酒）、长期戒酒与康复计划、家属参与支持、再次饮酒风险识别"],"management":["戒断症状监测：按时评估CIWA-Ar评分（每1～4小时），记录震颤、出汗、心率、血压与意识状态","安全护理：防跌倒与外伤（震颤与共济失调）、癫痫发作时保护气道与安全、震颤谵妄者加床档与必要时约束","用药护理：苯二氮卓类按评分给药并监测呼吸（静推缓慢）、维生素B1在葡萄糖之前给予、观察电解质纠正效果","液体与电解质管理：记录出入量、监测血钾、镁、磷与血糖（每4～6小时，急性期）","营养护理：高蛋白高维生素饮食、少量多餐；不能进食者静脉营养与鼻饲","心理护理：戒断期焦虑与幻觉致恐惧，需安静环境、减少刺激、安抚解释并陪伴","宣教：不可自行突然停酒（戒断可致命）、长期戒酒与康复治疗、家属支持与识别复饮征象、随访计划"],"notes":["酒精戒断可危及生命（震颤谵妄病死率5%～15%），需按CIWA-Ar评分规范使用苯二氮卓类","维生素B1必须在葡萄糖之前给予（葡萄糖可耗竭B1并诱发Wernicke脑病）","肝功能不全者首选劳拉西泮（不经肝代谢），避免地西泮蓄积","低钾、低镁与低磷在酒精性患者常见（需积极纠正，防心律失常与谵妄加重）","长期戒酒需药物（纳曲酮/阿坎酸）+心理治疗+社会支持综合干预（单纯急性期治疗复发率高）"],"emergency":["震颤谵妄（意识模糊、幻觉、剧烈震颤、发热与心动过速）→ 大剂量苯二氮卓类+ICU监护，纠正电解质","戒断性癫痫发作持续或反复 → 地西泮静推+负荷抗癫痫药，评估头颅CT","严重低钾/低镁伴心律失常 → 积极补钾补镁并心电监护","低血糖昏迷 → 立即静推葡萄糖（在B1之后或同时给予B1）","Wernicke脑病（眼肌麻痹、共济失调、意识障碍）→ 立即大剂量维生素B1静脉治疗（不可延误）"],"pinyin":"jjdjzhz","icd10":"F10.3","physical_exam":["生命体征：体温（震颤谵妄可发热）、心率（增快>100次/分）、血压（升高）、呼吸","意识与定向力：意识模糊、定向障碍、注意力不集中（震颤谵妄）","震颤与自主神经：手抖（粗大震颤）、出汗、瞳孔扩大、皮肤潮红","神经系统：眼肌麻痹与共济失调（Wernicke脑病）、腱反射、病理反射与癫痫发作后状态","肝病体征：黄疸、蜘蛛痣、肝掌、肝脾大小与腹水（酒精性肝病）","营养状态：消瘦、肌肉萎缩、口角炎与舌炎（营养不良）","外伤：头部与四肢外伤（跌倒与癫痫发作所致）"],"lab_tests":["电解质（钾、镁、磷、钙）+血糖+肾功能：低钾、低镁、低磷与低血糖（酒精性常见）每4～6小时（急性期）","肝功能+白蛋白+胆红素+凝血功能：酒精性肝病与预后评估","血常规（MCV升高提示长期饮酒）+血小板：酒精性骨髓抑制评估","血气分析+血氨：酸碱失衡与肝性脑病鉴别","维生素B1水平（如可测）+神经系统评估：Wernicke脑病诊断","头颅CT/MRI：癫痫发作、意识障碍或外伤史（排除颅内病变）","心电图：心律失常（电解质紊乱与酒精性心肌病）"],"nursing":["戒断评估：按时评估CIWA-Ar评分并记录震颤、出汗、心率与意识，异常立即报告","安全护理：防跌倒（震颤与共济失调）、床档保护、癫痫发作时保护气道与安全、必要时约束","用药护理：苯二氮卓类按评分给药（静推缓慢并监测呼吸）、维生素B1在葡萄糖前给予、观察疗效与过度镇静","电解质与血糖监测：按时复查血钾、镁、磷与血糖，观察心律失常与抽搐（低钾低镁）","营养与饮食护理：高蛋白高维生素饮食、少量多餐；补充B族维生素与叶酸；必要时鼻饲或静脉营养","心理护理：安静环境、减少刺激、安抚幻觉与焦虑、陪伴与解释，减少约束使用","宣教：不可自行突然停酒（可致命）、长期戒酒与康复计划、家属支持与识别复饮、按时随访"],"diet":["高蛋白、高热量、高维生素饮食（酒精性营养不良常见）；少量多餐","补充B族维生素（尤其B1）、叶酸与维生素C；必要时口服营养补充剂","纠正低镁与低钾：富含钾（香蕉、橙子、土豆，肾功能正常者）与镁（坚果、绿叶蔬菜）的食物","急性期不能进食者：静脉营养（含维生素B1）或鼻饲","绝对禁酒（包括含酒精饮料与含酒精药物制剂）；避免咖啡因（加重焦虑与失眠）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1449},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"eed27c6b442b2ba1c2c97dd580a000f79d26a8463135259ed7e9b4d0db1b78f2","pinyin":"jiujingjieduanzonghezheng","initials":"jjjdzhz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","戒断早期（6～12小时）：手抖、出汗、恶心呕吐、焦虑、失眠与心率增快\\n戒断性癫痫发作（12～48小时）：全身强直-阵挛发作（可反复）\\n酒精性幻觉（12～48小时）：幻视或幻听（意识多清醒）\\n震颤谵妄（48～96小时）：意识模糊、定向障碍、幻觉、剧烈震颤、发热、大汗与心动过速（危急）\\n自主神经兴奋：血压升高、心率增快（>100次/分）、瞳孔扩大与体温升高",60],["摘要","酒精戒断综合征是长期大量饮酒者突然减少或停止饮酒后出现的症状群，轻者震颤、出汗、焦虑与失眠，重者出现戒断性癫痫发作、酒精性幻觉与震颤谵妄（DT，病死率可达5%～15%）。处理核心是苯二氮卓类替代治疗、补充维生素B1（防Wernicke脑病）与电解质纠正。",30],["疾病编码","F10.3",30],["原首字母","jjdjzhz",60]]},{"id":"orders-59e0ae8d30e907993e82","key":"v1-c9ccc21dfe2a3058|orders-59e0ae8d30e907993e82","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"自杀风险评估与危机干预","category":"精神心理","raw":{"name":"自杀风险评估与危机干预","category":"精神心理","summary":"自杀风险评估是识别自杀意念、计划与风险因素并采取干预措施的过程，属精神科急症。高危因素包括既往自杀企图、精神障碍（抑郁、双相、精神分裂、物质依赖）、社会支持缺乏、重大丧失与慢性疾病。干预包括安全监护、环境安全管理、治疗原发病与危机随访。","symptoms":["自杀意念（被动想死 → 主动自杀想法）与计划（方式、时间、地点与准备行为）","绝望感、无价值感与'安排后事'行为（写遗书、赠送物品、告别）","情绪激越或异常平静（决定自杀后）","精神症状：命令性幻听、被害妄想（精神分裂症）","高危行为：囤积药物、获取工具、搜索自杀方法、既往自杀未遂史"],"diagnosis":["直接询问（必做）：是否有自杀想法、计划、方式、可及性与准备行为（询问不会'植入'自杀意念）","风险评估工具：C-SSRS（哥伦比亚自杀严重程度评定量表）、PHQ-9第9题、Beck绝望量表","精神障碍评估：抑郁、双相、精神分裂症、物质依赖与人格障碍（近期诊断与治疗情况）","风险因素清单：既往自杀企图（最强预测因素）、家族自杀史、近期重大丧失（离婚、丧亲、失业）、慢性疾病与疼痛、社会隔离与冲动性","保护因素评估：家庭支持、生活责任（子女）、宗教信仰、治疗联盟与求助意愿","躯体与药物评估：药物过量风险（家中药物）、酒精与物质使用","自杀方式可及性评估：家中药物、农药、锐器与高处可及性（决定安全干预措施）"],"infusion":["⚠️ 危机期以口服治疗与安全监护为主，静脉用药用于重症与激越！","方案1（严重激越与精神症状）：","用法：氟哌啶醇 5mg 肌注（或 奥氮平 5～10mg 肌注）；必要时重复（监测锥体外系反应与心电图QT）","方案2（重度焦虑与失眠，短期）：","用法：劳拉西泮 1～2mg 静推/肌注（短期，监测呼吸与镇静程度）；避免用于有药物过量风险者（限制药量）","方案3（抑郁障碍需快速起效或拒食）：","用法：0.9%氯化钠/葡萄糖 静滴（补液与支持）；抗抑郁药以口服为主（必要时氯胺酮静脉治疗，需精神科专科与监护）","方案4（药物过量后抢救）：","用法：按毒物处理（洗胃、活性炭、解毒剂与血液净化）；同时精神科评估与安全监护","📌 危机期用药需限制总量（防过量）并由家属保管；静脉镇静药慎用（可能掩盖意识变化）；治疗原发精神障碍是根本。"],"oral_medication":["⚠️ 药物治疗原发精神障碍（需限制药量与家属保管）：","药物1（抑郁障碍，一线）：","用法：舍曲林 50mg qd 或 艾司西酞普兰 10mg qd（起效2～4周，早期可能增加自杀风险，需密切随访）","药物2（双相障碍/激越）：","用法：喹硫平 50～200mg qn 或 奥氮平 5～10mg qn（监测代谢与镇静）；碳酸锂（需监测血药浓度）","药物3（精神分裂症/命令性幻听）：","用法：奥氮平 10mg qn 或 利培酮 2mg bid（按精神科方案）","药物4（焦虑与失眠，短期小量）：","用法：劳拉西泮 0.5～1mg qn（限制药量，家属保管）；曲唑酮 25～50mg qn（睡眠）","📌 抗抑郁药早期（1～2周）可能增加自杀风险（需密切随访与家属监护）；所有药物应由家属保管并限制总量（防过量）。"],"treatment":["安全第一：环境安全管理（移除危险物品与药物、窗户限位、锐器管理）、专人陪护（不独处）、必要时保护性约束（按规范）","精神科评估与诊断：明确原发精神障碍（抑郁、双相、精神分裂症、物质依赖）并制定治疗方案","住院治疗指征：高自杀风险（有具体计划与准备）、精神病性症状、缺乏社会支持或门诊治疗无效者","药物治疗：抗抑郁药（抑郁）、心境稳定剂（双相）、抗精神病药（精神分裂症）；短期抗焦虑药；限制药量","心理治疗：危机干预（倾听、共情、problem-solving）、认知行为治疗（CBT）、辩证行为治疗（DBT，边缘型人格）","社会支持干预：家庭参与（安全教育、药物保管）、社会资源连接、就业与经济支持","随访与安全计划：制定书面'安全计划'（预警信号、应对策略、求助联系人）、24～48小时内随访（高危者）、24小时热线","宣教：自杀意念可治疗、既往企图是最强预警、家属监护与药物管理、避免酒精与物质使用"],"management":["安全监护：高危者专人陪护（不可独处）、移除危险物品（药物、锐器、绳索）、夜间与凌晨（高发时段）加强巡视","直接沟通与共情：直接询问自杀意念（不回避）、倾听与接纳、避免说教与评判，建立信任关系","环境安全管理：病室危险物品清单检查（每班）、窗户限位与卫生间巡视、药物由医护/家属保管并记录","药物管理：限制单次发药量（尤其抗抑郁药与镇静药）、每次服药后检查口腔（防藏药）、记录药量","观察与记录：情绪变化（异常平静或激越）、'安排后事'行为、睡眠与进食，异常立即报告","家属沟通与教育：告知风险与监护要求、药物保管、预警信号识别与紧急联系方式","随访与安全计划：出院前制定书面安全计划与随访安排（24～48小时内联系）、提供心理危机热线、确保复诊"],"notes":["直接询问自杀意念不会'植入'自杀想法，是评估的必要步骤（回避询问是常见错误）","既往自杀企图是最强的预测因素；'安排后事'与情绪突然平静可能提示已决定自杀（高危信号）","抗抑郁药治疗早期（1～2周）可能增加自杀风险，需密切随访与家属监护","高危者应住院治疗（有具体计划与准备、精神病性症状、缺乏支持），并实施环境安全管理","出院前必须制定书面安全计划与短期随访（24～48小时），单纯'嘱咐'不足"],"emergency":["正在实施自杀行为（服药、割腕、高处）→ 立即抢救（气道、循环、解毒与外科处理）+精神科会诊与安全监护","有具体自杀计划且工具可及 → 立即住院（精神科封闭病房）、环境安全管理与专人陪护","命令性幻听指示自伤 → 立即抗精神病药治疗并加强监护（精神科急症）","自杀未遂后（药物过量）→ 按毒物处理（洗胃、活性炭、解毒剂）并精神科评估随诊","严重激越伴攻击行为 → 短期镇静（氟哌啶醇/奥氮平）与保护性约束（按规范，监测生命体征）"],"pinyin":"zsfxpgYwjgy","icd10":"R45.851","physical_exam":["生命体征与意识：意识状态、瞳孔与生命体征（药物过量与外伤评估）","外伤检查：腕部切割伤、颈部伤痕、药物过量征象（瞳孔、心率与呼吸抑制）","精神状态：情绪（抑郁/激越/异常平静）、思维内容（自杀意念、绝望感、妄想）、知觉（幻听）","自杀准备征象：随身物品（遗书、药物）、身体伤痕与既往自杀痕迹（陈旧瘢痕）","物质使用征象：酒精气味、注射痕迹、瞳孔改变","躯体疾病：慢性疼痛、晚期疾病与功能障碍（自杀风险因素）","社会支持评估：有无家属陪伴与联系方式（保护因素与监护资源）"],"lab_tests":["毒物筛查+血药浓度（药物过量者）：确定毒物种类与程度（指导解毒）","电解质+血糖+肝肾功能+血气分析：过量与躯体状态评估","心电图：药物过量（三环类抗抑郁药致QT延长）与电解质紊乱","甲状腺功能+血常规：躯体疾病相关抑郁评估（甲减、贫血）","精神科量表：C-SSRS（自杀严重程度）、PHQ-9（含第9题）、GAD-7、Beck绝望量表","酒精与物质检测：物质依赖评估","头颅CT（意识障碍或外伤）：必要时"],"nursing":["安全监护：高危者专人陪护（不独处）、每班检查危险物品、夜间与凌晨加强巡视、卫生间与窗户管理","沟通与共情：直接询问自杀意念并倾听接纳、避免评判与说教、表达关心与陪伴","药物管理：限制单次药量、服药后检查口腔（防藏药）、药物由医护或家属保管并记录","行为观察与记录：情绪变化（异常平静/激越）、安排后事行为、睡眠与进食，异常立即报告","环境安全：移除锐器、绳索与药物，窗户限位，保持病室简洁（减少可用于自伤的物品）","家属教育与随访：告知风险与监护要求、药物保管、预警信号与紧急联系方式、出院前安全计划与随访安排"],"diet":["保证规律进食与充足水分（拒食者需静脉营养支持）","避免酒精与咖啡因（加重抑郁、焦虑与冲动）","均衡饮食、少量多餐；营养不良者补充蛋白与维生素","药物（如锂盐）治疗者：保持稳定盐分摄入（低盐可致锂中毒）","与家属共同进餐（增进支持与观察进食情况）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1450},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"84390b74109b2a7d4c92c5a414b68b556b05e23ec151fc64cd11b04171e982c1","pinyin":"zishafengxianpingguyuweijiganyu","initials":"zsfxpgywjgy","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","自杀意念（被动想死 → 主动自杀想法）与计划（方式、时间、地点与准备行为）\\n绝望感、无价值感与'安排后事'行为（写遗书、赠送物品、告别）\\n情绪激越或异常平静（决定自杀后）\\n精神症状：命令性幻听、被害妄想（精神分裂症）\\n高危行为：囤积药物、获取工具、搜索自杀方法、既往自杀未遂史",60],["摘要","自杀风险评估是识别自杀意念、计划与风险因素并采取干预措施的过程，属精神科急症。高危因素包括既往自杀企图、精神障碍（抑郁、双相、精神分裂、物质依赖）、社会支持缺乏、重大丧失与慢性疾病。干预包括安全监护、环境安全管理、治疗原发病与危机随访。",30],["疾病编码","R45.851",30],["原首字母","zsfxpgYwjgy",60]]},{"id":"orders-b4779e45b873c3bf95aa","key":"v1-c9ccc21dfe2a3058|orders-b4779e45b873c3bf95aa","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"吞咽障碍康复","category":"康复医学","raw":{"name":"吞咽障碍康复","category":"康复医学","summary":"吞咽障碍是脑卒中、颅脑外伤、帕金森病、头颈部肿瘤与老年衰弱患者常见功能障碍，可致误吸、吸入性肺炎、脱水与营养不良。康复包括临床与仪器评估（洼田饮水试验、VFSS与FEES）、间接与直接训练（口腔运动、感觉刺激、姿势调整、食物性状调整）与并发症防治。","symptoms":["进食或饮水时呛咳、哽噎感、食物滞留于口腔","流涎、口腔食物残留、吞咽后声音'湿哑'（湿性嗓音）","进食时间延长、进食量减少、体重下降与脱水","隐性误吸（无呛咳但反复肺部感染、发热）","心理社会影响：进食恐惧、拒绝进食与社交回避"],"diagnosis":["临床筛查：洼田饮水试验（30ml温水，观察时间与呛咳）、反复唾液吞咽试验与EAT-10问卷","吞咽功能评估：口唇、舌、软腭运动与感觉，咽反射、咳嗽反射与自主咳嗽能力","电视透视吞咽检查（VFSS，金标准）：动态观察各期吞咽与误吸（可量化）","纤维内镜吞咽检查（FEES）：床旁可行，观察咽部残留与误吸（尤其分泌物管理）","营养与水分评估：体重、白蛋白、前白蛋白与出入量","误吸风险评估：咳嗽反射减弱、声带麻痹、气管切开与意识障碍者风险高","病因评估：脑卒中部位（脑干/双侧半球）、帕金森病、头颈部肿瘤治疗史与神经肌肉疾病"],"infusion":["⚠️ 吞咽障碍以康复训练为主，静脉用药用于并发症与营养支持！","方案1（吸入性肺炎，抗感染）：","用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h（覆盖厌氧菌）；按痰培养调整〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案2（脱水与电解质紊乱）：","用法：0.9%氯化钠 1000ml + 10%氯化钾 10～20ml 静滴（按脱水程度与血钾调整）；平衡盐溶液补液","方案3（营养支持，不能经口进食）：","用法：全肠外营养（葡萄糖+氨基酸+脂肪乳+电解质+维生素）经中心静脉；白蛋白 10g 静滴（低蛋白者）","方案4（病因相关，如帕金森病）：","用法：0.9%氯化钠 静滴；左旋多巴（口服/鼻饲，按方案）；必要时调整多巴胺能药物（在餐前30分钟给药以改善吞咽）","📌 吞咽障碍治疗核心是康复训练与食物性状调整；避免在评估前经口喂食（误吸风险）；严重者需鼻胃管或经皮胃造瘘（PEG）营养支持。"],"oral_medication":["⚠️ 以康复训练为主，药物注意剂型与给药途径：","药物1（促吞咽功能与神经康复，辅助）：","用法：甲钴胺 0.5mg tid；维生素B1 10mg tid；尼莫地平（脑卒中后，遵医嘱）","药物2（减少唾液分泌，防误吸）：","用法：格隆溴铵 1mg bid（抗胆碱能，注意认知与口干副作用）或 东莨菪碱贴剂（按医嘱）","药物3（帕金森病相关吞咽障碍）：","用法：左旋多巴/卡比多巴 按方案（餐前30分钟给药，改善吞咽的'关期'问题）；避免与高蛋白餐同服（影响吸收）","药物4（营养补充）：","用法：口服营养补充剂（增稠型，2～3份/日）；维生素与微量元素补充；必要时使用增稠剂调整食物性状","📌 药物剂型需考虑吞咽能力（液体、颗粒或可碾碎片剂，注意缓释片不可碾碎）；增稠剂需按评估结果选择浓度。"],"treatment":["间接训练（不进食）：口腔运动训练（唇、舌、颊与下颌）、感觉刺激（冷刺激、酸刺激）、门德尔松手法、声门上吞咽法、用力吞咽法与Shaker训练","直接训练（进食训练）：姿势调整（低头吞咽、头转向患侧、侧方吞咽）、食物性状调整（糊状→半流质→软食→普食，按评估结果）、一口量控制（3～5ml起始）","食物性状与增稠：使用增稠剂（花蜜状/蜂蜜状/布丁状），避免稀薄液体（误吸风险高）与混合质地食物（如汤泡饭）","物理治疗与神经调控：神经肌肉电刺激（NMES，刺激舌骨上肌群）、经颅磁刺激（rTMS，研究支持）、生物反馈","代偿策略与环境：进食时坐位90°、头颈中立、专心进食（避免说话与看电视）、餐后保持坐位30～60分钟、口腔清洁","营养支持：经口不足者鼻胃管（短期）或经皮胃造瘘（PEG，长期>4周）；营养师制定个体化配方","并发症处理：吸入性肺炎（抗感染）、脱水与营养不良（补液与营养支持）、气道管理（气管切开者分泌物处理）","随访与宣教：定期复评（VFSS/FEES）、家庭训练指导与照顾者培训（喂食技巧、急救方法）、预防误吸（口腔卫生、疫苗接种）"],"management":["进食前评估与准备：确认进食体位（坐位90°或床头抬高≥60°）、食物性状与一口量，进食前评估意识与咳嗽能力","进食过程监护：观察呛咳、湿性嗓音、食物残留与呼吸变化；出现呛咳立即停止喂食、清理口腔并评估","口腔护理（每日2～3次）：减少口腔细菌（降低吸入性肺炎风险，是重要循证措施）","体位与姿势管理：餐后保持坐位30～60分钟（防反流误吸）、夜间床头抬高、避免平卧进食","训练执行与记录：按康复计划执行训练（每日多次，短时高频）、记录训练内容与进展","营养与水分监测：记录进食量、体重与出入量；经口不足者遵医嘱补充（鼻饲/ONS）","照顾者培训：正确喂食技巧（小口、慢速、确认吞咽完成）、食物制备与增稠、呛咳急救（海姆立克法）","宣教：吞咽障碍可改善（需坚持训练）、疫苗（流感与肺炎球菌）接种、口腔卫生重要性、误吸征象识别与就医"],"notes":["吞咽障碍评估前不应经口喂食（误吸风险）；洼田饮水试验为筛查手段，确诊需VFSS或FEES","隐性误吸（无呛咳）在老年与脑卒中患者中常见，需警惕不明原因发热与肺部感染","稀薄液体误吸风险高（流速快），用增稠剂调整至合适浓度可显著降低风险","口腔护理是降低吸入性肺炎的循证措施（每日2～3次），常被忽视","经口进食不足4周以上者应考虑经皮胃造瘘（PEG）；鼻胃管长期留置增加鼻窦炎、反流与肺炎风险"],"emergency":["进食中突发呛咳、呼吸困难与发绀（窒息/严重误吸）→ 立即停止喂食、清理气道、海姆立克法或吸引，必要时气管插管","发热伴咳嗽与肺部浸润（吸入性肺炎）→ 抗感染+吸氧，必要时住院","脱水与电解质紊乱（进食进水不足）→ 静脉补液纠正并调整营养支持途径","鼻胃管脱出或堵塞 → 评估并重新置管（避免盲目插管致误吸）","气管切开患者分泌物增多伴呼吸困难 → 立即吸痰、检查套管与气囊，必要时更换套管"],"pinyin":"tyzzkf","icd10":"R13","physical_exam":["意识与认知：意识水平与配合能力（影响训练与进食安全）","口面部检查：口唇闭合、舌运动与力量、软腭上抬、颊肌力量与面部感觉","咽部功能：咽反射、咳嗽反射（自主与反射性）、声音质量（湿性嗓音）与音质变化","颈部与气道：喉上抬（吞咽时）、气管切开套管与气囊状态、颈部淋巴结","营养与水分：体重、BMI、皮肤弹性、口腔黏膜湿润度与肌肉量","肺部：呼吸音与啰音（误吸与肺炎征象）、血氧","功能状态：坐位平衡与耐力（进食体位要求）、日常生活活动能力"],"lab_tests":["洼田饮水试验+EAT-10问卷：临床筛查（洼田：30ml水，Ⅰ级5秒内一次饮完无呛咳为正常）","电视透视吞咽检查（VFSS）：金标准，动态评估各期吞咽与误吸（可量化）","纤维内镜吞咽检查（FEES）：床旁评估（观察分泌物、残留与误吸）","营养指标：白蛋白、前白蛋白、血红蛋白与体重（营养评估）","电解质+肾功能：脱水与电解质紊乱评估","胸部影像（疑误吸/肺炎）：胸片或CT","病因相关检查：头颅MRI（脑卒中部位）、肌电图（神经肌肉疾病）与内镜（头颈部肿瘤）"],"nursing":["进食护理：体位（坐位90°或床头≥60°）、食物性状与一口量确认、喂食速度慢、确认吞咽完成后给下一口","误吸观察与处理：呛咳、湿性嗓音、呼吸变化立即停止喂食并清理口腔；备吸引器与急救设备","口腔护理：每日2～3次（刷牙、含漱与黏膜清洁），减少细菌定植（降低吸入性肺炎）","体位管理：餐后坐位30～60分钟、夜间床头抬高、避免平卧进食与立即平卧","营养与水分监测：记录进食量、体重与出入量；经口不足者配合鼻饲或ONS补充","训练配合与记录：按康复计划执行训练（口腔运动、冷刺激与吞咽手法），记录进展与耐受","照顾者培训与宣教：喂食技巧、增稠剂使用、呛咳急救（海姆立克法）、口腔卫生与疫苗接种"],"diet":["按评估结果选择食物性状：糊状→半流质→软食→普食（循序渐进，避免稀薄液体与混合质地食物）","使用增稠剂将液体调至合适浓度（花蜜状/蜂蜜状），避免稀水与清汤","高蛋白、高热量、易吞咽的食物（蒸蛋、豆腐、鱼肉泥、酸奶）；必要时口服营养补充剂","一口量控制（3～5ml起始），小口慢咽，避免大块与干燥食物（如馒头、坚果）","餐后保持坐位30～60分钟；口腔卫生（餐后漱口与刷牙）；避免饮酒与辛辣刺激（刺激分泌物）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1451},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"0006a2c2757f9e16725eeb83bced9a9008aa59a6f931bfac69d5eaa450fac0e0","pinyin":"tunyanzhangaikangfu","initials":"tyzakf","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","进食或饮水时呛咳、哽噎感、食物滞留于口腔\\n流涎、口腔食物残留、吞咽后声音'湿哑'（湿性嗓音）\\n进食时间延长、进食量减少、体重下降与脱水\\n隐性误吸（无呛咳但反复肺部感染、发热）\\n心理社会影响：进食恐惧、拒绝进食与社交回避",60],["摘要","吞咽障碍是脑卒中、颅脑外伤、帕金森病、头颈部肿瘤与老年衰弱患者常见功能障碍，可致误吸、吸入性肺炎、脱水与营养不良。康复包括临床与仪器评估（洼田饮水试验、VFSS与FEES）、间接与直接训练（口腔运动、感觉刺激、姿势调整、食物性状调整）与并发症防治。",30],["疾病编码","R13",30],["原首字母","tyzzkf",60]]},{"id":"orders-457ea893120012e5d32f","key":"v1-c9ccc21dfe2a3058|orders-457ea893120012e5d32f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"失语症康复","category":"康复医学","raw":{"name":"失语症康复","category":"康复医学","summary":"失语症是脑损伤（多为左侧大脑半球卒中）导致的语言功能损害，表现为听、说、读、写障碍。按类型分为运动性（Broca，表达障碍）、感觉性（Wernicke，理解障碍）、传导性、命名性、经皮质与完全性失语。康复以语言训练为核心，配合药物与心理支持，早期介入与高频训练效果最佳。","symptoms":["表达障碍：找词困难、言语不流畅、电报式语言（运动性失语）","理解障碍：听不懂他人言语、答非所问（感觉性失语）","复述障碍：不能复述词句（传导性失语）","命名障碍：说不出物品名称（命名性失语）","读写障碍（失读、失写）与伴随症状：右侧偏瘫、视野缺损与构音障碍"],"diagnosis":["语言功能评估：西方失语症成套测验（WAB）、波士顿诊断性失语症检查（BDAE）与中国康复研究中心汉语标准失语症检查（CRRCAE）","失语类型判定：流畅性、理解、复述与命名四项能力评估（波士顿分类）","神经影像：头颅MRI/CT明确病灶部位与范围（左侧额下回=Broca区；颞上回后部=Wernicke区）","鉴别诊断：构音障碍（言语不清但语言功能正常）、言语失用、痴呆（认知全面下降）与谵妄","认知功能评估：注意力、记忆与执行功能（影响康复训练与预后）","抑郁与情绪评估：卒中后抑郁常见（影响训练参与度）","听力与视力评估：排除感觉输入障碍对语言评估的影响"],"infusion":["⚠️ 失语症以语言康复训练为主，静脉用药用于病因与并发症！","","方案1（急性脑卒中病因治疗）：","  用法：缺血性卒中——阿替普酶 0.9mg/kg 静脉溶栓（4.5小时内，按方案）或血管内取栓；阿司匹林 100mg qd（口服/鼻饲）；神经保护与改善循环药物（依达拉奉 30mg（NS 100ml）静滴 bid、丁苯酞 25mg 静滴 bid）〔调 ★ 活动性溃疡禁用；阿司匹林哮喘禁用；儿童病毒感染禁用〕","","方案2（脑水肿与颅压增高）：","  用法：20%甘露醇 125～250ml 静滴 q6～8h（监测肾功能与电解质）；或 3%氯化钠 100～150ml 静滴〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","","方案3（营养神经与康复辅助）：","  用法：甲钴胺 0.5mg 静推 qd；胞磷胆碱 0.5g（NS 100ml 或 5%GS 100ml；亦可肌注）静滴 qd；脑蛋白水解物（遵医嘱）","","方案4（营养与补液支持）：","  用法：0.9%氯化钠/葡萄糖 静滴；不能进食者肠内营养（鼻饲）或肠外营养","","📌 失语症康复的核心是早期、高频、个体化的语言训练；药物（如多奈哌齐、吡拉西坦）证据有限，仅作辅助；卒中急性期治疗（溶栓与取栓）影响语言功能预后。"],"oral_medication":["⚠️ 语言训练为主，药物辅助：","药物1（神经与认知辅助）：","用法：多奈哌齐 5mg qn（部分研究显示有助失语症恢复，遵医嘱）；尼莫地平 30mg tid（卒中后）；甲钴胺 0.5mg tid","药物2（卒中二级预防，关键）：","用法：阿司匹林 100mg qd + 氯吡格雷 75mg qd（短期双抗，按方案）或单抗；阿托伐他汀 20～40mg qn；降压药（氨氯地平 5mg qd 等，血压目标个体化）〔调 ★ 活动性肝病禁用；甲减/肌病史慎用；妊娠哺乳禁用〕","药物3（抑郁与情绪，卒中后抑郁常见）：","用法：舍曲林 50mg qd 或 艾司西酞普兰 10mg qd（改善情绪与训练参与度）","药物4（基础病管理）：","用法：降糖药（糖尿病患者）、抗凝药（房颤者，如利伐沙班 20mg qd）；戒烟限酒〔调 ★ CrCl 15-30 减量、<15 禁用；活动性出血禁用；机械瓣禁用〕","📌 药物不能替代语言训练；卒中二级预防（抗血小板、他汀、降压与控糖）可降低复发风险（直接影响语言功能）；卒中后抑郁需积极治疗（影响康复依从性）。"],"treatment":["语言训练（核心）：一对一训练（命名、复述、理解与阅读训练）、小组训练（交流功能）、计算机辅助训练（高频重复）、强制性诱导失语症治疗（CIAT，限制非语言交流促进口语）","训练强度与时机：早期介入（卒中后尽早）、高频（每日≥30～60分钟，每周≥5天）、长期坚持（数月到数年）","交流功能训练：手势、图画交流板、书写与辅助沟通设备（AAC），降低交流挫折与促进参与","照顾者参与：培训家属交流技巧（简短短句、给足时间、不代答、使用手势与写字）与训练延续","心理支持：卒中后抑郁与焦虑治疗（药物+心理治疗）、减少社交回避与孤独","药物辅助：多奈哌齐等（证据有限）；神经调控（经颅磁刺激/直流电刺激，研究支持）","病因与危险因素管理：卒中二级预防（抗血小板/抗凝、他汀、降压与控糖）、戒烟限酒与康复运动","随访与评估：定期复评语言功能（每1～3个月），调整训练目标（功能性交流优先于完美语法）"],"management":["交流环境营造：安静环境、放慢语速、使用简短句子与手势、给予充足反应时间（不催促、不代答）","训练执行与记录：按康复计划执行语言训练（每日多次短时训练）、记录训练内容与进步","情绪与心理护理：观察抑郁与焦虑（哭泣、拒绝训练、社交回避），及时报告并支持","安全与吞咽评估：失语常合并吞咽障碍（进食前评估，防误吸）；观察理解能力与配合程度","照顾者培训：交流技巧（简单直接、肯定与鼓励）、训练延续（家庭作业）、避免过度代替交流","功能目标设定：以日常交流功能为目标（如表达需求、打电话与购物），设定现实可达成的短期目标","宣教：失语症恢复需长期训练（卒中后3～6个月进步最快但可持续数年）、家属支持是关键、避免因交流困难而减少社交"],"notes":["失语症康复的核心是早期、高频、个体化的语言训练（训练强度与时长直接影响疗效）","失语症（语言功能损害）与构音障碍（发音不清）不同，评估需专业语言治疗师参与","感觉性失语（理解障碍）患者常答非所问，易被误认为'精神异常'或'不配合'（需理解与耐心）","卒中后抑郁常见且影响康复依从性（需筛查与治疗）","失语常合并吞咽障碍与认知障碍，需全面评估（多学科康复团队）"],"emergency":["突发新发或加重语言障碍伴肢体无力（卒中复发）→ 立即卒中绿色通道（溶栓/取栓评估）","失语患者出现意识障碍（谵妄/颅内病变）→ 立即神经影像与评估","吞咽障碍致误吸与发热（吸入性肺炎）→ 抗感染+禁食评估+营养支持","严重抑郁伴自杀意念（卒中后）→ 精神科评估与安全监护","癫痫发作（卒中后）→ 抗癫痫治疗与保护气道"],"pinyin":"syzakf","icd10":"R47.0","physical_exam":["语言功能：自发语言流畅性与内容、理解（指令执行）、复述与命名（四项核心）","构音与言语：发音清晰度、语速与韵律（构音障碍鉴别）","神经系统：肢体肌力与偏瘫侧、面部对称性、视野（偏盲）与感觉","认知功能：注意力、定向力与执行功能（影响训练）","吞咽功能：饮水试验与咽喉检查（失语常合并吞咽障碍）","情绪状态：抑郁与焦虑表现（哭泣、淡漠与拒绝训练）","听力与视力：感觉输入功能（影响语言评估）"],"lab_tests":["语言功能成套测验（WAB/BDAE/CRRCAE）：失语类型与严重度评估（康复前后对比）","头颅MRI/CT：病灶部位（Broca区/Wernicke区）与范围（预后判断）","认知功能评估（MMSE/MoCA）：合并认知障碍评估","吞咽功能评估（洼田饮水试验/VFSS）：合并吞咽障碍","抑郁量表（PHQ-9）：卒中后抑郁筛查","听力与视力检查：感觉输入评估","卒中相关检查：颈动脉超声、心脏超声、血脂与血糖（病因与二级预防）"],"nursing":["交流护理：放慢语速、使用简短句子与手势、给予充分反应时间、不代答不催促、保持耐心与尊重","训练配合：按语言治疗师计划执行每日训练（卡片命名、复述与阅读练习）、记录进展与困难","情绪观察与支持：观察抑郁、焦虑与训练抵触（哭泣、沉默），及时报告并给予鼓励","安全护理：跌倒预防（偏瘫与认知障碍）、吞咽评估与进食监护（防误吸）、药物核对（理解障碍易致用药错误）","照顾者培训：交流技巧、训练延续（家庭练习）、情绪支持与压力缓解","宣教：失语症可改善但需长期训练、家属参与的重要性、避免因交流困难减少社交、按时服药与随访（卒中二级预防）"],"diet":["均衡饮食（地中海饮食模式有益卒中预防）：蔬果、全谷物、深海鱼与橄榄油","限盐（每日<5g）、低脂、控制体重与血糖（卒中危险因素管理）","合并吞咽障碍者：按评估选择食物性状（糊状/半流质）与增稠液体","保证充足水分与膳食纤维（防便秘，避免用力排便致血压升高）","戒烟限酒；避免高盐加工食品与含糖饮料"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1452},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"dd1712ef3746eb545f6f2229054bf318977bfa9138a9a0ea504c0da46f6134da","pinyin":"shiyuzhengkangfu","initials":"syzkf","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","表达障碍：找词困难、言语不流畅、电报式语言（运动性失语）\\n理解障碍：听不懂他人言语、答非所问（感觉性失语）\\n复述障碍：不能复述词句（传导性失语）\\n命名障碍：说不出物品名称（命名性失语）\\n读写障碍（失读、失写）与伴随症状：右侧偏瘫、视野缺损与构音障碍",60],["摘要","失语症是脑损伤（多为左侧大脑半球卒中）导致的语言功能损害，表现为听、说、读、写障碍。按类型分为运动性（Broca，表达障碍）、感觉性（Wernicke，理解障碍）、传导性、命名性、经皮质与完全性失语。康复以语言训练为核心，配合药物与心理支持，早期介入与高频训练效果最佳。",30],["疾病编码","R47.0",30],["原首字母","syzakf",60]]},{"id":"orders-309325d6250bf2ba0d11","key":"v1-c9ccc21dfe2a3058|orders-309325d6250bf2ba0d11","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"神经源性膀胱康复","category":"康复医学","raw":{"name":"神经源性膀胱康复","category":"康复医学","summary":"神经源性膀胱是神经系统病变（脊髓损伤、脑卒中、多发性硬化、糖尿病神经病变、脊柱裂）导致的下尿路功能障碍，表现为尿潴留、尿失禁或二者并存，可致上尿路损害（肾积水与肾衰竭）与泌尿系感染。康复核心是保护上尿路、安全排空膀胱（间歇导尿）与防治感染。","symptoms":["尿潴留（排尿困难、残余尿增多、充溢性尿失禁）","尿失禁（急迫性、压力性或反射性）","尿频、尿急与夜尿增多","反复泌尿系感染（尿混浊、发热与腰痛）","并发症：肾积水与肾功能损害（腰胀、少尿）、膀胱结石与自主神经反射异常（脊髓损伤T6以上，血压骤升）"],"diagnosis":["排尿日记：记录排尿时间、尿量、导尿量与失禁次数（72小时）","残余尿测定（超声，导尿后）：>100～150ml提示排空不全（需干预）","尿动力学检查（金标准）：评估膀胱压力、容量、顺应性与逼尿肌括约肌协同失调（决定治疗方案）","泌尿系超声+肾功能：上尿路损害评估（肾积水、肾皮质厚度与肌酐）","尿常规+尿培养：泌尿系感染筛查","神经系统评估：损伤平面（ASIA分级）、球海绵体反射与肛门括约肌张力（判断上/下运动神经元膀胱）","影像学（必要时）：膀胱造影（膀胱输尿管反流）、CT尿路成像（结石与上尿路评估）"],"infusion":["⚠️ 以康复训练与导尿管理为主，静脉用药用于感染与并发症！","方案1（泌尿系感染，抗感染）：","用法：左氧氟沙星 0.5g 静滴 qd 或 头孢曲松 1～2g 静滴 qd（按尿培养与药敏调整；疗程7～14天，复杂感染延长）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","方案2（严重感染/脓毒症）：","用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 美罗培南 1g 静滴 q8h（按药敏调整）；0.9%氯化钠 补液与循环支持〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","方案3（肾功能损害/电解质紊乱）：","用法：0.9%氯化钠 静滴（按尿量与心功能）；纠正电解质（高钾、酸中毒）；必要时CRRT（肾衰竭）","方案4（自主神经反射异常，脊髓损伤T6以上，急症）：","用法：立即解除诱因（导尿排空膀胱、解除便秘）；硝苯地平 10mg 舌下含服 或 硝酸甘油 0.5mg 舌下（降压）；必要时乌拉地尔 12.5mg 静推（按医嘱）〔调 ★ 收缩压<90 或右室梗死禁用；★ 24h内用过PDE5抑制剂禁用〕","📌 间歇导尿是神经源性膀胱的首选排空方式（比留置尿管感染率低）；膀胱压需保持在安全范围（<40cmH₂O）以保护上尿路；感染治疗需按尿培养（避免盲目预防性抗生素）。"],"oral_medication":["⚠️ 按尿动力学结果选择药物：","药物1（逼尿肌过度活动/痉挛，抗胆碱能药）：","用法：索利那新 5～10mg qd 或 托特罗定 2～4mg bid（注意口干、便秘与认知影响）；或 米拉贝隆 25～50mg qd（β3激动剂，副作用较少）","药物2（逼尿肌收缩无力，促进排空）：","用法：溴吡斯的明 60mg tid（遵医嘱，监测胆碱能副作用）；α受体阻滞剂（坦索罗辛 0.2mg qn）降低尿道阻力（尤其合并前列腺增生）","药物3（泌尿系感染）：","用法：按尿培养选择（呋喃妥因 0.1g tid、头孢克肟 0.1g bid 等）；无症状菌尿一般不需治疗（避免耐药）〔调 肾功能不全减量；青霉素过敏慎用〕","药物4（自主神经反射异常预防与通便）：","用法：硝苯地平 10mg 舌下（急救备用）；乳果糖 15ml bid（便秘可诱发自主神经反射异常）〔调 肠梗阻/穿孔禁用；糖尿病患者注意（含乳糖）〕","📌 抗胆碱能药物注意认知与便秘副作用（老年患者慎用）；无症状菌尿不建议预防性抗生素（增加耐药）；定期评估尿动力学调整方案。"],"treatment":["间歇导尿（首选，清洁间歇导尿CIC）：每4～6小时一次，控制液体摄入（1500～2000ml/日），残余尿<400ml为宜","留置导尿（不能行CIC者）：定期更换导管，注意感染与尿道损伤；耻骨上膀胱造瘘（长期留置者）","反射性排尿/触发排尿（特定患者）：Crede手法与Valsalva（需评估安全性，慎用以免膀胱压过高）、触发点（叩击下腹）","药物治疗：抗胆碱能药（逼尿肌过度活动）、米拉贝隆、α受体阻滞剂与溴吡斯的明（按尿动力学结果）","膀胱训练：定时排尿、延迟排尿与盆底肌训练（部分患者）","手术治疗：膀胱扩大术、尿流改道（严重低顺应性膀胱或上尿路损害）、骶神经调控（部分患者）、尿道括约肌切开（男性CIC困难者）","并发症防治：泌尿系感染（按尿培养治疗，避免盲目预防）、膀胱结石（定期超声）、自主神经反射异常（脊髓损伤T6以上者教育与管理）、肾功能监测","随访：定期尿动力学（每6～12个月或病情变化）、泌尿系超声与肾功能（每6～12个月）、评估上尿路保护效果"],"management":["排尿与导尿记录：记录排尿/导尿时间、尿量与失禁次数（排尿日记），评估残余尿与排空效果","间歇导尿护理：指导规范操作（洗手、润滑、轻柔插入）、频率（每4～6小时）、清洁与用物管理（减少感染）","液体管理：控制液体摄入量（1500～2000ml/日）并集中在白天，减少夜间导尿次数；避免咖啡因与酒精","感染监测与预防：观察尿混浊、异味、发热与腰痛；保证充足饮水、规律排空（避免膀胱过度充盈）；避免盲目使用抗生素","自主神经反射异常管理（脊髓损伤T6以上）：识别头痛、血压骤升、出汗与心动过缓等症状，立即排空膀胱/通便并降压（急症）","皮肤与尿道护理：会阴清洁、防压疮（尿失禁者）、防导管相关损伤（避免牵拉与压迫）","宣教：间歇导尿技术（患者与家属培训）、饮水与排尿计划、感染征兆识别、定期随访（尿动力学与肾功能）的重要性"],"notes":["神经源性膀胱管理的首要目标是保护上尿路（保持膀胱压<40cmH₂O），其次才是排空与控尿","间歇导尿（CIC）优于留置尿管（感染率低、并发症少），是首选排空方式","无症状菌尿不应常规使用抗生素（增加耐药与感染风险）；有症状感染按尿培养治疗","自主神经反射异常是脊髓损伤T6以上患者的危及生命并发症（血压骤升+头痛），首要处理是解除诱因（排空膀胱/通便）","需定期行尿动力学与肾功能评估（每6～12个月），及时发现低顺应性膀胱与上尿路损害"],"emergency":["血压骤升伴剧烈头痛、出汗与心动过缓（自主神经反射异常）→ 立即排空膀胱/解除便秘+舌下硝苯地平或硝酸甘油降压","高热寒战伴腰痛与尿混浊（急性肾盂肾炎/脓毒症）→ 尿培养+血培养+静脉抗生素+补液","少尿、无尿伴肾区胀痛与肌酐升高（梗阻性肾积水）→ 急诊影像+导尿/肾造瘘减压","不能排尿伴膀胱高度充盈疼痛（急性尿潴留）→ 立即导尿排空（控制速度防血尿与低血压）","长期留置尿管者尿道出血或导管堵塞 → 冲洗或更换导管，评估尿道损伤"],"pinyin":"sjxyngkKf","icd10":"N31.9","physical_exam":["生命体征：血压（自主神经反射异常）、体温（感染）与心率","腹部：下腹膨隆与浊音（膀胱充盈）、压痛（感染）与包块","神经系统：损伤平面（ASIA分级）、下肢肌力与感觉、球海绵体反射与肛门括约肌张力（上/下运动神经元判断）","会阴与尿道：皮肤完整性（尿失禁致皮炎）、尿道口位置与导管情况","泌尿系统：肋脊角叩击痛（上尿路感染/积水）","肾功能相关：水肿、贫血貌与皮肤瘙痒（肾衰竭）","直肠：便秘评估（便秘可诱发自主神经反射异常）"],"lab_tests":["残余尿测定（超声）：>100～150ml提示排空不全（需干预）","尿动力学检查：膀胱压力、容量、顺应性与逼尿肌括约肌协同性（治疗决策金标准，每6～12个月）","尿常规+尿培养+药敏：感染诊断与目标治疗（有症状时）","肾功能（肌酐、尿素氮）+电解质：上尿路损害评估（每6～12个月）","泌尿系超声：肾积水、肾皮质厚度与膀胱结石（每6～12个月）","排尿日记（72小时）：排尿与导尿量、失禁次数（评估疗效）","影像学（必要时）：膀胱造影（膀胱输尿管反流）与CT尿路成像（结石与上尿路）"],"nursing":["间歇导尿指导：规范操作与频率（每4～6小时）、清洁用物管理、观察尿量与性状，指导患者与家属掌握技术","液体管理：记录出入量与排尿日记，指导液体集中在白天并限制咖啡因与酒精","感染监测与预防：观察尿混浊、异味、发热与腰痛；鼓励饮水与规律排空；按医嘱使用抗生素（不盲目用药）","自主神经反射异常护理（T6以上损伤）：识别头痛、血压骤升与出汗，立即排空膀胱与通便并通知医师（备降压药）","皮肤与尿道护理：会阴清洁、失禁者防皮炎与压疮、导管避免牵拉与压迫","宣教：间歇导尿技术（患者与家属）、饮水计划、感染与梗阻征兆识别、定期尿动力学与肾功能随访"],"diet":["合理液体摄入（1500～2000ml/日，白天为主），避免夜间大量饮水影响睡眠与导尿","避免咖啡因、酒精与辛辣食物（刺激膀胱加重尿急与失禁）","高纤维饮食（蔬果、全谷物）防便秘（便秘诱发自主神经反射异常并加重排尿障碍）","肾功能不全者：限制蛋白、钾与磷（按分期），限制钠盐","保持理想体重（肥胖增加腹压与尿失禁）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1453},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"5d2d38ec2b478848a6ebaca401999643b04251f6454ab5f46cf101848b027e2f","pinyin":"shenjingyuanxingpangguangkangfu","initials":"sjyxpgkf","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","尿潴留（排尿困难、残余尿增多、充溢性尿失禁）\\n尿失禁（急迫性、压力性或反射性）\\n尿频、尿急与夜尿增多\\n反复泌尿系感染（尿混浊、发热与腰痛）\\n并发症：肾积水与肾功能损害（腰胀、少尿）、膀胱结石与自主神经反射异常（脊髓损伤T6以上，血压骤升）",60],["摘要","神经源性膀胱是神经系统病变（脊髓损伤、脑卒中、多发性硬化、糖尿病神经病变、脊柱裂）导致的下尿路功能障碍，表现为尿潴留、尿失禁或二者并存，可致上尿路损害（肾积水与肾衰竭）与泌尿系感染。康复核心是保护上尿路、安全排空膀胱（间歇导尿）与防治感染。",30],["疾病编码","N31.9",30],["原首字母","sjxyngkKf",60]]},{"id":"orders-ff0b22dc5d767c1e62b7","key":"v1-c9ccc21dfe2a3058|orders-ff0b22dc5d767c1e62b7","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"痉挛状态管理（肌张力增高）","category":"康复医学","raw":{"name":"痉挛状态管理（肌张力增高）","category":"康复医学","summary":"痉挛是上运动神经元损伤（脑卒中、脊髓损伤、脑瘫、多发性硬化）后肌张力速度依赖性增高，表现为肌肉僵硬、关节活动受限、疼痛与 Care 困难（清洁与会阴护理），可致挛缩与畸形。管理包括去除诱因、物理治疗、口服药物、局部注射（肉毒毒素）与手术（鞘内巴氯芬泵、选择性周围神经切断）。","symptoms":["肌肉僵硬与张力增高（被动活动阻力增大，速度依赖）","阵挛（踝阵挛常见）与深腱反射亢进","关节活动受限与畸形（内收肌痉挛致剪刀步态、屈肘与屈腕畸形）","疼痛与不适（痉挛性疼痛影响睡眠）","功能与护理影响：会阴清洁困难、穿脱衣物困难、坐位平衡差、压疮风险增加"],"diagnosis":["改良Ashworth量表（MAS）或Tardieu量表：评估肌张力增高的程度（0～4级）","功能评估：关节活动度、坐位与站立平衡、步行能力（步态分析）与日常生活活动（ADL）","疼痛评估：痉挛相关疼痛的部位与程度（NRS评分）","诱因寻找（关键）：尿路感染、便秘、压疮、深静脉血栓、疼痛、体位不当与药物（可加重痉挛）","病因评估：脑卒中（病程与部位）、脊髓损伤（平面与完全性）、脑瘫与多发性硬化","目标设定：明确治疗目标（改善功能、减轻疼痛、便于护理或预防挛缩）——决定治疗方式","必要时电生理检查：肌电图引导肉毒毒素注射定位"],"infusion":["⚠️ 以康复与局部治疗为主，静脉用药用于诱因与重症！","方案1（去除诱因，首要）：","用法：尿路感染——左氧氟沙星 0.5g 静滴 qd（按药敏）；便秘——乳果糖（口服为主）；压疮感染——抗感染+换药；深静脉血栓——抗凝（低分子肝素 0.4ml 皮下注射 qd）〔调 ★ CrCl<50 减量；18岁以下禁用；癫痫者慎用〕","方案2（鞘内巴氯芬泵试验与调整，重症，专科）：","用法：巴氯芬 50～100μg 鞘内注射（试验剂量，监测反应与呼吸抑制）——需神经外科/康复科专科操作","方案3（严重痉挛伴疼痛与睡眠障碍）：","用法：0.9%氯化钠 静滴；地西泮 5～10mg 缓慢静推（短期，注意呼吸与镇静）；必要时静脉镇痛（曲马多）〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","方案4（营养与支持）：","用法：0.9%氯化钠/葡萄糖 静滴；维生素B族与钙镁补充；营养支持（营养不良影响肌力与恢复）","📌 痉挛处理先去除诱因（感染、便秘、压疮与疼痛常致痉挛突然加重）；肉毒毒素注射与鞘内巴氯芬是重症的有效治疗（需专科）。"],"oral_medication":["⚠️ 口服药物为全身治疗（注意副作用与剂量滴定）：","药物1（一线口服，巴氯芬）：","用法：巴氯芬 5mg tid 起（逐渐加量至有效，最大80mg/日；不可骤停——可致戒断与癫痫）；肾功能不全者减量","药物2（二线/联合）：","用法：替扎尼定 2mg tid 起（α2激动剂，注意低血压与肝损）；或 丹曲林 25mg qd 起（注意肝毒性与肌无力）；苯二氮卓类（地西泮，短期）〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","药物3（局部注射，专科）：","用法：A型肉毒毒素 局部肌肉注射（按肌肉大小与痉挛程度选择剂量，效果维持3～6个月）；需肌电图或超声引导","药物4（神经病理性疼痛与辅助）：","用法：加巴喷丁 0.3g tid 或 普瑞巴林 75mg bid；甲钴胺 0.5mg tid（神经修复辅助）","📌 巴氯芬不可骤停（可致戒断综合征与癫痫）；替扎尼定与丹曲林需监测肝功能；肉毒毒素注射后需观察疗效与不良反应（无力、吞咽困难）。"],"treatment":["去除诱因（首要）：治疗尿路感染、便秘、压疮、深静脉血栓与疼痛；调整体位与护理方式","物理治疗：被动关节活动度训练（每日多次，防挛缩）、牵伸（缓慢持续）、体位摆放（良肢位）、冷热疗与电刺激","口服药物治疗：巴氯芬（一线）、替扎尼定、丹曲林与苯二氮卓类（按疗效与副作用滴定）","局部注射：A型肉毒毒素（局灶性痉挛，如内收肌、屈肘肌群，效果3～6个月）；酚或酒精神经阻滞（部分患者）","鞘内巴氯芬泵：重度全身性痉挛（口服无效或副作用大者），需专科评估与泵管理（注意过量致呼吸抑制）","手术治疗：选择性周围神经切断术（SPN）、肌腱延长/转移术与矫形手术（挛缩与畸形）","康复训练与功能训练：结合痉挛管理进行坐位平衡、转移与步行训练，提高日常生活能力","随访与评估：定期评估MAS评分、关节活动度、疼痛与功能（每1～3个月），调整治疗方案与目标"],"management":["痉挛评估与记录：按MAS评分记录各肌群张力、关节活动度与疼痛，评估功能影响（护理、坐位与步行）","诱因监测与处理：密切观察尿路感染（尿混浊、发热）、便秘、压疮与疼痛（痉挛加重的最常见原因）","体位与护理：良肢位摆放、定时更换体位（每2小时）、避免不良体位诱发痉挛；会阴与皮肤护理（痉挛致清洁困难）","用药护理：巴氯芬按时给药（不可骤停）、观察副作用（嗜睡、乏力、呼吸抑制）、替扎尼定监测血压与肝功能","康复训练配合：按计划进行被动活动、牵伸与功能训练，记录关节活动度与耐受情况","肉毒毒素注射后护理：观察疗效（2～4周起效）与不良反应（肌无力、吞咽困难与呼吸影响），记录注射部位","宣教：痉挛管理需长期综合治疗、去除诱因的重要性、口服药不可骤停、按时复诊与功能评估"],"notes":["痉挛突然加重首先寻找诱因（尿路感染、便秘、压疮、深静脉血栓与疼痛），而非立即加药","巴氯芬口服不可骤停（可致戒断综合征、幻觉与癫痫）；鞘内巴氯芬过量可致呼吸抑制（急症）","治疗目标应个体化：有的患者需要一定肌张力维持站立（过度降低张力反而影响功能）","肉毒毒素是局灶性痉挛的首选（效果维持3～6个月，需重复注射）","预防挛缩需早期、持续的被动活动与牵伸（每日多次），不可依赖药物"],"emergency":["鞘内巴氯芬过量（嗜睡、呼吸抑制与意识障碍）→ 立即停药、支持呼吸（必要时机械通气）并急诊评估","口服巴氯芬突然停药（幻觉、躁动、癫痫）→ 立即恢复用药并监护（戒断综合征）","痉挛突然加重伴高热与尿混浊（尿路感染）→ 尿培养+抗感染+去除诱因","严重痉挛致关节挛缩急性疼痛或骨折（骨质疏松者）→ 影像评估与镇痛，调整治疗","肉毒毒素注射后出现吞咽困难与呼吸困难 → 立即评估气道与吞咽功能，必要时住院观察"],"pinyin":"jlztgljzlzg","icd10":"R25.2","physical_exam":["肌张力评估：改良Ashworth量表（MAS）分级（各肌群）、速度依赖性阻力与阵挛","深腱反射：亢进程度（与上运动神经元损伤一致）","关节活动度：主动与被动范围、挛缩与畸形（内收、屈肘与马蹄足）","疼痛评估：部位、性质与程度（NRS），痉挛与疼痛的关系","功能评估：坐位与站立平衡、转移能力、步行能力与日常生活活动（ADL）","诱因检查：尿路（尿混浊与叩击痛）、肠道（腹胀与便秘）、皮肤（压疮）与下肢（深静脉血栓：肿胀与压痛）","病因体征：脑卒中（偏瘫侧）、脊髓损伤（平面与感觉运动缺失）与脑瘫（运动发育异常）"],"lab_tests":["改良Ashworth量表（MAS）+Tardieu量表：肌张力评估（治疗前后对比核心指标）","尿常规+尿培养：尿路感染（痉挛加重的最常见诱因）","电解质（钾、钠、钙、镁）+肾功能：电解质紊乱与巴氯芬剂量调整（肾功能不全者）","肝功能（替扎尼定、丹曲林）：药物不良反应监测（每月）","下肢静脉超声（疑深静脉血栓）：肿胀与疼痛时","肌电图/超声（肉毒毒素注射）：定位与剂量指导","影像学（必要时）：X线（关节挛缩与异位骨化）、MRI（病因评估）"],"nursing":["痉挛与功能评估：按MAS评分记录肌张力、关节活动度与疼痛，观察功能与护理影响","诱因观察：每日检查尿路（尿混浊、发热）、肠道（便秘）、皮肤（压疮）与下肢（深静脉血栓），异常立即报告","体位与皮肤护理：良肢位摆放、每2小时更换体位、会阴与皮肤清洁（痉挛致清洁困难者需耐心与技巧）","用药护理：巴氯芬按时给药并观察副作用（嗜睡、乏力）与戒断风险（不可骤停）；替扎尼定监测血压","康复训练配合：协助被动活动与牵伸（每日多次）、记录关节活动度与耐受，鼓励主动参与功能训练","肉毒毒素注射后观察：记录疗效（2～4周）与不良反应（无力、吞咽困难），异常报告","宣教：去除诱因的重要性、口服药不可骤停、坚持康复训练与预防挛缩、按时复诊评估"],"diet":["均衡饮食，保证蛋白与热量（康复训练需求增加）","高纤维饮食与充足水分（防便秘——便秘加重痉挛）","钙与维生素D补充（长期卧床与抗癫痫药者防骨质疏松）","巴氯芬与替扎尼定服用者避免饮酒（加重镇静与低血压）","吞咽障碍者按评估调整食物性状（防误吸）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1454},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"41af94306e54d6a210a0d1b09c7b7bab22f298db2cdc8b3ca7d5f4ab85261d44","pinyin":"jingluanzhuangtaiguanli（jizhanglizenggao）","initials":"jlztgl（jzlzg）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","肌肉僵硬与张力增高（被动活动阻力增大，速度依赖）\\n阵挛（踝阵挛常见）与深腱反射亢进\\n关节活动受限与畸形（内收肌痉挛致剪刀步态、屈肘与屈腕畸形）\\n疼痛与不适（痉挛性疼痛影响睡眠）\\n功能与护理影响：会阴清洁困难、穿脱衣物困难、坐位平衡差、压疮风险增加",60],["摘要","痉挛是上运动神经元损伤（脑卒中、脊髓损伤、脑瘫、多发性硬化）后肌张力速度依赖性增高，表现为肌肉僵硬、关节活动受限、疼痛与 Care 困难（清洁与会阴护理），可致挛缩与畸形。管理包括去除诱因、物理治疗、口服药物、局部注射（肉毒毒素）与手术（鞘内巴氯芬泵、选择性周围神经切断）。",30],["疾病编码","R25.2",30],["原首字母","jlztgljzlzg",60]]},{"id":"orders-7b7b49016eb68c549bf0","key":"v1-c9ccc21dfe2a3058|orders-7b7b49016eb68c549bf0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"儿童脑性瘫痪康复","category":"康复医学","raw":{"name":"儿童脑性瘫痪康复","category":"康复医学","summary":"脑性瘫痪（脑瘫）是发育早期（胎儿期至生后1个月内）脑损伤导致的持续性运动与姿势发育障碍，常伴智力、语言、癫痫与感知觉障碍。按类型分为痉挛型（最常见）、不随意运动型（手足徐动）、共济失调型与混合型。康复核心是早期干预、运动功能训练、矫形与家庭参与，目标是提高功能与生活质量。","symptoms":["运动发育迟缓（抬头、翻身、坐、爬与走里程碑延迟）","肌张力异常（增高：痉挛型；降低：肌张力低下型；波动：手足徐动型）","姿势异常（角弓反张、剪刀步态、尖足与屈肘屈腕）","原始反射持续存在（拥抱反射与握持反射不消失）与姿势反射异常","伴随障碍：智力障碍、癫痫、语言障碍、视听障碍与喂养困难"],"diagnosis":["发育里程碑评估：运动、语言与社交发育评估（与同龄比较）","神经系统检查：肌张力（Ashworth量表）、原始反射与姿势反射、病理反射与关节活动度","运动功能评估：粗大运动功能分级系统（GMFCS Ⅰ～Ⅴ级，预后与治疗依据）与精细运动分级（MACS）","头颅MRI（首选）：脑室周围白质软化、脑发育异常、基底节损伤（病因与预后）","脑电图（癫痫共病）：约30%～40%脑瘫患儿合并癫痫","视听与智力评估：视力听力检查、发育商/智力评估","鉴别诊断：遗传性痉挛性截瘫、肌营养不良、代谢性疾病与脊髓性肌萎缩（必要时基因检测）","喂养与营养评估：吞咽障碍与营养不良（常见）"],"infusion":["⚠️ 以康复训练为主，静脉用药用于共病与并发症！","","方案1（癫痫发作/持续状态）：","  用法：地西泮 0.3～0.5mg/kg 缓慢静推（最大10mg，监测呼吸）；或 咪达唑仑 0.2mg/kg 肌注；无效者 苯巴比妥 15～20mg/kg（NS 100ml 或 5%GS 100ml）静滴〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","","方案2（合并感染）：","  用法：头孢曲松 50～75mg/kg（NS 100ml 或 5%GS 100ml）静滴 qd 或 阿莫西林克拉维酸 30mg/kg 静滴 q8h（肺炎/泌尿道感染，按药敏调整）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","","方案3（营养支持与喂养困难）：","  用法：0.9%氯化钠/葡萄糖 静滴（补液）；白蛋白（低蛋白者）；必要时全肠外营养（严重营养不良或术后）","","方案4（肉毒毒素注射辅助，痉挛型）：","  用法：A型肉毒毒素 按体重与肌肉选择剂量（超声/肌电引导下注射，效果3～6个月）；注射后观察与康复训练配合","","📌 脑瘫康复需长期、综合、家庭参与；肉毒毒素与矫形手术用于痉挛管理；癫痫与喂养问题需同步处理；早期干预（1岁内）效果最好。"],"oral_medication":["⚠️ 按共病与痉挛管理选择药物：","药物1（痉挛管理）：","用法：巴氯芬 0.5mg/kg/日 分3次起（逐渐加量，不可骤停）；或 替扎尼定、地西泮（短期）；A型肉毒毒素局部注射（局灶性痉挛）〔调 ★ 肝功能不全及老年减量；呼吸功能不全慎用；妊娠禁用〕","药物2（抗癫痫，合并癫痫者）：","用法：左乙拉西坦 20～40mg/kg/日 分2次 或 丙戊酸钠 15～30mg/kg/日 分2次（监测肝功能与血药浓度）；不可骤停〔调 ★ 必须按 CrCl 减量；老年减量〕","药物3（营养与骨骼健康）：","用法：维生素D 400～800IU/日 + 碳酸钙（按年龄）；铁剂（贫血者）；多种维生素","药物4（对症与共病）：","用法：抗胆碱能药（流涎：格隆溴铵）；通便药（便秘：乳果糖）；抗反流（反流性食管炎：奥美拉唑）〔调 肝功能不全减量；★ 与氯吡格雷联用降效〕","📌 药物需按体重计算并定期调整；巴氯芬与抗癫痫药不可骤停；注意药物对认知与生长发育的影响。"],"treatment":["早期干预（关键）：1岁内开始康复训练（神经发育学疗法/ Bobath、Vojta与引导式教育），充分利用脑可塑性","运动功能训练：粗大运动（抬头、翻身、坐、爬、站与走）、精细运动（抓握与手眼协调）、平衡与转移训练","痉挛与肌张力管理：牵伸与体位摆放、巴氯芬（口服/鞘内）、肉毒毒素注射、系列石膏与矫形器（AFO等）","矫形手术：肌腱延长/转移（尖足、屈膝与内收畸形）、选择性脊神经后根切断术（SPR，痉挛型）、骨科矫形","辅助器具与设备：矫形器、站立架、助行器、轮椅与姿势支撑系统（维持功能与防畸形）","言语与吞咽康复：语言训练、吞咽评估与喂养指导（防误吸与营养不良）","共病管理：癫痫（抗癫痫药）、智力与学习障碍（特殊教育）、视听障碍（助听器与眼镜）、心理行为干预","家庭与多学科协作：家庭训练延续（每日多次）、康复科、儿科、神经科、骨科与特殊教育协作；定期评估GMFCS与功能目标"],"management":["发育与功能评估：定期评估运动里程碑、GMFCS分级与关节活动度，记录功能进展","康复训练执行：按康复计划协助训练（每日多次短时）、记录训练内容与耐受，鼓励家庭参与","体位与矫形器管理：良肢位摆放、矫形器佩戴时间与皮肤检查（压疮与不适）、定期调整矫形器","痉挛与疼痛观察：评估肌张力变化与疼痛（痉挛性疼痛、髋关节脱位与便秘致不适）","喂养与营养护理：评估吞咽与喂养困难、调整食物质地、记录进食量与体重（生长迟缓常见）","癫痫观察与用药：记录发作类型与频率、按时给药（不可骤停）、观察药物不良反应","心理与家庭支持：家长压力大（照护负担与预后焦虑），提供心理支持、家庭训练指导与社会资源连接；宣教早期干预与长期康复的重要性"],"notes":["脑瘫康复的核心是早期干预与家庭参与（1岁内开始效果最佳，脑可塑性强）","GMFCS分级是评估功能与预后的重要工具（Ⅰ～Ⅴ级），指导康复目标设定","约30%～40%脑瘫儿童合并癫痫，需脑电图评估与抗癫痫治疗（不可骤停）","痉挛管理需综合（牵伸、矫形器、肉毒毒素、巴氯芬与手术），目标是改善功能而非单纯降低肌张力","髋关节脱位与脊柱侧弯是常见并发症（需定期影像随访，尤其GMFCS Ⅳ～Ⅴ级）"],"emergency":["癫痫持续状态（发作>5分钟或反复）→ 地西泮 0.3～0.5mg/kg 缓慢静推（监测呼吸）→ 二线负荷药","喂养时呛咳、呼吸困难与发绀（窒息/误吸）→ 立即清理气道、吸氧与海姆立克法（按年龄），必要时插管","发热伴呼吸急促与肺部啰音（吸入性肺炎）→ 抗感染与呼吸支持，必要时住院","髋关节疼痛伴活动受限（髋关节脱位/半脱位）→ 影像评估与骨科处理","长期使用巴氯芬突然停药（躁动、幻觉与癫痫）→ 立即恢复用药并监护"],"pinyin":"etnxntkf","icd10":"G80.9","physical_exam":["运动发育：抬头、翻身、坐、爬、站与走的里程碑（与同龄比较）","肌张力：Ashworth量表分级、痉挛型/手足徐动型/肌张力低下型表现","姿势与畸形：角弓反张、剪刀步态、尖足、屈肘与脊柱侧弯；髋关节外展受限（脱位筛查）","原始反射与姿势反射：拥抱、握持与紧张性颈反射持续存在","关节活动度：各关节主动与被动范围（挛缩评估）","伴随障碍：智力与语言、视力与听力、癫痫发作与行为问题","营养与喂养：体重与生长曲线、吞咽功能与喂养困难、口腔卫生"],"lab_tests":["头颅MRI（首选）：脑室周围白质软化、脑发育异常与基底节损伤（病因与预后）","脑电图（含视频脑电）：癫痫诊断与分型（30%～40%合并癫痫）","运动功能评估：GMFCS（粗大运动）与MACS（精细运动）分级（每6～12个月评估）","视听检查：视力（屈光与斜视）与听力（听觉诱发电位）","发育与智力评估：发育商（DQ）或智力测试","髋关节X线（每6～12个月，尤其GMFCS Ⅳ～Ⅴ级）：髋关节脱位筛查","基因检测/代谢筛查（病因不明者）：鉴别遗传与代谢性疾病"],"nursing":["康复训练配合：按计划协助日常训练（被动活动、牵伸与功能训练），记录进展与耐受，指导家长家庭训练","体位与皮肤护理：良肢位摆放、每2小时更换体位、矫形器皮肤检查（压疮与不适）、会阴清洁（痉挛致清洁困难）","喂养护理：评估吞咽与喂养困难、调整食物性状与姿势（坐位）、防误吸、记录进食量与体重","癫痫观察：记录发作类型、时间与频率，按时给药（不可骤停），发作时保护气道与安全","痉挛与疼痛观察：评估肌张力与疼痛（痉挛、便秘与髋关节问题），异常报告","家庭支持与宣教：家长心理支持（照护负担）、家庭训练延续、社会资源与康复机构连接、按时随访与评估"],"diet":["高热量、高蛋白、高维生素饮食（脑瘫患儿生长与代谢需求高，常伴营养不良）","吞咽困难者：调整食物质地（糊状/半流质）、增稠液体、坐位进食与防误吸","便秘者：高纤维饮食、充足水分与腹部按摩（便秘常见且加重痉挛）","补充钙与维生素D（长期卧床与抗癫痫药者防骨质疏松）","定期监测体重与生长曲线（生长迟缓需营养干预与内分泌评估）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1455},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"1bdacae45091228028c8ce485ed9a00052948e606f593c00324715e2aca8381b","pinyin":"ertongnaoxingtanhuankangfu","initials":"etnxthkf","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","运动发育迟缓（抬头、翻身、坐、爬与走里程碑延迟）\\n肌张力异常（增高：痉挛型；降低：肌张力低下型；波动：手足徐动型）\\n姿势异常（角弓反张、剪刀步态、尖足与屈肘屈腕）\\n原始反射持续存在（拥抱反射与握持反射不消失）与姿势反射异常\\n伴随障碍：智力障碍、癫痫、语言障碍、视听障碍与喂养困难",60],["摘要","脑性瘫痪（脑瘫）是发育早期（胎儿期至生后1个月内）脑损伤导致的持续性运动与姿势发育障碍，常伴智力、语言、癫痫与感知觉障碍。按类型分为痉挛型（最常见）、不随意运动型（手足徐动）、共济失调型与混合型。康复核心是早期干预、运动功能训练、矫形与家庭参与，目标是提高功能与生活质量。",30],["疾病编码","G80.9",30],["原首字母","etnxntkf",60]]},{"id":"orders-8f05551dd019092abc62","key":"v1-c9ccc21dfe2a3058|orders-8f05551dd019092abc62","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"声带麻痹（喉返神经麻痹）","category":"耳鼻喉","raw":{"name":"声带麻痹（喉返神经麻痹）","category":"耳鼻喉","summary":"声带麻痹是喉返神经或迷走神经损伤导致声带运动障碍，表现为声音嘶哑、气息声与误吸。病因包括甲状腺/胸部手术损伤（最常见医源性）、颈部与胸部肿瘤（肺癌、食管癌、甲状腺癌）压迫、病毒感染、脑血管病与特发性。单侧多见，双侧可致呼吸困难需紧急处理。","symptoms":["声音嘶哑、发声费力、气息声与音量减小（单侧麻痹）","饮水呛咳、误吸（声门闭合不全）","双侧麻痹：吸气性呼吸困难、喘鸣（声门狭窄，可致窒息）","发声疲劳、音域变窄（职业用声者明显）","原发病表现：颈部包块（甲状腺肿瘤）、咯血与消瘦（肺癌）、吞咽困难（食管癌）"],"diagnosis":["喉镜检查（电子喉镜/频闪喉镜，必查）：声带位置（旁正中/正中）、运动受限（单/双侧）与声门闭合情况","喉肌电图（EMG）：鉴别神经损伤程度与预后（判断是否可恢复）","颈部与胸部影像（CT/MRI）：寻找病因（甲状腺、纵隔、肺与食管病变、淋巴结肿大）","甲状腺超声+甲状腺功能：甲状腺病变与术后损伤评估","胸部CT+支气管镜（疑肺癌）：喉返神经受压病因（左喉返神经绕主动脉弓，纵隔病变易累及）","头颅MRI（疑中枢性）：脑干病变与脑血管病","鉴别诊断：环杓关节脱位（插管后）、喉癌与喉结核、声带沟与瘢痕、功能性失音（癔症性）"],"infusion":["⚠️ 以病因治疗与嗓音康复为主，静脉用药用于病因与感染！","","方案1（病因治疗，肿瘤或压迫）：","  用法：按原发病治疗（化疗/放疗/手术）；神经营养支持：甲钴胺 0.5mg 静推 qd + 维生素B1 100mg 肌注 qd","","方案2（病毒感染后神经炎）：","  用法：地塞米松 10mg 静推 qd（3～5天，减轻神经水肿）；阿昔洛韦 5mg/kg（NS 100ml 或 5%GS 100ml）静滴 q8h（疑疱疹病毒感染，7～10天）；甲钴胺+维生素B1〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（双侧麻痹伴呼吸困难）：","  用法：吸氧；地塞米松 10mg 静推（减轻水肿）；必要时气管插管或气管切开（紧急气道处理）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案4（误吸致肺炎）：","  用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h（按痰培养调整）〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","","📌 甲状腺术后声嘶需区分神经损伤（暂时性/永久性）与环杓关节脱位；双侧麻痹致呼吸困难是急症；早期嗓音康复训练有助代偿。"],"oral_medication":["⚠️ 神经营养与嗓音康复为主：","药物1（神经营养）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid（疗程1～3个月）；胞磷胆碱 0.2g tid（辅助）","药物2（减轻炎症与水肿）：","用法：泼尼松 30mg qd（晨起，逐渐减量，短期）；或 甲泼尼龙片（按医嘱）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","药物3（咽喉症状对症）：","用法：奥美拉唑 20mg qd（合并咽喉反流者）；西地碘含片 1片 tid（咽喉不适）；生理盐水雾化（湿润咽喉）〔调 肝功能不全减量；★ 与氯吡格雷联用降效〕","药物4（误吸与咳嗽管理）：","用法：进食时稠厚食物（减少误吸）；避免镇静药与酒精（抑制咳嗽反射）","📌 声带麻痹恢复期需嗓音训练（呼吸支持、发声与共鸣训练）；避免过度用声、清嗓与吸烟；定期喉镜复查（3～6个月评估恢复）。"],"treatment":["病因治疗（首要）：甲状腺/胸部手术损伤（观察或神经修复）、肿瘤压迫（手术/放化疗）、病毒感染（激素与抗病毒）、中枢病变（神经科治疗）","嗓音康复训练：呼吸支持训练、硬起音练习、共鸣训练与代偿性发声（患侧声带代偿可改善发音）","嗓音治疗与手术：声带注射填充（自体脂肪/透明质酸）改善声门闭合、甲状软骨成形术（Ⅰ型，内移声带）、杓状软骨内移术","双侧麻痹处理：呼吸困难者需气道干预（气管切开或声带外移手术）；部分患者行杓状软骨切除+声带外移（改善通气同时保留发音）","误吸管理：吞咽评估（吞咽造影/FEES）、食物质地调整（稠厚食物）、进食姿势调整与吞咽训练","嗓音卫生宣教：避免过度用声、清嗓与吸烟；充足饮水与嗓音休息","随访：喉镜与嗓音功能评估（每1～3个月，观察6～12个月判断是否永久性麻痹）","原发病随访：肿瘤患者按肿瘤随访计划复查（颈部与胸部影像）"],"management":["呼吸与误吸观察：评估呼吸频率与喘鸣（双侧麻痹者警惕呼吸困难）、进食呛咳与发热（吸入性肺炎）","嗓音评估与记录：记录声音嘶哑程度、发声疲劳与音域变化（GRBAS评分）","嗓音训练配合：协助完成呼吸与发声训练，指导嗓音休息与用声技巧（避免耳语——反而加重声带紧张）","吞咽管理：吞咽评估后进行食物质地调整（稠厚食物、小口慢咽）、坐位进食与餐后清洁口腔","心理护理：声音改变影响交流与职业（教师、歌手），提供心理支持与交流替代方式（写字、扩音器）","宣教：甲状腺术后声嘶需随访（多数暂时性损伤3～6个月恢复）、避免过度用声与吸烟、按时复查喉镜与嗓音功能"],"notes":["左侧喉返神经行程长（绕主动脉弓），纵隔病变与肺癌易致左侧麻痹；右侧损伤多见于甲状腺与颈部手术","甲状腺术后声嘶需鉴别喉返神经损伤（暂时性/永久性）与环杓关节脱位（插管所致，需复位）","双侧声带麻痹可致吸气性呼吸困难与窒息（急症，需气道处理）","喉肌电图有助判断神经损伤程度与预后（决定是否需要手术干预）","声带麻痹不能仅观察：病因不明的单侧麻痹需排查肿瘤（颈部、肺与纵隔）"],"emergency":["双侧声带麻痹致吸气性呼吸困难与喘鸣 → 立即吸氧、激素，必要时气管插管或气管切开","误吸后突发呛咳、呼吸困难与发绀 → 立即清理气道、吸氧与吸引，必要时插管","术后突发颈部肿胀伴呼吸困难（血肿压迫气道）→ 立即床旁拆线清除血肿并准备气管切开","声音嘶哑进行性加重伴咯血与消瘦（疑喉癌/肺癌）→ 尽快喉镜与胸部影像检查","喉镜检查后出现喉痉挛与呼吸困难 → 立即吸氧与激素，必要时插管"],"pinyin":"sdbmhfhjsm","icd10":"J38.0","physical_exam":["声音评估：嘶哑程度、气息声、音量与音域（GRBAS评分）","喉镜所见：声带位置（旁正中/正中/中间位）、运动受限、声门闭合（缝隙大小）与声带形态（萎缩、沟状）","颈部：甲状腺大小与结节、颈部淋巴结、手术瘢痕","吞咽功能：饮水试验与呛咳（误吸评估）、咽反射与咳嗽反射","呼吸：呼吸频率与喘鸣（双侧麻痹）、吸气性三凹征","神经系统：其他颅神经功能（迷走神经、舌咽神经）、肢体肌力（中枢病变）","原发病体征：锁骨上淋巴结（肺癌）、纵隔（胸部影像）、颈部包块（甲状腺）"],"lab_tests":["电子喉镜/频闪喉镜（必查）：声带位置、运动与闭合评估","喉肌电图（EMG）：神经损伤程度与预后判断","颈部+胸部增强CT/MRI：病因筛查（甲状腺、纵隔、肺、食管与淋巴结）","甲状腺超声+甲状腺功能：甲状腺病变与术后评估","胸部CT+支气管镜（疑肺癌）：喉返神经受压病因（左侧麻痹必查）","头颅MRI（疑中枢病变）：脑干与脑血管评估","吞咽造影（VFSS）/FEES（误吸者）：吞咽功能评估"],"nursing":["呼吸观察：监测呼吸频率与喘鸣（双侧麻痹者），备气管切开包与急救设备","嗓音护理：嗓音休息、避免耳语与清嗓、充足饮水、避免吸烟与刺激性气体；配合嗓音训练","吞咽与喂养护理：吞咽评估后调整食物质地（稠厚食物）、坐位进食、小口慢咽，观察呛咳与发热","心理护理：声音改变致交流困难与职业影响，提供心理支持与非言语交流方式（写字板、扩音器）","术后护理（甲状腺/胸部手术）：观察颈部肿胀、呼吸与引流（血肿压迫气道），记录声音变化","宣教：多数暂时性损伤3～6个月恢复、按时复查喉镜与嗓音评估、避免过度用声、识别呼吸困难与误吸征兆及时就诊"],"diet":["合并吞咽障碍者：稠厚食物（糊状、果泥），避免稀薄液体（误吸风险高）","小口慢咽、坐位进食、餐后保持坐位30分钟并清洁口腔","避免辛辣、过烫与刺激性食物（刺激咽喉）；戒烟限酒","充足饮水（湿润咽喉，但吞咽障碍者需增稠）","高蛋白与维生素（神经修复需要，如B族维生素食物）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1456},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"69ed69d64e464fc65f811d5a4716a5974a69bb39341ebc5389205ffdc338e0bb","pinyin":"shengdaimabi（houfanshenjingmabi）","initials":"sdmb（hfsjmb）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","声音嘶哑、发声费力、气息声与音量减小（单侧麻痹）\\n饮水呛咳、误吸（声门闭合不全）\\n双侧麻痹：吸气性呼吸困难、喘鸣（声门狭窄，可致窒息）\\n发声疲劳、音域变窄（职业用声者明显）\\n原发病表现：颈部包块（甲状腺肿瘤）、咯血与消瘦（肺癌）、吞咽困难（食管癌）",60],["摘要","声带麻痹是喉返神经或迷走神经损伤导致声带运动障碍，表现为声音嘶哑、气息声与误吸。病因包括甲状腺/胸部手术损伤（最常见医源性）、颈部与胸部肿瘤（肺癌、食管癌、甲状腺癌）压迫、病毒感染、脑血管病与特发性。单侧多见，双侧可致呼吸困难需紧急处理。",30],["疾病编码","J38.0",30],["原首字母","sdbmhfhjsm",60]]},{"id":"orders-e1a8569a104e42d1af72","key":"v1-c9ccc21dfe2a3058|orders-e1a8569a104e42d1af72","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"耳带状疱疹（Ramsay Hunt综合征）","category":"耳鼻喉","raw":{"name":"耳带状疱疹（Ramsay Hunt综合征）","category":"耳鼻喉","summary":"耳带状疱疹（Ramsay Hunt综合征）是水痘-带状疱疹病毒侵犯面神经膝状神经节引起的综合征，表现为耳痛、耳部疱疹、同侧周围性面瘫，可伴眩晕、听力下降与耳鸣。预后较单纯面瘫差（面神经恢复率低），需尽早抗病毒与糖皮质激素治疗（72小时内最佳）。","symptoms":["耳部剧烈疼痛（耳廓、外耳道与耳后，可为刺痛或烧灼痛）","外耳道、耳廓或口腔黏膜簇集性水疱（疱疹）","同侧周围性面瘫（额纹消失、眼睑闭合不全、口角歪斜）","眩晕、恶心呕吐与眼球震颤（前庭受累）","听力下降、耳鸣（耳蜗受累）；味觉减退（鼓索神经受累）"],"diagnosis":["典型临床表现（耳痛+疱疹+面瘫）：临床诊断（三联征）","耳镜检查：外耳道与鼓膜疱疹、充血与渗出","面神经功能评估（House-Brackmann分级）：面瘫程度与疗效评估","听力学检查（纯音测听+声导抗）：感音神经性听力下降评估","前庭功能检查（必要时）：眼震电图与视频头脉冲试验（前庭受累）","病毒学检测（必要时）：水痘-带状疱疹病毒PCR（疱液或血清IgM）","头颅MRI（增强）：面神经强化（鉴别其他面神经病变，如肿瘤与炎症）","鉴别诊断：贝尔面瘫（无疱疹）、单纯疱疹、耳部湿疹、急性中耳炎与面神经肿瘤"],"infusion":["⚠️ 抗病毒与激素须尽早（72小时内最佳）！","","方案1（抗病毒，尽早使用）：","  用法：阿昔洛韦 10mg/kg（NS 100ml 或 5%GS 100ml）静滴 q8h（7～10天）或 更昔洛韦 5mg/kg 静滴 q12h；口服方案（轻症）：伐昔洛韦 1g tid（7天）或 泛昔洛韦 500mg tid","","方案2（糖皮质激素，减轻神经水肿与炎症）：","  用法：地塞米松 10mg 静推 qd（3～5天）或 甲泼尼龙 1mg/kg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（5天后逐渐减量，总疗程10～14天）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（神经营养与循环改善）：","  用法：甲钴胺 0.5mg 静推 qd；维生素B1 100mg 肌注 qd；前列地尔 10μg 静推 qd（改善微循环）","","方案4（眩晕与疼痛对症）：","  用法：倍他司汀 20mg（NS 100ml 或 5%GS 100ml；亦可直接静推）静滴 qd（眩晕）；地塞米松（同方案2）；必要时镇痛（曲马多 100mg 静滴）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","📌 抗病毒与激素越早越好（72小时内，可显著改善面神经恢复率）；外耳道疱疹需保持清洁防感染；眼睑闭合不全者需眼部保护（防角膜损伤）。"],"oral_medication":["⚠️ 恢复期与轻症口服治疗：","药物1（抗病毒口服）：","用法：伐昔洛韦 1g tid（7天）或 泛昔洛韦 500mg tid；阿昔洛韦 0.8g 每日5次（依从性差）","药物2（激素减量）：","用法：泼尼松 40～60mg qd（晨起，每3～5天减10mg至停，总疗程10～14天）；不可骤停（防反跳）〔调 ★ 肝功能严重不全者疗效降低（宜改用甲泼尼龙）〕","药物3（神经营养与对症）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid；普瑞巴林 75mg bid（神经痛，遵医嘱）；加巴喷丁 0.3g tid","药物4（眼部与皮肤护理）：","用法：人工泪液 1滴 q2h + 眼膏 睡前（眼睑闭合不全）；阿昔洛韦乳膏 外用（疱疹处，防感染）","📌 面瘫恢复需数周至数月（不完全恢复者常见）；眼睑闭合不全者必须眼部保护（人工泪液、眼膏与眼罩，必要时眼睑缝合）；神经痛可用加巴喷丁/普瑞巴林。"],"treatment":["抗病毒治疗（尽早）：阿昔洛韦400～800mg口服5次/d或伐昔洛韦1g口服tid或泛昔洛韦500mg口服tid（疗程7～10天），72小时内开始效果最佳","糖皮质激素：地塞米松10mg/d静滴或甲泼尼龙1mg/kg/d口服，逐渐减量（总疗程10～14天）","面神经功能康复：面部按摩与表情肌训练、针灸（辅助）、电刺激（争议）、面瘫康复体操","眼部保护（重要）：眼睑闭合不全者用人工泪液、眼膏与眼罩，必要时眼睑缝合（防暴露性角膜炎与角膜溃疡）","眩晕与听力处理：倍他司汀6～12mg口服tid、前庭康复训练（眩晕）；听力下降者按感音神经性耳聋处理（营养神经与改善循环）","疼痛管理：神经病理性疼痛用加巴喷丁300mg/d起或普瑞巴林75mg bid口服，必要时阿片类（短期）","并发症处理：角膜损伤（眼科处理）、面肌联动与痉挛（后期，肉毒毒素注射）、带状疱疹后神经痛（长期管理）","随访：面神经功能评估（House-Brackmann，每2～4周）、听力复查、眼科随访（角膜情况）"],"management":["皮疹护理：保持外耳道与耳廓疱疹区清洁干燥、避免搔抓与挤压、按医嘱外用抗病毒软膏（防继发感染）","眼部护理（重点）：评估眼睑闭合情况（闭眼时露白），定时滴人工泪液与眼膏、夜间眼罩保护，观察角膜刺激症状（眼红、疼痛与视物模糊）","面瘫护理：面部保暖、按摩与表情肌训练（每日多次）、避免风吹与冷水刺激","疼痛评估与管理：评估耳痛与神经痛程度（NRS），按医嘱镇痛并观察疗效","眩晕护理：卧床休息（减少头部活动）、防跌倒（眩晕者）、必要时止晕药物与安静环境","心理护理：面瘫影响外观与交流，易致焦虑与社交回避，提供心理支持与康复信心","宣教：抗病毒治疗需尽早（延误影响恢复）、面瘫恢复需数周至数月（不完全恢复常见）、眼部保护不可忽视、按时复诊与功能评估"],"notes":["Ramsay Hunt综合征预后较贝尔面瘫差（面神经恢复率约50%～70%），抗病毒+激素须在72小时内开始","眼睑闭合不全是角膜损伤的高危因素，必须积极眼部保护（人工泪液、眼膏与眼罩，必要时眼睑缝合）","耳部疱疹出现前可仅有耳痛（易误诊为普通耳痛或中耳炎），需警惕","眩晕与听力下降提示前庭与耳蜗受累（预后与治疗需重视）","带状疱疹后神经痛可持续数月（需加巴喷丁/普瑞巴林等长期管理）"],"emergency":["眼睑闭合不全伴角膜溃疡（眼红、剧痛与视力下降）→ 立即眼科会诊与眼部保护治疗","面瘫伴剧烈耳痛与疱疹扩散至颈部（多颅神经受累）→ 评估住院与强化抗病毒治疗","严重眩晕伴呕吐与脱水 → 补液与止晕治疗","听力急剧下降（突发性感音神经性聋）→ 尽快听力检查与综合治疗（激素与改善循环）","疱疹继发细菌感染（红肿、脓性分泌物与发热）→ 抗感染治疗"],"pinyin":"edzpzRamsayHunt","icd10":"B02.2","physical_exam":["耳部：外耳道、耳廓与鼓膜疱疹（簇集水疱）、红肿与渗出，耳周淋巴结肿大与压痛","面神经功能：House-Brackmann分级（额纹、眼睑闭合、鼻唇沟、口角与鼓腮）","眼部：眼睑闭合不全程度、角膜刺激症状（眼红与畏光）与角膜感觉","听力：音叉试验与纯音测听（感音神经性听力下降）","前庭：眼震、闭目难立与步态（眩晕评估）","口腔与味觉：口腔黏膜疱疹、舌前2/3味觉（鼓索神经受累）","神经系统：其他颅神经功能（Ⅴ、Ⅸ、Ⅹ）与带状疱疹分布（颈部与耳周）"],"lab_tests":["纯音测听+声导抗：感音神经性听力下降评估（每1～2周复查）","面神经功能分级（House-Brackmann）：治疗前后对比（核心疗效指标）","病毒学检测（PCR，疱液）：水痘-带状疱疹病毒确认（必要时）","头颅MRI增强（必要时）：面神经强化与其他面神经病变鉴别","前庭功能检查（眼震电图/vHIT）：前庭受累评估","眼科检查（角膜荧光素染色）：角膜损伤评估（眼睑闭合不全者）","血常规+CRP（疑继发感染）：感染评估"],"nursing":["眼部护理：评估眼睑闭合（闭眼时露白程度）、定时人工泪液与眼膏、夜间眼罩，观察角膜刺激症状并报告","皮疹护理：保持外耳道清洁干燥、避免搔抓与挤压、按医嘱外用抗病毒软膏，观察渗出与红肿（继发感染）","面瘫护理：面部保暖与按摩、表情肌训练指导、避免冷风直吹与冷水洗脸","疼痛与眩晕护理：评估疼痛（NRS）与眩晕程度、卧床休息、防跌倒（加床档与协助活动）、遵医嘱镇痛止晕","用药护理：抗病毒药按时给予（静脉滴注注意速度与肾毒性）、激素按医嘱逐渐减量（不可骤停）、观察不良反应","心理护理与宣教：解释面瘫恢复需时间（数周至数月）、眼部保护重要性、按时复诊评估面神经与听力"],"diet":["清淡易消化饮食，高蛋白与B族维生素（神经修复）；避免辛辣刺激与酒类（加重神经痛）","充足饮水（抗病毒药需水化，防肾毒性）","咀嚼困难者（面瘫侧）：软食、小块进食，避免咀嚼费力与食物滞留颊部（餐后检查并清洁口腔）","味觉减退者注意食物温度（防烫伤）；营养均衡促进恢复","必要时口服营养补充剂（进食不足者）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1457},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"ef312353c3ab0a9f9a9cd42022f99c49a37fdc1b08afe01db24fbd0f8d347275","pinyin":"erdaizhuangpaozhen（Ramsay Huntzonghezheng）","initials":"edzpz（zhz）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","耳部剧烈疼痛（耳廓、外耳道与耳后，可为刺痛或烧灼痛）\\n外耳道、耳廓或口腔黏膜簇集性水疱（疱疹）\\n同侧周围性面瘫（额纹消失、眼睑闭合不全、口角歪斜）\\n眩晕、恶心呕吐与眼球震颤（前庭受累）\\n听力下降、耳鸣（耳蜗受累）；味觉减退（鼓索神经受累）",60],["摘要","耳带状疱疹（Ramsay Hunt综合征）是水痘-带状疱疹病毒侵犯面神经膝状神经节引起的综合征，表现为耳痛、耳部疱疹、同侧周围性面瘫，可伴眩晕、听力下降与耳鸣。预后较单纯面瘫差（面神经恢复率低），需尽早抗病毒与糖皮质激素治疗（72小时内最佳）。",30],["疾病编码","B02.2",30],["原首字母","edzpzRamsayHunt",60]]},{"id":"orders-052705d649f0424f8a5f","key":"v1-c9ccc21dfe2a3058|orders-052705d649f0424f8a5f","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"咽喉反流性疾病","category":"耳鼻喉","raw":{"name":"咽喉反流性疾病","category":"耳鼻喉","summary":"咽喉反流性疾病（LPRD）是胃内容物（胃酸与胃蛋白酶）反流至咽喉部引起的慢性炎症，表现为咽异物感、清嗓、声音嘶哑、慢性咳嗽与咽痛（与胃食管反流不同，多无明显烧心）。诊断依靠症状量表（RSI）与喉镜评分（RFS），治疗以质子泵抑制剂（PPI）足疗程+生活方式干预为核心。","symptoms":["咽异物感（'癔球症'）、频繁清嗓与咽部黏痰感","声音嘶哑（晨起明显）、发声疲劳与音域变窄","慢性咳嗽（干咳）、咽痛与咽部烧灼感","吞咽不适、喉痉挛（少见）与夜间呛咳","常无明显烧心与反酸（'沉默性反流'）"],"diagnosis":["症状量表（RSI，反流症状指数）>13分提示LPRD；喉镜评分（RFS）>7分支持诊断","电子喉镜检查（必查）：喉后部黏膜红斑、水肿、声带水肿与喉室消失（杓间区红肿与'假声带沟'）","PPI诊断性治疗（8周）：症状与喉镜改善支持诊断（最实用）","24小时咽喉食管pH-阻抗监测（金标准，难治性病例）：咽喉部反流事件与反流物性质","胃镜（必要时）：排除食管炎、Barrett食管与胃部病变","食管测压（必要时）：食管动力障碍与括约肌功能评估","鉴别诊断：慢性咽炎、咽异感症、声带病变（息肉/小结/白斑）、过敏性鼻炎致鼻后滴漏、哮喘与慢性咳嗽其他病因"],"infusion":["⚠️ LPRD以口服PPI为主，静脉用药用于重症与手术期！","","方案1（重症/不能口服，PPI静脉）：","  用法：艾司奥美拉唑 40mg 静推 q12h 或 奥美拉唑 40mg（NS 100ml 或 5%GS 100ml）静滴 q12h（2～3天后改口服）〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","方案2（急性喉痉挛/喉水肿）：","  用法：地塞米松 10mg 静推（减轻喉水肿）；布地奈德 1mg 雾化吸入（喉部炎症）；吸氧（呼吸困难者）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（合并反流性食管炎出血）：","  用法：艾司奥美拉唑 80mg 静推后 8mg/h 泵入 72小时；0.9%氯化钠 静滴〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","","方案4（手术前准备，腹腔镜抗反流手术）：","  用法：按围手术期常规（补液与预防性抗感染）；术前PPI继续使用","","📌 LPRD治疗核心是PPI足量足疗程（8～12周）+生活方式干预；静脉PPI仅用于不能口服或重症；","抗反流手术（胃底折叠术）适用于药物无效或不愿长期服药者。"],"oral_medication":["⚠️ PPI足疗程是核心（餐前30分钟服用）：","药物1（PPI，一线）：","用法：艾司奥美拉唑 20～40mg bid（餐前30分钟，疗程8～12周，必要时延长至6个月）；或 雷贝拉唑 10～20mg bid、兰索拉唑 30mg bid〔调 肝功能不全减量；★ 与氯吡格雷联用降效；长期用注意低镁〕","药物2（促动力药，辅助）：","用法：莫沙必利 5mg tid（餐前）或 伊托必利 50mg tid；多潘立酮 10mg tid（短期）〔调 ★ 消化道出血/穿孔/梗阻禁用；QT延长者慎用〕","药物3（藻酸盐与黏膜保护）：","用法：藻酸盐混悬液（海藻酸钠）10～20ml 餐后与睡前（形成'筏'阻隔反流）；硫糖铝 1g qid（黏膜保护）","药物4（夜间酸突破与辅助）：","用法：睡前加用 H2受体拮抗剂（法莫替丁 20mg 睡前，短期，易耐受）；必要时巴氯芬 5mg tid（减少一过性括约肌松弛，副作用限制）","📌 PPI需餐前30分钟服用（疗效关键）；疗程足够（8～12周，LPRD较GERD需更长）；难治者需24小时pH-阻抗监测重新评估。"],"treatment":["PPI治疗（核心）：足量（bid）足疗程（8～12周），餐前30分钟服用；无效者加量、换药或加用H2受体拮抗剂（睡前）","生活方式干预（必需）：减重、抬高床头（15～20cm）、睡前3小时禁食、避免高脂/巧克力/咖啡/浓茶/辛辣食物与酒精、戒烟","促动力药与藻酸盐：莫沙必利、伊托必利与藻酸盐混悬液（辅助屏障）","难治性LPRD：24小时咽喉食管pH-阻抗监测明确反流类型（酸/非酸/弱酸），调整治疗（如加用巴氯芬、抗反流手术）","抗反流手术：腹腔镜胃底折叠术（药物依赖或无效、解剖异常者）；内镜下治疗（部分患者）","相关疾病处理：肥胖（减重）、食管裂孔疝（手术）、幽门螺杆菌感染（根除）、睡眠呼吸暂停（治疗）","嗓音与咽喉康复：嗓音卫生（避免清嗓与过度用声）、充足饮水、咽喉保湿与蒸汽吸入","随访：8～12周评估症状（RSI）与喉镜（RFS），无效者重新评估诊断与治疗依从性"],"management":["症状与用药依从性评估：记录RSI评分、用药时间（餐前30分钟）与漏服情况（依从性差是治疗失败主因）","喉镜随访：按时复查喉镜评估喉部黏膜改善（RFS评分），记录变化","饮食与生活方式指导：睡前3小时禁食、抬高床头（15～20cm）、减少高脂与刺激性食物、戒烟限酒、减重","嗓音护理：避免清嗓（改吞咽或喝水）、避免用力发声与长时间说话、充足饮水与咽喉保湿（蒸汽吸入）","难治性病例配合：解释24小时pH-阻抗监测的必要性与注意事项（停用PPI时间按医嘱）","手术患者护理：抗反流手术前宣教、术后饮食过渡（流质→软食）与观察（吞咽困难、腹胀与气促）","宣教：LPRD治疗需时间（8～12周起效，症状改善慢于GERD）、坚持用药与生活方式改变、症状复发需复诊"],"notes":["LPRD常无烧心与反酸（'沉默性反流'），诊断依赖症状量表（RSI）+喉镜（RFS）+PPI诊断性治疗","PPI必须餐前30分钟服用（疗效差异显著），疗程需8～12周（比GERD更长）","生活方式干预与药物同等重要（睡前禁食、抬高床头、减重与戒烟是基础）","难治性患者应行24小时咽喉食管pH-阻抗监测（明确酸/非酸反流，指导治疗）","反复清嗓与用力发声加重喉部损伤（需嗓音卫生指导）"],"emergency":["突发喉痉挛与呼吸困难（严重反流刺激）→ 吸氧、激素与雾化，必要时气管插管","反流物误吸致呛咳、发热与肺部浸润（吸入性肺炎）→ 抗感染与呼吸支持","呕血或黑便（反流性食管炎出血）→ PPI静脉泵入+内镜评估","严重吞咽困难伴体重下降（需排除食管狭窄与肿瘤）→ 胃镜与影像评估","抗反流手术后突发胸痛与气促（气胸/穿孔）→ 急诊影像与外科评估"],"pinyin":"yqflxHjb","icd10":"K21.9","physical_exam":["咽喉（电子喉镜）：杓间区红斑与水肿、声带水肿、喉室消失与后连合黏膜增生（RFS评分）","口咽：咽后壁滤泡与黏液附着、扁桃体与软腭","颈部：甲状腺与淋巴结（排除其他病因）","声音：嘶哑程度、发声疲劳与音域（GRBAS评分）","腹部：上腹压痛（反流相关）、有无腹块","体重与BMI：肥胖评估（减重指征）","其他：鼻腔（鼻后滴漏鉴别）、肺部（哮喘与慢性咳嗽鉴别）"],"lab_tests":["反流症状指数（RSI）量表：>13分提示LPRD（治疗前后对比）","电子喉镜+反流表现评分（RFS）：喉部黏膜评估（>7分支持诊断）","24小时咽喉食管pH-阻抗监测（难治性病例金标准）：酸/非酸反流事件","胃镜：排除食管炎、Barrett食管、食管裂孔疝与胃部病变","食管测压（必要时）：食管动力与括约肌功能","幽门螺杆菌检测：感染筛查与根除指征","PPI诊断性治疗（8周）反应：诊断依据之一（症状+喉镜改善）"],"nursing":["用药依从性护理：强调PPI餐前30分钟服用（疗效关键）、按时足疗程（8～12周）、记录漏服","饮食与生活方式指导：睡前3小时禁食、床头抬高15～20cm、避免高脂/咖啡/浓茶/辛辣/酒、戒烟、减重","嗓音护理：避免清嗓与用力发声、充足饮水与咽喉保湿、避免长时间说话与刺激性气体","症状记录：记录RSI评分、咽喉症状与咳嗽变化，复诊时提供","难治性病例配合：24小时pH-阻抗监测的停用药指导与注意事项","宣教：治疗需时间与耐心（8～12周起效）、生活方式改变与药物同等重要、症状复发及时复诊"],"diet":["避免高脂、油炸、巧克力、咖啡、浓茶、碳酸饮料、辛辣与酸性食物（降低括约肌压力与刺激咽喉）","少量多餐，避免过饱；睡前3小时不进食（夜间反流高发）","戒烟限酒；餐后保持直立1～2小时，避免立即平卧与弯腰","减重（肥胖增加腹压与反流）；避免紧身衣物与束腹","充足温水（湿润咽喉，减轻刺激）；避免过烫与过冷饮品"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1458},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"29aebd105df8c61687bdf85f7dfde964fa30beb81b683e9dc7437497ef9ba3c9","pinyin":"yanhoufanliuxingjibing","initials":"yhflxjb","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","咽异物感（'癔球症'）、频繁清嗓与咽部黏痰感\\n声音嘶哑（晨起明显）、发声疲劳与音域变窄\\n慢性咳嗽（干咳）、咽痛与咽部烧灼感\\n吞咽不适、喉痉挛（少见）与夜间呛咳\\n常无明显烧心与反酸（'沉默性反流'）",60],["摘要","咽喉反流性疾病（LPRD）是胃内容物（胃酸与胃蛋白酶）反流至咽喉部引起的慢性炎症，表现为咽异物感、清嗓、声音嘶哑、慢性咳嗽与咽痛（与胃食管反流不同，多无明显烧心）。诊断依靠症状量表（RSI）与喉镜评分（RFS），治疗以质子泵抑制剂（PPI）足疗程+生活方式干预为核心。",30],["疾病编码","K21.9",30],["原首字母","yqflxHjb",60]]},{"id":"orders-28cb71be1c661bee5cde","key":"v1-c9ccc21dfe2a3058|orders-28cb71be1c661bee5cde","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"鼻骨骨折","category":"耳鼻喉","raw":{"name":"鼻骨骨折","category":"耳鼻喉","summary":"鼻骨骨折是最常见的面部骨折，多由外伤（打斗、运动、跌倒）引起，表现为鼻出血、鼻部肿胀变形与鼻塞。诊断依靠体检与影像（鼻骨侧位片/CT），处理包括止血、消肿与复位（闭合复位多在伤后7～10天内、肿胀消退后）。需警惕合并伤（鼻中隔血肿、眶壁骨折与颅底损伤）。","symptoms":["鼻出血（常见，多可自行停止或压迫止血）","鼻部疼痛、肿胀与变形（鼻梁偏斜或塌陷）","鼻塞（鼻中隔偏移、黏膜肿胀或血肿）","鼻部触痛与骨擦感（骨折端移动）","合并伤：鼻中隔血肿（鼻塞+鼻中隔膨隆，需紧急处理）、眶周瘀斑与眼球活动受限（眶壁骨折）、脑脊液鼻漏（颅底骨折）"],"diagnosis":["体格检查：鼻外形（偏斜/塌陷）、触诊（骨擦感与台阶感）、鼻内镜（鼻中隔偏曲与血肿、黏膜撕裂）","鼻骨侧位X线/鼻骨CT：明确骨折部位与移位程度（CT更准确，可同时评估眶壁与鼻窦）","面部CT（疑合并伤）：眶壁、颧骨、上颌骨与颅底评估（多发面骨骨折）","鼻中隔检查（重点）：鼻中隔血肿（膨隆、暗红、触软）需紧急处理（否则致鼻中隔坏死与鞍鼻畸形）","脑脊液鼻漏评估（疑颅底损伤）：清水样鼻漏、'靶征'（血性液体中心清亮）与葡萄糖检测","眼科评估（疑眶壁骨折）：视力、眼球运动与复视、眶周感觉（眶下神经）","鉴别诊断：鼻部软组织挫伤（无骨擦感）、先天性鼻畸形与陈旧性鼻骨骨折"],"infusion":["⚠️ 以止血与复位为主，静脉用药用于出血与合并伤！","","方案1（鼻出血处理）：","  用法：局部压迫（捏鼻翼10～15分钟）与鼻腔填塞（凡士林纱条/膨胀海绵）；必要时氨甲环酸 0.5～1g 静滴；出血多者补液与输血（0.9%氯化钠+红细胞悬液）〔调 ★ 血栓性疾病史禁用/慎用；严重肾功能不全减量〕","","方案2（消肿与镇痛）：","  用法：地塞米松 10mg 静推 qd（2～3天，减轻水肿）；七叶皂苷钠 10mg + 0.9%氯化钠 250ml 静滴 qd；镇痛（氟比洛芬酯 50mg 静滴或曲马多）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","","方案3（开放性骨折/合并感染）：","  用法：头孢呋辛 1.5g 静滴 q8h（或头孢唑林 1g q8h）+ 甲硝唑 0.5g 静滴 q8h；破伤风抗毒素 1500IU 皮下注射（污染伤口）〔调 CrCl<30 减量；青霉素过敏禁用〕","","方案4（合并颅底骨折/脑脊液鼻漏）：","  用法：头孢曲松 2g（NS 100ml 或 5%GS 100ml）静滴 qd（预防颅内感染）；避免填塞与用力擤鼻；必要时神经外科评估〔调 肾功能不全一般无需调整；★ 新生儿禁与含钙输液同瓶〕","","📌 闭合复位宜在伤后7～10天内（肿胀消退后、骨痂形成前）；鼻中隔血肿需立即切开引流（否则致鼻中隔坏死）；疑脑脊液鼻漏者禁填塞与擤鼻。"],"oral_medication":["⚠️ 术后与恢复期用药：","药物1（抗感染）：","用法：头孢呋辛酯 0.25g bid 或 阿莫西林克拉维酸 0.625g tid（疗程5～7天，开放性骨折或填塞后）〔调 ★ CrCl<30 减量且不建议用；青霉素过敏禁用〕","药物2（消肿与镇痛）：","用法：地奥司明片 2片 bid 或 迈之灵 2片 bid；对乙酰氨基酚 0.5g 必要时（避免NSAIDs——加重出血）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","药物3（鼻腔护理）：","用法：生理盐水鼻腔喷雾/冲洗（清洁与湿润，填塞取出后使用）；复方薄荷油滴鼻剂（湿润黏膜）","药物4（辅助）：","用法：维生素C 0.2g tid（促愈合）；必要时口服抗生素与镇痛药（按医嘱）","📌 复位后2周内避免碰撞、擤鼻与戴眼镜（可致再移位）；鼻腔填塞期间张口呼吸（注意口腔湿润）。"],"treatment":["急救处理：鼻出血者局部压迫或填塞止血；清理血块与评估气道；开放性伤口清创","鼻中隔血肿处理（急症）：立即切开引流+鼻腔填塞（防鼻中隔坏死与鞍鼻畸形）+抗生素","闭合复位：伤后7～10天内（肿胀消退后）行鼻骨闭合复位（局麻或全麻），术后外固定与鼻腔填塞","开放复位（手术指征）：严重粉碎性骨折、闭合复位失败、鼻中隔严重偏曲或陈旧性骨折（鼻成形术）","合并伤处理：眶壁骨折（眼科与颌面外科评估，必要时手术）、颅底骨折（神经外科，禁填塞与擤鼻）、鼻窦骨折","消肿与镇痛：伤后48小时内冷敷（减轻肿胀）、抬高头部、镇痛与激素（短期）","术后护理：鼻腔填塞（2～3天）后取出、外固定（1～2周）、避免碰撞与擤鼻、鼻腔冲洗","随访：复位后1周、2周、1个月复查（鼻外形与通气），必要时二次复位（1～2周内）"],"management":["出血与气道观察：记录鼻出血量与性质（持续出血需重新填塞）、观察呼吸与吞咽（填塞致不适）","鼻中隔血肿监测：观察鼻中隔膨隆与鼻塞加重（血肿需急诊处理），异常立即报告","体位与护理：半卧位（减少出血与肿胀）、伤后48小时冷敷、避免低头与用力","填塞护理：填塞期间张口呼吸（口腔湿润与护理）、观察填塞物渗血与脱出、按时取出（2～3天）","疼痛与肿胀管理：评估疼痛评分并遵医嘱镇痛、观察肿胀消退（评估复位时机）","宣教：复位后2周内避免碰撞、擤鼻与戴眼镜、避免剧烈运动与用力、鼻腔冲洗方法、按时复查（鼻外形与通气）"],"notes":["鼻骨骨折闭合复位的最佳时机是伤后7～10天内（肿胀消退后、骨痂形成前），过晚需鼻成形术","鼻中隔血肿是急症（需立即切开引流，否则可致鼻中隔坏死与鞍鼻畸形）","疑颅底骨折/脑脊液鼻漏者禁止鼻腔填塞与擤鼻（增加颅内感染风险）","伤后48小时内冷敷（减轻肿胀），48小时后改热敷（促进吸收）","避免使用NSAIDs（加重出血与肿胀）"],"emergency":["大量鼻出血不止（填塞后仍出血或血压下降）→ 重新填塞、后鼻孔填塞或血管介入栓塞，补液输血","鼻中隔血肿（鼻中隔膨隆、鼻塞加重）→ 立即切开引流+填塞+抗生素","清水样鼻漏伴头痛（脑脊液鼻漏/颅底骨折）→ 禁止填塞与擤鼻、抬高头部、抗生素、神经外科评估","眶周瘀斑伴眼球活动受限与复视（眶壁骨折/眶内血肿）→ 急诊眼科与CT评估","开放性鼻骨骨折伴大量污染（需清创与抗感染）→ 急诊清创、抗生素与破伤风预防"],"pinyin":"bggz","icd10":"S02.2","physical_exam":["鼻外形：偏斜、塌陷或鞍鼻畸形、鼻背肿胀与瘀斑","鼻触诊：骨擦感、台阶感与压痛（骨折部位）","鼻内镜：鼻中隔偏曲、黏膜撕裂、鼻中隔血肿（膨隆、暗红与触软）","鼻腔：出血与血块、填塞物位置、鼻腔通畅度","眼部：眶周瘀斑、眼球活动与复视、视力与瞳孔（眶壁骨折/眶内损伤）","面部其他：颧骨、上颌骨与眶缘压痛（多发面骨骨折）","神经系统：脑脊液鼻漏、嗅觉减退（筛板损伤）与意识状态（颅脑损伤）"],"lab_tests":["鼻骨侧位X线/鼻骨CT：骨折部位与移位（CT更准确）","面部CT（含三维重建）：多发面骨骨折、眶壁与鼻窦评估","头颅CT（疑颅脑损伤/颅底骨折）：颅内出血、气颅与颅底骨折","鼻漏液葡萄糖检测（疑脑脊液漏）：β2转铁蛋白（确诊）","血常规+凝血功能：出血与术前评估","眼科检查（视力、眼球运动与复视）：眶壁骨折评估","嗅觉测试（必要时）：筛板损伤评估"],"nursing":["出血观察与护理：记录鼻出血量与性质，配合局部压迫与填塞，观察血压与意识（大量出血）","鼻中隔血肿监测：观察鼻中隔膨隆与鼻塞加重，异常立即报告（需急诊切开）","体位与冷敷：半卧位、伤后48小时内冷敷（每次15～20分钟）、避免低头与用力","填塞护理：张口呼吸与口腔湿润护理、观察填塞物渗血与脱出、按时取出并观察出血","疼痛与肿胀观察：评估疼痛评分、观察肿胀消退（决定复位时机）、遵医嘱镇痛（避免NSAIDs）","宣教：复位后2周内避免碰撞、擤鼻与戴眼镜、避免剧烈运动、鼻腔冲洗方法、按时复查鼻外形与通气"],"diet":["清淡易消化饮食，避免过热食物（加重鼻出血）与辛辣刺激","温凉流质与软食（填塞期间咀嚼与吞咽不适）","充足水分（填塞期间张口呼吸致口干）；避免饮酒（加重出血与肿胀）","高蛋白、高维生素C饮食促进愈合","填塞期间避免用力咀嚼与大笑（牵拉不适），少量多餐"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1459},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"245dd804c52f15c87c532f283a18c3c4fdd27c5ced1208b8960484dc43a2b762","pinyin":"biguguzhe","initials":"bggz","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","鼻出血（常见，多可自行停止或压迫止血）\\n鼻部疼痛、肿胀与变形（鼻梁偏斜或塌陷）\\n鼻塞（鼻中隔偏移、黏膜肿胀或血肿）\\n鼻部触痛与骨擦感（骨折端移动）\\n合并伤：鼻中隔血肿（鼻塞+鼻中隔膨隆，需紧急处理）、眶周瘀斑与眼球活动受限（眶壁骨折）、脑脊液鼻漏（颅底骨折）",60],["摘要","鼻骨骨折是最常见的面部骨折，多由外伤（打斗、运动、跌倒）引起，表现为鼻出血、鼻部肿胀变形与鼻塞。诊断依靠体检与影像（鼻骨侧位片/CT），处理包括止血、消肿与复位（闭合复位多在伤后7～10天内、肿胀消退后）。需警惕合并伤（鼻中隔血肿、眶壁骨折与颅底损伤）。",30],["疾病编码","S02.2",30],["原首字母","bggz",60]]},{"id":"orders-6a835b99404d2208939c","key":"v1-c9ccc21dfe2a3058|orders-6a835b99404d2208939c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"汞中毒","category":"中毒/理化","raw":{"name":"汞中毒","category":"中毒/理化","summary":"汞中毒由金属汞蒸气（职业暴露：仪表、冶炼与牙科）、无机汞（含汞中药与化妆品）或有机汞（甲基汞，污染鱼贝类）引起。急性中毒表现为腐蚀性胃肠炎与肾损害，慢性中毒以神经精神症状（易兴奋症）、震颤与口腔炎为特征。治疗核心是脱离接触+驱汞治疗（二巯丙磺钠、二巯丁二酸）。","symptoms":["慢性中毒（常见）：易兴奋症（失眠、多梦、易激动、记忆力减退）、震颤（手指、眼睑与舌，精细动作困难如写字）与口腔炎（流涎、牙龈红肿与汞线）","神经系统：头痛、头晕、肢体麻木、周围神经病与情绪障碍（抑郁与焦虑）","肾脏：蛋白尿、肾病综合征（膜性肾病，无机汞）与肾功能损害","消化道（急性）：口腔与咽部烧灼痛、恶心呕吐、腹痛、血性腹泻（腐蚀性胃肠炎）","其他：皮疹（汞过敏）、唾液增多、食欲减退与体重下降"],"diagnosis":["血汞（急性暴露）：>1.5μmol/L（30μg/L）提示中毒；尿汞（慢性暴露）：>0.25μmol/L（50μg/L）需驱汞试验","驱汞试验（二巯丙磺钠或二巯丁二酸后测尿汞）：诊断与治疗指征（尿汞明显增加支持中毒）","尿常规+24小时尿蛋白定量+肾功能：肾损害评估（蛋白尿与肾病综合征）","肝功能+电解质：器官功能评估","神经与精神评估：震颤程度、情绪与认知（易兴奋症）","暴露史（关键）：职业（仪表、冶炼、牙科与荧光灯制造）、饮食（大量深海鱼）、含汞化妆品与中药（朱砂、轻粉）","鉴别诊断：帕金森病（震颤但无汞暴露）、甲状腺功能亢进（震颤+易激动）、酒精戒断（震颤）与肾病综合征其他病因"],"infusion":["⚠️ 驱汞治疗须在确诊后进行，急性中毒需先处理腐蚀性损伤！","方案1（慢性/亚急性中毒，二巯丙磺钠）：","用法：二巯丙磺钠 125～250mg 肌注 qd（或 5%二巯丙磺钠 2～3ml 肌注 qd，疗程3～4天，间歇3～4天后再用，共2～3个疗程）","方案2（急性无机汞中毒/腐蚀性损伤）：","用法：二巯丙磺钠 250mg 肌注 q4～6h（首日）→ 减量（疗程5～7天）；0.9%氯化钠/葡萄糖 静滴（补液与纠正电解质）；禁洗胃（腐蚀性损伤，可口服牛奶或蛋清保护黏膜）","方案3（急性肾损伤与支持）：","用法：0.9%氯化钠 静滴（维持尿量）；碳酸氢钠 静滴（碱化尿液，遵医嘱）；必要时CRRT/血液透析（急性肾衰竭与汞清除）〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","方案4（对症与营养支持）：","用法：0.9%氯化钠 静滴；维生素C 2g 静滴 qd；维生素B1 100mg 肌注 qd（神经损害）；白蛋白（低蛋白）","📌 急性腐蚀性汞中毒禁洗胃（可致穿孔）；驱汞药物有肾毒性与骨髓抑制（监测尿量、肾功能与血常规）；严重肾衰竭时血液净化可清除汞-螯合物。"],"oral_medication":["⚠️ 驱汞与对症口服用药：","药物1（口服驱汞，轻中度）：","用法：二巯丁二酸 10mg/kg tid（疗程5天，或按方案重复）；青霉胺 250mg qid（备选，青霉素过敏禁用）","药物2（口腔炎与神经症状）：","用法：复方氯己定含漱液 含漱 bid（口腔炎）；甲钴胺 0.5mg tid + 维生素B1 10mg tid（周围神经病）；普瑞巴林 75mg bid（神经痛，遵医嘱）","药物3（震颤与情绪）：","用法：普萘洛尔 10mg bid（震颤，按心率调整）；必要时抗焦虑药（劳拉西泮 0.5mg bid，短期）","药物4（营养与支持）：","用法：维生素C 0.2g tid；复合维生素B 2片 tid；锌剂（竞争吸收，葡萄糖酸锌 1片 bid）","📌 慢性汞中毒恢复慢（震颤与神经精神症状可持续数月至数年）；治疗期间须彻底脱离汞接触（包括更换牙科汞合金与停用含汞化妆品/中药）；定期复查尿汞与肾功能。"],"treatment":["脱离接触（根本）：调离职业岗位、停用含汞化妆品与中药（朱砂等）、去除环境汞污染（汞泄漏清理与通风）、更换牙科汞合金（必要时）","驱汞治疗：二巯丙磺钠（静脉/肌注，慢性与急性）或二巯丁二酸（口服），按疗程重复并监测不良反应","急性腐蚀性损伤处理：禁洗胃，口服牛奶或蛋清保护黏膜，补液与纠正电解质，必要时胃镜评估；急性肾衰竭行血液净化","肾损害处理：肾病综合征（激素±免疫抑制剂，肾内科指导）、保护肾功能与避免肾毒性药物","神经系统症状处理：营养神经（B族维生素、甲钴胺）、震颤用普萘洛尔、情绪障碍心理治疗与抗焦虑药","口腔炎处理：口腔卫生（含漱液）、避免刺激性食物、必要时止痛","血液净化（重症/急性）：血液透析或CRRT（急性肾衰竭与汞-螯合物清除），必要时血浆置换","随访：尿汞与血汞复查（治疗后）、肾功能与尿蛋白（每1～3个月）、神经精神症状评估与康复"],"management":["症状与暴露观察：记录震颤、口腔炎、情绪与尿量变化；了解并指导脱离汞暴露源（职业防护与环境清理）","驱汞护理：按时给药并观察不良反应（过敏、皮疹与肾功能），监测尿量与尿汞","肾功能监测：尿常规与尿蛋白（每日或隔日）、记录出入量，观察水肿与尿量变化","口腔护理：口腔清洁（含漱液）、观察牙龈红肿与汞线、避免刺激性食物与烟酒","心理精神护理：易兴奋症与情绪障碍常见（易激惹、失眠与抑郁），提供心理支持与情绪疏导","环境与卫生宣教：汞泄漏处理（硫磺粉覆盖与通风）、职业防护（口罩与手套）、洗手与更衣、避免含汞化妆品与中药","宣教：汞中毒恢复慢（需坚持治疗与随访）、彻底脱离接触是关键、避免使用含汞偏方与化妆品（尤其美白产品）"],"notes":["慢性汞中毒的典型三联征是『易兴奋症+震颤+口腔炎』（常被误诊为神经衰弱或甲亢）","急性腐蚀性汞中毒禁止洗胃（可致消化道穿孔）；应先保护黏膜与补液","驱汞药物均有肾毒性与骨髓抑制，需监测尿量、肾功能与血常规","含汞化妆品（美白产品）与中药（朱砂、轻粉、水银）是常见的隐匿汞来源（需详细询问）","严重肾衰竭时血液净化可清除汞-螯合物（但单纯汞难以透析清除，需先螯合）"],"emergency":["急性汞盐摄入伴口腔烧灼痛、血性腹泻与休克 → 禁洗胃、口服牛奶/蛋清、补液抗休克与驱汞治疗","急性肾衰竭（少尿、无尿与肌酐升高）→ 驱汞+CRRT/血液透析，监测电解质","汞中毒伴喉头水肿与呼吸困难 → 吸氧、激素与气道管理","严重震颤影响进食与生活（无法自理）→ 住院驱汞治疗与康复评估","汞泄漏事故致多人头痛与呼吸道刺激（吸入性汞蒸气中毒）→ 立即脱离现场、通风与吸氧，评估血汞与尿汞"],"pinyin":"gzd","icd10":"T56.1","physical_exam":["生命体征：血压、心率、呼吸与体温（急性中毒）","口腔：牙龈红肿与汞线（蓝黑色）、流涎与口腔黏膜糜烂（急性腐蚀性损伤）","神经系统：震颤（手指、眼睑与舌，意向性加重）、腱反射、感觉与共济（周围神经病）","精神情绪：易激惹、失眠、情绪不稳与认知减退（易兴奋症）","肾脏：水肿（肾病综合征）、尿量与血压（肾损害）","皮肤：皮疹与瘙痒（汞过敏）、色素沉着","职业与环境：工作场所（仪表、冶炼与牙科）、化妆品与中药使用史、饮食（大量深海鱼）"],"lab_tests":["血汞（急性暴露）+尿汞（慢性暴露）：诊断与随访（尿汞>0.25μmol/L需驱汞试验）","驱汞试验（二巯丙磺钠/二巯丁二酸后尿汞）：诊断与治疗指征","尿常规+24小时尿蛋白定量+肾功能：肾损害（肾病综合征与肾小管损害）评估","肝功能+电解质+血常规（驱汞监测）：药物不良反应与器官功能","神经传导+肌电图（周围神经病）：神经损害评估","甲状腺功能（鉴别震颤病因）+头颅MRI（必要时）：鉴别诊断","发汞/指甲汞（慢性暴露评估，必要时）：长期暴露标志（参考价值有限）"],"nursing":["症状观察：记录震颤程度（写字与持物）、口腔炎与情绪变化，观察尿量与水肿（肾损害）","驱汞护理：按时给药并监测尿量、肾功能与血常规；观察皮疹与过敏反应，异常立即报告","口腔护理：口腔清洁与含漱、观察牙龈与汞线、避免刺激性食物与烟酒","心理护理：易兴奋症致情绪不稳与失眠（易与家属冲突），提供心理支持、环境安静与情绪疏导","环境与卫生宣教：汞泄漏处理（硫磺粉、通风与密闭收集）、职业防护（口罩手套与更衣）、勤洗手、停用含汞化妆品与中药","宣教：慢性汞中毒恢复慢（数月至数年）、彻底脱离接触是关键、遵医嘱完成驱汞疗程并定期复查尿汞与肾功能"],"diet":["高蛋白、高维生素饮食（促进汞排泄与组织修复）；急性期口腔损伤者流质或半流质温凉饮食","补充富含锌与硒食物（竞争吸收与抗氧化）：海产品、瘦肉、坚果与全谷物","避免大量食用深海大型鱼类（甲基汞蓄积：鲨鱼、旗鱼与金枪鱼）","避免含汞中药（朱砂、轻粉）与含汞化妆品；避免饮酒（加重肝肾负担）","肾功能损害者：限制蛋白与钠盐（按肾功能分期），监测电解质"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1460},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"56cbe2b8a7fffad88f917531a499853c3af49a5050b3e57baac66d68a7c90e25","pinyin":"gongzhongdu","initials":"gzd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","慢性中毒（常见）：易兴奋症（失眠、多梦、易激动、记忆力减退）、震颤（手指、眼睑与舌，精细动作困难如写字）与口腔炎（流涎、牙龈红肿与汞线）\\n神经系统：头痛、头晕、肢体麻木、周围神经病与情绪障碍（抑郁与焦虑）\\n肾脏：蛋白尿、肾病综合征（膜性肾病，无机汞）与肾功能损害\\n消化道（急性）：口腔与咽部烧灼痛、恶心呕吐、腹痛、血性腹泻（腐蚀性胃肠炎）\\n其他：皮疹（汞过敏）、唾液增多、食欲减退与体重下降",60],["摘要","汞中毒由金属汞蒸气（职业暴露：仪表、冶炼与牙科）、无机汞（含汞中药与化妆品）或有机汞（甲基汞，污染鱼贝类）引起。急性中毒表现为腐蚀性胃肠炎与肾损害，慢性中毒以神经精神症状（易兴奋症）、震颤与口腔炎为特征。治疗核心是脱离接触+驱汞治疗（二巯丙磺钠、二巯丁二酸）。",30],["疾病编码","T56.1",30],["原首字母","gzd",60]]},{"id":"orders-959623f2b2dcda67140c","key":"v1-c9ccc21dfe2a3058|orders-959623f2b2dcda67140c","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"硫化氢中毒","category":"中毒/理化","raw":{"name":"硫化氢中毒","category":"中毒/理化","summary":"硫化氢（H₂S）是有毒气体（臭鸡蛋味，高浓度时嗅觉麻痹），常见于下水道、化粪池、沼气池、造纸与石油工业。吸入后与细胞色素氧化酶结合抑制细胞呼吸（细胞内窒息），高浓度可致'电击样'死亡。抢救核心是立即脱离现场、高浓度吸氧与对症支持（无特效解毒剂）。","symptoms":["轻度：眼刺痛、流泪、畏光、咽喉灼痛、咳嗽与头晕头痛（低浓度）","中度：剧烈头痛、恶心呕吐、呼吸困难、胸闷与步态不稳","重度：意识模糊、抽搐、昏迷、呼吸抑制与循环衰竭（'电击样'死亡，极高浓度）","眼部：化学性结膜炎与角膜损伤（眼灼痛、视物模糊）","迟发：中毒后数天至数周可出现迟发性脑病（头痛、认知障碍与运动障碍）"],"diagnosis":["现场暴露史（关键）：下水道、化粪池、沼气池与工业环境；同伴同时发病（群体中毒特征）","生命体征与意识评估：呼吸频率与形态、血氧、心率、血压与意识状态（GCS）","血气分析+乳酸：代谢性酸中毒与组织缺氧（乳酸明显升高，PaO₂可正常但组织缺氧）","血硫化物/硫化血红蛋白（辅助）：血硫化物升高（检测条件有限）","心电图+心肌酶：心肌损害与心律失常","头颅CT/MRI（意识障碍或迟发脑病）：脑水肿与基底节病变（迟发性脑病特征）","鉴别诊断：一氧化碳中毒（碳氧血红蛋白升高）、氰化物中毒（同样细胞窒息）、缺氧性脑病与其他刺激性气体中毒"],"infusion":["⚠️ 无特效解毒剂，抢救以脱离现场、高浓度吸氧与对症支持为主！","方案1（高浓度吸氧与气道管理）：","用法：立即脱离现场、高流量吸氧（10～15L/min，面罩）；必要时气管插管与机械通气（呼吸抑制者）；高压氧治疗（意识障碍与重度中毒，早期使用）","方案2（细胞色素氧化酶保护与解毒尝试）：","用法：高铁血红蛋白形成剂（亚硝酸钠 3% 10ml 缓慢静推，或 4-二甲氨基苯酚 3mg/kg 肌注）——理论上可结合硫化氢（证据有限，可试用）；硫代硫酸钠 12.5g + 0.9%氯化钠 250ml 静滴（辅助）","方案3（脑水肿与抽搐）：","用法：20%甘露醇 125～250ml 静滴 q6～8h（脑水肿）；地西泮 10mg 缓慢静推（抽搐）；地塞米松 10mg 静推 qd（减轻脑水肿）〔调 ★ 糖尿病/高血压/骨质疏松慎用；感染未控制禁用〕","方案4（循环支持与对症）：","用法：0.9%氯化钠 静滴（补液）；去甲肾上腺素 0.05～0.5μg/kg/min 泵入（低血压）；5%碳酸氢钠 静滴（严重代谢性酸中毒，pH<7.1）；眼部损伤用生理盐水冲洗〔调 心衰/肾功能不全/钠潴留者慎用；代谢性碱中毒禁用〕","📌 施救者必须佩戴防护装备（防止二次中毒，多人施救时最常见死亡原因）；高浓度吸氧与高压氧是主要治疗；无特效解毒剂，以器官支持为主。"],"oral_medication":["⚠️ 急性期以吸氧与支持治疗为主，恢复期用药：","药物1（神经营养与脑代谢）：","用法：甲钴胺 0.5mg tid + 维生素B1 10mg tid；胞磷胆碱 0.2g tid；维生素C 0.2g tid（抗氧化）","药物2（迟发性脑病与认知障碍）：","用法：多奈哌齐 5mg qn（认知障碍，遵医嘱）；尼莫地平 30mg tid（改善脑循环）；抗癫痫药（有癫痫发作者）","药物3（眼部损伤，恢复期）：","用法：人工泪液 1滴 qid；抗生素眼膏 睡前（角膜上皮损伤）；避免强光刺激（戴墨镜）","药物4（对症与支持）：","用法：对乙酰氨基酚 0.5g 必要时（头痛）；复合维生素B 2片 tid；必要时抗焦虑药（情绪障碍）〔调 ★ 肝功能不全每日≤2g；总量≤4g/d（含复方）〕","📌 重度中毒者需长期随访神经系统（迟发性脑病多在2～4周出现），认知与运动康复训练；眼部损伤需眼科随访（角膜瘢痕）。"],"treatment":["立即脱离现场与现场急救：施救者佩戴正压式空气呼吸器（严禁无防护施救）、迅速将患者移至通风处、松解衣领保持气道通畅","高浓度吸氧与呼吸支持：面罩高流量吸氧（10～15L/min）、必要时气管插管与机械通气、高压氧治疗（早期、重度与意识障碍者）","解毒尝试：亚硝酸钠 3% 10～15mL（300～450mg）缓慢静注（2.5～5mL/min）或4-二甲氨基苯酚 3mg/kg 静注+硫代硫酸钠 12.5～25g（50%溶液25～50mL）静注（证据有限，可试用）","脑水肿与抽搐处理：甘露醇 0.25～0.5g/kg 静滴 q6～8h、地塞米松 10mg 静推 q6h（短期）与地西泮 10mg 缓慢静推止惊；控制体温与血糖","循环支持与酸碱纠正：生理盐水补液、去甲肾上腺素 0.05～0.5μg/kg/min 静滴维持血压与 5%碳酸氢钠 100～250mL 静滴（严重酸中毒）","眼部与呼吸道损伤处理：大量生理盐水冲洗眼部（至少15分钟）、眼科评估（角膜损伤）；吸入性肺损伤（甲泼尼龙 40～80mg 静滴 qd 与呼吸支持）","迟发性脑病监测与治疗：中毒后2～4周出现认知与运动障碍（头颅MRI随访），予甲钴胺 0.5mg 口服 tid、胞磷胆碱 0.5g 静滴 qd 营养神经与康复治疗","随访：每3～6个月神经系统（认知、运动与情绪）与眼科随访（角膜损伤），必要时康复治疗与伤残鉴定"],"management":["现场安全：施救者必须佩戴防护装备（正压呼吸器），切断气源与加强通风（防止二次中毒）","生命体征监测：呼吸频率与形态、血氧、心率、血压与意识（每15～30分钟，急性期），必要时ICU监护","气道与氧疗护理：保持气道通畅、高流量吸氧、观察呼吸抑制与发绀，备插管与吸引设备","神经系统观察：意识、瞳孔、抽搐与迟发脑病表现（2～4周内出现头痛与认知障碍需报告）","眼部护理：生理盐水充分冲洗（至少15分钟）、避免强光、按医嘱眼部用药并观察角膜情况","心理护理：事故性中毒常伴恐惧与创伤（尤其同伴死亡者），提供心理支持与后续随访","宣教：下水道与化粪池作业必须通风与佩戴防护设备、'无人防护下不得施救'、中毒后需长期随访神经系统"],"notes":["硫化氢中毒无特效解毒剂，抢救核心是脱离现场+高浓度吸氧（尽早高压氧）与器官支持","高浓度硫化氢可致嗅觉迅速麻痹（闻不到臭鸡蛋味反而更危险）与'电击样'死亡","施救者无防护进入现场是最常见的死亡原因（必须佩戴正压式空气呼吸器）","乳酸明显升高而PaO₂正常提示细胞窒息（组织缺氧）——是硫化氢与氰化物中毒的特征","迟发性脑病可在中毒后2～4周出现（需长期随访神经系统与影像）"],"emergency":["现场发现昏迷患者（疑硫化氢中毒）→ 施救者佩戴防护装备，迅速移至通风处、高流量吸氧并呼叫救援","呼吸抑制或呼吸停止 → 立即气管插管与机械通气，高浓度吸氧","抽搐与昏迷（脑水肿）→ 甘露醇降颅压+地西泮止惊，转ICU与高压氧治疗","眼部剧痛与视物模糊（化学性角膜损伤）→ 立即生理盐水冲洗至少15分钟并眼科急会诊","休克（低血压与乳酸升高）→ 补液+血管活性药，纠正酸中毒"],"pinyin":"lhzH2Szd","icd10":"T59.6","physical_exam":["生命体征：呼吸频率与形态、血氧、心率、血压与体温（每15～30分钟）","意识与神经系统：GCS评分、瞳孔、抽搐与肌张力（脑水肿与缺氧性脑损伤）","眼部：结膜充血、角膜混浊与荧光素染色（化学性角膜炎）","呼吸系统：呼吸音、啰音（吸入性肺损伤）、发绀与三凹征","心血管：心率与心律（心肌损害）、血压（休克）","皮肤与黏膜：黏膜刺激征、皮肤发绀或樱桃红（与其他中毒鉴别）","现场相关：同伴同时发病、环境中臭鸡蛋味（高浓度时可无味）、通风与防护情况"],"lab_tests":["血气分析+乳酸（每1～4小时）：代谢性酸中毒与组织缺氧（乳酸显著升高而PaO₂可正常）","血硫化物/硫化血红蛋白（有条件时）：中毒证据","心电图+心肌酶：心肌损害与心律失常","肝肾功能+电解质：器官功能与电解质紊乱","头颅CT/MRI（意识障碍或迟发脑病）：脑水肿与基底节病变","碳氧血红蛋白（鉴别一氧化碳中毒）+血氰化物（鉴别氰化物中毒）","眼科检查（角膜荧光素染色）：化学性角膜损伤评估"],"nursing":["现场安全与转运：施救者佩戴防护装备、确保现场通风、转运途中持续吸氧与监护","氧疗护理：高流量吸氧（面罩）并观察疗效，配合高压氧治疗前准备与宣教","气道护理：保持气道通畅、按需吸痰、观察呼吸抑制与发绀，备插管与吸引设备","神经系统观察：每15～30分钟评估意识与瞳孔，观察抽搐；中毒后2～4周注意迟发脑病表现（头痛与认知障碍）","眼部护理：生理盐水充分冲洗（至少15分钟）、避免强光、按医嘱用药并观察角膜恢复情况","心理护理：突发中毒事件与同伴死亡易致创伤后应激，提供心理支持与随访","宣教：下水道与化粪池作业必须通风与佩戴防护设备、严禁无防护施救、中毒后长期随访神经系统"],"diet":["急性期：意识障碍者禁食（静脉营养支持）；清醒者流质或半流质（口腔与咽喉刺激）","高蛋白、高维生素饮食促进组织修复；补充维生素C与B族维生素（抗氧化与神经修复）","多饮水（促代谢物排泄，心肾功能允许下）；避免饮酒与辛辣刺激","恢复期：均衡营养、保证热量（脑损伤修复需求增加）","吞咽障碍者（重度中毒后）：鼻饲或经口进食评估（防误吸）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1461},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"294f954bfe5733aeec87e5d4c5304c4a0ef1ef5f1425a07383f4a344f3fdbaf1","pinyin":"liuhuaqingzhongdu","initials":"lhqzd","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","轻度：眼刺痛、流泪、畏光、咽喉灼痛、咳嗽与头晕头痛（低浓度）\\n中度：剧烈头痛、恶心呕吐、呼吸困难、胸闷与步态不稳\\n重度：意识模糊、抽搐、昏迷、呼吸抑制与循环衰竭（'电击样'死亡，极高浓度）\\n眼部：化学性结膜炎与角膜损伤（眼灼痛、视物模糊）\\n迟发：中毒后数天至数周可出现迟发性脑病（头痛、认知障碍与运动障碍）",60],["摘要","硫化氢（H₂S）是有毒气体（臭鸡蛋味，高浓度时嗅觉麻痹），常见于下水道、化粪池、沼气池、造纸与石油工业。吸入后与细胞色素氧化酶结合抑制细胞呼吸（细胞内窒息），高浓度可致'电击样'死亡。抢救核心是立即脱离现场、高浓度吸氧与对症支持（无特效解毒剂）。",30],["疾病编码","T59.6",30],["原首字母","lhzH2Szd",60]]},{"id":"orders-17659f17e53fbadf0ad0","key":"v1-c9ccc21dfe2a3058|orders-17659f17e53fbadf0ad0","module":"orders","moduleKey":"v1-c9ccc21dfe2a3058|orders","version":"v1-c9ccc21dfe2a3058","title":"有机溶剂中毒（苯及同系物）","category":"中毒/理化","raw":{"name":"有机溶剂中毒（苯及同系物）","category":"中毒/理化","summary":"苯及同系物（甲苯、二甲苯）是常见有机溶剂，经呼吸道与皮肤吸收，急性中毒表现为中枢神经抑制（头晕、意识障碍与呼吸抑制），慢性中毒以造血系统损害为特征（白细胞减少、再生障碍性贫血与白血病，主要为苯）。治疗核心是脱离接触+对症支持（无特效解毒剂）。","symptoms":["急性中毒：头晕、头痛、恶心、步态不稳、意识模糊与昏迷（中枢神经抑制），重者呼吸抑制与心律失常","黏膜刺激：眼刺痛、流泪、咽痛与咳嗽（蒸气刺激）","慢性中毒（苯）：乏力、头晕、失眠与记忆力减退；造血抑制（白细胞与血小板减少、贫血）","皮肤：干燥、脱脂、皮炎与皲裂（长期接触）","严重慢性中毒：再生障碍性贫血（贫血、感染与出血倾向）与白血病"],"diagnosis":["暴露史（关键）：职业（喷漆、制鞋、印刷、化工与实验室）、密闭空间作业与通风不良；皮肤接触史","血常规+外周血涂片+网织红细胞：造血系统损害（白细胞、血小板与血红蛋白下降，慢性苯中毒核心）","尿代谢产物（尿酚、尿马尿酸与甲基马尿酸）：暴露生物标志（班后尿检测）","肝肾功能+电解质+心肌酶：器官功能评估","血气分析+乳酸：组织缺氧与酸中毒（急性重度）","心电图：心律失常（苯对心肌的致敏作用，增加儿茶酚胺敏感性）","骨髓穿刺（慢性重度/疑白血病）：造血系统损害评估","鉴别诊断：其他溶剂中毒（甲醇、三氯乙烯）、一氧化碳中毒、低血糖与中枢神经系统疾病"],"infusion":["⚠️ 无特效解毒剂，以脱离接触、氧疗与器官支持为主！","方案1（脱离接触与氧疗）：","用法：立即脱离现场、脱去污染衣物并清洗皮肤（大量温水与肥皂）、高流量吸氧（面罩）；必要时机械通气","方案2（心律失常处理，苯致心肌致敏）：","用法：禁用肾上腺素（可诱发室性心律失常）；室性心律失常用 利多卡因 1～1.5mg/kg 静推后 1～4mg/min 泵入；窦性心动过速（慎用β受体阻滞剂，遵医嘱）","方案3（中枢抑制与脑水肿）：","用法：纳洛酮 0.4～0.8mg 静推（意识障碍，试用）；20%甘露醇 125～250ml 静滴（脑水肿）；地西泮 10mg 缓慢静推（抽搐）〔调 ★ eGFR<30 禁用/慎用；心衰肺水肿禁用〕","方案4（慢性造血损害支持）：","用法：维生素B族与叶酸补充；粒细胞缺乏伴发热——广谱抗生素（哌拉西林他唑巴坦 4.5g q8h）；贫血——红细胞悬液输注；血小板减少——血小板输注〔调 ★ CrCl<40 减量；青霉素过敏禁用〕","📌 苯中毒禁用肾上腺素（致心律失常）；急性中毒以支持治疗为主；慢性中毒需脱离接触并长期监测血常规（造血系统损害可迟发与进展）。"],"oral_medication":["⚠️ 慢性中毒恢复期用药（无特效解毒剂）：","药物1（造血支持）：","用法：利可君 20mg tid 或 鲨肝醇 50mg tid（升白细胞，遵医嘱）；叶酸 5mg qd + 维生素B12（巨幼样改变）；维生素B4 10mg tid","药物2（免疫与支持，再障）：","用法：环孢素 3～5mg/kg/日（再障免疫抑制治疗，血液科指导）；司坦唑醇 2mg tid（促造血，监测肝功能）","药物3（对症与营养）：","用法：复合维生素B 2片 tid；维生素C 0.2g tid；甲钴胺 0.5mg tid（神经症状）","药物4（皮肤护理）：","用法：保湿霜（皮肤脱脂与皲裂）；避免继续接触有机溶剂；必要时糖皮质激素软膏（皮炎）","📌 慢性苯中毒需终身随访血常规（造血损害可迟发与进展为白血病）；再障与白血病按血液科方案治疗；脱离接触是根本。"],"treatment":["立即脱离接触（首要）：转移至通风处、脱去污染衣物、皮肤与眼部大量清水冲洗（至少15分钟）","氧疗与呼吸支持：高流量吸氧、必要时机械通气（呼吸抑制与昏迷者）；禁用肾上腺素（致心律失常）","心律失常处理：利多卡因 50～100mg 静推（1mg/kg，5～10分钟可重复，继以 1～4mg/min 静滴）、纠正电解质与酸碱失衡、持续心电监护","中枢神经系统支持：意识障碍者监测GCS与瞳孔、甘露醇 0.25～0.5g/kg 静滴 q6～8h 降颅压（脑水肿）、止惊用地西泮 10mg 缓慢静推","慢性造血系统损害处理：脱离接触+利可君 20mg 口服 tid 或 G-CSF 5μg/kg 皮下 qd 升白细胞、再障（环孢素 3～5mg/kg/d 口服+抗胸腺细胞球蛋白）、白血病（化疗）与支持治疗（输血、抗感染）","皮肤与眼部损伤：清水冲洗、皮肤保湿与换药、眼科评估（角膜损伤）","职业健康监护：定期血常规（每3～6个月）、尿代谢产物监测、职业卫生评估与防护改进（通风、密闭化与个体防护）","随访：急性中毒后随访神经系统；慢性中毒终身随访血液系统（每3～6个月），必要时骨髓检查与伤残鉴定"],"management":["脱离接触落实：指导职业防护（通风、密闭操作与呼吸防护）、避免密闭空间作业与皮肤接触","生命体征与心律监测：急性中毒者持续心电监护（苯致心肌致敏）、监测意识与呼吸，禁用肾上腺素并提示医师与护士","皮肤与眼部护理：脱去污染衣物、温水肥皂清洗皮肤（避免热水与酒精擦洗）、眼部生理盐水冲洗至少15分钟","血常规监测（慢性）：每3～6个月复查血常规与网织红细胞，记录白细胞、血小板与血红蛋白趋势","防感染与出血护理（造血抑制）：保护性隔离（粒细胞缺乏）、口腔护理、观察出血倾向（皮肤瘀斑与牙龈出血）","心理护理：慢性中毒涉及职业病认定与预后焦虑，提供心理支持与随访安排","宣教：密闭空间作业必须通风与佩戴防护装备、长期接触者定期体检（血常规）、出现乏力与出血倾向立即就诊"],"notes":["急性有机溶剂中毒以中枢神经抑制为主，抢救核心是脱离接触+氧疗与器官支持（无特效解毒剂）","苯中毒禁用肾上腺素（增加心肌对儿茶酚胺敏感性，可诱发室性心律失常）","慢性苯中毒主要损害造血系统（白细胞减少→再障→白血病），需长期随访血常规","尿酚与尿马尿酸（或甲基马尿酸）是暴露的生物监测指标（班后尿检测）","喷漆、制鞋、印刷与化工行业是苯暴露的主要职业（需通风与个体防护）"],"emergency":["昏迷与呼吸抑制（急性重度中毒）→ 立即脱离现场、高流量吸氧与机械通气，监测心电（禁用肾上腺素）","室性心律失常（苯致心肌致敏）→ 利多卡因+纠正电解质，避免肾上腺素与儿茶酚胺类药物","抽搐与脑水肿 → 地西泮止惊+甘露醇降颅压，转ICU","粒细胞缺乏伴发热（慢性苯中毒）→ 立即广谱抗生素+保护性隔离（1小时内）","严重出血（血小板显著减少）→ 输注血小板+止血处理，血液科评估"],"pinyin":"yjrjzdBjtXw","icd10":"T52.1","physical_exam":["生命体征：呼吸（抑制）、心率与心律（心律失常）、血压与体温","意识与神经系统：GCS评分、瞳孔、步态与共济失调（中枢抑制）；慢性者腱反射与感觉（周围神经病）","皮肤与黏膜：皮肤脱脂、干燥与皲裂、皮炎；黏膜刺激征与颜色（发绀或苍白）","眼部：结膜充血与角膜损伤（化学性刺激）","呼吸系统：呼吸音、啰音与咳嗽（吸入性损伤）","血液系统体征（慢性）：贫血貌、皮肤瘀斑与出血点、口腔溃疡与牙龈出血、肝脾与淋巴结肿大（白血病）","职业与环境：工作场所通风、防护设备使用与密闭空间作业情况"],"lab_tests":["血常规+外周血涂片+网织红细胞（慢性中毒核心）：白细胞、血小板与血红蛋白监测（每3～6个月）","尿代谢产物（尿酚、尿马尿酸/甲基马尿酸）：暴露生物监测（班后尿）","肝肾功能+电解质+心肌酶：器官功能评估","血气分析+乳酸：组织缺氧与酸中毒（急性重度）","心电图+心肌酶（急性）：心律失常与心肌损害（苯致心肌致敏）","骨髓穿刺+活检（慢性重度/疑白血病）：造血系统损害评估","头颅CT（意识障碍）：脑水肿评估"],"nursing":["急救护理：脱离现场、脱去污染衣物与皮肤清洗（温水肥皂）、高流量吸氧、持续心电监护","用药安全提示：牢记苯中毒禁用肾上腺素（可致室性心律失常），提醒医师与抢救团队","生命体征与意识观察：每15～30分钟监测意识、呼吸与心律，异常立即报告","血液系统观察（慢性）：监测血常规趋势、观察贫血（乏力与气促）、出血（瘀斑与牙龈）与感染（发热）征象","防感染与出血护理：保护性隔离（粒细胞缺乏）、口腔护理、避免创伤性操作与肌肉注射（血小板低者）","职业健康宣教：通风与密闭化作业、呼吸防护与皮肤防护、定期体检（血常规）、避免密闭空间作业与皮肤长时间接触"],"diet":["高蛋白、高维生素饮食（造血系统修复需要）；补充叶酸与维生素B12（绿叶蔬菜与动物性食物）","富含铁食物（红肉、动物肝脏）配合维生素C促进吸收（贫血者）","充足水分（促进代谢物排泄）；避免饮酒（加重肝损害与造血抑制）","粒细胞缺乏者：食物充分加热、避免生冷与不洁食物（防感染）","血小板减少者：避免粗糙坚硬与带刺食物（防消化道出血）"]},"locator":{"file":"临床医嘱/临床医嘱_全部_20261111.json","arrayRow":1462},"sourceHash":"d7a1403a3bddd3d3e93039b106b40a5ba48ad7f0dc98dc9fe5b46d2870c7123f","contentHash":"524f0febee97fa12613be5a3ac00853828c11ff075fe6733e88d0617713cff04","pinyin":"youjirongjizhongdu（benjitongxiwu）","initials":"yjrjzd（bjtxw）","flags":[],"emptySymptoms":false,"quickFields":[["常见症状","急性中毒：头晕、头痛、恶心、步态不稳、意识模糊与昏迷（中枢神经抑制），重者呼吸抑制与心律失常\\n黏膜刺激：眼刺痛、流泪、咽痛与咳嗽（蒸气刺激）\\n慢性中毒（苯）：乏力、头晕、失眠与记忆力减退；造血抑制（白细胞与血小板减少、贫血）\\n皮肤：干燥、脱脂、皮炎与皲裂（长期接触）\\n严重慢性中毒：再生障碍性贫血（贫血、感染与出血倾向）与白血病",60],["摘要","苯及同系物（甲苯、二甲苯）是常见有机溶剂，经呼吸道与皮肤吸收，急性中毒表现为中枢神经抑制（头晕、意识障碍与呼吸抑制），慢性中毒以造血系统损害为特征（白细胞减少、再生障碍性贫血与白血病，主要为苯）。治疗核心是脱离接触+对症支持（无特效解毒剂）。",30],["疾病编码","T52.1",30],["原首字母","yjrjzdBjtXw",60]]}]);